/* Original reimplementation of a tiny C compiler - common header */
#ifndef TCC_H
#define TCC_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdarg.h>
#include <setjmp.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/time.h>

#define TCC_VERSION "0.9.28rc"
#define TCC_BUILD_INFO "2026-06-12 build@c6162e3"

/* ---------------------------------------------------------------- */
/* utilities */

typedef struct CStr {
    int len, cap;
    char *data;
} CStr;

void cstr_init(CStr *s);
void cstr_free(CStr *s);
void cstr_reset(CStr *s);
void cstr_cat(CStr *s, const char *str, int len);
void cstr_ccat(CStr *s, int c);
void cstr_printf(CStr *s, const char *fmt, ...);
void *xmalloc(size_t n);
void *xrealloc(void *p, size_t n);
void *xcalloc(size_t n);
char *xstrdup(const char *s);
char *xstrndup(const char *s, int n);
const char *intern(const char *s, int len);

/* dynamic array of pointers */
typedef struct PVec {
    int len, cap;
    void **p;
} PVec;
void pvec_push(PVec *v, void *x);

/* ---------------------------------------------------------------- */
/* tokens */

enum {
    TOK_EOF = -1,
    TOK_LINEFEED = 10,
    /* multi-char punctuators (>= 128) */
    TOK_ARROW = 0x80,  /* -> */
    TOK_INC,           /* ++ */
    TOK_DEC,           /* -- */
    TOK_SHL,           /* << */
    TOK_SAR,           /* >> */
    TOK_LE,            /* <= */
    TOK_GE,            /* >= */
    TOK_EQ,            /* == */
    TOK_NE,            /* != */
    TOK_LAND,          /* && */
    TOK_LOR,           /* || */
    TOK_DOTS,          /* ... */
    TOK_TWOSHARPS,     /* ## */
    TOK_A_ADD,         /* += */
    TOK_A_SUB,         /* -= */
    TOK_A_MUL,         /* *= */
    TOK_A_DIV,         /* /= */
    TOK_A_MOD,         /* %= */
    TOK_A_AND,         /* &= */
    TOK_A_OR,          /* |= */
    TOK_A_XOR,         /* ^= */
    TOK_A_SHL,         /* <<= */
    TOK_A_SAR,         /* >>= */
    /* literals */
    TOK_PPNUM,         /* preprocessing number (spelling kept) */
    TOK_STR,           /* string literal (raw spelling incl. quotes and prefix) */
    TOK_CHAR,          /* char constant (raw spelling) */
    TOK_NOSUBST,       /* marker: following ident must not be expanded */
    TOK_PLACEHOLDER,   /* empty argument placemarker */
    TOK_PRAGMA_LINE,   /* internal */
    TOK_IDENT = 256
};

/* keyword ids: fixed order, starting at TOK_IDENT */
enum {
    TOK_KW_START = TOK_IDENT,
#define KW(id, str) id,
#include "keywords.h"
#undef KW
    TOK_KW_END
};

typedef struct Tok {
    int id;
    const char *s;   /* spelling (interned) for PPNUM/STR/CHAR, NULL otherwise */
} Tok;

typedef struct TokVec {
    int len, cap;
    Tok *t;
} TokVec;
void tv_push(TokVec *v, int id, const char *s);
void tv_free(TokVec *v);

struct Sym;
struct Macro;

typedef struct Ident {
    int id;
    char *name;
    int len;
    struct Macro *mac;
    struct Macro *mac_stack;   /* for push_macro */
    struct Sym *sym_id;        /* identifiers (vars, typedefs, functions) */
    struct Sym *sym_struct;    /* struct/union/enum tags */
    struct Sym *sym_label;     /* labels */
    struct Ident *hnext;
} Ident;

extern Ident **idents;
extern int nb_idents;
Ident *ident_get(int id);
int ident_lookup(const char *s, int len);     /* intern name, return id */
const char *tok_name(int id);                 /* spelling of ident/keyword/punct */
const char *tok_spelling(const Tok *t);       /* spelling of any token */
int is_ident_tok(int id);

/* ---------------------------------------------------------------- */
/* macros */

typedef struct Macro {
    int id;
    int is_func;
    int nparams;
    int variadic;      /* last param is variadic */
    int *params;       /* ids; for "..." the id of __VA_ARGS__ */
    TokVec body;
    struct Macro *next; /* for push_macro stack */
} Macro;

/* ---------------------------------------------------------------- */
/* files */

#define IFDEF_STACK_SIZE 128
#define INCLUDE_STACK_SIZE 32

typedef struct File {
    char *data;            /* whole file + '\0' */
    const char *p;         /* current position */
    int line_num;
    int line_ref;
    char filename[1024];   /* name as displayed */
    char truename[1024];
    int inc_idx;           /* include path index where found (-1 relative) */
    int ifdef_depth;       /* ifdef stack depth at open */
    int ifndef_macro;      /* guard macro candidate */
    int ifndef_macro_saved;
    struct File *prev;
} File;

extern File *file;

/* conditional stack */
typedef struct IfState {
    int taking;      /* current group active */
    int any_taken;   /* some group already taken */
    int seen_else;
    int parent_taking;
} IfState;

/* ---------------------------------------------------------------- */
/* compiler state */

enum { OUT_MEMORY = 1, OUT_EXE, OUT_DLL, OUT_OBJ, OUT_PREPROCESS };
enum { FT_NONE, FT_C, FT_ASM, FT_ASMPP, FT_BIN, FT_LIB, FT_OBJ };
enum { PFLAG_NORMAL, PFLAG_NONE, PFLAG_STD };

typedef struct InFile {
    char *name;
    int type;
} InFile;

typedef struct State {
    int verbose;
    int nostdinc, nostdlib;
    int output_type;
    int do_bench;
    int do_debug;
    int do_bounds_check;
    int do_backtrace;
    int rt_num_callers;
    int static_link;
    int rdynamic;
    int run_test;
    int dflag;          /* -dD=1 -dM=2 -dt=16 */
    int pflag;          /* -P */
    int cversion;       /* 199901 or 201112 */
    int char_is_unsigned;
    int leading_underscore;
    int optimize;
    int pthread;
    int ms_extensions;
    int ms_bitfields;
    int dollars_in_identifiers;
    int warn_write_strings;
    int warn_unsupported;
    int warn_implicit_function_declaration;
    int warn_discarded_qualifiers;
    int warn_error;
    int warn_all;
    int warn_none;
    int gnu89_inline;
    int reverse_funcargs;
    int unwind_tables;
    int test_coverage;
    int common;
    int nosse;
    int gen_deps;        /* -MD */
    int just_deps;       /* -M */
    int filetype;
    int nb_errors;
    int nb_warnings;
    int seen_o;
    int seen_E_action;
    char *outfile;
    char *deps_outfile;
    char *tcc_lib_path;
    char *soname;
    char *rpath;
    char *elfint;
    char *init_symbol, *fini_symbol;
    int symbolic;
    int enable_new_dtags;
    uint64_t text_addr;
    int has_text_addr;
    int section_align;
    char *entryname;
    PVec include_paths;
    PVec sysinclude_paths;
    PVec library_paths;
    PVec crt_paths;
    PVec files;          /* InFile* */
    PVec cmdline_defs;   /* strings "-Dx" / "-Ux" in order */
    PVec cmdline_incl;   /* -include files */
    PVec target_deps;    /* char* */
    PVec pragma_libs;
    PVec linker_args;
    char *run_stdin;
    int run_argc;
    char **run_argv;
    CStr cmdline_buf;
    FILE *ppfp;
    int ifdef_stack_ptr_val;
} State;

extern State S;

/* ---------------------------------------------------------------- */
/* error handling */

extern jmp_buf error_jmp_buf;
extern int error_set_jmp_enabled;

void tcc_error(const char *fmt, ...) __attribute__((noreturn));
void tcc_error_noabort(const char *fmt, ...);
void tcc_warning(const char *fmt, ...);
void tcc_warning_c(int *flag, const char *fmt, ...);
void tcc_fatal(const char *fmt, ...) __attribute__((noreturn));

/* ---------------------------------------------------------------- */
/* preprocessor API (pp.c) */

#define PARSE_FLAG_PREPROCESS 0x0001
#define PARSE_FLAG_TOK_NUM    0x0002
#define PARSE_FLAG_LINEFEED   0x0004
#define PARSE_FLAG_ASM_FILE   0x0008
#define PARSE_FLAG_SPACES     0x0010
#define PARSE_FLAG_ACCEPT_STRAYS 0x0020
#define PARSE_FLAG_TOK_STR    0x0040

extern int parse_flags;
extern int tok;
extern const char *tokstr;   /* spelling of current literal token */
extern Tok tokcur;

void pp_init(void);
void pp_new_file(const char *filename, char *data, int len);
int pp_open_file(const char *filename, int inc_idx);
void pp_close_file(void);
void pp_start(int is_asm);
void pp_end(void);
void next(void);
void next_nomacro(void);
void unget_tok(int last_tok);
void skip(int c);
void expect(const char *msg);
int preprocess_file(const char *filename, const char *data, int len);
void pp_define_cmdline(const char *def, int is_undef);
void pp_build_cmdline_buf(void);
int pp_eval_const_expr(void);
int file_type_from_name(const char *name);
char *tcc_basename(const char *name);
char *tcc_fileextension(const char *name);
const char *get_tok_str(int id, const char *s);
void pp_run_preprocess(FILE *f);
void pp_print_deps(FILE *f);
void pp_add_dep(const char *name);
void pp_unexpanded_push(void); /* unused */
void pp_check_eof(void);
const char *pp_cur_filename(void);
int pp_cur_line(void);
int pp_include_depth(void);

/* string parsing */
void parse_string_literal(const char *s, CStr *out, int *is_wide, int *char_size);
int parse_char_const(const char *s, int64_t *val, int *is_wide, int *nb);

/* compiler API (parse.c / gen.c) */
void tccgen_init(void);
void tccgen_compile(void);
void tccgen_finish(void);
void tccelf_begin(void);
int tccelf_output_file(const char *filename);
void tccelf_end(void);
int tcc_add_file(const char *filename, int filetype);
int tcc_compile_string_c(const char *str);
void tcc_run_setup(void);
void asm_file(int preprocess);

/* ar */
int tcc_tool_ar(int argc, char **argv);

#endif
EOF
