static unsigned hash_str(const char *s, int len)
{
    unsigned h = 1;
    while (len-- > 0) h = h * 263 + (unsigned char)*s++;
    return h;
}

const char *intern(const char *s, int len)
{
    unsigned h;
    IStr *p;
    if (len < 0) len = strlen(s);
    h = hash_str(s, len) % INTERN_HASH;
    for (p = intern_tab[h]; p; p = p->next)
        if (p->len == len && !memcmp(p->s, s, len))
            return p->s;
    p = xmalloc(sizeof(IStr) + len);
    p->len = len;
    memcpy(p->s, s, len);
    p->s[len] = 0;
    p->next = intern_tab[h];
    intern_tab[h] = p;
    return p->s;
}

