int ident_lookup(const char *s, int len)
{
    unsigned h;
    Ident *p;
    if (len < 0) len = strlen(s);
    h = hash_str(s, len) % IDENT_HASH;
    for (p = ident_hash[h]; p; p = p->hnext)
        if (p->len == len && !memcmp(p->name, s, len))
            return p->id;
    p = xcalloc(sizeof(Ident));
    p->name = xstrndup(s, len);
    p->len = len;
    if (nb_idents >= idents_cap) {
        idents_cap = idents_cap ? idents_cap * 2 : 1024;
        idents = xrealloc(idents, idents_cap * sizeof(Ident *));
    }
    p->id = TOK_IDENT + nb_idents;
    idents[nb_idents++] = p;
    p->hnext = ident_hash[h];
    ident_hash[h] = p;
    return p->id;
}

void idents_init(void)
{
    int i;
    for (i = 0; i < (int)(sizeof(kw_names) / sizeof(kw_names[0])); i++)
        ident_lookup(kw_names[i], -1);
}

int is_ident_tok(int id) { return id >= TOK_IDENT; }

static const char *punct_names[] = {
    "->", "++", "--", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||", "...", "##",
    "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<=", ">>=",
};

const char *tok_name(int id)
{
    static char buf[8][4];
    static int bi;
    if (id >= TOK_IDENT)
        return ident_get(id)->name;
    if (id >= TOK_ARROW && id <= TOK_A_SAR)
        return punct_names[id - TOK_ARROW];
    if (id == TOK_EOF)
        return "<eof>";
    if (id == TOK_LINEFEED)
        return "\n";
    if (id >= 0 && id < 128) {
        char *b = buf[bi++ & 7];
        b[0] = id; b[1] = 0;
        return b;
    }
    return "<?>";
}

