    h = hash_str(s, len) % IDENT_HASH;
    for (p = ident_hash[h]; p; p = p->hnext)
        if (p->len == len && !memcmp(p->name, s, len))
            return p->id;
    p = xcalloc(sizeof(Ident));
    p->name = xstrndup(s, len);
    p->len = len;
    if (nb_idents >= idents_cap) {
        idents_cap = idents_cap ? idents_cap * 2 : 1024;
        idents = xrealloc(idents, idents_cap * sizeof(Ident *));
    }
    p->id = TOK_IDENT + nb_idents;
    idents[nb_idents++] = p;
    p->hnext = ident_hash[h];
    ident_hash[h] = p;
    return p->id;
}

void idents_init(void)
{
    int i;
    for (i = 0; i < (int)(sizeof(kw_names) / sizeof(kw_names[0])); i++)
        ident_lookup(kw_names[i], -1);
}

int is_ident_tok(int id) { return id >= TOK_IDENT; }

static const char *punct_names[] = {
    "->", "++", "--", "<<", ">>", "<=", ">=", "==", "!=", "&&", "||", "...", "##",
    "+=", "-=", "*=", "/=", "%=", "&=", "|=", "^=", "<<=", ">>=",
};

const char *tok_name(int id)
{
    static char buf[8][4];
    static int bi;
    if (id >= TOK_IDENT)
        return ident_get(id)->name;
    if (id >= TOK_ARROW && id <= TOK_A_SAR)
        return punct_names[id - TOK_ARROW];
    if (id == TOK_EOF)
        return "<eof>";
    if (id == TOK_LINEFEED)
        return "\n";
    if (id >= 0 && id < 128) {
        char *b = buf[bi++ & 7];
        b[0] = id; b[1] = 0;
        return b;
    }
    return "<?>";
}

const char *tok_spelling(const Tok *t)
{
    if (t->s)
        return t->s;
    return tok_name(t->id);
}

/* error handling */
State S;
jmp_buf error_jmp_buf;
int error_set_jmp_enabled;

static void print_file_context(void)
{
    /* print include chain */
    File *f;
    File *chain[INCLUDE_STACK_SIZE + 2];
    int n = 0, i;
    if (!file)
        return;
    for (f = file->prev; f; f = f->prev)
        chain[n++] = f;
    for (i = n - 1; i >= 0; i--)
        fprintf(stderr, "In file included from %s:%d:\n", chain[i]->filename, chain[i]->line_num);
    fprintf(stderr, "%s:%d: ", file->filename, file->line_num);
}

/* hook so that the parser can add "in function" context */
const char *(*error_func_context)(void);

static void error1(int is_warning, const char *fmt, va_list ap)
{
    if (file) {
        print_file_context();
    } else {
        fprintf(stderr, "tcc: ");
    }
    fprintf(stderr, is_warning ? "warning: " : "error: ");
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    fflush(stderr);
}

void tcc_error(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    error1(0, fmt, ap);
    va_end(ap);
    S.nb_errors++;
    if (error_set_jmp_enabled)
        longjmp(error_jmp_buf, 1);
    exit(1);
}

void tcc_error_noabort(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    error1(0, fmt, ap);
    va_end(ap);
    S.nb_errors++;
}

void tcc_warning(const char *fmt, ...)
{
    va_list ap;
    if (S.warn_none)
        return;
    va_start(ap, fmt);
    if (S.warn_error) {
        error1(0, fmt, ap);
        va_end(ap);
        S.nb_errors++;
        if (error_set_jmp_enabled)
            longjmp(error_jmp_buf, 1);
        exit(1);
    }
    error1(1, fmt, ap);
    va_end(ap);
    S.nb_warnings++;
}

/* warning controlled by flag: 0 = off, 1 = on, 2 = error */
void tcc_warning_c(int *flag, const char *fmt, ...)
{
    va_list ap;
    int f = *flag;
    if (S.warn_none || f == 0)
        return;
    va_start(ap, fmt);
    if (f == 2 || (S.warn_error && f != 3)) {
        error1(0, fmt, ap);
        va_end(ap);
        S.nb_errors++;
        if (error_set_jmp_enabled)
            longjmp(error_jmp_buf, 1);
        exit(1);
    }
    error1(1, fmt, ap);
    va_end(ap);
    S.nb_warnings++;
}

void tcc_fatal(const char *fmt, ...)
{
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "tcc: error: ");
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
    exit(1);
}
