    int len;
    char *data = read_whole_file(filename, &len);
    File *f;
    if (!data)
        return -1;
    f = new_file(filename, data);
    f->inc_idx = inc_idx;
    return 0;
}

void pp_close_file(void)
{
    File *f = file;
    if (!f)
        return;
    file = f->prev;
    free(f->data);
    free(f);
    tok_bol = 1;
}

const char *pp_cur_filename(void) { return file ? file->filename : ""; }
int pp_cur_line(void) { return file ? file->line_num : 0; }
int pp_include_depth(void)
{
    int n = 0;
    File *f;
    for (f = file; f; f = f->prev) n++;
    return n;
}

/* ---------------------------------------------------------------- */
/* character level: handle backslash-newline */

static inline void skip_splices(void)
{
    const char *p = file->p;
    for (;;) {
        if (p[0] == '\\') {
            if (p[1] == '\n') {
                p += 2;
                file->line_num++;
                continue;
            }
            if (p[1] == '\r' && p[2] == '\n') {
                p += 3;
                file->line_num++;
                continue;
            }
        }
        break;
    }
    file->p = p;
}

/* peek current char */
static inline int pc(void)
{
    skip_splices();
    return (unsigned char)*file->p;
}

static inline void adv(void)
{
    file->p++;
}

static inline int is_idstart(int c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' || c >= 0x80
        || (c == '$' && S.dollars_in_identifiers);
}
static inline int is_idchar(int c)
{
    return is_idstart(c) || (c >= '0' && c <= '9');
}
static inline int is_space_char(int c)
{
    return c == ' ' || c == '\t' || c == '\f' || c == '\v' || c == '\r';
}

/* ---------------------------------------------------------------- */
/* raw lexer */

static CStr lexbuf;

/* Scan the rest of a string/char literal starting after the opening quote.
   The whole token spelling (prefix + quotes) is accumulated in lexbuf. */
static void lex_string_rest(int quote)
{
    int c;
    for (;;) {
        c = pc();
        if (c == quote) {
            cstr_ccat(&lexbuf, c);
            adv();
            break;
        }
        if (c == '\n' || c == 0) {
            tcc_error("missing terminating %c character", quote);
        }
        if (c == '\\') {
            cstr_ccat(&lexbuf, c);
            adv();
            c = pc();
            if (c == 0 || c == '\n')
                tcc_error("missing terminating %c character", quote);
            cstr_ccat(&lexbuf, c);
            adv();
            continue;
        }
        cstr_ccat(&lexbuf, c);
        adv();
    }
}

static void lex_ppnum(int c)
{
    /* c is the first char (digit or '.') already known; accumulate */
    for (;;) {
        cstr_ccat(&lexbuf, c);
        adv();
        c = pc();
        if (c == 'e' || c == 'E' || c == 'p' || c == 'P') {
            const char *save = file->p;
            int saveline = file->line_num;
            cstr_ccat(&lexbuf, c);
            adv();
            c = pc();
            if (c == '+' || c == '-') {
                continue;
            }
            /* not a sign: just continue normally with c (already added e) */
            lexbuf.len--;  /* undo, re-add in loop */
            file->p = save;
            file->line_num = saveline;
            c = pc();
            if (!is_idchar(c) && c != '.')
                break;
            continue;
        }
        if (is_idchar(c) || c == '.')
            continue;
        break;
    }
    lexbuf.data[lexbuf.len] = 0;
}

/* Skip a C comment; file->p is after the opening "/*".  */
static void skip_comment(void)
{
    int c;
    for (;;) {
        c = pc();
        if (c == 0)
            tcc_error("unexpected end of file in comment");
        if (c == '*') {
            adv();
            if (pc() == '/') {
                adv();
                return;
            }
            continue;
        }
        if (c == '\n')
            file->line_num++;
        adv();
    }
}

static void skip_line_comment(void)
{
    int c;
    for (;;) {
        c = pc();
        if (c == '\n' || c == 0)
            return;
        adv();
    }
}

/* Read one raw token from the current file. Spaces are returned as ' '
   tokens (s = " " or "\t"), comments as ' '. Newline as TOK_LINEFEED. */
static void lex_raw(Tok *t)
{
    int c;
    t->s = NULL;
again:
    c = pc();
    switch (c) {
    case 0:
        t->id = TOK_EOF;
        return;
    case '\n':
        adv();
        file->line_num++;
        t->id = TOK_LINEFEED;
        return;
    case ' ': case '\t': case '\f': case '\v': case '\r':
        adv();
        t->id = ' ';
        t->s = c == '\t' ? "\t" : " ";
        return;
    case '/':
        adv();
        c = pc();
        if (c == '*') {
            adv();
            skip_comment();
            t->id = ' ';
            t->s = " ";
            return;
        }
        if (c == '/') {
            adv();
            skip_line_comment();
            goto again;
        }
        if (c == '=') { adv(); t->id = TOK_A_DIV; return; }
        t->id = '/';
        return;
    case '0': case '1': case '2': case '3': case '4':
    case '5': case '6': case '7': case '8': case '9':
        cstr_reset(&lexbuf);
        lex_ppnum(c);
        t->id = TOK_PPNUM;
        t->s = intern(lexbuf.data, lexbuf.len);
        return;
    case '.':
        adv();
        c = pc();
        if (c >= '0' && c <= '9') {
            cstr_reset(&lexbuf);
            cstr_ccat(&lexbuf, '.');
            lex_ppnum(c);
            t->id = TOK_PPNUM;
            t->s = intern(lexbuf.data, lexbuf.len);
            return;
        }
        if (c == '.') {
            const char *save = file->p;
            int saveline = file->line_num;
            adv();
            if (pc() == '.') {
                adv();
                t->id = TOK_DOTS;
                return;
            }
            file->p = save;
            file->line_num = saveline;
        }
        t->id = '.';
        return;
    case '"':
    case '\'':
        cstr_reset(&lexbuf);
        cstr_ccat(&lexbuf, c);
        adv();
        lex_string_rest(c);
        t->id = c == '"' ? TOK_STR : TOK_CHAR;
        t->s = intern(lexbuf.data, lexbuf.len);
        return;
    case '<':
        adv();
        c = pc();
        if (c == '<') {
            adv();
            if (pc() == '=') { adv(); t->id = TOK_A_SHL; return; }
            t->id = TOK_SHL;
            return;
        }
        if (c == '=') { adv(); t->id = TOK_LE; return; }
        t->id = '<';
        return;
    case '>':
        adv();
        c = pc();
        if (c == '>') {
            adv();
            if (pc() == '=') { adv(); t->id = TOK_A_SAR; return; }
            t->id = TOK_SAR;
            return;
        }
        if (c == '=') { adv(); t->id = TOK_GE; return; }
        t->id = '>';
        return;
    case '&':
        adv();
        c = pc();
        if (c == '&') { adv(); t->id = TOK_LAND; return; }
        if (c == '=') { adv(); t->id = TOK_A_AND; return; }
        t->id = '&';
        return;
    case '|':
        adv();
        c = pc();
        if (c == '|') { adv(); t->id = TOK_LOR; return; }
        if (c == '=') { adv(); t->id = TOK_A_OR; return; }
        t->id = '|';
        return;
    case '+':
        adv();
        c = pc();
        if (c == '+') { adv(); t->id = TOK_INC; return; }
        if (c == '=') { adv(); t->id = TOK_A_ADD; return; }
        t->id = '+';
        return;
    case '-':
        adv();
        c = pc();
        if (c == '-') { adv(); t->id = TOK_DEC; return; }
        if (c == '=') { adv(); t->id = TOK_A_SUB; return; }
        if (c == '>') { adv(); t->id = TOK_ARROW; return; }
        t->id = '-';
        return;
    case '*':
        adv();
        if (pc() == '=') { adv(); t->id = TOK_A_MUL; return; }
        t->id = '*';
        return;
    case '%':
        adv();
        if (pc() == '=') { adv(); t->id = TOK_A_MOD; return; }
        t->id = '%';
        return;
    case '^':
        adv();
        if (pc() == '=') { adv(); t->id = TOK_A_XOR; return; }
        t->id = '^';
        return;
    case '=':
        adv();
        if (pc() == '=') { adv(); t->id = TOK_EQ; return; }
        t->id = '=';
        return;
    case '!':
        adv();
        if (pc() == '=') { adv(); t->id = TOK_NE; return; }
        t->id = '!';
        return;
    case '#':
        adv();
        if (pc() == '#') { adv(); t->id = TOK_TWOSHARPS; return; }
        t->id = '#';
        return;
    case '(': case ')': case '[': case ']': case '{': case '}':
    case ',': case ';': case ':': case '?': case '~': case '@':
    case '\\':
        adv();
        t->id = c;
        return;
    default:
        if (is_idstart(c)) {
            const char *start;
            /* fast path: no splices inside */
            cstr_reset(&lexbuf);
            start = file->p;
            for (;;) {
                cstr_ccat(&lexbuf, c);
                adv();
                c = pc();
                if (!is_idchar(c))
                    break;
            }
            (void)start;
            /* wide string / char */
            if (lexbuf.len == 1 && lexbuf.data[0] == 'L' && (c == '"' || c == '\'')) {
                cstr_ccat(&lexbuf, c);
                adv();
                lex_string_rest(c);
                t->id = c == '"' ? TOK_STR : TOK_CHAR;
                t->s = intern(lexbuf.data, lexbuf.len);
                return;
            }
            t->id = ident_lookup(lexbuf.data, lexbuf.len);
            return;
        }
        if (c == '$') {
            /* dollars disabled */
            adv();
            tcc_error("unrecognized character \\x%02x", c);
        }
        adv();
        tcc_error("unrecognized character \\x%02x", c);
    }
}
