/* ---------------------------------------------------------------- */
/* hidesets */

typedef struct HS {
    int id;
    const struct HS *next;
} HS;

static char *hs_arena;
static int hs_arena_pos, hs_arena_cap;

static void hs_reset(void) { hs_arena_pos = 0; }

static HS *hs_new(int id, const HS *next)
{
    HS *h;
    if (hs_arena_pos + (int)sizeof(HS) > hs_arena_cap) {
        /* allocate a new arena block; old blocks are leaked until reset (we
           keep a simple list) */
        static PVec blocks;
        static int cur_block;
        if (hs_arena_pos == 0 || cur_block + 1 >= blocks.len) {
            hs_arena_cap = 1 << 20;
            hs_arena = xmalloc(hs_arena_cap);
            pvec_push(&blocks, hs_arena);
            cur_block = blocks.len - 1;
        } else {
            cur_block++;
            hs_arena = blocks.p[cur_block];
        }
        hs_arena_pos = 0;
    }
    h = (HS *)(hs_arena + hs_arena_pos);
    hs_arena_pos += sizeof(HS);
    h->id = id;
    h->next = next;
    return h;
}

static int hs_has(const HS *h, int id)
{
    for (; h; h = h->next) {
        if (h->id == id) return 1;
        if (h->id > id) return 0;
    }
    return 0;
}

static const HS *hs_add(const HS *h, int id)
{
    if (!h || h->id > id)
        return hs_new(id, h);
    if (h->id == id)
        return h;
    return hs_new(h->id, hs_add(h->next, id));
}

static const HS *hs_union(const HS *a, const HS *b)
{
    if (!a) return b;
    if (!b) return a;
    if (a->id == b->id) return hs_new(a->id, hs_union(a->next, b->next));
    if (a->id < b->id) return hs_new(a->id, hs_union(a->next, b));
    return hs_new(b->id, hs_union(a, b->next));
}

static const HS *hs_inter(const HS *a, const HS *b)
{
    while (a && b) {
        if (a->id == b->id) return hs_new(a->id, hs_inter(a->next, b->next));
        if (a->id < b->id) a = a->next; else b = b->next;
    }
    return NULL;
}

/* ---------------------------------------------------------------- */
/* token frames (results of macro expansion being re-read) */

typedef struct Frame {
    Tok *t;
    int len, pos;
    int barrier;     /* end-of-input barrier for isolated expansion */
    int owned;
} Frame;

static Frame *frames;
static int nframes, frames_cap;

static void push_frame(Tok *t, int len, int owned)
{
    Frame *f;
    if (nframes >= frames_cap) {
        frames_cap = frames_cap ? frames_cap * 2 : 64;
        frames = xrealloc(frames, frames_cap * sizeof(Frame));
    }
    f = &frames[nframes++];
    f->t = t;
    f->len = len;
    f->pos = 0;
    f->barrier = 0;
    f->owned = owned;
}

static void push_barrier(void)
{
    push_frame(NULL, 0, 0);
    frames[nframes - 1].barrier = 1;
}

static void pop_frame(void)
{
    Frame *f = &frames[--nframes];
    if (f->owned)
        free(f->t);
}

/* ---------------------------------------------------------------- */
/* directive processing forward decls */
static void preprocess_directive(void);
static int lex_token_level(Tok *t);

/* Read a raw token from the frames or the lexer. Frames are consumed first.
   Returns TOK_EOF at a barrier. Space tokens and linefeeds are returned. */
static void get_tok_raw(Tok *t)
{
    while (nframes > 0) {
        Frame *f = &frames[nframes - 1];
        if (f->barrier) {
            t->id = TOK_EOF;
            t->s = NULL;
            t->hs = NULL;
            return;
        }
        if (f->pos < f->len) {
            *t = f->t[f->pos++];
            return;
        }
        pop_frame();
    }
    if (nframes == 0)
        hs_reset();
    t->hs = NULL;
    lex_token_level(t);
}

/* lexer level with directive handling. Returns raw tokens incl. spaces/LF */
static int lex_token_level(Tok *t)
{
    for (;;) {
        lex_raw(t);
        if (t->id == TOK_LINEFEED) {
            tok_bol = 1;
            return 0;
        }
        if (t->id == ' ')
            return 0;
        if (t->id == '#' && tok_bol && !in_directive && !lex_no_directives
            && (parse_flags & PARSE_FLAG_PREPROCESS)) {
            tok_bol = 0;
            preprocess_directive();
            tok_bol = 1;
            /* directive consumed its line */
            if (pp_output_mode || (parse_flags & PARSE_FLAG_LINEFEED)) {
                /* behave as if a linefeed was seen (already counted) */
                continue;
            }
            continue;
        }
        if (t->id == TOK_EOF) {
            return 0;
        }
        tok_bol = 0;
        return 0;
    }
}

/* ---------------------------------------------------------------- */
/* macro expansion */

static int is_space_tok(int id) { return id == ' '; }

static void tv_push_tok(TokVec *v, const Tok *t)
{
    tv_push(v, t->id, t->s);
    v->t[v->len - 1].hs = t->hs;
}

/* normalize: collapse consecutive spaces, trim leading/trailing */
static void tv_normalize(TokVec *v)
{
    int i, j = 0;
    for (i = 0; i < v->len; i++) {
        if (v->t[i].id == TOK_PLACEHOLDER)
            continue;
        if (v->t[i].id == ' ') {
            if (j == 0 || v->t[j - 1].id == ' ')
                continue;
            v->t[j].id = ' ';
            v->t[j].s = " ";
            v->t[j].hs = NULL;
            j++;
            continue;
        }
        v->t[j++] = v->t[i];
    }
    while (j > 0 && v->t[j - 1].id == ' ')
        j--;
    v->len = j;
}

static int find_param(Macro *m, int id)
{
    int i;
    for (i = 0; i < m->nparams; i++)
        if (m->params[i] == id)
            return i;
    return -1;
}

/* stringify an argument token list */
static const char *stringify(Tok *t, int n)
{
    CStr cs;
    int i, prev_space = 1;
    cstr_init(&cs);
    cstr_ccat(&cs, '"');
    for (i = 0; i < n; i++) {
        const char *s;
        if (t[i].id == ' ' || t[i].id == TOK_LINEFEED) {
            if (!prev_space)
                cstr_ccat(&cs, ' ');
            prev_space = 1;
            continue;
        }
        if (t[i].id == TOK_PLACEHOLDER)
            continue;
        prev_space = 0;
        s = tok_spelling(&t[i]);
        if (t[i].id == TOK_STR || t[i].id == TOK_CHAR) {
            for (; *s; s++) {
                if (*s == '"' || *s == '\\')
                    cstr_ccat(&cs, '\\');
                cstr_ccat(&cs, *s);
            }
        } else
            cstr_cat(&cs, s, -1);
    }
    /* remove trailing space */
    while (cs.len > 1 && cs.data[cs.len - 1] == ' ')
        cs.len--;
    cstr_ccat(&cs, '"');
    s_ret: ;
    {
        const char *r = intern(cs.data, cs.len);
        cstr_free(&cs);
        return r;
    }
}

static void expand_list(Tok *in, int n, TokVec *out);
static void next_expanded(Tok *t);

/* paste two tokens; returns 1 on success and fills *r */
static int paste_tokens(const Tok *a, const Tok *b, Tok *r)
{
    CStr cs;
    char *data;
    File *save_file;
    int save_bol, save_flags, save_indir;
    Tok t1, t2;
    int ok;

    cstr_init(&cs);
    cstr_cat(&cs, tok_spelling(a), -1);
    cstr_cat(&cs, tok_spelling(b), -1);
    data = xstrdup(cs.data);
    cstr_free(&cs);

    /* lex from a temporary buffer */
    save_file = file;
    save_bol = tok_bol;
    save_indir = in_directive;
    save_flags = parse_flags;
    {
        File *f = xcalloc(sizeof(File));
        f->data = data;
        f->p = data;
        f->line_num = save_file ? save_file->line_num : 1;
        snprintf(f->filename, sizeof f->filename, "%s", save_file ? save_file->filename : "");
        f->prev = NULL;
        file = f;
    }
    in_directive = 1;
    lex_no_directives = 1;
    ok = 0;
    lex_raw(&t1);
    if (t1.id != TOK_EOF && t1.id != ' ' && t1.id != TOK_LINEFEED) {
        lex_raw(&t2);
        if (t2.id == TOK_EOF)
            ok = 1;
    }
    lex_no_directives = 0;
    free(file);
    file = save_file;
    tok_bol = save_bol;
    in_directive = save_indir;
    parse_flags = save_flags;
    if (ok) {
        r->id = t1.id;
        r->s = t1.s;
        r->hs = NULL;
    }
    free(data);
    return ok;
}

static int paste_fail_newline;

/* substitute arguments into macro body, handle # and ## */
static void subst_macro(Macro *m, TokVec *args, Tok **raw_args, int *raw_lens,
                        const HS *hs, TokVec *out)
{
    TokVec tmp;
    int i, n = m->body.len;
    Tok *body = m->body.t;
    memset(&tmp, 0, sizeof tmp);

    /* pass 1: parameter substitution */
    for (i = 0; i < n; i++) {
        Tok *t = &body[i];
        int pi;
        if (m->is_func && t->id == '#') {
            /* stringification: skip spaces, expect param */
            int j = i + 1;
            while (j < n && body[j].id == ' ') j++;
            if (j < n && (pi = find_param(m, body[j].id)) >= 0) {
                Tok st;
                st.id = TOK_STR;
                st.s = stringify(raw_args[pi], raw_lens[pi]);
                st.hs = NULL;
                tv_push_tok(&tmp, &st);
                i = j;
                continue;
            }
            tcc_error("macro parameter after '#' expected");
        }
        if (m->is_func && t->id == ',' && i + 1 < n && body[i + 1].id == TOK_TWOSHARPS) {
            /* GNU comma extension: , ## __VA_ARGS__ */
            int j = i + 2;
            while (j < n && body[j].id == ' ') j++;
            if (j < n && m->variadic && (pi = find_param(m, body[j].id)) == m->nparams - 1) {
                int empty = 1, k;
                for (k = 0; k < raw_lens[pi]; k++)
                    if (raw_args[pi][k].id != ' ') { empty = 0; break; }
                if (empty) {
                    i = j; /* drop ',' '##' spaces and param */
                    continue;
                }
                /* keep comma, drop '##' */
                tv_push_tok(&tmp, t);
                i = i + 1;
                continue;
            }
        }
        if (m->is_func && t->id >= TOK_IDENT && (pi = find_param(m, t->id)) >= 0) {
            /* operand of ## ? */
            int before = 0, after = 0, j;
            j = i - 1;
            while (j >= 0 && body[j].id == ' ') j--;
            if (j >= 0 && body[j].id == TOK_TWOSHARPS) before = 1;
            j = i + 1;
            while (j < n && body[j].id == ' ') j++;
            if (j < n && body[j].id == TOK_TWOSHARPS) after = 1;
            if (before || after) {
                int k, nonsp = 0;
                for (k = 0; k < raw_lens[pi]; k++)
                    if (raw_args[pi][k].id != ' ') nonsp = 1;
                if (!nonsp) {
                    Tok ph = { TOK_PLACEHOLDER, NULL, NULL };
                    tv_push_tok(&tmp, &ph);
                } else {
                    /* raw arg, trimmed */
                    int s = 0, e = raw_lens[pi];
                    while (s < e && raw_args[pi][s].id == ' ') s++;
                    while (e > s && raw_args[pi][e - 1].id == ' ') e--;
                    for (k = s; k < e; k++)
                        tv_push_tok(&tmp, &raw_args[pi][k]);
                }
            } else {
                int k;
                if (args[pi].len == 0) {
                    /* empty expanded arg: nothing */
                } else {
                    for (k = 0; k < args[pi].len; k++)
                        tv_push_tok(&tmp, &args[pi].t[k]);
                }
            }
            continue;
        }
        tv_push_tok(&tmp, t);
    }

    /* pass 2: handle ## */
    {
        TokVec res;
        memset(&res, 0, sizeof res);
        for (i = 0; i < tmp.len; i++) {
            Tok *t = &tmp.t[i];
            if (t->id == TOK_TWOSHARPS) {
                int j = i + 1;
                Tok *left, right, pasted;
                while (j < tmp.len && tmp.t[j].id == ' ') j++;
                /* left operand: last token in res (skip trailing spaces) */
                while (res.len > 0 && res.t[res.len - 1].id == ' ') res.len--;
                if (res.len == 0) {
                    /* nothing on left (should not happen) */
                    i = j - 1;
                    continue;
                }
                left = &res.t[res.len - 1];
                if (j >= tmp.len) {
                    i = j - 1;
                    continue;
                }
                right = tmp.t[j];
                if (left->id == TOK_PLACEHOLDER) {
                    *left = right;
                } else if (right.id == TOK_PLACEHOLDER) {
                    /* keep left */
                } else if (paste_tokens(left, &right, &pasted)) {
                    *left = pasted;
                } else {
                    /* invalid paste: keep both separated by a space */
                    Tok lc = *left;
                    const char *ls = tok_spelling(&lc), *rs = tok_spelling(&right);
                    if (pp_output_mode && S.ppfp)
                        fputs("\n", S.ppfp);
                    tcc_warning("pasting \"%s\" and \"%s\" does not give a valid preprocessing token", ls, rs);
                    {
                        Tok sp = { ' ', " ", NULL };
                        tv_push_tok(&res, &sp);
                    }
                    tv_push_tok(&res, &right);
                }
                i = j;
                continue;
            }
            tv_push_tok(&res, t);
        }
        tv_free(&tmp);
        tmp = res;
    }

    /* remove placeholders, normalize spaces, apply hideset */
    tv_normalize(&tmp);
    for (i = 0; i < tmp.len; i++) {
        Tok *t = &tmp.t[i];
        t->hs = hs_union(t->hs, hs);
        tv_push_tok(out, t);
    }
    tv_free(&tmp);
}

/* read macro arguments; the '(' has been consumed. Returns the ')' token */
static void collect_args(Macro *m, TokVec **praw, int *nargs_out, Tok *rparen)
{
    TokVec *raw;
    int nargs = 0, depth = 0, cap = m->nparams + 1;
    Tok t;
    int seen_any = 0;
    raw = xcalloc(sizeof(TokVec) * (cap + 1));
    for (;;) {
        get_tok_raw(&t);
        if (t.id == TOK_EOF) {
            tcc_error("EOF in invocation of macro '%s'", tok_name(m->id));
        }
        if (t.id == TOK_LINEFEED) {
            t.id = ' ';
            t.s = " ";
        }
        if (depth == 0 && t.id == ')') {
            *rparen = t;
            break;
        }
        if (depth == 0 && t.id == ',' && !(m->variadic && nargs == m->nparams - 1)) {
            nargs++;
            if (nargs >= cap) {
                /* too many args; keep collecting to find the end, but error later */
                cap = nargs + 1;
                raw = xrealloc(raw, sizeof(TokVec) * (cap + 1));
                memset(&raw[nargs], 0, sizeof(TokVec));
            }
            seen_any = 1;
            continue;
        }
        if (t.id == '(') depth++;
        if (t.id == ')') depth--;
        if (nargs >= cap) {
            cap = nargs + 1;
            raw = xrealloc(raw, sizeof(TokVec) * (cap + 1));
            memset(&raw[nargs], 0, sizeof(TokVec));
        }
        tv_push_tok(&raw[nargs], &t);
        if (t.id != ' ')
            seen_any = 1;
    }
    /* number of args: nargs+1 unless no tokens at all and macro has 0 params */
    {
        int total = nargs + 1;
        int nonsp = 0, k;
        for (k = 0; k < raw[0].len; k++) if (raw[0].t[k].id != ' ') nonsp = 1;
        if (nargs == 0 && !nonsp && m->nparams == 0)
            total = 0;
        if (nargs == 0 && !nonsp && m->nparams == 1 && m->variadic)
            total = 1;
        if (total > m->nparams)
            tcc_error("macro '%s' used with too many args", tok_name(m->id));
        if (total < m->nparams) {
            if (!(m->variadic && total == m->nparams - 1))
                tcc_error("macro '%s' used with too few args", tok_name(m->id));
        }
        *nargs_out = total;
    }
    (void)seen_any;
    *praw = raw;
}

/* builtin macros */
static int builtin_macro(Tok *t, TokVec *out)
{
    char buf[64];
    Tok r;
    r.hs = NULL;
    switch (t->id) {
    case TOK___LINE__:
        snprintf(buf, sizeof buf, "%d", file->line_num);
        r.id = TOK_PPNUM;
        r.s = intern(buf, -1);
        break;
    case TOK___FILE__: {
        CStr cs;
        const char *p;
        cstr_init(&cs);
        cstr_ccat(&cs, '"');
        for (p = file->filename; *p; p++) {
            if (*p == '"' || *p == '\\') cstr_ccat(&cs, '\\');
            cstr_ccat(&cs, *p);
        }
        cstr_ccat(&cs, '"');
        r.id = TOK_STR;
        r.s = intern(cs.data, cs.len);
        cstr_free(&cs);
        break;
    }
    case TOK___COUNTER__:
        snprintf(buf, sizeof buf, "%d", pp_counter++);
        r.id = TOK_PPNUM;
        r.s = intern(buf, -1);
        break;
    case TOK___DATE__:
    case TOK___TIME__: {
        time_t ti;
        struct tm *tm;
        static const char *months[] = { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
            "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
        time(&ti);
        tm = localtime(&ti);
        if (t->id == TOK___DATE__)
            snprintf(buf, sizeof buf, "\"%s %2d %d\"", months[tm->tm_mon], tm->tm_mday, tm->tm_year + 1900);
        else
            snprintf(buf, sizeof buf, "\"%02d:%02d:%02d\"", tm->tm_hour, tm->tm_min, tm->tm_sec);
        r.id = TOK_STR;
        r.s = intern(buf, -1);
        break;
    }
    default:
        return 0;
    }
    tv_push_tok(out, &r);
    return 1;
}

/* Try to expand the macro for identifier token t. Returns 1 if an expansion
   frame was pushed (caller should loop), 0 if token is to be returned as is. */
static int try_expand(Tok *t)
{
    Ident *id;
    Macro *m;
    TokVec out;

    if (t->id < TOK_IDENT)
        return 0;
    if (pp_defined_state > 0) {
        if (t->id != ' ') pp_defined_state--;
        return 0;
    }
    if (pp_expr_mode && t->id == TOK_DEFINED) {
        pp_defined_state = 1; /* following ident (or '(' ident ')') raw */
        return 0;
    }
    if (t->id == TOK___LINE__ || t->id == TOK___FILE__ || t->id == TOK___COUNTER__
        || t->id == TOK___DATE__ || t->id == TOK___TIME__) {
        if (!ident_get(t->id)->mac) {
            memset(&out, 0, sizeof out);
            builtin_macro(t, &out);
            push_frame(out.t, out.len, 1);
            return 1;
        }
    }
    id = ident_get(t->id);
    m = id->mac;
    if (!m)
        return 0;
    if (hs_has(t->hs, t->id))
        return 0;
    memset(&out, 0, sizeof out);
    if (!m->is_func) {
        const HS *hs = hs_add(t->hs, m->id);
        subst_macro(m, NULL, NULL, NULL, hs, &out);
    } else {
        /* look ahead for '(' */
        TokVec skipped;
        Tok nt;
        Tok rparen;
        TokVec *raw;
        int nargs, i;
        TokVec *args;
        Tok **raw_ptrs;
        int *raw_lens;
        const HS *hs;

        memset(&skipped, 0, sizeof skipped);
        for (;;) {
            get_tok_raw(&nt);
            if (nt.id == ' ' || nt.id == TOK_LINEFEED) {
                tv_push_tok(&skipped, &nt);
                continue;
            }
            break;
        }
        if (nt.id != '(') {
            /* push back */
            if (nt.id != TOK_EOF || nframes == 0 || !frames[nframes - 1].barrier)
                tv_push_tok(&skipped, &nt);
            else {
                /* EOF from barrier: do not push it back */
            }
            if (skipped.len)
                push_frame(skipped.t, skipped.len, 1);
            else
                tv_free(&skipped);
            return 0;
        }
        tv_free(&skipped);
        collect_args(m, &raw, &nargs, &rparen);
        args = xcalloc(sizeof(TokVec) * (m->nparams + 1));
        raw_ptrs = xcalloc(sizeof(Tok *) * (m->nparams + 1));
        raw_lens = xcalloc(sizeof(int) * (m->nparams + 1));
        for (i = 0; i < m->nparams; i++) {
            if (i < nargs) {
                raw_ptrs[i] = raw[i].t;
                raw_lens[i] = raw[i].len;
            } else {
                raw_ptrs[i] = NULL;
                raw_lens[i] = 0;
            }
        }
        /* pre-expand args that are used without # / ## */
        for (i = 0; i < m->nparams; i++) {
            int used_plain = 0, j;
            Tok *body = m->body.t;
            for (j = 0; j < m->body.len; j++) {
                if (body[j].id == m->params[i]) {
                    int before = 0, after = 0, k;
                    k = j - 1;
                    while (k >= 0 && body[k].id == ' ') k--;
                    if (k >= 0 && (body[k].id == TOK_TWOSHARPS || body[k].id == '#')) before = 1;
                    k = j + 1;
                    while (k < m->body.len && body[k].id == ' ') k++;
                    if (k < m->body.len && body[k].id == TOK_TWOSHARPS) after = 1;
                    if (!before && !after) { used_plain = 1; break; }
                }
            }
            if (used_plain && raw_lens[i] > 0)
                expand_list(raw_ptrs[i], raw_lens[i], &args[i]);
            tv_normalize(&args[i]);
        }
        hs = hs_add(hs_inter(t->hs, rparen.hs), m->id);
        subst_macro(m, args, raw_ptrs, raw_lens, hs, &out);
        for (i = 0; i < m->nparams; i++)
            tv_free(&args[i]);
        for (i = 0; i <= nargs && i < m->nparams + 1; i++)
            tv_free(&raw[i]);
        free(raw);
        free(args);
        free(raw_ptrs);
        free(raw_lens);
    }
    if (out.len == 0) {
        tv_free(&out);
        /* expansion to nothing: still need to loop */
        push_frame(NULL, 0, 0);
        return 1;
    }
    push_frame(out.t, out.len, 1);
    return 1;
}

/* get next token with macro expansion (raw spaces/LF included) */
static void next_expanded(Tok *t)
{
    for (;;) {
        get_tok_raw(t);
        if (t->id >= TOK_IDENT && try_expand(t))
            continue;
        if (t->id < TOK_IDENT && pp_defined_state > 0 && t->id != ' ')
            pp_defined_state--;
        return;
    }
}

/* expand a token list in isolation */
static void expand_list(Tok *in, int n, TokVec *out)
{
    Tok t;
    Tok *copy = xmalloc(sizeof(Tok) * (n ? n : 1));
    memcpy(copy, in, sizeof(Tok) * n);
    push_barrier();
    push_frame(copy, n, 1);
    for (;;) {
        next_expanded(&t);
        if (t.id == TOK_EOF)
            break;
        if (t.id == TOK_LINEFEED) { t.id = ' '; t.s = " "; }
        tv_push_tok(out, &t);
    }
    /* pop until barrier removed */
    while (nframes > 0) {
        int b = frames[nframes - 1].barrier;
        pop_frame();
        if (b) break;
    }
}
