/* ---------------------------------------------------------------- */
/* directive helpers */

/* read next raw token in directive, skipping spaces */
static void dir_next(Tok *t)
{
    for (;;) {
        lex_raw(t);
        if (t->id == ' ')
            continue;
        if (t->id == TOK_EOF) {
            t->id = TOK_LINEFEED;
        }
        return;
    }
}

/* skip to end of directive line; warn if extra tokens */
static void dir_end(int warn)
{
    Tok t;
    int extra = 0;
    for (;;) {
        lex_raw(&t);
        if (t.id == TOK_EOF)
            break;
        if (t.id == TOK_LINEFEED) {
            break;
        }
        if (t.id != ' ')
            extra = 1;
    }
    if (extra && warn)
        tcc_warning("extra tokens after directive");
}

/* skip the rest of the line without tokenizing errors (for #error etc.);
   returns raw text (comments kept) */
static void dir_rest_raw(CStr *cs)
{
    int c;
    cstr_reset(cs);
    /* skip leading spaces */
    for (;;) {
        c = pc();
        if (is_space_char(c)) { adv(); continue; }
        break;
    }
    for (;;) {
        c = pc();
        if (c == '\n' || c == 0)
            break;
        cstr_ccat(cs, c);
        adv();
    }
    if (c == '\n') {
        adv();
        file->line_num++;
    }
}

/* ---------------------------------------------------------------- */
/* #if expression evaluation */

typedef struct PPVal { int64_t v; int uns; } PPVal;

static Tok *ex_toks;
static int ex_n, ex_pos;
static const char *ex_dirname;
static int ex_err;

static void pp_expr_error(void)
{
    CStr cs;
    int i;
    cstr_init(&cs);
    cstr_printf(&cs, "#%s", ex_dirname);
    for (i = 0; i < ex_n; i++) {
        cstr_ccat(&cs, ' ');
        cstr_cat(&cs, tok_spelling(&ex_toks[i]), -1);
    }
    tcc_error("bad preprocessor expression: %s", cs.data);
}

static int ex_peek(void) { return ex_pos < ex_n ? ex_toks[ex_pos].id : TOK_EOF; }
static void ex_adv(void) { ex_pos++; }

/* parse integer constant spelling; returns 0 if invalid */
int parse_int_const(const char *s, uint64_t *pv, int *puns, int *plonglong, int for_pp);

static PPVal pp_ternary(void);

static PPVal pp_unary(void)
{
    PPVal r;
    int t = ex_peek();
    switch (t) {
    case '+': ex_adv(); r = pp_unary(); return r;
    case '-': ex_adv(); r = pp_unary(); r.v = -(uint64_t)r.v; return r;
    case '~': ex_adv(); r = pp_unary(); r.v = ~r.v; return r;
    case '!': ex_adv(); r = pp_unary(); r.v = !r.v; r.uns = 0; return r;
    case '(':
        ex_adv();
        r = pp_ternary();
        if (ex_peek() != ')')
            pp_expr_error();
        ex_adv();
        return r;
    case TOK_PPNUM: {
        uint64_t v; int uns, ll;
        if (!parse_int_const(ex_toks[ex_pos].s, &v, &uns, &ll, 1))
            tcc_error("invalid constant in preprocessor expression");
        ex_adv();
        r.v = v; r.uns = uns;
        return r;
    }
    case TOK_CHAR: {
        int64_t v; int wide, nb;
        parse_char_const(ex_toks[ex_pos].s, &v, &wide, &nb);
        ex_adv();
        r.v = v; r.uns = 0;
        return r;
    }
    case TOK_STR:
        tcc_error("invalid constant in preprocessor expression");
    default:
        if (t >= TOK_IDENT) {
            /* undefined identifier -> 0 (already replaced) */
            ex_adv();
            r.v = 0; r.uns = 0;
            return r;
        }
        pp_expr_error();
    }
    return r;
}

static int pp_prec(int t)
{
    switch (t) {
    case '*': case '/': case '%': return 10;
    case '+': case '-': return 9;
    case TOK_SHL: case TOK_SAR: return 8;
    case '<': case '>': case TOK_LE: case TOK_GE: return 7;
    case TOK_EQ: case TOK_NE: return 6;
    case '&': return 5;
    case '^': return 4;
    case '|': return 3;
    case TOK_LAND: return 2;
    case TOK_LOR: return 1;
    }
    return 0;
}

static PPVal pp_binary(int minprec)
{
    PPVal l = pp_unary();
    for (;;) {
        int op = ex_peek();
        int p = pp_prec(op);
        PPVal r;
        if (p == 0 || p < minprec)
            return l;
        ex_adv();
        r = pp_binary(p + 1);
        if (op == TOK_LAND) { l.v = l.v && r.v; l.uns = 0; continue; }
        if (op == TOK_LOR) { l.v = l.v || r.v; l.uns = 0; continue; }
        {
            int uns = l.uns || r.uns;
            uint64_t a = l.v, b = r.v;
            switch (op) {
            case '*': l.v = a * b; break;
            case '/':
                if (b == 0) pp_expr_error();
                l.v = uns ? (int64_t)(a / b) : (l.v == INT64_MIN && r.v == -1 ? l.v : l.v / r.v);
                break;
            case '%':
                if (b == 0) pp_expr_error();
                l.v = uns ? (int64_t)(a % b) : (r.v == -1 ? 0 : l.v % r.v);
                break;
            case '+': l.v = a + b; break;
            case '-': l.v = a - b; break;
            case TOK_SHL: l.v = (int64_t)(a << (b & 63)); break;
            case TOK_SAR: l.v = uns ? (int64_t)(a >> (b & 63)) : (l.v >> (b & 63)); break;
            case '<': l.v = uns ? a < b : l.v < r.v; uns = 0; break;
            case '>': l.v = uns ? a > b : l.v > r.v; uns = 0; break;
            case TOK_LE: l.v = uns ? a <= b : l.v <= r.v; uns = 0; break;
            case TOK_GE: l.v = uns ? a >= b : l.v >= r.v; uns = 0; break;
            case TOK_EQ: l.v = a == b; uns = 0; break;
            case TOK_NE: l.v = a != b; uns = 0; break;
            case '&': l.v = a & b; break;
            case '^': l.v = a ^ b; break;
            case '|': l.v = a | b; break;
            }
            l.uns = uns;
        }
    }
}

static PPVal pp_ternary(void)
{
    PPVal c = pp_binary(1);
    if (ex_peek() == '?') {
        PPVal a, b;
        ex_adv();
        if (ex_peek() == ':') {
