            a = c;
        } else
            a = pp_ternary();
        if (ex_peek() != ':')
            pp_expr_error();
        ex_adv();
        b = pp_ternary();
        if (c.v) { a.uns = a.uns || b.uns; return a; }
        b.uns = a.uns || b.uns;
        return b;
    }
    return c;
}

