/* ---------------------------------------------------------------- */
/* numeric / char / string constant parsing */

/* Parse an integer constant. Returns 0 if not a valid integer (e.g. float).
   Emits errors for malformed numbers. */
int parse_int_const(const char *s, uint64_t *pv, int *puns, int *plonglong, int for_pp)
{
    const char *p = s;
    int base = 10;
    uint64_t v = 0;
    int uns = 0, nl = 0, overflow = 0;
    int ndig = 0;
    const char *digits_start;
    uint64_t trunc_val = 0;
    int trunc_set = 0;

    /* detect float: contains '.' or (not hex and contains e/E) or (hex and p/P) */
    if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) {
        base = 16;
        p += 2;
    } else if (p[0] == '0' && (p[1] == 'b' || p[1] == 'B')) {
        base = 2;
        p += 2;
    } else if (p[0] == '0' && p[1] >= '0' && p[1] <= '9') {
        base = 8;
        p += 1;
    }
    {
        const char *q;
        for (q = s; *q; q++) {
            if (*q == '.')
                return 0;
            if (base == 16) {
                if (*q == 'p' || *q == 'P')
                    return 0;
            } else if (base != 2 && (*q == 'e' || *q == 'E')) {
                /* decimal/octal float with exponent */
                return 0;
            }
        }
    }
    digits_start = p;
    for (;;) {
        int c = *p, d;
        if (c >= '0' && c <= '9') d = c - '0';
        else if (c >= 'a' && c <= 'f') d = c - 'a' + 10;
        else if (c >= 'A' && c <= 'F') d = c - 'A' + 10;
        else break;
        if (d >= base) {
            if (base == 8 || base == 2) {
                if (c >= '0' && c <= '9')
                    tcc_error("invalid digit");
            }
            break;
        }
        {
            uint64_t nv = v * base + d;
            if (!overflow && (v > (UINT64_MAX - d) / base)) {
                overflow = 1;
                trunc_val = v;
                trunc_set = 1;
            }
            v = nv;
        }
        ndig++;
        p++;
    }
    (void)digits_start;
    /* suffixes */
    for (;;) {
        int c = *p;
        if (c == 'u' || c == 'U') {
            if (uns)
                tcc_error("two 'u's in integer constant");
            uns = 1;
            p++;
        } else if (c == 'l' || c == 'L') {
            nl++;
            p++;
            if (*p == c) { p++; nl++; }
        } else
