    } else {
        /* C rules: int, unsigned, long, unsigned long */
        int is_ll = 0, is_u = uns;
        if (nl == 0) {
            if (uns) {
                if (v > 0xffffffffULL) is_ll = 1;
            } else {
                if (v <= 0x7fffffffULL) ;
                else if (base != 10 && v <= 0xffffffffULL) is_u = 1;
                else if (v <= 0x7fffffffffffffffULL) is_ll = 1;
                else { is_ll = 1; is_u = 1; }
            }
