int parse_char_const(const char *s, int64_t *val, int *is_wide, int *nb)
{
    int wide = 0;
    const char *p = s;
    int64_t v = 0;
    int n = 0;
    if (*p == 'L') { wide = 1; p++; }
    p++;
    while (*p && *p != '\'') {
