        const char *q;
        for (q = s; *q; q++) {
            if (*q == '.')
                return 0;
            if (base == 16) {
                if (*q == 'p' || *q == 'P')
                    return 0;
            } else if (base != 2 && (*q == 'e' || *q == 'E')) {
                /* decimal/octal float with exponent */
                return 0;
            }
        }
