/* ---------------------------------------------------------------- */
/* include path search */

static PVec pragma_once_files;  /* char* canonical names */

static int file_exists(const char *name)
{
    struct stat st;
    if (stat(name, &st) < 0)
        return 0;
    return 1;
}

static void path_dirname(const char *name, char *out, int outsz)
{
    const char *p = strrchr(name, '/');
    if (!p) {
        out[0] = 0;
        return;
    }
    snprintf(out, outsz, "%.*s", (int)(p - name + 1), name);
}

/* Search include file. Returns 1 if found; fills out with the path and
   *pidx with the index of the search path used (-1 for the current dir). */
int pp_search_include(const char *name, int angle, int is_next, char *out, int outsz, int *pidx)
{
    int i, start = 0, n;
    int total = S.include_paths.len + S.sysinclude_paths.len;
    if (name[0] == '/') {
        snprintf(out, outsz, "%s", name);
        *pidx = -1;
        return file_exists(out);
    }
    if (is_next) {
        start = file->inc_idx + 1;
    } else if (!angle) {
        char dir[1024];
        path_dirname(file->filename, dir, sizeof dir);
        snprintf(out, outsz, "%s%s", dir, name);
        if (file_exists(out)) {
            *pidx = -1;
            return 1;
        }
    }
    n = total;
    for (i = start; i < n; i++) {
        const char *dir = i < S.include_paths.len ? S.include_paths.p[i]
            : S.sysinclude_paths.p[i - S.include_paths.len];
        snprintf(out, outsz, "%s/%s", dir, name);
        if (file_exists(out)) {
            *pidx = i;
            return 1;
        }
    }
    return 0;
}

void pp_add_dep(const char *name)
{
    int i;
    for (i = 0; i < S.target_deps.len; i++)
        if (!strcmp(S.target_deps.p[i], name))
            return;
    pvec_push(&S.target_deps, xstrdup(name));
}

static int is_pragma_once(const char *path)
{
    int i;
    for (i = 0; i < pragma_once_files.len; i++)
        if (!strcmp(pragma_once_files.p[i], path))
            return 1;
    return 0;
}

/* ---------------------------------------------------------------- */
/* skipping of false conditional groups */

static int skip_saw_directive;

/* skip rest of current line in skip mode (raw), handling comments */
static void skip_line_raw(int in_warn)
{
    int c;
    for (;;) {
        c = pc();
        if (c == 0)
            return;
        if (c == '\n') {
            adv();
            file->line_num++;
            return;
        }
        if (!in_warn && (c == '"' || c == '\'')) {
            int q = c;
            adv();
            for (;;) {
                c = pc();
                if (c == 0 || c == '\n')
                    break;
                if (c == '\\') {
                    adv();
                    c = pc();
                    if (c == 0 || c == '\n')
                        break;
                    adv();
                    continue;
                }
                adv();
                if (c == q)
                    break;
            }
            continue;
        }
        if (!in_warn && c == '/') {
            adv();
            c = pc();
            if (c == '*') {
                adv();
                skip_comment();
            } else if (c == '/') {
                adv();
                skip_line_comment();
            }
            continue;
        }
        adv();
    }
}

static void eof_in_skip(void)
{
    file->line_num--;
    if (skip_saw_directive)
        file->line_num++;
    tcc_error("#endif expected");
}

/* Called when the current group of the top ifstack entry must be skipped.
   Returns when a group to be processed begins, or after #endif. */
static void skip_group(void)
{
    int depth = 0;
    Tok t;
    IfState *st = &ifstack[ifsp - 1];
    skip_saw_directive = 0;
    for (;;) {
        int c;
        /* at start of line */
        for (;;) {
            c = pc();
            if (is_space_char(c)) { adv(); continue; }
            break;
        }
        if (c == 0) {
            eof_in_skip();
        }
        if (c == '\n') {
            adv();
            file->line_num++;
            continue;
        }
        if (c == '/') {
            /* comment at line start */
            const char *save = file->p;
            int saveline = file->line_num;
            adv();
            c = pc();
            if (c == '*') {
                adv();
                skip_comment();
                /* stay on this logical line: continue scanning from here */
                /* a directive after a comment is still allowed in tcc? no: treat rest as text */
                skip_line_raw(0);
                continue;
            }
            if (c == '/') {
                adv();
                skip_line_comment();
                continue;
            }
            file->p = save;
            file->line_num = saveline;
            skip_line_raw(0);
            continue;
        }
        if (c != '#') {
            skip_line_raw(0);
            continue;
        }
        adv();
        /* directive */
        in_directive = 1;
        dir_next(&t);
        in_directive = 0;
        if (t.id == TOK_LINEFEED) {
            /* bare '#': line consumed if LINEFEED token consumed it */
            continue;
        }
        skip_saw_directive = 1;
        if (t.id == TOK_IF || t.id == TOK_IFDEF || t.id == TOK_IFNDEF) {
            depth++;
            skip_line_raw(0);
            continue;
        }
        if (t.id == TOK_ENDIF) {
            if (depth == 0) {
                dir_end(1);
                ifsp--;
                return;
            }
            depth--;
            skip_line_raw(0);
            continue;
        }
        if (t.id == TOK_ELSE) {
            if (depth == 0) {
                if (st->seen_else)
                    tcc_error("#else after #else");
                st->seen_else = 1;
                dir_end(1);
                if (!st->any_taken) {
                    st->taking = st->any_taken = 1;
                    return;
                }
                continue;
            }
            skip_line_raw(0);
            continue;
        }
        if (t.id == TOK_ELIF) {
            if (depth == 0) {
                if (st->seen_else)
                    tcc_error("#elif after #else");
                if (!st->any_taken) {
                    int r = eval_if_expr("elif");
                    if (r) {
                        st->taking = st->any_taken = 1;
                        return;
                    }
                } else
                    skip_line_raw(0);
                continue;
            }
            skip_line_raw(0);
            continue;
        }
        if (t.id == TOK_ERROR || t.id == TOK_WARNING) {
            skip_line_raw(1);
            continue;
        }
        skip_line_raw(0);
    }
}

/* ---------------------------------------------------------------- */
/* #define */

static void free_macro(Macro *m)
{
    if (!m) return;
    free(m->params);
    tv_free(&m->body);
    free(m);
}

static int macro_equal(Macro *a, Macro *b)
{
    int i;
    if (a->is_func != b->is_func || a->nparams != b->nparams || a->variadic != b->variadic)
        return 0;
    for (i = 0; i < a->nparams; i++)
        if (a->params[i] != b->params[i])
            return 0;
    if (a->body.len != b->body.len)
        return 0;
    for (i = 0; i < a->body.len; i++) {
        if (a->body.t[i].id != b->body.t[i].id)
            return 0;
        if (a->body.t[i].s != b->body.t[i].s) {
            if (!a->body.t[i].s || !b->body.t[i].s || strcmp(a->body.t[i].s, b->body.t[i].s))
                return 0;
        }
    }
    return 1;
}

static void define_macro(Macro *m)
{
    Ident *id = ident_get(m->id);
    if (id->mac) {
        if (!macro_equal(id->mac, m))
            tcc_warning("%s redefined", id->name);
        free_macro(id->mac);
    }
    id->mac = m;
}

static void undef_macro(int id)
{
    Ident *i = ident_get(id);
    if (i->mac) {
        free_macro(i->mac);
        i->mac = NULL;
    }
}

static void parse_define(void)
{
    Tok t;
    Macro *m;
    int c;
    in_directive = 1;
    dir_next(&t);
    if (t.id < TOK_IDENT) {
        tcc_error("invalid macro name '%s'", tok_spelling(&t));
    }
    if (t.id == TOK_DEFINED)
        tcc_error("invalid macro name 'defined'");
    m = xcalloc(sizeof(Macro));
    m->id = t.id;
    /* function-like if '(' immediately follows */
    c = pc();
    if (c == '(') {
        int cap = 0;
        adv();
        m->is_func = 1;
        for (;;) {
            dir_next(&t);
            if (t.id == ')' && m->nparams == 0)
                break;
            if (t.id == TOK_DOTS) {
                if (m->nparams >= cap) { cap = cap ? cap * 2 : 4; m->params = xrealloc(m->params, cap * sizeof(int)); }
                m->params[m->nparams++] = TOK___VA_ARGS__;
                m->variadic = 1;
                dir_next(&t);
                if (t.id != ')')
                    tcc_error("bad macro parameter list");
                break;
            }
            if (t.id < TOK_IDENT)
                tcc_error("bad macro parameter list");
            if (m->nparams >= cap) { cap = cap ? cap * 2 : 4; m->params = xrealloc(m->params, cap * sizeof(int)); }
            m->params[m->nparams++] = t.id;
            dir_next(&t);
            if (t.id == TOK_DOTS) {
                m->variadic = 1;
                dir_next(&t);
                if (t.id != ')')
                    tcc_error("bad macro parameter list");
                break;
            }
            if (t.id == ')')
                break;
            if (t.id != ',')
                tcc_error("bad macro parameter list");
        }
    }
    /* body */
    {
        int spc = 1; /* at start: skip spaces */
        for (;;) {
            lex_raw(&t);
            if (t.id == TOK_LINEFEED || t.id == TOK_EOF)
                break;
            if (t.id == ' ') {
                if (spc)
                    continue;
                spc = 1;
                tv_push(&m->body, ' ', " ");
                continue;
            }
            if (t.id == TOK_TWOSHARPS) {
                /* remove spaces before ## */
                while (m->body.len > 0 && m->body.t[m->body.len - 1].id == ' ')
                    m->body.len--;
            }
            spc = 0;
            tv_push_tok(&m->body, &t);
        }
        while (m->body.len > 0 && m->body.t[m->body.len - 1].id == ' ')
            m->body.len--;
        if (m->body.len > 0 && (m->body.t[0].id == TOK_TWOSHARPS
                                || m->body.t[m->body.len - 1].id == TOK_TWOSHARPS))
            tcc_error("'##' cannot appear at either end of macro");
    }
    in_directive = 0;
    define_macro(m);
    pp_debug_tok = TOK_DEFINE;
    pp_debug_symv = m->id;
}

/* print macro definition (for -dD/-dM) */
static void define_print(FILE *fp, int id)
{
    Ident *ident = ident_get(id);
    Macro *m = ident->mac;
    int i;
    if (!m)
        return;
    fprintf(fp, "#define %s", ident->name);
    if (m->is_func) {
        fputc('(', fp);
        for (i = 0; i < m->nparams; i++) {
            if (i) fputc(',', fp);
            fputs(tok_name(m->params[i]), fp);
        }
        fputc(')', fp);
    }
    if (m->body.len) {
        fputc(' ', fp);
        for (i = 0; i < m->body.len; i++)
            fputs(tok_spelling(&m->body.t[i]), fp);
    }
    fputc('\n', fp);
}

/* ---------------------------------------------------------------- */
/* #include */

static int include_depth;

static void parse_include(int is_next)
{
    Tok t;
    CStr name;
    int angle = 0;
    char path[1024];
    int idx;
    cstr_init(&name);
    in_directive = 1;
    /* skip spaces */
    for (;;) {
        int c = pc();
        if (is_space_char(c)) { adv(); continue; }
        break;
    }
    if (pc() == '<') {
        adv();
        for (;;) {
            int c = pc();
            if (c == '>') { adv(); break; }
            if (c == '\n' || c == 0)
                tcc_error("missing terminating > character");
            cstr_ccat(&name, c);
            adv();
        }
        angle = 1;
    } else if (pc() == '"') {
        lex_raw(&t);
        cstr_cat(&name, t.s + 1, strlen(t.s) - 2);
    } else {
        /* macro expanded */
        TokVec v;
        int i;
        memset(&v, 0, sizeof v);
        for (;;) {
            next_expanded(&t);
            if (t.id == TOK_LINEFEED || t.id == TOK_EOF)
                break;
            tv_push_tok(&v, &t);
        }
        i = 0;
        while (i < v.len && v.t[i].id == ' ') i++;
        if (i < v.len && v.t[i].id == TOK_STR) {
            cstr_cat(&name, v.t[i].s + 1, strlen(v.t[i].s) - 2);
            i++;
        } else if (i < v.len && v.t[i].id == '<') {
            i++;
            for (;;) {
                if (i >= v.len)
                    tcc_error("'>' expected");
                if (v.t[i].id == '>') { i++; break; }
                cstr_cat(&name, tok_spelling(&v.t[i]), -1);
                i++;
            }
            angle = 1;
        } else {
            tcc_error("'#include' expects \"FILENAME\" or <FILENAME>");
        }
        /* extra tokens */
        {
            int extra = 0;
            for (; i < v.len; i++)
                if (v.t[i].id != ' ') extra = 1;
            if (extra)
                tcc_warning("extra tokens after directive");
        }
        tv_free(&v);
        in_directive = 0;
        /* the LINEFEED was consumed by next_expanded */
        goto do_include;
    }
    dir_end(1);
    in_directive = 0;
do_include:
    if (pp_include_depth() >= INCLUDE_STACK_SIZE)
        tcc_error("#include recursion too deep");
    if (!pp_search_include(name.data, angle, is_next, path, sizeof path, &idx)) {
        tcc_error("include file '%s' not found", name.data);
    }
    cstr_free(&name);
    if (is_pragma_once(path))
        return;
    pp_add_dep(path);
    if (pp_open_file(path, idx) < 0)
        tcc_error("include file '%s' not found", path);
    /* new file: the output driver detects the include stack change */
}

/* ---------------------------------------------------------------- */
/* #pragma */

static void (*pragma_hook)(TokVec *toks);  /* compile-mode pragma handling */

static void parse_pragma(void)
{
    Tok t;
    in_directive = 1;
    dir_next(&t);
    if (t.id == TOK_ONCE) {
        pvec_push(&pragma_once_files, xstrdup(file->filename));
        dir_end(1);
        in_directive = 0;
        return;
    }
    if (t.id == TOK_PUSH_MACRO || t.id == TOK_POP_MACRO) {
        Tok n;
        int is_push = t.id == TOK_PUSH_MACRO;
        int id;
        dir_next(&n);
        if (n.id != '(') tcc_error("'(' expected");
        dir_next(&n);
        if (n.id != TOK_STR) tcc_error("string constant expected");
        id = ident_lookup(n.s + 1, strlen(n.s) - 2);
        dir_next(&n);
        if (n.id != ')') tcc_error("')' expected");
        dir_end(1);
        in_directive = 0;
        {
            Ident *ident = ident_get(id);
            if (is_push) {
                Macro *copy = NULL;
                if (ident->mac) {
                    int i;
                    copy = xcalloc(sizeof(Macro));
                    *copy = *ident->mac;
                    copy->params = NULL;
                    memset(&copy->body, 0, sizeof copy->body);
                    if (ident->mac->nparams) {
                        copy->params = xmalloc(sizeof(int) * ident->mac->nparams);
                        memcpy(copy->params, ident->mac->params, sizeof(int) * ident->mac->nparams);
                    }
                    for (i = 0; i < ident->mac->body.len; i++)
                        tv_push_tok(&copy->body, &ident->mac->body.t[i]);
                }
                /* push: a NULL copy means "undefined" - we store a sentinel */
                if (!copy) {
                    copy = xcalloc(sizeof(Macro));
                    copy->id = -1;
                }
                copy->next = ident->mac_stack;
                ident->mac_stack = copy;
            } else {
                Macro *m = ident->mac_stack;
                if (m) {
                    ident->mac_stack = m->next;
                    m->next = NULL;
                    if (ident->mac) free_macro(ident->mac);
                    if (m->id == -1) {
                        free_macro(m);
                        ident->mac = NULL;
                    } else
                        ident->mac = m;
                }
            }
        }
        return;
    }
    /* other pragmas */
    {
        TokVec v;
        int i;
        memset(&v, 0, sizeof v);
        if (t.id != TOK_LINEFEED) {
            t.hs = t.id >= TOK_IDENT ? hs_add(NULL, t.id) : NULL;
            tv_push_tok(&v, &t);
            /* rest of line: raw tokens with spaces, macro expanded later */
            for (;;) {
                lex_raw(&t);
                if (t.id == TOK_LINEFEED || t.id == TOK_EOF)
                    break;
                tv_push_tok(&v, &t);
            }
        }
        in_directive = 0;
        if (pp_output_mode) {
            TokVec out;
            Tok h;
            memset(&out, 0, sizeof out);
            h.id = '#'; h.s = NULL; h.hs = NULL;
            tv_push_tok(&out, &h);
            h.id = TOK_PRAGMA; h.hs = hs_add(NULL, TOK_PRAGMA);
            tv_push_tok(&out, &h);
            if (v.len) {
                h.id = ' '; h.s = " "; h.hs = NULL;
                tv_push_tok(&out, &h);
                for (i = 0; i < v.len; i++)
                    tv_push_tok(&out, &v.t[i]);
            }
            h.id = TOK_LINEFEED; h.s = NULL; h.hs = NULL;
            tv_push_tok(&out, &h);
            /* the linefeed of the directive was consumed by lexer: compensate
               by not counting... the pushed LINEFEED will be output */
            file->line_num--; /* will be re-incremented when LINEFEED token is processed */
            tv_free(&v);
            push_frame(out.t, out.len, 1);
            /* mark: the pushed linefeed must increment line_num */
            frames[nframes - 1].barrier = 2;
            return;
        }
        if (pragma_hook)
            pragma_hook(&v);
        tv_free(&v);
    }
}

void pp_set_pragma_hook(void (*hook)(TokVec *))
{
    pragma_hook = hook;
}

/* ---------------------------------------------------------------- */
/* main directive dispatcher */

static void parse_line_directive(Tok *t)
{
    /* t is the PPNUM or we are after 'line' */
    Tok n;
    int line;
    uint64_t v; int uns, ll;
    char *end;
    const char *s = t->s;
    /* must be plain decimal digits */
    for (end = (char *)s; *end; end++)
        if (*end < '0' || *end > '9')
            tcc_error("wrong #line format");
    v = strtoull(s, NULL, 10);
    line = (int)v;
    (void)uns; (void)ll;
    dir_next(&n);
    if (n.id == TOK_STR) {
        CStr fn;
        int wide, cs;
        cstr_init(&fn);
        parse_string_literal(n.s, &fn, &wide, &cs);
        if (fn.len)
            snprintf(file->filename, sizeof file->filename, "%.*s", fn.len, fn.data);
        else
            file->filename[0] = 0;
        cstr_free(&fn);
        /* flags: ignore numbers */
        {
            int extra = 0;
            for (;;) {
                lex_raw(&n);
                if (n.id == TOK_LINEFEED || n.id == TOK_EOF) break;
                if (n.id == ' ') continue;
                if (n.id == TOK_PPNUM && t->id == TOK_PPNUM) continue;
                extra = 1;
            }
            if (extra)
                tcc_warning("extra tokens after directive");
        }
        file->line_num = line;
        return;
    }
    if (n.id != TOK_LINEFEED)
        tcc_error("wrong #line format");
    file->line_num = line;
}

static void preprocess_directive(void)
{
    Tok t;
    in_directive = 1;
    dir_next(&t);
    in_directive = 0;
    if (t.id == TOK_LINEFEED)
        return;
    if (t.id == TOK_PPNUM) {
        in_directive = 1;
        parse_line_directive(&t);
        in_directive = 0;
        return;
    }
    switch (t.id) {
    case TOK_DEFINE:
        parse_define();
        return;
    case TOK_UNDEF:
        in_directive = 1;
        dir_next(&t);
        if (t.id < TOK_IDENT)
            tcc_error("invalid macro name '%s'", tok_spelling(&t));
        undef_macro(t.id);
        dir_end(1);
        in_directive = 0;
        pp_debug_tok = TOK_UNDEF;
        pp_debug_symv = t.id;
        return;
    case TOK_INCLUDE:
    case TOK_INCLUDE_NEXT:
        parse_include(t.id == TOK_INCLUDE_NEXT);
        return;
    case TOK_IF:
    case TOK_IFDEF:
    case TOK_IFNDEF: {
        int c;
        IfState *st;
        if (ifsp >= IFDEF_STACK_SIZE)
            tcc_error("memory full (ifdef)");
        if (t.id == TOK_IF) {
            c = eval_if_expr("if");
        } else {
            Tok n;
            in_directive = 1;
            dir_next(&n);
            if (n.id < TOK_IDENT)
                tcc_error("invalid argument for '#%s'", t.id == TOK_IFDEF ? "ifdef" : "ifndef");
            c = ident_get(n.id)->mac != NULL
                || n.id == TOK___LINE__ || n.id == TOK___FILE__ || n.id == TOK___COUNTER__
                || n.id == TOK___DATE__ || n.id == TOK___TIME__ || n.id == TOK___HAS_INCLUDE
                || n.id == TOK___HAS_INCLUDE_NEXT;
            if (t.id == TOK_IFNDEF)
                c = !c;
            dir_end(1);
            in_directive = 0;
        }
        st = &ifstack[ifsp++];
        st->taking = c;
        st->any_taken = c;
        st->seen_else = 0;
        if (!c)
            skip_group();
        return;
    }
    case TOK_ELIF:
    case TOK_ELSE:
    case TOK_ENDIF: {
        IfState *st;
        if (ifsp <= file->ifdef_depth)
            tcc_error("#%s without matching #if", tok_name(t.id));
        st = &ifstack[ifsp - 1];
        if (t.id == TOK_ENDIF) {
            in_directive = 1;
            dir_end(1);
            in_directive = 0;
            ifsp--;
            return;
        }
        if (t.id == TOK_ELSE) {
            if (st->seen_else)
                tcc_error("#else after #else");
            st->seen_else = 1;
            in_directive = 1;
            dir_end(1);
            in_directive = 0;
            /* current group was taken: skip the rest */
            skip_group();
            return;
        }
        /* elif in a taken group: skip without evaluating */
        if (st->seen_else)
            tcc_error("#elif after #else");
        skip_line_raw(0);
        skip_group();
        return;
    }
    case TOK_LINE: {
        Tok n;
        in_directive = 1;
        dir_next(&n);
        if (n.id != TOK_PPNUM) {
            /* macro expanded? */
            if (n.id >= TOK_IDENT && ident_get(n.id)->mac) {
                TokVec v;
                int i = 0;
                memset(&v, 0, sizeof v);
                /* push back and expand */
                {
                    Tok *copy = xmalloc(sizeof(Tok));
                    *copy = n;
                    push_frame(copy, 1, 1);
                }
                for (;;) {
                    Tok x;
                    next_expanded(&x);
                    if (x.id == TOK_LINEFEED || x.id == TOK_EOF) break;
                    if (x.id == ' ') continue;
                    tv_push_tok(&v, &x);
                }
                if (v.len >= 1 && v.t[0].id == TOK_PPNUM) {
                    const char *s = v.t[0].s;
                    const char *e;
                    for (e = s; *e; e++)
                        if (*e < '0' || *e > '9')
                            tcc_error("wrong #line format");
                    if (v.len >= 2 && v.t[1].id == TOK_STR) {
                        CStr fn; int wide, cs;
                        cstr_init(&fn);
                        parse_string_literal(v.t[1].s, &fn, &wide, &cs);
                        snprintf(file->filename, sizeof file->filename, "%.*s", fn.len, fn.data);
                        cstr_free(&fn);
                        i = 2;
                    } else
                        i = 1;
                    if (i != v.len)
                        tcc_error("wrong #line format");
                    file->line_num = atoi(s);
                    tv_free(&v);
                    in_directive = 0;
                    return;
                }
                tcc_error("wrong #line format");
            }
            tcc_error("wrong #line format");
        }
        parse_line_directive(&n);
        in_directive = 0;
        return;
    }
    case TOK_ERROR:
    case TOK_WARNING: {
        CStr cs;
        int is_err = t.id == TOK_ERROR;
        cstr_init(&cs);
        dir_rest_raw(&cs);
        if (is_err)
            tcc_error("#error %s", cs.data);
        if (pp_output_mode && S.ppfp)
            fputs("\n", S.ppfp);
        tcc_warning("#warning %s", cs.data);
        cstr_free(&cs);
        return;
    }
    case TOK_PRAGMA:
        parse_pragma();
        return;
    default:
        break;
    }
    if (t.id >= TOK_IDENT || t.id < 256) {
        in_directive = 1;
        tcc_warning("ignoring unknown preprocessing directive #%s", tok_spelling(&t));
        /* skip rest of line */
        for (;;) {
            lex_raw(&t);
            if (t.id == TOK_LINEFEED || t.id == TOK_EOF) break;
        }
        in_directive = 0;
    }
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat >> pp.c <<'EOF'

/* ---------------------------------------------------------------- */
/* include path search */

static PVec pragma_once_files;  /* char* canonical names */

static int file_exists(const char *name)
{
    struct stat st;
    if (stat(name, &st) < 0)
        return 0;
    return 1;
}

static void path_dirname(const char *name, char *out, int outsz)
{
    const char *p = strrchr(name, '/');
    if (!p) {
        out[0] = 0;
        return;
    }
    snprintf(out, outsz, "%.*s", (int)(p - name + 1), name);
}

/* Search include file. Returns 1 if found; fills out with the path and
   *pidx with the index of the search path used (-1 for the current dir). */
int pp_search_include(const char *name, int angle, int is_next, char *out, int outsz, int *pidx)
{
    int i, start = 0, n;
    int total = S.include_paths.len + S.sysinclude_paths.len;
    if (name[0] == '/') {
        snprintf(out, outsz, "%s", name);
        *pidx = -1;
        return file_exists(out);
    }
    if (is_next) {
        start = file->inc_idx + 1;
    } else if (!angle) {
        char dir[1024];
        path_dirname(file->filename, dir, sizeof dir);
        snprintf(out, outsz, "%s%s", dir, name);
        if (file_exists(out)) {
            *pidx = -1;
            return 1;
        }
    }
    n = total;
    for (i = start; i < n; i++) {
        const char *dir = i < S.include_paths.len ? S.include_paths.p[i]
            : S.sysinclude_paths.p[i - S.include_paths.len];
        snprintf(out, outsz, "%s/%s", dir, name);
        if (file_exists(out)) {
            *pidx = i;
            return 1;
        }
    }
    return 0;
}

void pp_add_dep(const char *name)
{
    int i;
    for (i = 0; i < S.target_deps.len; i++)
        if (!strcmp(S.target_deps.p[i], name))
            return;
    pvec_push(&S.target_deps, xstrdup(name));
}

static int is_pragma_once(const char *path)
{
    int i;
    for (i = 0; i < pragma_once_files.len; i++)
        if (!strcmp(pragma_once_files.p[i], path))
            return 1;
    return 0;
}

/* ---------------------------------------------------------------- */
/* skipping of false conditional groups */

static int skip_saw_directive;

/* skip rest of current line in skip mode (raw), handling comments */
static void skip_line_raw(int in_warn)
{
    int c;
    for (;;) {
        c = pc();
        if (c == 0)
            return;
        if (c == '\n') {
            adv();
            file->line_num++;
            return;
        }
        if (!in_warn && (c == '"' || c == '\'')) {
            int q = c;
            adv();
            for (;;) {
                c = pc();
                if (c == 0 || c == '\n')
                    break;
                if (c == '\\') {
                    adv();
                    c = pc();
                    if (c == 0 || c == '\n')
                        break;
                    adv();
                    continue;
                }
                adv();
                if (c == q)
                    break;
            }
            continue;
        }
        if (!in_warn && c == '/') {
            adv();
            c = pc();
            if (c == '*') {
                adv();
                skip_comment();
            } else if (c == '/') {
                adv();
                skip_line_comment();
            }
            continue;
        }
        adv();
    }
}

static void eof_in_skip(void)
{
    file->line_num--;
    if (skip_saw_directive)
        file->line_num++;
    tcc_error("#endif expected");
}

/* Called when the current group of the top ifstack entry must be skipped.
   Returns when a group to be processed begins, or after #endif. */
static void skip_group(void)
{
    int depth = 0;
    Tok t;
    IfState *st = &ifstack[ifsp - 1];
    skip_saw_directive = 0;
    for (;;) {
        int c;
        /* at start of line */
        for (;;) {
            c = pc();
            if (is_space_char(c)) { adv(); continue; }
            break;
        }
        if (c == 0) {
            eof_in_skip();
        }
        if (c == '\n') {
            adv();
            file->line_num++;
            continue;
        }
        if (c == '/') {
            /* comment at line start */
            const char *save = file->p;
            int saveline = file->line_num;
            adv();
            c = pc();
            if (c == '*') {
                adv();
                skip_comment();
                /* stay on this logical line: continue scanning from here */
                /* a directive after a comment is still allowed in tcc? no: treat rest as text */
                skip_line_raw(0);
                continue;
            }
            if (c == '/') {
                adv();
                skip_line_comment();
                continue;
            }
            file->p = save;
            file->line_num = saveline;
            skip_line_raw(0);
            continue;
        }
        if (c != '#') {
            skip_line_raw(0);
            continue;
        }
        adv();
        /* directive */
        in_directive = 1;
        dir_next(&t);
        in_directive = 0;
        if (t.id == TOK_LINEFEED) {
            /* bare '#': line consumed if LINEFEED token consumed it */
            continue;
        }
        skip_saw_directive = 1;
        if (t.id == TOK_IF || t.id == TOK_IFDEF || t.id == TOK_IFNDEF) {
            depth++;
            skip_line_raw(0);
            continue;
        }
        if (t.id == TOK_ENDIF) {
            if (depth == 0) {
                dir_end(1);
                ifsp--;
                return;
            }
            depth--;
            skip_line_raw(0);
            continue;
        }
        if (t.id == TOK_ELSE) {
            if (depth == 0) {
                if (st->seen_else)
                    tcc_error("#else after #else");
                st->seen_else = 1;
                dir_end(1);
                if (!st->any_taken) {
                    st->taking = st->any_taken = 1;
                    return;
                }
                continue;
            }
            skip_line_raw(0);
            continue;
        }
        if (t.id == TOK_ELIF) {
            if (depth == 0) {
                if (st->seen_else)
                    tcc_error("#elif after #else");
                if (!st->any_taken) {
                    int r = eval_if_expr("elif");
                    if (r) {
                        st->taking = st->any_taken = 1;
                        return;
                    }
                } else
                    skip_line_raw(0);
                continue;
            }
            skip_line_raw(0);
            continue;
        }
        if (t.id == TOK_ERROR || t.id == TOK_WARNING) {
            skip_line_raw(1);
            continue;
        }
        skip_line_raw(0);
    }
}

/* ---------------------------------------------------------------- */
/* #define */

static void free_macro(Macro *m)
{
    if (!m) return;
    free(m->params);
    tv_free(&m->body);
    free(m);
}

static int macro_equal(Macro *a, Macro *b)
{
    int i;
    if (a->is_func != b->is_func || a->nparams != b->nparams || a->variadic != b->variadic)
        return 0;
    for (i = 0; i < a->nparams; i++)
        if (a->params[i] != b->params[i])
            return 0;
    if (a->body.len != b->body.len)
        return 0;
    for (i = 0; i < a->body.len; i++) {
        if (a->body.t[i].id != b->body.t[i].id)
            return 0;
        if (a->body.t[i].s != b->body.t[i].s) {
            if (!a->body.t[i].s || !b->body.t[i].s || strcmp(a->body.t[i].s, b->body.t[i].s))
                return 0;
        }
    }
    return 1;
}

static void define_macro(Macro *m)
{
    Ident *id = ident_get(m->id);
    if (id->mac) {
        if (!macro_equal(id->mac, m))
            tcc_warning("%s redefined", id->name);
        free_macro(id->mac);
    }
    id->mac = m;
}

static void undef_macro(int id)
{
    Ident *i = ident_get(id);
    if (i->mac) {
        free_macro(i->mac);
        i->mac = NULL;
    }
}

static void parse_define(void)
{
    Tok t;
    Macro *m;
    int c;
    in_directive = 1;
    dir_next(&t);
    if (t.id < TOK_IDENT) {
        tcc_error("invalid macro name '%s'", tok_spelling(&t));
    }
    if (t.id == TOK_DEFINED)
        tcc_error("invalid macro name 'defined'");
    m = xcalloc(sizeof(Macro));
    m->id = t.id;
    /* function-like if '(' immediately follows */
    c = pc();
    if (c == '(') {
        int cap = 0;
        adv();
        m->is_func = 1;
        for (;;) {
            dir_next(&t);
            if (t.id == ')' && m->nparams == 0)
                break;
            if (t.id == TOK_DOTS) {
                if (m->nparams >= cap) { cap = cap ? cap * 2 : 4; m->params = xrealloc(m->params, cap * sizeof(int)); }
                m->params[m->nparams++] = TOK___VA_ARGS__;
                m->variadic = 1;
                dir_next(&t);
                if (t.id != ')')
                    tcc_error("bad macro parameter list");
                break;
            }
            if (t.id < TOK_IDENT)
                tcc_error("bad macro parameter list");
            if (m->nparams >= cap) { cap = cap ? cap * 2 : 4; m->params = xrealloc(m->params, cap * sizeof(int)); }
            m->params[m->nparams++] = t.id;
            dir_next(&t);
            if (t.id == TOK_DOTS) {
                m->variadic = 1;
                dir_next(&t);
                if (t.id != ')')
                    tcc_error("bad macro parameter list");
                break;
            }
            if (t.id == ')')
                break;
            if (t.id != ',')
                tcc_error("bad macro parameter list");
        }
    }
    /* body */
    {
        int spc = 1; /* at start: skip spaces */
        for (;;) {
            lex_raw(&t);
            if (t.id == TOK_LINEFEED || t.id == TOK_EOF)
                break;
            if (t.id == ' ') {
                if (spc)
                    continue;
                spc = 1;
                tv_push(&m->body, ' ', " ");
                continue;
            }
            if (t.id == TOK_TWOSHARPS) {
                /* remove spaces before ## */
                while (m->body.len > 0 && m->body.t[m->body.len - 1].id == ' ')
                    m->body.len--;
            }
            spc = 0;
            tv_push_tok(&m->body, &t);
        }
        while (m->body.len > 0 && m->body.t[m->body.len - 1].id == ' ')
            m->body.len--;
        if (m->body.len > 0 && (m->body.t[0].id == TOK_TWOSHARPS
                                || m->body.t[m->body.len - 1].id == TOK_TWOSHARPS))
            tcc_error("'##' cannot appear at either end of macro");
    }
    in_directive = 0;
    define_macro(m);
    pp_debug_tok = TOK_DEFINE;
    pp_debug_symv = m->id;
}

/* print macro definition (for -dD/-dM) */
static void define_print(FILE *fp, int id)
{
    Ident *ident = ident_get(id);
    Macro *m = ident->mac;
    int i;
    if (!m)
        return;
    fprintf(fp, "#define %s", ident->name);
    if (m->is_func) {
        fputc('(', fp);
        for (i = 0; i < m->nparams; i++) {
            if (i) fputc(',', fp);
            fputs(tok_name(m->params[i]), fp);
        }
        fputc(')', fp);
    }
    if (m->body.len) {
        fputc(' ', fp);
        for (i = 0; i < m->body.len; i++)
            fputs(tok_spelling(&m->body.t[i]), fp);
    }
    fputc('\n', fp);
}

/* ---------------------------------------------------------------- */
/* #include */

static int include_depth;

static void parse_include(int is_next)
{
    Tok t;
    CStr name;
    int angle = 0;
    char path[1024];
    int idx;
    cstr_init(&name);
    in_directive = 1;
    /* skip spaces */
    for (;;) {
        int c = pc();
        if (is_space_char(c)) { adv(); continue; }
        break;
    }
    if (pc() == '<') {
        adv();
        for (;;) {
            int c = pc();
            if (c == '>') { adv(); break; }
            if (c == '\n' || c == 0)
                tcc_error("missing terminating > character");
            cstr_ccat(&name, c);
            adv();
        }
        angle = 1;
    } else if (pc() == '"') {
        lex_raw(&t);
        cstr_cat(&name, t.s + 1, strlen(t.s) - 2);
    } else {
        /* macro expanded */
        TokVec v;
        int i;
        memset(&v, 0, sizeof v);
        for (;;) {
            next_expanded(&t);
            if (t.id == TOK_LINEFEED || t.id == TOK_EOF)
                break;
            tv_push_tok(&v, &t);
        }
        i = 0;
        while (i < v.len && v.t[i].id == ' ') i++;
        if (i < v.len && v.t[i].id == TOK_STR) {
            cstr_cat(&name, v.t[i].s + 1, strlen(v.t[i].s) - 2);
            i++;
        } else if (i < v.len && v.t[i].id == '<') {
            i++;
            for (;;) {
                if (i >= v.len)
                    tcc_error("'>' expected");
                if (v.t[i].id == '>') { i++; break; }
                cstr_cat(&name, tok_spelling(&v.t[i]), -1);
                i++;
            }
            angle = 1;
        } else {
            tcc_error("'#include' expects \"FILENAME\" or <FILENAME>");
        }
        /* extra tokens */
        {
            int extra = 0;
            for (; i < v.len; i++)
                if (v.t[i].id != ' ') extra = 1;
            if (extra)
                tcc_warning("extra tokens after directive");
        }
        tv_free(&v);
        in_directive = 0;
        /* the LINEFEED was consumed by next_expanded */
        goto do_include;
    }
    dir_end(1);
    in_directive = 0;
do_include:
    if (pp_include_depth() >= INCLUDE_STACK_SIZE)
        tcc_error("#include recursion too deep");
    if (!pp_search_include(name.data, angle, is_next, path, sizeof path, &idx)) {
        tcc_error("include file '%s' not found", name.data);
    }
    cstr_free(&name);
    if (is_pragma_once(path))
        return;
    pp_add_dep(path);
    if (pp_open_file(path, idx) < 0)
        tcc_error("include file '%s' not found", path);
    /* new file: the output driver detects the include stack change */
}

/* ---------------------------------------------------------------- */
/* #pragma */

static void (*pragma_hook)(TokVec *toks);  /* compile-mode pragma handling */

static void parse_pragma(void)
{
    Tok t;
    in_directive = 1;
    dir_next(&t);
    if (t.id == TOK_ONCE) {
        pvec_push(&pragma_once_files, xstrdup(file->filename));
        dir_end(1);
        in_directive = 0;
        return;
    }
    if (t.id == TOK_PUSH_MACRO || t.id == TOK_POP_MACRO) {
        Tok n;
        int is_push = t.id == TOK_PUSH_MACRO;
        int id;
        dir_next(&n);
        if (n.id != '(') tcc_error("'(' expected");
        dir_next(&n);
        if (n.id != TOK_STR) tcc_error("string constant expected");
        id = ident_lookup(n.s + 1, strlen(n.s) - 2);
        dir_next(&n);
        if (n.id != ')') tcc_error("')' expected");
        dir_end(1);
        in_directive = 0;
        {
            Ident *ident = ident_get(id);
            if (is_push) {
                Macro *copy = NULL;
                if (ident->mac) {
                    int i;
                    copy = xcalloc(sizeof(Macro));
                    *copy = *ident->mac;
                    copy->params = NULL;
                    memset(&copy->body, 0, sizeof copy->body);
                    if (ident->mac->nparams) {
                        copy->params = xmalloc(sizeof(int) * ident->mac->nparams);
                        memcpy(copy->params, ident->mac->params, sizeof(int) * ident->mac->nparams);
                    }
                    for (i = 0; i < ident->mac->body.len; i++)
                        tv_push_tok(&copy->body, &ident->mac->body.t[i]);
                }
                /* push: a NULL copy means "undefined" - we store a sentinel */
                if (!copy) {
                    copy = xcalloc(sizeof(Macro));
                    copy->id = -1;
                }
                copy->next = ident->mac_stack;
                ident->mac_stack = copy;
            } else {
                Macro *m = ident->mac_stack;
                if (m) {
                    ident->mac_stack = m->next;
                    m->next = NULL;
                    if (ident->mac) free_macro(ident->mac);
                    if (m->id == -1) {
                        free_macro(m);
                        ident->mac = NULL;
                    } else
                        ident->mac = m;
                }
            }
        }
        return;
    }
    /* other pragmas */
    {
        TokVec v;
        int i;
        memset(&v, 0, sizeof v);
        if (t.id != TOK_LINEFEED) {
            t.hs = t.id >= TOK_IDENT ? hs_add(NULL, t.id) : NULL;
            tv_push_tok(&v, &t);
            /* rest of line: raw tokens with spaces, macro expanded later */
            for (;;) {
                lex_raw(&t);
                if (t.id == TOK_LINEFEED || t.id == TOK_EOF)
                    break;
                tv_push_tok(&v, &t);
            }
        }
        in_directive = 0;
        if (pp_output_mode) {
            TokVec out;
            Tok h;
            memset(&out, 0, sizeof out);
            h.id = '#'; h.s = NULL; h.hs = NULL;
            tv_push_tok(&out, &h);
            h.id = TOK_PRAGMA; h.hs = hs_add(NULL, TOK_PRAGMA);
            tv_push_tok(&out, &h);
            if (v.len) {
                h.id = ' '; h.s = " "; h.hs = NULL;
                tv_push_tok(&out, &h);
                for (i = 0; i < v.len; i++)
                    tv_push_tok(&out, &v.t[i]);
            }
            h.id = TOK_LINEFEED; h.s = NULL; h.hs = NULL;
            tv_push_tok(&out, &h);
            /* the linefeed of the directive was consumed by lexer: compensate
               by not counting... the pushed LINEFEED will be output */
            file->line_num--; /* will be re-incremented when LINEFEED token is processed */
            tv_free(&v);
            push_frame(out.t, out.len, 1);
            /* mark: the pushed linefeed must increment line_num */
            frames[nframes - 1].barrier = 2;
            return;
        }
        if (pragma_hook)
            pragma_hook(&v);
        tv_free(&v);
    }
}

void pp_set_pragma_hook(void (*hook)(TokVec *))
{
    pragma_hook = hook;
}

/* ---------------------------------------------------------------- */
/* main directive dispatcher */

static void parse_line_directive(Tok *t)
{
    /* t is the PPNUM or we are after 'line' */
    Tok n;
    int line;
    uint64_t v; int uns, ll;
    char *end;
    const char *s = t->s;
    /* must be plain decimal digits */
    for (end = (char *)s; *end; end++)
        if (*end < '0' || *end > '9')
            tcc_error("wrong #line format");
    v = strtoull(s, NULL, 10);
    line = (int)v;
    (void)uns; (void)ll;
    dir_next(&n);
    if (n.id == TOK_STR) {
        CStr fn;
        int wide, cs;
        cstr_init(&fn);
        parse_string_literal(n.s, &fn, &wide, &cs);
        if (fn.len)
            snprintf(file->filename, sizeof file->filename, "%.*s", fn.len, fn.data);
        else
            file->filename[0] = 0;
        cstr_free(&fn);
        /* flags: ignore numbers */
        {
            int extra = 0;
            for (;;) {
                lex_raw(&n);
                if (n.id == TOK_LINEFEED || n.id == TOK_EOF) break;
                if (n.id == ' ') continue;
                if (n.id == TOK_PPNUM && t->id == TOK_PPNUM) continue;
                extra = 1;
            }
            if (extra)
                tcc_warning("extra tokens after directive");
        }
        file->line_num = line;
        return;
    }
    if (n.id != TOK_LINEFEED)
        tcc_error("wrong #line format");
    file->line_num = line;
}

static void preprocess_directive(void)
{
    Tok t;
    in_directive = 1;
    dir_next(&t);
    in_directive = 0;
    if (t.id == TOK_LINEFEED)
        return;
    if (t.id == TOK_PPNUM) {
        in_directive = 1;
        parse_line_directive(&t);
        in_directive = 0;
        return;
    }
    switch (t.id) {
    case TOK_DEFINE:
        parse_define();
        return;
    case TOK_UNDEF:
        in_directive = 1;
        dir_next(&t);
        if (t.id < TOK_IDENT)
            tcc_error("invalid macro name '%s'", tok_spelling(&t));
        undef_macro(t.id);
        dir_end(1);
        in_directive = 0;
        pp_debug_tok = TOK_UNDEF;
        pp_debug_symv = t.id;
        return;
    case TOK_INCLUDE:
    case TOK_INCLUDE_NEXT:
        parse_include(t.id == TOK_INCLUDE_NEXT);
        return;
    case TOK_IF:
    case TOK_IFDEF:
    case TOK_IFNDEF: {
        int c;
        IfState *st;
        if (ifsp >= IFDEF_STACK_SIZE)
            tcc_error("memory full (ifdef)");
        if (t.id == TOK_IF) {
            c = eval_if_expr("if");
        } else {
            Tok n;
            in_directive = 1;
            dir_next(&n);
            if (n.id < TOK_IDENT)
                tcc_error("invalid argument for '#%s'", t.id == TOK_IFDEF ? "ifdef" : "ifndef");
            c = ident_get(n.id)->mac != NULL
                || n.id == TOK___LINE__ || n.id == TOK___FILE__ || n.id == TOK___COUNTER__
                || n.id == TOK___DATE__ || n.id == TOK___TIME__ || n.id == TOK___HAS_INCLUDE
                || n.id == TOK___HAS_INCLUDE_NEXT;
            if (t.id == TOK_IFNDEF)
                c = !c;
            dir_end(1);
            in_directive = 0;
        }
        st = &ifstack[ifsp++];
        st->taking = c;
        st->any_taken = c;
        st->seen_else = 0;
        if (!c)
            skip_group();
        return;
    }
    case TOK_ELIF:
    case TOK_ELSE:
    case TOK_ENDIF: {
        IfState *st;
        if (ifsp <= file->ifdef_depth)
            tcc_error("#%s without matching #if", tok_name(t.id));
        st = &ifstack[ifsp - 1];
        if (t.id == TOK_ENDIF) {
            in_directive = 1;
            dir_end(1);
            in_directive = 0;
            ifsp--;
            return;
        }
        if (t.id == TOK_ELSE) {
            if (st->seen_else)
                tcc_error("#else after #else");
            st->seen_else = 1;
            in_directive = 1;
            dir_end(1);
            in_directive = 0;
            /* current group was taken: skip the rest */
            skip_group();
            return;
        }
        /* elif in a taken group: skip without evaluating */
        if (st->seen_else)
            tcc_error("#elif after #else");
        skip_line_raw(0);
        skip_group();
        return;
    }
    case TOK_LINE: {
        Tok n;
        in_directive = 1;
        dir_next(&n);
        if (n.id != TOK_PPNUM) {
            /* macro expanded? */
            if (n.id >= TOK_IDENT && ident_get(n.id)->mac) {
                TokVec v;
                int i = 0;
                memset(&v, 0, sizeof v);
                /* push back and expand */
                {
                    Tok *copy = xmalloc(sizeof(Tok));
                    *copy = n;
                    push_frame(copy, 1, 1);
                }
                for (;;) {
                    Tok x;
                    next_expanded(&x);
                    if (x.id == TOK_LINEFEED || x.id == TOK_EOF) break;
                    if (x.id == ' ') continue;
                    tv_push_tok(&v, &x);
                }
                if (v.len >= 1 && v.t[0].id == TOK_PPNUM) {
                    const char *s = v.t[0].s;
                    const char *e;
                    for (e = s; *e; e++)
                        if (*e < '0' || *e > '9')
                            tcc_error("wrong #line format");
                    if (v.len >= 2 && v.t[1].id == TOK_STR) {
                        CStr fn; int wide, cs;
                        cstr_init(&fn);
                        parse_string_literal(v.t[1].s, &fn, &wide, &cs);
                        snprintf(file->filename, sizeof file->filename, "%.*s", fn.len, fn.data);
                        cstr_free(&fn);
                        i = 2;
                    } else
                        i = 1;
                    if (i != v.len)
                        tcc_error("wrong #line format");
                    file->line_num = atoi(s);
                    tv_free(&v);
                    in_directive = 0;
                    return;
                }
                tcc_error("wrong #line format");
            }
            tcc_error("wrong #line format");
        }
        parse_line_directive(&n);
        in_directive = 0;
        return;
    }
    case TOK_ERROR:
    case TOK_WARNING: {
        CStr cs;
        int is_err = t.id == TOK_ERROR;
        cstr_init(&cs);
        dir_rest_raw(&cs);
        if (is_err)
            tcc_error("#error %s", cs.data);
        if (pp_output_mode && S.ppfp)
            fputs("\n", S.ppfp);
        tcc_warning("#warning %s", cs.data);
        cstr_free(&cs);
        return;
    }
    case TOK_PRAGMA:
        parse_pragma();
        return;
    default:
        break;
    }
    if (t.id >= TOK_IDENT || t.id < 256) {
        in_directive = 1;
        tcc_warning("ignoring unknown preprocessing directive #%s", tok_spelling(&t));
        /* skip rest of line */
        for (;;) {
            lex_raw(&t);
            if (t.id == TOK_LINEFEED || t.id == TOK_EOF) break;
        }
        in_directive = 0;
    }
}
