/* return next token with macro expansion; in compile mode spaces and
   linefeeds are skipped */
void next(void)
{
    Tok t;
    if (unget_valid) {
        unget_valid = 0;
        tokcur = unget_saved;
        tok = tokcur.id;
        tokstr = tokcur.s;
        return;
