    tokstr = t.s;
}

/* push back the current token; 'last' becomes current */
void unget_tok(int last_tok)
{
    unget_saved = tokcur;
    unget_valid = 1;
    tok = last_tok;
    tokcur.id = last_tok;
    tokcur.s = NULL;
