    for (;;) {
        get_tok_raw(&t);
        if (!pp_output_mode) {
            if (t.id == ' ')
                continue;
            if (t.id == TOK_LINEFEED && !(parse_flags & PARSE_FLAG_LINEFEED))
                continue;
        }
        break;
    }
    tokcur = t;
    tok = t.id;
    tokstr = t.s;
}

/* push back the current token; 'last' becomes current */
void unget_tok(int last_tok)
{
    unget_saved = tokcur;
    unget_valid = 1;
    tok = last_tok;
    tokcur.id = last_tok;
    tokcur.s = NULL;
}

/* token string for error messages */
const char *get_tok_str(int id, const char *s)
{
    if (s && (id == TOK_PPNUM || id == TOK_STR || id == TOK_CHAR))
        return s;
    return tok_name(id);
}

void skip(int c)
{
    if (tok != c)
        tcc_error("'%s' expected (got \"%s\")", tok_name(c), get_tok_str(tok, tokstr));
    next();
}

void expect(const char *msg)
{
    tcc_error("%s expected", msg);
}

/* ---------------------------------------------------------------- */
/* command line buffer (predefined macros) */

static int cmdline_nb_lines;

static void add_predef_line(CStr *cs, const char *line)
{
    cstr_cat(cs, line, -1);
    cstr_ccat(cs, '\n');
}

void pp_build_cmdline_buf(const char *main_filename, int is_pp)
{
    CStr *cs = &S.cmdline_buf;
    int i;
    cstr_reset(cs);
    add_predef_line(cs, "#define __TINYC__ 928");
    add_predef_line(cs, "#define __x86_64__ 1");
    add_predef_line(cs, "#define __x86_64 1");
    add_predef_line(cs, "#define __amd64__ 1");
    add_predef_line(cs, "#define __linux__ 1");
    add_predef_line(cs, "#define __linux 1");
    add_predef_line(cs, "#define __unix__ 1");
    add_predef_line(cs, "#define __unix 1");
    if (is_pp)
        add_predef_line(cs, "#define __TCC_PP__ 1");
    if (S.do_backtrace || S.do_bounds_check)
        add_predef_line(cs, "#define __TCC_BACKTRACE__ 1");
    if (S.do_bounds_check)
        add_predef_line(cs, "#define __TCC_BCHECK__ 1");
    if (S.char_is_unsigned)
