    if (S.pthread)
        add_predef_line(cs, "#define _REENTRANT 1");
    if (S.leading_underscore)
        add_predef_line(cs, "#define __leading_underscore 1");
    add_predef_line(cs, "#define __SIZEOF_POINTER__ 8");
    add_predef_line(cs, "#define __SIZEOF_LONG__ 8");
    add_predef_line(cs, "#define __STDC__ 1");
    add_predef_line(cs, "#define __STDC_HOSTED__ 1");
    cstr_printf(cs, "#define __STDC_VERSION__ %dL\n", S.cversion);
    add_predef_line(cs, "#define __SIZE_TYPE__ unsigned long");
    add_predef_line(cs, "#define __PTRDIFF_TYPE__ long");
    add_predef_line(cs, "#define __LP64__ 1");
    add_predef_line(cs, "#define __INT64_TYPE__ long");
    add_predef_line(cs, "#define __SIZEOF_INT__ 4");
    add_predef_line(cs, "#define __INT_MAX__ 0x7fffffff");
    add_predef_line(cs, "#define __LONG_MAX__ 0x7fffffffffffffffL");
    add_predef_line(cs, "#define __SIZEOF_LONG_LONG__ 8");
    add_predef_line(cs, "#define __LONG_LONG_MAX__ 0x7fffffffffffffffLL");
    add_predef_line(cs, "#define __CHAR_BIT__ 8");
    add_predef_line(cs, "#define __ORDER_LITTLE_ENDIAN__ 1234");
    add_predef_line(cs, "#define __ORDER_BIG_ENDIAN__ 4321");
    add_predef_line(cs, "#define __BYTE_ORDER__ __ORDER_LITTLE_ENDIAN__");
    add_predef_line(cs, "#define __WCHAR_TYPE__ int");
    add_predef_line(cs, "#define __WINT_TYPE__ unsigned int");
    add_predef_line(cs, "#if __STDC_VERSION__ >= 201112L");
    add_predef_line(cs, "#define __STDC_NO_ATOMICS__ 1");
    add_predef_line(cs, "#define __STDC_NO_COMPLEX__ 1");
    add_predef_line(cs, "#define __STDC_NO_THREADS__ 1");
    add_predef_line(cs, "#define __STDC_UTF_16__ 1");
    add_predef_line(cs, "#define __STDC_UTF_32__ 1");
    add_predef_line(cs, "#endif");
    add_predef_line(cs, "#define __UINTPTR_TYPE__ unsigned __PTRDIFF_TYPE__");
    add_predef_line(cs, "#define __INTPTR_TYPE__ __PTRDIFF_TYPE__");
    add_predef_line(cs, "#define __INT32_TYPE__ int");
    add_predef_line(cs, "#define __REDIRECT(name,proto,alias) name proto __asm__(#alias)");
    add_predef_line(cs, "#define __REDIRECT_NTH(name,proto,alias) name proto __asm__(#alias)__THROW");
    add_predef_line(cs, "#define __REDIRECT_NTHNL(name,proto,alias) name proto __asm__(#alias)__THROWNL");
    add_predef_line(cs, "#define __PRETTY_FUNCTION__ __FUNCTION__");
    add_predef_line(cs, "#define __has_builtin(x) 0");
    add_predef_line(cs, "#define __has_feature(x) 0");
    add_predef_line(cs, "#define __has_attribute(x) 0");
    add_predef_line(cs, "#define _Nonnull");
    add_predef_line(cs, "#define _Nullable");
    add_predef_line(cs, "#define _Nullable_result");
    add_predef_line(cs, "#define _Null_unspecified");
    /* compile-mode block: 110 lines total */
    {
        static const char *cblock[] = {
            "#ifndef __TCC_PP__",
            "typedef struct {",
            "    unsigned gp_offset, fp_offset;",
            "    union {",
            "        unsigned overflow_offset;",
            "        char *overflow_arg_area;",
            "    };",
            "    char *reg_save_area;",
            "} __builtin_va_list[1];",
            "#define __builtin_va_start(ap,last) (*(ap)=*(__builtin_va_list)((char*)__builtin_frame_address(0)-24))",
            "#define __builtin_va_arg(ap,t) (*(t*)(__va_arg(ap,__builtin_va_arg_types(t),sizeof(t),__alignof__(t))))",
            "#define __builtin_va_end(ap) (void)(ap)",
            "#define __builtin_va_copy(d,s) (*(d)=*(s))",
            "#define __builtin_offsetof(type,field) ((__SIZE_TYPE__)&((type*)0)->field)",
            "#define __builtin_extract_return_addr(x) x",
            "#endif",
        };
        int n = sizeof(cblock) / sizeof(cblock[0]);
        for (i = 0; i < n; i++)
            add_predef_line(cs, cblock[i]);
        for (; i < 110; i++)
            add_predef_line(cs, "");
    }
    /* __BASE_FILE__ */
    {
        const char *p;
        cstr_cat(cs, "#define __BASE_FILE__ \"", -1);
        for (p = main_filename; *p; p++) {
            if (*p == '"' || *p == '\\') cstr_ccat(cs, '\\');
            cstr_ccat(cs, *p);
        }
        cstr_cat(cs, "\"\n", -1);
    }
    /* -D / -U options */
    for (i = 0; i < S.cmdline_defs.len; i++) {
        const char *d = S.cmdline_defs.p[i];
        if (d[0] == 'U') {
            cstr_printf(cs, "#undef %s\n", d + 1);
        } else {
            const char *eq = strchr(d + 1, '=');
            if (eq)
                cstr_printf(cs, "#define %.*s %s\n", (int)(eq - d - 1), d + 1, eq + 1);
            else
                cstr_printf(cs, "#define %s 1\n", d + 1);
        }
    }
    cmdline_nb_lines = 0;
}

/* process the cmdline buffer as an include of the current (main) file.
   In -E mode with -dD defines are printed as they are processed. */
static void pp_line_out(File *f, int level);
static void pp_debug_defines(void);

static void process_cmdline_buf(void)
{
    Tok t;
    char *data = xstrdup(S.cmdline_buf.data);
    File *f;
    int save_flags = parse_flags;
    /* the cmdline buffer is included from line 0 of the main file */
    f = new_file("<command line>", data);
    (void)f;
    file->prev->line_num = 0;
    if (pp_output_mode && S.ppfp)
        pp_line_out(file, 1);
    pp_eof_stop = 1;
    parse_flags = PARSE_FLAG_PREPROCESS | PARSE_FLAG_LINEFEED;
    for (;;) {
        get_tok_raw(&t);
        if (pp_output_mode && S.ppfp && (S.dflag & 3)) {
            pp_debug_defines();
        }
        if (t.id == TOK_EOF)
            break;
    }
    pp_eof_stop = 0;
    parse_flags = save_flags;
    pp_close_file();
    file->line_num = 1;
    tok_bol = 1;
}

/* ---------------------------------------------------------------- */
/* -E output */

static int pp_token_seen = TOK_LINEFEED;

static void pp_line_out(File *f, int level)
{
    int d = f->line_num - f->line_ref;
    FILE *fp = S.ppfp;
    if (S.dflag & 2) /* -dM: no output */
        return;
    if (S.pflag == PFLAG_NONE) {
        ;
    } else if (level == 0 && f->line_ref && d < 8) {
        while (d > 0) {
            fputs("\n", fp);
            d--;
        }
    } else if (S.pflag == PFLAG_STD) {
        fprintf(fp, "#line %d \"%s\"\n", f->line_num, f->filename);
    } else {
        fprintf(fp, "# %d \"%s\"%s\n", f->line_num, f->filename,
                level > 0 ? " 1" : level < 0 ? " 2" : "");
    }
    f->line_ref = f->line_num;
}

static void pp_debug_defines(void)
{
    int t = pp_debug_tok, v = pp_debug_symv;
    FILE *fp = S.ppfp;
    if (t == 0)
        return;
    file->line_num--;
    pp_line_out(file, 0);
    file->line_ref = ++file->line_num;
    if (t == TOK_DEFINE) {
        define_print(fp, v);
    } else if (t == TOK_UNDEF) {
        fprintf(fp, "#undef %s\n", tok_name(v));
    } else if (t == TOK_PUSH_MACRO) {
        fprintf(fp, "#pragma push_macro(\"%s\")\n", tok_name(v));
    } else if (t == TOK_POP_MACRO) {
        fprintf(fp, "#pragma pop_macro(\"%s\")\n", tok_name(v));
    }
    pp_debug_tok = 0;
}

/* returns 'E' if token is a pp-number ending in e/E, else the token id */
static int pp_check_he0xE(const Tok *t)
{
    if (t->id == TOK_PPNUM) {
        int n = strlen(t->s);
        int c = t->s[n - 1];
        if (c == 'e' || c == 'E')
            return 'E';
    }
    return t->id;
}

static int pp_need_space(int a, int b)
{
    if (a == 'E')
        return b == '+' || b == '-';
    if (a == '+')
        return b == TOK_INC || b == '+';
    if (a == '-')
        return b == TOK_DEC || b == '-';
    if (a >= TOK_IDENT || a == TOK_PPNUM)
        return b >= TOK_IDENT || b == TOK_PPNUM;
    return 0;
}

/* preprocess current file to S.ppfp */
void pp_run_preprocess(void)
{
    FILE *fp = S.ppfp;
    Tok t;
    char white[400];
    int spcs = 0;
    File *main_file = file;
    int depth_before;

    pp_output_mode = 1;
    pp_token_seen = TOK_LINEFEED;
    parse_flags = PARSE_FLAG_PREPROCESS | PARSE_FLAG_LINEFEED | PARSE_FLAG_SPACES;

    /* initial line markers */
    pp_line_out(main_file, 0);
    process_cmdline_buf();
    pp_line_out(main_file, -1);
    tok_bol = 1;

    for (;;) {
        int level;
        depth_before = pp_include_depth();
        {
            File *before = file;
            if (nframes == 0)
                hs_reset();
            next_expanded(&t);
            level = pp_include_depth() - depth_before;
            if (level) {
                if (level > 0) {
                    /* print parent's position */
                    pp_line_out(before, 0);
                }
                pp_line_out(file, level);
            }
        }
        if (t.id == TOK_EOF)
            break;
        if (S.dflag & 3) {
            pp_debug_defines();
            if (S.dflag & 2)
                continue;
        }
        if (t.id == ' ') {
            if (spcs < (int)sizeof white - 1)
                white[spcs++] = t.s ? t.s[0] : ' ';
            continue;
        } else if (t.id == TOK_LINEFEED) {
            spcs = 0;
            if (pp_token_seen == TOK_LINEFEED)
                continue;
            file->line_ref++;
        } else if (pp_token_seen == TOK_LINEFEED) {
            pp_line_out(file, 0);
        } else if (spcs == 0 && pp_need_space(pp_token_seen, t.id)) {
            white[spcs++] = ' ';
        }
        white[spcs] = 0;
        fputs(white, fp);
        spcs = 0;
        fputs(tok_spelling(&t), fp);
        pp_token_seen = pp_check_he0xE(&t);
    }
    /* final newline if needed */
    if (pp_token_seen != TOK_LINEFEED && !(S.dflag & 2))
        fputs("\n", fp);
    pp_output_mode = 0;
}

/* dependency output */
void pp_print_deps(FILE *f, const char *target)
{
    int i;
    fprintf(f, "%s: \\\n", target);
    for (i = 0; i < S.target_deps.len; i++) {
        fprintf(f, "  %s%s\n", (char *)S.target_deps.p[i],
                i + 1 < S.target_deps.len ? " \\" : "");
    }
}

/* start preprocessing a file for compilation (not -E) */
void pp_start_compile(void)
{
    pp_output_mode = 0;
    parse_flags = PARSE_FLAG_PREPROCESS;
    process_cmdline_buf();
    tok_bol = 1;
}

void pp_reset_state(void)
{
    /* reset per-file state */
    ifsp = 0;
    nframes = 0;
    unget_valid = 0;
    pp_token_seen = TOK_LINEFEED;
    pp_debug_tok = 0;
    tok_bol = 1;
    in_directive = 0;
    pp_counter = 0;
}

/* undefine all macros (between files) */
void pp_clear_macros(void)
{
    int i;
    for (i = 0; i < nb_idents; i++) {
        Ident *id = idents[i];
        if (id->mac) {
            free_macro(id->mac);
            id->mac = NULL;
        }
        while (id->mac_stack) {
            Macro *m = id->mac_stack;
            id->mac_stack = m->next;
            free_macro(m);
        }
    }
    pragma_once_files.len = 0;
}
