        if (!strcmp(p, "write-strings")) target = &S.warn_write_strings;
        else if (!strcmp(p, "unsupported")) target = &S.warn_unsupported;
        else if (!strcmp(p, "implicit-function-declaration")) target = &S.warn_implicit_function_declaration;
        else if (!strcmp(p, "discarded-qualifiers")) target = &S.warn_discarded_qualifiers;
        if (target) {
            if (err) {
                /* -Werror=x: set to error; -Wno-error=x: back to on */
                *target = no ? 1 : 2;
            } else
                *target = no ? 0 : 1;
            return;
        }
        if (err)
            return;
    }
    if (S.warn_unsupported)
        fprintf(stderr, "tcc: warning: unsupported option '-W%s'\n", opt);
}

static void set_f_option(const char *opt)
{
    int no = 0;
    const char *p = opt;
    if (!strncmp(p, "no-", 3)) { no = 1; p += 3; }
    if (!strcmp(p, "unsigned-char")) S.char_is_unsigned = !no;
    else if (!strcmp(p, "signed-char")) S.char_is_unsigned = no;
    else if (!strcmp(p, "common")) S.common = !no;
    else if (!strcmp(p, "leading-underscore")) S.leading_underscore = !no;
    else if (!strcmp(p, "ms-extensions")) S.ms_extensions = !no;
    else if (!strcmp(p, "dollars-in-identifiers")) S.dollars_in_identifiers = !no;
    else if (!strcmp(p, "reverse-funcargs")) S.reverse_funcargs = !no;
    else if (!strcmp(p, "gnu89-inline")) S.gnu89_inline = !no;
    else if (!strcmp(p, "asynchronous-unwind-tables")) S.unwind_tables = !no;
    else if (!strcmp(p, "test-coverage")) S.test_coverage = !no;
    else if (S.warn_unsupported)
        fprintf(stderr, "tcc: warning: unsupported option '-f%s'\n", opt);
}

static void set_m_option(const char *opt)
{
    int no = 0;
    const char *p = opt;
    if (!strncmp(p, "no-", 3)) { no = 1; p += 3; }
    if (!strcmp(p, "ms-bitfields")) S.ms_bitfields = !no;
    else if (!strcmp(p, "sse")) S.nosse = no;
    else if (!strcmp(opt, "32") || !strcmp(opt, "64")) {
        /* -m32: defer to i386-tcc */
        if (!strcmp(opt, "32")) {
            fprintf(stderr, "tcc: could not run '%s'\n", "/workspace/i386-tcc");
            exit(1);
        }
    } else if (S.warn_unsupported)
        fprintf(stderr, "tcc: warning: unsupported option '-m%s'\n", opt);
}

static uint64_t parse_num_arg(const char *s)
{
    return strtoull(s, NULL, 0);
}

static void set_linker_option(const char *opt)
{
    const char *p;
    while (*opt) {
        char buf[1024];
        const char *end = strchr(opt, ',');
        int len = end ? (int)(end - opt) : (int)strlen(opt);
        snprintf(buf, sizeof buf, "%.*s", len, opt);
        p = buf;
        if (!strcmp(p, "-Bsymbolic")) S.symbolic = 1;
        else if (!strcmp(p, "-nostdlib")) S.nostdlib = 1;
        else if (!strcmp(p, "-whole-archive") || !strcmp(p, "-no-whole-archive")) ;
        else if (!strcmp(p, "-export-all-symbols") || !strcmp(p, "-export-dynamic") || !strcmp(p, "--export-dynamic")) S.rdynamic = 1;
        else if (!strncmp(p, "-image-base=", 12)) { S.text_addr = parse_num_arg(p + 12); S.has_text_addr = 1; }
        else if (!strncmp(p, "-Ttext=", 7)) { S.text_addr = parse_num_arg(p + 7); S.has_text_addr = 1; }
        else if (!strncmp(p, "-section-alignment=", 19)) S.section_align = parse_num_arg(p + 19);
        else if (!strncmp(p, "-rpath=", 7)) {
            if (S.rpath) {
                char *n = xmalloc(strlen(S.rpath) + strlen(p + 7) + 2);
                sprintf(n, "%s:%s", S.rpath, p + 7);
                free(S.rpath);
                S.rpath = n;
            } else
                S.rpath = xstrdup(p + 7);
        }
        else if (!strcmp(p, "-enable-new-dtags")) S.enable_new_dtags = 1;
        else if (!strncmp(p, "-soname=", 8)) S.soname = xstrdup(p + 8);
        else if (!strncmp(p, "-I", 2)) S.elfint = xstrdup(p + 2);
        else if (!strncmp(p, "-dynamic-linker=", 16)) S.elfint = xstrdup(p + 16);
        else if (!strncmp(p, "-oformat=", 9)) ;
        else if (!strncmp(p, "-init=", 6)) S.init_symbol = xstrdup(p + 6);
        else if (!strncmp(p, "-fini=", 6)) S.fini_symbol = xstrdup(p + 6);
        else if (!strncmp(p, "-Map=", 5)) ;
        else if (!strcmp(p, "-as-needed") || !strcmp(p, "--as-needed") || !strcmp(p, "-O") || !strncmp(p, "-O", 2) || !strncmp(p, "-z", 2)) ;
        else if (!strncmp(p, "-e=", 3)) S.entryname = xstrdup(p + 3);
        else {
            tcc_fatal("unsupported linker option '%s'", p);
        }
        if (!end)
            break;
        opt = end + 1;
    }
}

/* ---------------------------------------------------------------- */

static int output_type_set;
static int nb_libraries;

static void set_output_type(int t, const char *optname)
{
    if (output_type_set)
        fprintf(stderr, "tcc: warning: %s: overriding compiler action already specified\n", optname);
    output_type_set = 1;
    S.output_type = t;
}

static void add_file(const char *name, int type)
{
    InFile *f = xcalloc(sizeof(InFile));
    f->name = xstrdup(name);
    f->type = type;
    pvec_push(&S.files, f);
}

char *tcc_basename(const char *name)
{
    char *p = strrchr(name, '/');
    return p ? p + 1 : (char *)name;
}

char *tcc_fileextension(const char *name)
{
    char *b = tcc_basename(name);
    char *e = strrchr(b, '.');
    return e ? e : strchr(b, 0);
}

int file_type_from_name(const char *name)
{
    const char *ext = tcc_fileextension(name);
    if (ext[0] == '.') ext++;
    if (!strcmp(ext, "S")) return FT_ASMPP;
    if (!strcmp(ext, "s")) return FT_ASM;
    if (!strcmp(ext, "c") || !strcmp(ext, "h") || !strcmp(ext, "i")) return FT_C;
    if (!*ext) return FT_C;  /* no extension: C */
    return FT_OBJ; /* object/library/other */
}

static int parse_args(int argc, char **argv);

static int parse_listfile(const char *name)
{
    int len;
    char *data;
    int fd = open(name, O_RDONLY);
    char **av = NULL;
    int ac = 0, cap = 0;
    char *p, *q;
    if (fd < 0)
        tcc_fatal("listfile '%s' not found", name);
    {
        struct stat st;
        fstat(fd, &st);
        len = st.st_size;
        data = xmalloc(len + 1);
        len = read(fd, data, len);
        if (len < 0) len = 0;
        data[len] = 0;
        close(fd);
    }
    p = data;
    for (;;) {
        while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
        if (!*p) break;
        q = p;
        if (*p == '"' || *p == '\'') {
            int qc = *p++;
            q = p;
            while (*p && *p != qc) p++;
            if (*p) *p++ = 0;
        } else {
            while (*p && *p != ' ' && *p != '\t' && *p != '\n' && *p != '\r') p++;
            if (*p) *p++ = 0;
        }
        if (ac >= cap) { cap = cap ? cap * 2 : 16; av = xrealloc(av, cap * sizeof(char *)); }
        av[ac++] = q;
    }
    parse_args(ac, av);
    return 0;
}

static int next_filetype = FT_NONE;
static int run_mode_argi = -1;
static char **g_argv;
static int g_argc;

/* returns index of first run argument or -1 */
static int parse_args(int argc, char **argv)
{
    int i;
    for (i = 0; i < argc; i++) {
        const char *a = argv[i];
        const char *arg;
#define NEED_ARG(optname) do { \
            if (a[strlen(optname)]) arg = a + strlen(optname); \
            else if (i + 1 < argc) arg = argv[++i]; \
            else tcc_fatal("argument to '%s' is missing", optname); \
        } while (0)
        if (a[0] == '@' && a[1]) {
            parse_listfile(a + 1);
            continue;
        }
        if (a[0] != '-' || a[1] == 0) {
            int ft = next_filetype != FT_NONE ? next_filetype : file_type_from_name(a);
            add_file(a, ft);
            if (S.output_type == OUT_MEMORY && run_mode_argi < 0 && g_argv) {
                /* in -run mode, following args go to the program */
                run_mode_argi = i + 1;
                return i + 1;
            }
            continue;
        }
        /* options */
        if (!strcmp(a, "-c")) { set_output_type(OUT_OBJ, "-c"); continue; }
        if (!strcmp(a, "-E")) { set_output_type(OUT_PREPROCESS, "-E"); continue; }
        if (!strcmp(a, "-r")) { set_output_type(OUT_OBJ, "-r"); S.output_type = OUT_OBJ; /* relocatable */ S.static_link |= 0; S.rdynamic |= 0; S.gen_deps |= 0; extern int opt_reloc; opt_reloc = 1; continue; }
        if (!strcmp(a, "-shared")) { set_output_type(OUT_DLL, "-shared"); continue; }
        if (!strcmp(a, "-run")) {
            set_output_type(OUT_MEMORY, "-run");
            continue;
        }
        if (!strcmp(a, "-rstdin")) { NEED_ARG("-rstdin"); S.run_stdin = xstrdup(arg); continue; }
        if (!strcmp(a, "-o")) { NEED_ARG("-o"); if (S.outfile) fprintf(stderr, "tcc: warning: multiple -o option\n"); S.outfile = xstrdup(arg); continue; }
        if (!strncmp(a, "-o", 2)) { if (S.outfile) fprintf(stderr, "tcc: warning: multiple -o option\n"); S.outfile = xstrdup(a + 2); continue; }
        if (!strcmp(a, "-v") || !strcmp(a, "--version") || !strcmp(a, "-version")) { S.verbose++; continue; }
        if (!strcmp(a, "-vv")) { S.verbose += 2; continue; }
        if (!strcmp(a, "-vvv")) { S.verbose += 3; continue; }
        if (!strcmp(a, "-h") || !strcmp(a, "-?") || !strcmp(a, "--help")) { fputs(help_text, stdout); exit(0); }
        if (!strcmp(a, "-hh")) { fputs(help2_text, stdout); exit(0); }
        if (!strcmp(a, "-bench")) { S.do_bench = 1; continue; }
        if (!strcmp(a, "-w")) { S.warn_none = 1; continue; }
        if (!strncmp(a, "-W", 2)) {
            if (!strncmp(a, "-Wl,", 4)) { set_linker_option(a + 4); continue; }
            if (!strncmp(a, "-Wp,", 4)) {
                char *copy = xstrdup(a + 4), *p = copy, *q;
                for (;;) {
                    q = strchr(p, ',');
                    if (q) *q = 0;
                    parse_args(1, &p);
                    if (!q) break;
                    p = q + 1;
                }
                continue;
            }
            set_W_option(a + 2);
            continue;
        }
        if (!strncmp(a, "-f", 2) && a[2]) { set_f_option(a + 2); continue; }
        if (!strncmp(a, "-m", 2) && a[2]) { set_m_option(a + 2); continue; }
        if (!strcmp(a, "-I")) { NEED_ARG("-I"); pvec_push(&S.include_paths, xstrdup(arg)); continue; }
        if (!strncmp(a, "-I", 2)) { pvec_push(&S.include_paths, xstrdup(a + 2)); continue; }
        if (!strcmp(a, "-isystem")) { NEED_ARG("-isystem"); pvec_push(&S.sysinclude_paths, xstrdup(arg)); continue; }
        if (!strcmp(a, "-include")) { NEED_ARG("-include"); pvec_push(&S.cmdline_incl, xstrdup(arg)); continue; }
        if (!strcmp(a, "-D")) { NEED_ARG("-D"); { char *d = xmalloc(strlen(arg) + 2); sprintf(d, "D%s", arg); pvec_push(&S.cmdline_defs, d); } continue; }
        if (!strncmp(a, "-D", 2)) { char *d = xmalloc(strlen(a)); sprintf(d, "D%s", a + 2); pvec_push(&S.cmdline_defs, d); continue; }
        if (!strcmp(a, "-U")) { NEED_ARG("-U"); { char *d = xmalloc(strlen(arg) + 2); sprintf(d, "U%s", arg); pvec_push(&S.cmdline_defs, d); } continue; }
        if (!strncmp(a, "-U", 2)) { char *d = xmalloc(strlen(a)); sprintf(d, "U%s", a + 2); pvec_push(&S.cmdline_defs, d); continue; }
        if (!strcmp(a, "-L")) { NEED_ARG("-L"); pvec_push(&S.library_paths, xstrdup(arg)); continue; }
        if (!strncmp(a, "-L", 2)) { pvec_push(&S.library_paths, xstrdup(a + 2)); continue; }
        if (!strcmp(a, "-l")) { NEED_ARG("-l"); { char buf[1024]; snprintf(buf, sizeof buf, "-l%s", arg); add_file(buf, FT_LIB); nb_libraries++; } continue; }
        if (!strncmp(a, "-l", 2)) { add_file(a, FT_LIB); nb_libraries++; continue; }
        if (!strcmp(a, "-B")) { NEED_ARG("-B"); S.tcc_lib_path = xstrdup(arg); continue; }
        if (!strncmp(a, "-B", 2)) { S.tcc_lib_path = xstrdup(a + 2); continue; }
        if (!strcmp(a, "-nostdinc")) { S.nostdinc = 1; continue; }
        if (!strcmp(a, "-nostdlib")) { S.nostdlib = 1; continue; }
        if (!strcmp(a, "-static")) { S.static_link = 1; continue; }
        if (!strcmp(a, "-rdynamic")) { S.rdynamic = 1; continue; }
        if (!strcmp(a, "-soname")) { NEED_ARG("-soname"); S.soname = xstrdup(arg); continue; }
        if (!strcmp(a, "-pthread")) { S.pthread = 1; add_file("-lpthread", FT_LIB); nb_libraries++; continue; }
        if (!strcmp(a, "-b")) { S.do_bounds_check = 1; S.do_debug = 1; continue; }
        if (!strncmp(a, "-bt", 3)) { S.do_backtrace = 1; S.rt_num_callers = a[3] ? atoi(a + 3) : 6; S.do_debug = 1; continue; }
        if (!strcmp(a, "-g")) { S.do_debug = 1; continue; }
        if (!strncmp(a, "-g", 2)) { S.do_debug = 1; continue; }
        if (!strncmp(a, "-std=", 5)) {
            if (!strcmp(a + 5, "c11") || !strcmp(a + 5, "gnu11")) S.cversion = 201112;
            else if (!strcmp(a + 5, "c99") || !strcmp(a + 5, "gnu99") || !strcmp(a + 5, "c89") || !strcmp(a + 5, "gnu89")) S.cversion = 199901;
            continue;
        }
        if (!strncmp(a, "-O", 2)) {
            if (a[2] == 0) S.optimize = 1;
            else if (a[2] >= '0' && a[2] <= '9') S.optimize = atoi(a + 2);
            else S.optimize = 1;
            continue;
        }
        if (!strcmp(a, "-x")) {
            NEED_ARG("-x");
            goto set_x;
        }
        if (!strncmp(a, "-x", 2)) {
            arg = a + 2;
        set_x:
            if (*arg == 'c') next_filetype = FT_C;
            else if (*arg == 'a') next_filetype = FT_ASMPP;
            else if (*arg == 'b') next_filetype = FT_BIN;
            else if (*arg == 'n') next_filetype = FT_NONE;
            else fprintf(stderr, "tcc: warning: unsupported language '%s'\n", arg);
            continue;
        }
        if (!strcmp(a, "-M")) { S.just_deps = 1; S.gen_deps = 1; continue; }
        if (!strcmp(a, "-MM")) { S.just_deps = 1; S.gen_deps = 2; continue; }
        if (!strcmp(a, "-MD")) { S.gen_deps = 1; continue; }
        if (!strcmp(a, "-MMD")) { S.gen_deps = 2; continue; }
        if (!strcmp(a, "-MF")) { NEED_ARG("-MF"); S.deps_outfile = xstrdup(arg); continue; }
        if (!strcmp(a, "-MP")) { continue; }
        if (!strcmp(a, "-P")) { S.pflag = PFLAG_NONE; continue; }
        if (!strncmp(a, "-P", 2)) { S.pflag = a[2] == '1' ? PFLAG_STD : (a[2] == '2' ? PFLAG_NORMAL : PFLAG_NONE); if (!strcmp(a+2, "1")) S.pflag = PFLAG_STD; continue; }
        if (!strncmp(a, "-d", 2)) {
            const char *p = a + 2;
            if (!strcmp(p, "umpversion")) { printf("%s\n", TCC_VERSION); exit(0); }
            for (; *p; p++) {
                if (*p == 'D') S.dflag |= 1;
                else if (*p == 'M') S.dflag |= 2;
                else if (*p == 't') S.dflag |= 16;
            }
            continue;
        }
        if (!strcmp(a, "-print-search-dirs")) { S.verbose = 0; extern int opt_print_search_dirs; opt_print_search_dirs = 1; continue; }
        if (!strcmp(a, "-dumpversion")) { printf("%s\n", TCC_VERSION); exit(0); }
        if (!strcmp(a, "-ar")) { extern int opt_ar; opt_ar = i; return -2; }
        if (!strcmp(a, "-arch") || !strcmp(a, "-C") || !strcmp(a, "--param") || !strcmp(a, "-pedantic")
            || !strcmp(a, "-pipe") || !strcmp(a, "-s") || !strcmp(a, "-traditional")) {
            if (S.warn_unsupported)
                fprintf(stderr, "tcc: warning: unsupported option '%s'\n", a);
            if (!strcmp(a, "-arch") || !strcmp(a, "--param")) {
                /* these take an argument */
                if (i + 1 < argc) i++;
            }
            continue;
        }
        if (!strcmp(a, "--")) {
            /* rest are run args */
            continue;
        }
        tcc_fatal("invalid option -- '%s'", a);
    }
    return -1;
}

int opt_reloc;
int opt_print_search_dirs;
int opt_ar = -1;

/* ---------------------------------------------------------------- */
/* compilation driver (implemented in compile.c) */
int tcc_compile_file(InFile *f, const char *outname);
int tcc_preprocess_file(InFile *f, FILE *out);
int tcc_link_output(const char *outfile);
int tcc_run_output(int argc, char **argv);

static void setup_paths(void)
{
    if (!S.tcc_lib_path)
        S.tcc_lib_path = xstrdup(TCC_INSTALL_DIR);
    if (!S.nostdinc) {
        char buf[1024];
        snprintf(buf, sizeof buf, "%s/include", S.tcc_lib_path);
        pvec_push(&S.sysinclude_paths, xstrdup(buf));
        pvec_push(&S.sysinclude_paths, xstrdup("/usr/local/include/x86_64-linux-gnu"));
        pvec_push(&S.sysinclude_paths, xstrdup("/usr/local/include"));
        pvec_push(&S.sysinclude_paths, xstrdup("/usr/include/x86_64-linux-gnu"));
        pvec_push(&S.sysinclude_paths, xstrdup("/usr/include"));
    }
    {
        char buf[1024];
        /* library paths: tcc dir first, then standard */
        PVec lp;
        int i;
        memset(&lp, 0, sizeof lp);
        pvec_push(&lp, xstrdup(S.tcc_lib_path));
        pvec_push(&lp, xstrdup("/usr/lib/x86_64-linux-gnu"));
        pvec_push(&lp, xstrdup("/usr/lib"));
        pvec_push(&lp, xstrdup("/lib/x86_64-linux-gnu"));
        pvec_push(&lp, xstrdup("/lib"));
        pvec_push(&lp, xstrdup("/usr/local/lib/x86_64-linux-gnu"));
        pvec_push(&lp, xstrdup("/usr/local/lib"));
        /* user -L paths come first */
        for (i = 0; i < lp.len; i++)
            pvec_push(&S.library_paths, lp.p[i]);
        pvec_push(&S.crt_paths, xstrdup("/usr/lib/x86_64-linux-gnu"));
        (void)buf;
    }
}

static char *default_outname(const char *first, const char *ext)
{
    char *base = tcc_basename(first);
    char *e = tcc_fileextension(base);
    char *out = xmalloc(strlen(base) + strlen(ext) + 1);
    snprintf(out, strlen(base) + strlen(ext) + 1, "%.*s%s", (int)(e - base), base, ext);
    return out;
}

static char *replace_ext(const char *name, const char *ext)
{
    char *e = tcc_fileextension(name);
    char *out = xmalloc(strlen(name) + strlen(ext) + 1);
    snprintf(out, strlen(name) + strlen(ext) + 1, "%.*s%s", (int)(e - name), name, ext);
    return out;
}

int main(int argc, char **argv)
{
    int ret = 0;
    int run_argi;
    int i;
    const char *first_file = NULL;
    FILE *ppout = NULL;

    S.cversion = 199901;
    S.warn_implicit_function_declaration = 1;
    S.warn_discarded_qualifiers = 1;
    S.dollars_in_identifiers = 1;
    S.unwind_tables = 1;
    S.output_type = OUT_EXE;
    S.pflag = PFLAG_NORMAL;
    pp_init();

    g_argv = argv;
    g_argc = argc;
    run_argi = parse_args(argc - 1, argv + 1);
    if (opt_ar >= 0)
        return tcc_tool_ar(argc - opt_ar - 2, argv + opt_ar + 2);
    if (run_argi >= 0)
        run_argi += 1; /* skip argv[0] */

    setup_paths();

    if (opt_print_search_dirs) {
        print_search_dirs();
        return 0;
    }
    if (S.verbose && S.files.len == 0) {
        print_version();
        if (S.verbose >= 2)
            print_search_dirs();
        return 0;
    }
    if (S.files.len == 0) {
        if (S.verbose == 0 && argc == 1) {
            fputs(help_text, stdout);
            return 0;
        }
        tcc_fatal("no input files");
    }
    if (S.verbose)
        print_version();

    /* count source files */
    {
        int nsrc = 0;
        for (i = 0; i < S.files.len; i++) {
            InFile *f = S.files.p[i];
            if (f->type != FT_LIB && f->type != FT_OBJ) nsrc++;
            if (!first_file && f->type != FT_LIB) first_file = f->name;
        }
        if (S.output_type == OUT_OBJ && !opt_reloc && S.outfile && nsrc > 1)
            tcc_fatal("cannot specify output file with -c many files");
        if (!first_file)
            first_file = ((InFile *)S.files.p[0])->name;
    }

    if (S.output_type == OUT_PREPROCESS) {
        if (S.outfile && strcmp(S.outfile, "-")) {
            ppout = fopen(S.outfile, "w");
            if (!ppout)
                tcc_fatal("could not write '%s'", S.outfile);
        } else
            ppout = stdout;
        S.ppfp = ppout;
    }

    for (i = 0; i < S.files.len; i++) {
        InFile *f = S.files.p[i];
        if (f->type == FT_LIB)
            continue;
        if (S.output_type == OUT_PREPROCESS) {
            if (f->type == FT_OBJ)
                continue;
            if (S.verbose) printf("-> %s\n", f->name);
            ret = tcc_preprocess_file(f, ppout);
            if (ret) break;
            continue;
        }
        if (S.output_type == OUT_OBJ && !opt_reloc) {
            char *outname;
            if (f->type == FT_OBJ)
                continue;
            if (S.just_deps) {
                ret = tcc_compile_file(f, NULL);
            } else {
                outname = S.outfile ? xstrdup(S.outfile) : default_outname(f->name, ".o");
                if (S.verbose) printf("-> %s\n", f->name);
                ret = tcc_compile_file(f, outname);
                if (!ret && S.verbose) printf("<- %s\n", outname);
            }
            if (ret) break;
            continue;
        }
        /* link modes: compile everything into one module */
        if (S.verbose) printf("-> %s\n", f->name);
        ret = tcc_compile_file(f, NULL);
        if (ret) break;
    }
    if (S.just_deps && !ret) {
        /* -M: print dependencies */
        FILE *df = stdout;
        char *target;
        if (S.deps_outfile) {
            df = fopen(S.deps_outfile, "w");
            if (!df) tcc_fatal("could not write '%s'", S.deps_outfile);
        }
        target = S.outfile ? xstrdup(S.outfile) : default_outname(first_file, ".o");
        pp_print_deps(df, target);
        if (df != stdout) fclose(df);
        return ret ? 1 : 0;
    }
    if (S.gen_deps && !ret) {
        char *dname;
        FILE *df;
        char *target;
        if (S.deps_outfile)
            dname = xstrdup(S.deps_outfile);
        else if (S.outfile)
            dname = replace_ext(S.outfile, ".d");
        else
            dname = default_outname(first_file, ".d");
        target = S.outfile ? xstrdup(S.outfile) : default_outname(first_file, ".o");
        if (S.output_type == OUT_OBJ && !S.outfile)
            target = default_outname(first_file, ".o");
        df = fopen(dname, "w");
        if (df) {
            pp_print_deps(df, target);
            fclose(df);
        }
    }
    if (ret)
        return 1;
    if (S.output_type == OUT_PREPROCESS) {
        if (ppout != stdout) fclose(ppout);
        return 0;
    }
    if (S.output_type == OUT_OBJ && !opt_reloc)
        return 0;
    if (S.output_type == OUT_MEMORY) {
        return tcc_run_output(run_argi >= 0 ? argc - run_argi : 0, run_argi >= 0 ? argv + run_argi : NULL);
    }
    {
        char *outfile = S.outfile ? S.outfile : (S.output_type == OUT_DLL ? default_outname(first_file, ".so") : (opt_reloc ? default_outname(first_file, ".o") : "a.out"));
        ret = tcc_link_output(outfile);
        if (!ret && S.verbose) printf("<- %s\n", outfile);
    }
    return ret ? 1 : 0;
}
EOF
echo ok"}

