#define TCC_INSTALL_DIR "/usr/local/lib/tcc"

static void print_version(void)
{
    printf("tcc version %s %s (x86_64 Linux)\n", TCC_VERSION, TCC_BUILD_INFO);
}

static void print_paths(const char *msg, PVec *v)
{
    int i;
    printf("%s:\n%s", msg, v->len ? "" : "  -\n");
    for (i = 0; i < v->len; i++)
        printf("  %s\n", (char *)v->p[i]);
}

static void print_search_dirs(void)
{
    PVec crt;
    PVec l1;
    memset(&crt, 0, sizeof crt);
    memset(&l1, 0, sizeof l1);
    printf("install: %s\n", S.tcc_lib_path);
    /* include: user + system */
    {
        PVec all;
        int i;
        memset(&all, 0, sizeof all);
        for (i = 0; i < S.include_paths.len; i++) pvec_push(&all, S.include_paths.p[i]);
        for (i = 0; i < S.sysinclude_paths.len; i++) pvec_push(&all, S.sysinclude_paths.p[i]);
        print_paths("include", &all);
    }
    print_paths("libraries", &S.library_paths);
    {
        char buf[1024];
        snprintf(buf, sizeof buf, "%s/libtcc1.a", S.tcc_lib_path);
        pvec_push(&l1, xstrdup(buf));
        print_paths("libtcc1", &l1);
    }
    print_paths("crt", &S.crt_paths);
    printf("elfinterp:\n  %s\n", "/lib64/ld-linux-x86-64.so.2");
}

/* ---------------------------------------------------------------- */

int tcc_warning_flags[8];  /* named warnings: 0 off, 1 on, 2 error */
enum { WF_WRITE_STRINGS, WF_UNSUPPORTED, WF_IMPLICIT_FUNC, WF_DISCARDED_QUALIFIERS, WF_ALL };

static void set_W_option(const char *opt)
{
    int no = 0, err = 0;
    const char *p = opt;
    if (!strcmp(p, "all")) { S.warn_all = 1; S.warn_implicit_function_declaration = 1; S.warn_discarded_qualifiers = 1; return; }
    if (!strcmp(p, "no-all")) { S.warn_implicit_function_declaration = 0; S.warn_discarded_qualifiers = 0; return; }
    if (!strncmp(p, "no-", 3)) { no = 1; p += 3; }
    if (!strncmp(p, "error", 5) && (p[5] == 0 || p[5] == '=')) {
        if (p[5] == 0) {
            S.warn_error = !no;
            return;
        }
        p += 6;
        err = 1;
    }
    if (!strcmp(p, "all")) {
        int v = no ? 0 : (err ? 2 : 1);
        S.warn_implicit_function_declaration = v;
        S.warn_discarded_qualifiers = v;
        return;
    }
    {
        int *target = NULL;
        if (!strcmp(p, "write-strings")) target = &S.warn_write_strings;
        else if (!strcmp(p, "unsupported")) target = &S.warn_unsupported;
        else if (!strcmp(p, "implicit-function-declaration")) target = &S.warn_implicit_function_declaration;
        else if (!strcmp(p, "discarded-qualifiers")) target = &S.warn_discarded_qualifiers;
        if (target) {
            if (err) {
                /* -Werror=x: set to error; -Wno-error=x: back to on */
                *target = no ? 1 : 2;
            } else
                *target = no ? 0 : 1;
            return;
        }
        if (err)
            return;
    }
    if (S.warn_unsupported)
        fprintf(stderr, "tcc: warning: unsupported option '-W%s'\n", opt);
}

static void set_f_option(const char *opt)
{
    int no = 0;
    const char *p = opt;
    if (!strncmp(p, "no-", 3)) { no = 1; p += 3; }
    if (!strcmp(p, "unsigned-char")) S.char_is_unsigned = !no;
    else if (!strcmp(p, "signed-char")) S.char_is_unsigned = no;
    else if (!strcmp(p, "common")) S.common = !no;
    else if (!strcmp(p, "leading-underscore")) S.leading_underscore = !no;
    else if (!strcmp(p, "ms-extensions")) S.ms_extensions = !no;
    else if (!strcmp(p, "dollars-in-identifiers")) S.dollars_in_identifiers = !no;
    else if (!strcmp(p, "reverse-funcargs")) S.reverse_funcargs = !no;
    else if (!strcmp(p, "gnu89-inline")) S.gnu89_inline = !no;
    else if (!strcmp(p, "asynchronous-unwind-tables")) S.unwind_tables = !no;
    else if (!strcmp(p, "test-coverage")) S.test_coverage = !no;
    else if (S.warn_unsupported)
        fprintf(stderr, "tcc: warning: unsupported option '-f%s'\n", opt);
}

static void set_m_option(const char *opt)
{
    int no = 0;
    const char *p = opt;
    if (!strncmp(p, "no-", 3)) { no = 1; p += 3; }
    if (!strcmp(p, "ms-bitfields")) S.ms_bitfields = !no;
    else if (!strcmp(p, "sse")) S.nosse = no;
    else if (!strcmp(opt, "32") || !strcmp(opt, "64")) {
        /* -m32: defer to i386-tcc */
        if (!strcmp(opt, "32")) {
            fprintf(stderr, "tcc: could not run '%s'\n", "/workspace/i386-tcc");
            exit(1);
        }
    } else if (S.warn_unsupported)
        fprintf(stderr, "tcc: warning: unsupported option '-m%s'\n", opt);
}

static uint64_t parse_num_arg(const char *s)
{
    return strtoull(s, NULL, 0);
}

static void set_linker_option(const char *opt)
{
    const char *p;
    while (*opt) {
        char buf[1024];
        const char *end = strchr(opt, ',');
        int len = end ? (int)(end - opt) : (int)strlen(opt);
        snprintf(buf, sizeof buf, "%.*s", len, opt);
        p = buf;
        if (!strcmp(p, "-Bsymbolic")) S.symbolic = 1;
        else if (!strcmp(p, "-nostdlib")) S.nostdlib = 1;
        else if (!strcmp(p, "-whole-archive") || !strcmp(p, "-no-whole-archive")) ;
        else if (!strcmp(p, "-export-all-symbols") || !strcmp(p, "-export-dynamic") || !strcmp(p, "--export-dynamic")) S.rdynamic = 1;
        else if (!strncmp(p, "-image-base=", 12)) { S.text_addr = parse_num_arg(p + 12); S.has_text_addr = 1; }
        else if (!strncmp(p, "-Ttext=", 7)) { S.text_addr = parse_num_arg(p + 7); S.has_text_addr = 1; }
        else if (!strncmp(p, "-section-alignment=", 19)) S.section_align = parse_num_arg(p + 19);
        else if (!strncmp(p, "-rpath=", 7)) {
            if (S.rpath) {
                char *n = xmalloc(strlen(S.rpath) + strlen(p + 7) + 2);
                sprintf(n, "%s:%s", S.rpath, p + 7);
                free(S.rpath);
                S.rpath = n;
            } else
                S.rpath = xstrdup(p + 7);
        }
        else if (!strcmp(p, "-enable-new-dtags")) S.enable_new_dtags = 1;
        else if (!strncmp(p, "-soname=", 8)) S.soname = xstrdup(p + 8);
        else if (!strncmp(p, "-I", 2)) S.elfint = xstrdup(p + 2);
        else if (!strncmp(p, "-dynamic-linker=", 16)) S.elfint = xstrdup(p + 16);
        else if (!strncmp(p, "-oformat=", 9)) ;
        else if (!strncmp(p, "-init=", 6)) S.init_symbol = xstrdup(p + 6);
        else if (!strncmp(p, "-fini=", 6)) S.fini_symbol = xstrdup(p + 6);
        else if (!strncmp(p, "-Map=", 5)) ;
        else if (!strcmp(p, "-as-needed") || !strcmp(p, "--as-needed") || !strcmp(p, "-O") || !strncmp(p, "-O", 2) || !strncmp(p, "-z", 2)) ;
        else if (!strncmp(p, "-e=", 3)) S.entryname = xstrdup(p + 3);
        else {
            tcc_fatal("unsupported linker option '%s'", p);
        }
        if (!end)
            break;
        opt = end + 1;
    }
}

/* ---------------------------------------------------------------- */

static int output_type_set;
static int nb_libraries;

static void set_output_type(int t, const char *optname)
{
    if (output_type_set)
        fprintf(stderr, "tcc: warning: %s: overriding compiler action already specified\n", optname);
    output_type_set = 1;
    S.output_type = t;
}

static void add_file(const char *name, int type)
{
    InFile *f = xcalloc(sizeof(InFile));
    f->name = xstrdup(name);
    f->type = type;
    pvec_push(&S.files, f);
}

char *tcc_basename(const char *name)
{
    char *p = strrchr(name, '/');
    return p ? p + 1 : (char *)name;
}

char *tcc_fileextension(const char *name)
{
    char *b = tcc_basename(name);
    char *e = strrchr(b, '.');
    return e ? e : strchr(b, 0);
}

int file_type_from_name(const char *name)
{
    const char *ext = tcc_fileextension(name);
    if (ext[0] == '.') ext++;
    if (!strcmp(ext, "S")) return FT_ASMPP;
    if (!strcmp(ext, "s")) return FT_ASM;
    if (!strcmp(ext, "c") || !strcmp(ext, "h") || !strcmp(ext, "i")) return FT_C;
    if (!*ext) return FT_C;  /* no extension: C */
    return FT_OBJ; /* object/library/other */
}

static int parse_args(int argc, char **argv);

static int parse_listfile(const char *name)
{
    int len;
    char *data;
    int fd = open(name, O_RDONLY);
    char **av = NULL;
    int ac = 0, cap = 0;
    char *p, *q;
    if (fd < 0)
        tcc_fatal("listfile '%s' not found", name);
    {
        struct stat st;
        fstat(fd, &st);
        len = st.st_size;
        data = xmalloc(len + 1);
        len = read(fd, data, len);
        if (len < 0) len = 0;
        data[len] = 0;
        close(fd);
    }
    p = data;
    for (;;) {
        while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
        if (!*p) break;
        q = p;
        if (*p == '"' || *p == '\'') {
            int qc = *p++;
            q = p;
            while (*p && *p != qc) p++;
            if (*p) *p++ = 0;
        } else {
            while (*p && *p != ' ' && *p != '\t' && *p != '\n' && *p != '\r') p++;
            if (*p) *p++ = 0;
        }
        if (ac >= cap) { cap = cap ? cap * 2 : 16; av = xrealloc(av, cap * sizeof(char *)); }
        av[ac++] = q;
    }
    parse_args(ac, av);
    return 0;
}

static int next_filetype = FT_NONE;
static int run_mode_argi = -1;
static char **g_argv;
static int g_argc;

/* returns index of first run argument or -1 */
static int parse_args(int argc, char **argv)
{
    int i;
    for (i = 0; i < argc; i++) {
        const char *a = argv[i];
        const char *arg;
#define NEED_ARG(optname) do { \
            if (a[strlen(optname)]) arg = a + strlen(optname); \
            else if (i + 1 < argc) arg = argv[++i]; \
            else tcc_fatal("argument to '%s' is missing", optname); \
        } while (0)
        if (a[0] == '@' && a[1]) {
            parse_listfile(a + 1);
            continue;
        }
        if (a[0] != '-' || a[1] == 0) {
            int ft = next_filetype != FT_NONE ? next_filetype : file_type_from_name(a);
            add_file(a, ft);
            if (S.output_type == OUT_MEMORY && run_mode_argi < 0 && g_argv) {
                /* in -run mode, following args go to the program */
                run_mode_argi = i + 1;
                return i + 1;
            }
            continue;
        }
        /* options */
        if (!strcmp(a, "-c")) { set_output_type(OUT_OBJ, "-c"); continue; }
        if (!strcmp(a, "-E")) { set_output_type(OUT_PREPROCESS, "-E"); continue; }
        if (!strcmp(a, "-r")) { set_output_type(OUT_OBJ, "-r"); S.output_type = OUT_OBJ; /* relocatable */ S.static_link |= 0; S.rdynamic |= 0; S.gen_deps |= 0; extern int opt_reloc; opt_reloc = 1; continue; }
        if (!strcmp(a, "-shared")) { set_output_type(OUT_DLL, "-shared"); continue; }
        if (!strcmp(a, "-run")) {
            set_output_type(OUT_MEMORY, "-run");
            continue;
        }
        if (!strcmp(a, "-rstdin")) { NEED_ARG("-rstdin"); S.run_stdin = xstrdup(arg); continue; }
        if (!strcmp(a, "-o")) { NEED_ARG("-o"); if (S.outfile) fprintf(stderr, "tcc: warning: multiple -o option\n"); S.outfile = xstrdup(arg); continue; }
        if (!strncmp(a, "-o", 2)) { if (S.outfile) fprintf(stderr, "tcc: warning: multiple -o option\n"); S.outfile = xstrdup(a + 2); continue; }
        if (!strcmp(a, "-v") || !strcmp(a, "--version") || !strcmp(a, "-version")) { S.verbose++; continue; }
        if (!strcmp(a, "-vv")) { S.verbose += 2; continue; }
        if (!strcmp(a, "-vvv")) { S.verbose += 3; continue; }
        if (!strcmp(a, "-h") || !strcmp(a, "-?") || !strcmp(a, "--help")) { fputs(help_text, stdout); exit(0); }
        if (!strcmp(a, "-hh")) { fputs(help2_text, stdout); exit(0); }
        if (!strcmp(a, "-bench")) { S.do_bench = 1; continue; }
        if (!strcmp(a, "-w")) { S.warn_none = 1; continue; }
        if (!strncmp(a, "-W", 2)) {
            if (!strncmp(a, "-Wl,", 4)) { set_linker_option(a + 4); continue; }
            if (!strncmp(a, "-Wp,", 4)) {
                char *copy = xstrdup(a + 4), *p = copy, *q;
                for (;;) {
                    q = strchr(p, ',');
                    if (q) *q = 0;
                    parse_args(1, &p);
                    if (!q) break;
                    p = q + 1;
                }
                continue;
            }
            set_W_option(a + 2);
            continue;
        }
        if (!strncmp(a, "-f", 2) && a[2]) { set_f_option(a + 2); continue; }
        if (!strncmp(a, "-m", 2) && a[2]) { set_m_option(a + 2); continue; }
        if (!strcmp(a, "-I")) { NEED_ARG("-I"); pvec_push(&S.include_paths, xstrdup(arg)); continue; }
        if (!strncmp(a, "-I", 2)) { pvec_push(&S.include_paths, xstrdup(a + 2)); continue; }
        if (!strcmp(a, "-isystem")) { NEED_ARG("-isystem"); pvec_push(&S.sysinclude_paths, xstrdup(arg)); continue; }
        if (!strcmp(a, "-include")) { NEED_ARG("-include"); pvec_push(&S.cmdline_incl, xstrdup(arg)); continue; }
        if (!strcmp(a, "-D")) { NEED_ARG("-D"); { char *d = xmalloc(strlen(arg) + 2); sprintf(d, "D%s", arg); pvec_push(&S.cmdline_defs, d); } continue; }
        if (!strncmp(a, "-D", 2)) { char *d = xmalloc(strlen(a)); sprintf(d, "D%s", a + 2); pvec_push(&S.cmdline_defs, d); continue; }
        if (!strcmp(a, "-U")) { NEED_ARG("-U"); { char *d = xmalloc(strlen(arg) + 2); sprintf(d, "U%s", arg); pvec_push(&S.cmdline_defs, d); } continue; }
        if (!strncmp(a, "-U", 2)) { char *d = xmalloc(strlen(a)); sprintf(d, "U%s", a + 2); pvec_push(&S.cmdline_defs, d); continue; }
        if (!strcmp(a, "-L")) { NEED_ARG("-L"); pvec_push(&S.library_paths, xstrdup(arg)); continue; }
        if (!strncmp(a, "-L", 2)) { pvec_push(&S.library_paths, xstrdup(a + 2)); continue; }
        if (!strcmp(a, "-l")) { NEED_ARG("-l"); { char buf[1024]; snprintf(buf, sizeof buf, "-l%s", arg); add_file(buf, FT_LIB); nb_libraries++; } continue; }
        if (!strncmp(a, "-l", 2)) { add_file(a, FT_LIB); nb_libraries++; continue; }
