        if (!strcmp(a, "-nostdlib")) { S.nostdlib = 1; continue; }
        if (!strcmp(a, "-static")) { S.static_link = 1; continue; }
        if (!strcmp(a, "-rdynamic")) { S.rdynamic = 1; continue; }
        if (!strcmp(a, "-soname")) { NEED_ARG("-soname"); S.soname = xstrdup(arg); continue; }
        if (!strcmp(a, "-pthread")) { S.pthread = 1; add_file("-lpthread", FT_LIB); nb_libraries++; continue; }
