    Tok t;
    Tok *copy = xmalloc(sizeof(Tok) * (n ? n : 1));
    int k, serial;
    memcpy(copy, in, sizeof(Tok) * n);
    push_frame(copy, n, 1);
    k = nframes - 1;
    serial = frames[k].serial = ++frame_serial_counter;
    for (;;) {
        /* drop exhausted frames above ours */
        while (nframes - 1 > k && frames[nframes - 1].pos >= frames[nframes - 1].len)
            pop_frame();
        if (k >= nframes || frames[k].serial != serial)
            break;  /* our frame was consumed by a nested expansion */
        if (nframes - 1 == k && frames[k].pos >= frames[k].len) {
