static int expand_macro(Tok *t, TokVec *out)
{
    Ident *id;
    Macro *m;
    TokVec tmp;

    if (t->id < TOK_IDENT)
        return 0;
    if (pp_defined_state > 0) {
        if (t->id != ' ') pp_defined_state--;
        return 0;
    }
    if (pp_expr_mode && t->id == TOK_DEFINED) {
        pp_defined_state = 1; /* following ident (or '(' ident ')') raw */
        return 0;
    }
    if (t->id == TOK___LINE__ || t->id == TOK___FILE__ || t->id == TOK___COUNTER__
        || t->id == TOK___DATE__ || t->id == TOK___TIME__) {
        if (!ident_get(t->id)->mac) {
            builtin_macro(t, out);
            return 1;
        }
    }
    id = ident_get(t->id);
    m = id->mac;
    if (!m)
        return 0;
    if (hs_has(t->hs, t->id))
        return 0;
    memset(&tmp, 0, sizeof tmp);
    if (!m->is_func) {
        const HS *hs = hs_add(t->hs, m->id);
        subst_macro(m, NULL, NULL, NULL, hs, &tmp);
    } else {
        /* look ahead for '(' */
        TokVec skipped;
        Tok rparen;
        TokVec *raw;
        int nargs, i;
        TokVec *args;
        Tok **raw_ptrs;
        int *raw_lens;
        const HS *hs;
        int saw_lf = 0, found = 0;

        memset(&skipped, 0, sizeof skipped);
        for (;;) {
            if (nframes > 0) {
                Frame *f = &frames[nframes - 1];
                if (f->pos < f->len) {
                    Tok *ft = &f->t[f->pos];
                    if (ft->id == ' ' || ft->id == TOK_LINEFEED) {
                        tv_push_tok(&skipped, ft);
                        f->pos++;
                        continue;
                    }
                    if (ft->id == '(') {
                        f->pos++;
                        found = 1;
                    }
                    break;
                }
                pop_frame();
                continue;
            }
            /* character level in file */
            {
                int c = pc();
                Tok w;
                w.hs = NULL;
                if (is_space_char(c)) {
                    w.id = ' '; w.s = c == '\t' ? "\t" : " ";
                    tv_push_tok(&skipped, &w);
                    adv();
                    continue;
                }
                if (c == '\n') {
                    w.id = TOK_LINEFEED; w.s = NULL;
                    tv_push_tok(&skipped, &w);
                    adv();
                    file->line_num++;
                    saw_lf = 1;
                    continue;
                }
                if (c == '/') {
                    const char *save = file->p;
                    int saveline = file->line_num;
                    adv();
                    c = pc();
                    if (c == '*') {
                        adv();
                        skip_comment();
                        w.id = ' '; w.s = " ";
                        tv_push_tok(&skipped, &w);
                        continue;
                    }
                    if (c == '/') {
                        adv();
                        skip_line_comment();
                        w.id = ' '; w.s = " ";
                        tv_push_tok(&skipped, &w);
                        continue;
                    }
                    file->p = save;
                    file->line_num = saveline;
                    break;
                }
                if (c == '(') {
                    adv();
                    found = 1;
                }
                break;
            }
        }
        if (!found) {
            if (skipped.len)
                push_frame(skipped.t, skipped.len, 1);
            else
                tv_free(&skipped);
            if (saw_lf)
                tok_bol = 1;
            return 0;
        }
        tv_free(&skipped);
        collect_args(m, &raw, &nargs, &rparen);
        args = xcalloc(sizeof(TokVec) * (m->nparams + 1));
        raw_ptrs = xcalloc(sizeof(Tok *) * (m->nparams + 1));
        raw_lens = xcalloc(sizeof(int) * (m->nparams + 1));
        for (i = 0; i < m->nparams; i++) {
            if (i < nargs) {
                raw_ptrs[i] = raw[i].t;
                raw_lens[i] = raw[i].len;
            } else {
                raw_ptrs[i] = NULL;
                raw_lens[i] = 0;
            }
        }
        /* pre-expand args that are used without # / ## */
        for (i = 0; i < m->nparams; i++) {
            int used_plain = 0, j;
            Tok *body = m->body.t;
            for (j = 0; j < m->body.len; j++) {
                if (body[j].id == m->params[i]) {
                    int before = 0, after = 0, k;
                    k = j - 1;
                    while (k >= 0 && body[k].id == ' ') k--;
                    if (k >= 0 && (body[k].id == TOK_TWOSHARPS || body[k].id == '#')) before = 1;
                    k = j + 1;
                    while (k < m->body.len && body[k].id == ' ') k++;
                    if (k < m->body.len && body[k].id == TOK_TWOSHARPS) after = 1;
                    /* GNU comma case: , ## __VA_ARGS__ uses expanded arg when non-empty */
                    if (before && m->variadic && i == m->nparams - 1) {
                        int k2 = k - 1;
                        while (k2 >= 0 && body[k2].id == ' ') k2--;
                        /* k2 is at '##'; check ',' before it */
                        if (k2 >= 1 && body[k2 - 1].id == ',')
                            before = 0;
                    }
                    if (!before && !after) { used_plain = 1; break; }
                }
            }
            if (used_plain && raw_lens[i] > 0)
                expand_list(raw_ptrs[i], raw_lens[i], &args[i]);
            tv_normalize(&args[i]);
        }
        hs = hs_add(hs_inter(t->hs, rparen.hs), m->id);
        subst_macro(m, args, raw_ptrs, raw_lens, hs, &tmp);
        for (i = 0; i < m->nparams; i++)
            tv_free(&args[i]);
        for (i = 0; i <= nargs && i < m->nparams + 1; i++)
            tv_free(&raw[i]);
        free(raw);
        free(args);
        free(raw_ptrs);
        free(raw_lens);
    }
    /* eagerly rescan the result (nested macros), then normalize spaces */
    {
        TokVec fin;
        memset(&fin, 0, sizeof fin);
        if (tmp.len)
            expand_list(tmp.t, tmp.len, &fin);
        tv_free(&tmp);
        tv_normalize(&fin);
        {
            int i;
            for (i = 0; i < fin.len; i++)
                tv_push_tok(out, &fin.t[i]);
        }
        tv_free(&fin);
    }
    return 1;
}

/* get next token with macro expansion (raw spaces/LF included) */
static void next_expanded(Tok *t)
{
    for (;;) {
        get_tok_raw(t);
        if (t->id >= TOK_IDENT) {
            TokVec res;
            memset(&res, 0, sizeof res);
            if (expand_macro(t, &res)) {
                if (res.len)
                    push_frame(res.t, res.len, 1);
                else
                    tv_free(&res);
                continue;
            }
        } else if (pp_defined_state > 0 && t->id != ' ')
            pp_defined_state--;
        return;
    }
}

/* Expand a token list; nested macro invocations may read beyond the list
   (into enclosing frames or the file), like the original compiler does. */
static void expand_list(Tok *in, int n, TokVec *out)
{
    Tok t;
    Tok *copy = xmalloc(sizeof(Tok) * (n ? n : 1));
    int k, serial;
    memcpy(copy, in, sizeof(Tok) * n);
    push_frame(copy, n, 1);
    k = nframes - 1;
    serial = frames[k].serial = ++frame_serial_counter;
    for (;;) {
        /* drop exhausted frames above ours */
        while (nframes - 1 > k && frames[nframes - 1].pos >= frames[nframes - 1].len)
            pop_frame();
        if (k >= nframes || frames[k].serial != serial)
            break;  /* our frame was consumed by a nested expansion */
        if (nframes - 1 == k && frames[k].pos >= frames[k].len) {
            pop_frame();
            break;
        }
        get_tok_raw(&t);
        if (t.id == TOK_LINEFEED) { t.id = ' '; t.s = " "; }
        if (t.id >= TOK_IDENT && expand_macro(&t, out))
            continue;
        if (t.id < TOK_IDENT && pp_defined_state > 0 && t.id != ' ')
            pp_defined_state--;
        tv_push_tok(out, &t);
    }
}

