new = r'''/* number parsing: result types */
typedef struct NumVal {
    int is_float;      /* 0: integer, 1: float, 2: double, 3: long double */
    int uns;           /* unsigned */
    int longlong;      /* 64-bit integer */
    uint64_t u;
    long double f;
} NumVal;

static int digit_val(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'z') return c - 'a' + 10;
    if (c >= 'A' && c <= 'Z') return c - 'A' + 10;
    return 100;
}

/* parse a pp-number spelling into a value; emits errors on malformed numbers */
void parse_number(const char *s, NumVal *nv)
{
    const char *p = s;
    int base = 10;
    int is_float = 0;
    memset(nv, 0, sizeof *nv);

    if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) {
        base = 16;
        p += 2;
    } else if (p[0] == '0' && (p[1] == 'b' || p[1] == 'B')) {
        base = 2;
        p += 2;
    }
    /* scan digits to find whether it is a float */
    {
        const char *q = p;
        while (digit_val(*q) < base || (base == 16 && digit_val(*q) < 16))
            q++;
        if (*q == '.' || ((base == 16 && (*q == 'p' || *q == 'P')) ||
                          (base != 16 && base != 2 && (*q == 'e' || *q == 'E'))))
            is_float = 1;
        if (base == 10 && !is_float && p[0] == '0' && p[1])
            base = 8;
    }
    if (is_float) {
        /* floating point: use strtold on a normalized copy */
        char buf[512];
        int n = 0;
        const char *q = p;
        int seen_digits = 0;
        if (base == 16) { buf[n++] = '0'; buf[n++] = 'x'; }
        while (digit_val(*q) < (base == 16 ? 16 : 10)) { buf[n++] = *q++; seen_digits = 1; }
        if (*q == '.') {
            buf[n++] = *q++;
            while (digit_val(*q) < (base == 16 ? 16 : 10)) { buf[n++] = *q++; seen_digits = 1; }
        }
        if (base == 16) {
            if (*q != 'p' && *q != 'P')
                tcc_error("exponent expected");
        }
        if (*q == 'e' || *q == 'E' || *q == 'p' || *q == 'P') {
            buf[n++] = *q++;
            if (*q == '+' || *q == '-') buf[n++] = *q++;
            if (!(*q >= '0' && *q <= '9'))
                tcc_error("exponent digits expected");
            while (*q >= '0' && *q <= '9') buf[n++] = *q++;
        }
        buf[n] = 0;
        (void)seen_digits;
        nv->f = strtold(buf, NULL);
        nv->is_float = 2;
        if (*q == 'f' || *q == 'F') { nv->is_float = 1; q++; }
        else if (*q == 'l' || *q == 'L') { nv->is_float = 3; q++; }
        if (*q)
            tcc_error("invalid number");
        return;
    }
