static int digit_val(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'z') return c - 'a' + 10;
    if (c >= 'A' && c <= 'Z') return c - 'A' + 10;
    return 100;
}

/* parse a pp-number spelling into a value; emits errors on malformed numbers */
void parse_number(const char *s, NumVal *nv)
{
    const char *p = s;
    int base = 10;
    int is_float = 0;
    memset(nv, 0, sizeof *nv);

    if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) {
        base = 16;
        p += 2;
    } else if (p[0] == '0' && (p[1] == 'b' || p[1] == 'B')) {
        base = 2;
        p += 2;
    }
    /* scan digits to find whether it is a float */
    {
        const char *q = p;
        while (digit_val(*q) < base || (base == 16 && digit_val(*q) < 16))
            q++;
        if (*q == '.' || ((base == 16 && (*q == 'p' || *q == 'P')) ||
                          (base != 16 && base != 2 && (*q == 'e' || *q == 'E'))))
            is_float = 1;
        if (base == 10 && !is_float && p[0] == '0' && p[1])
            base = 8;
    }
    if (is_float) {
        /* floating point: use strtold on a normalized copy */
        char buf[512];
        int n = 0;
        const char *q = p;
        int seen_digits = 0;
        if (base == 16) { buf[n++] = '0'; buf[n++] = 'x'; }
        while (digit_val(*q) < (base == 16 ? 16 : 10)) { buf[n++] = *q++; seen_digits = 1; }
        if (*q == '.') {
            buf[n++] = *q++;
            while (digit_val(*q) < (base == 16 ? 16 : 10)) { buf[n++] = *q++; seen_digits = 1; }
        }
        if (base == 16) {
            if (*q != 'p' && *q != 'P')
                tcc_error("exponent expected");
        }
        if (*q == 'e' || *q == 'E' || *q == 'p' || *q == 'P') {
            buf[n++] = *q++;
            if (*q == '+' || *q == '-') buf[n++] = *q++;
            if (!(*q >= '0' && *q <= '9'))
                tcc_error("exponent digits expected");
            while (*q >= '0' && *q <= '9') buf[n++] = *q++;
        }
        buf[n] = 0;
        (void)seen_digits;
        nv->f = strtold(buf, NULL);
        nv->is_float = 2;
        if (*q == 'f' || *q == 'F') { nv->is_float = 1; q++; }
        else if (*q == 'l' || *q == 'L') { nv->is_float = 3; q++; }
        if (*q)
            tcc_error("invalid number");
        return;
    }
    /* integer */
    {
        uint64_t v = 0;
        int overflow = 0;
        uint64_t trunc_val = 0;
        int uns = 0, nl = 0;
        for (;;) {
            int d = digit_val(*p);
            if (d >= base) {
                if ((base == 8 || base == 2) && *p >= '0' && *p <= '9')
                    tcc_error("invalid digit");
                break;
            }
            if (!overflow && v > (UINT64_MAX - d) / base) {
                overflow = 1;
                trunc_val = v;
            }
            v = v * base + d;
            p++;
        }
        for (;;) {
            int c = *p;
            if (c == 'u' || c == 'U') {
                if (uns)
                    tcc_error("two 'u's in integer constant");
                uns = 1;
                p++;
            } else if (c == 'l' || c == 'L') {
                nl++;
                p++;
                if (*p == c) { p++; nl++; }
            } else
                break;
        }
        if (*p)
            tcc_error("invalid number");
        if (overflow) {
            tcc_warning("integer constant overflow, using %llu, did you mean %llu?",
                        (unsigned long long)v, (unsigned long long)trunc_val);
        } else if (base == 10 && !uns && v > (uint64_t)INT64_MAX) {
            tcc_warning("integer constant overflow, using %llu, did you mean %llu?",
                        (unsigned long long)v, (unsigned long long)v);
        }
        nv->u = v;
        {
            int is_ll = 0, is_u = uns;
            if (nl == 0) {
                if (uns) {
                    if (v > 0xffffffffULL) is_ll = 1;
                } else {
                    if (v <= 0x7fffffffULL) ;
                    else if (base != 10 && v <= 0xffffffffULL) is_u = 1;
                    else if (v <= 0x7fffffffffffffffULL) is_ll = 1;
                    else { is_ll = 1; is_u = 1; }
                }
            } else {
                is_ll = 1;
                if (!uns && v > 0x7fffffffffffffffULL) is_u = 1;
            }
            nv->uns = is_u;
            nv->longlong = is_ll;
        }
    }
}

