output.arguments:
{"command":"cd /workspace/src && cat > types.c <<'EOF'
#include "cc.h"

Type *type_void, *type_int, *type_uint, *type_char, *type_uchar, *type_schar, *type_short, *type_ushort,
    *type_long, *type_ulong, *type_llong, *type_ullong, *type_float, *type_double, *type_ldouble,
    *type_bool, *type_charptr, *type_voidptr, *type_size_t, *type_ptrdiff_t;

Type *type_new(int kind)
{
    Type *t = xcalloc(sizeof(Type));
    t->kind = kind;
    t->len = -1;
    return t;
}

static Type *type_basic(int kind, int uns)
{
    Type *t = type_new(kind);
    t->uns = uns;
    return t;
}

void types_init(void)
{
    type_void = type_basic(T_VOID, 0);
    type_bool = type_basic(T_BOOL, 1);
    type_char = type_basic(T_CHAR, S.char_is_unsigned);
    type_uchar = type_basic(T_CHAR, 1);
    type_schar = type_basic(T_CHAR, 0);
    type_short = type_basic(T_SHORT, 0);
    type_ushort = type_basic(T_SHORT, 1);
    type_int = type_basic(T_INT, 0);
    type_uint = type_basic(T_INT, 1);
    type_long = type_basic(T_LONG, 0);
    type_ulong = type_basic(T_LONG, 1);
    type_llong = type_basic(T_LLONG, 0);
    type_ullong = type_basic(T_LLONG, 1);
    type_float = type_basic(T_FLOAT, 0);
    type_double = type_basic(T_DOUBLE, 0);
    type_ldouble = type_basic(T_LDOUBLE, 0);
    type_charptr = type_ptr(type_char);
    type_voidptr = type_ptr(type_void);
    type_size_t = type_ulong;
    type_ptrdiff_t = type_long;
}

Type *type_ptr(Type *t)
{
    Type *p = type_new(T_PTR);
    p->ref = t;
    return p;
}

Type *type_array(Type *t, int len)
{
    Type *p = type_new(T_ARRAY);
    p->ref = t;
    p->len = len;
    return p;
}

Type *type_qual(Type *t, int quals)
{
    Type *n;
    if ((t->quals | quals) == t->quals)
        return t;
    n = xmalloc(sizeof(Type));
    *n = *t;
    n->quals |= quals;
    return n;
}

Type *type_unqual(Type *t)
{
    Type *n;
    if (!t->quals)
        return t;
    n = xmalloc(sizeof(Type));
    *n = *t;
    n->quals = 0;
    return n;
}

int is_integer(Type *t)
{
    return t->kind >= T_BOOL && t->kind <= T_LLONG || t->kind == T_ENUM;
}
int is_float(Type *t) { return t->kind >= T_FLOAT && t->kind <= T_LDOUBLE; }
int is_arith(Type *t) { return is_integer(t) || is_float(t); }
int is_ptr(Type *t) { return t->kind == T_PTR; }
int is_scalar(Type *t) { return is_arith(t) || is_ptr(t); }
int is_func(Type *t) { return t->kind == T_FUNC; }
int is_array(Type *t) { return t->kind == T_ARRAY; }
int is_struct(Type *t) { return t->kind == T_STRUCT || t->kind == T_UNION; }
int is_void(Type *t) { return t->kind == T_VOID; }

/* size in bytes, -1 if incomplete */
int type_size(Type *t, int *align)
{
    int a = 1, s;
    switch (t->kind) {
    case T_VOID: s = 1; a = 1; break;
    case T_BOOL: case T_CHAR: s = 1; a = 1; break;
    case T_SHORT: s = 2; a = 2; break;
    case T_INT: case T_ENUM: s = 4; a = 4; break;
    case T_LONG: case T_LLONG: s = 8; a = 8; break;
    case T_FLOAT: s = 4; a = 4; break;
    case T_DOUBLE: s = 8; a = 8; break;
    case T_LDOUBLE: s = 16; a = 16; break;
    case T_PTR: s = 8; a = 8; break;
    case T_FUNC: s = 1; a = 1; break;
    case T_ARRAY: {
        int ea;
        int es = type_size(t->ref, &ea);
        a = ea;
        if (t->len < 0 || es < 0) s = -1;
        else s = es * t->len;
        break;
    }
    case T_STRUCT: case T_UNION:
        if (!t->sym || t->sym->size < 0) { s = -1; a = t->sym ? (t->sym->align > 0 ? t->sym->align : 1) : 1; }
        else { s = t->sym->size; a = t->sym->align; }
        break;
    default: s = -1; a = 1;
    }
    if (t->align > a)
        a = t->align;
    if (align) *align = a;
    return s;
}

int type_align(Type *t)
{
    int a;
    type_size(t, &a);
    return a;
}

int type_rank(Type *t)
{
    switch (t->kind) {
    case T_BOOL: return 1;
    case T_CHAR: return 2;
    case T_SHORT: return 3;
    case T_INT: case T_ENUM: return 4;
    case T_LONG: return 5;
    case T_LLONG: return 6;
    case T_FLOAT: return 7;
    case T_DOUBLE: return 8;
    case T_LDOUBLE: return 9;
    }
    return 0;
}

/* integer promotion */
Type *type_promote(Type *t)
{
    if (t->kind == T_BOOL || t->kind == T_CHAR || t->kind == T_SHORT)
        return type_int;
    if (t->kind == T_ENUM)
        return t->uns ? type_uint : type_int;
    return type_unqual(t);
}

Type *type_common_arith(Type *a, Type *b)
{
    int ra, rb;
    if (a->kind == T_LDOUBLE || b->kind == T_LDOUBLE) return type_ldouble;
    if (a->kind == T_DOUBLE || b->kind == T_DOUBLE) return type_double;
    if (a->kind == T_FLOAT || b->kind == T_FLOAT) return type_float;
    a = type_promote(a);
    b = type_promote(b);
    ra = type_rank(a); rb = type_rank(b);
    if (ra == rb) {
        if (a->uns) return a;
        return b;
    }
    if (ra < rb) { Type *t = a; a = b; b = t; }
    /* a has higher rank */
    if (a->uns) return a;
    /* a signed, b lower rank: if a can represent all of b */
    if (!b->uns) return a;
    /* b unsigned lower rank: long vs unsigned int -> long */
    return a;
}

static int params_compatible(Type *a, Type *b)
{
    Sym *pa, *pb;
    if (a->oldstyle || b->oldstyle)
        return 1;
    if (a->variadic != b->variadic || a->nparams != b->nparams)
        return 0;
    for (pa = a->params, pb = b->params; pa && pb; pa = pa->next, pb = pb->next) {
        if (!type_compatible(pa->type, pb->type, 0))
            return 0;
    }
    return 1;
}

int type_compatible(Type *a, Type *b, int strict_quals)
{
    if (a == b) return 1;
    if (strict_quals && a->quals != b->quals) return 0;
    {
        int ka = a->kind, kb = b->kind;
        if (ka == T_ENUM) ka = T_INT;
        if (kb == T_ENUM) kb = T_INT;
        if (ka != kb) {
            /* long and long long are compatible here (both 64 bit) */
            if ((ka == T_LONG && kb == T_LLONG) || (ka == T_LLONG && kb == T_LONG))
                ;
            else
                return 0;
        }
    }
    switch (a->kind) {
    case T_PTR:
        return type_compatible(a->ref, b->ref, 1);
    case T_ARRAY:
        if (a->len >= 0 && b->len >= 0 && a->len != b->len) return 0;
        return type_compatible(a->ref, b->ref, 1);
    case T_FUNC:
        if (!type_compatible(a->ref, b->ref, 0)) return 0;
        return params_compatible(a, b);
    case T_STRUCT: case T_UNION:
        return a->sym == b->sym;
    default:
        if (a->kind == T_ENUM || b->kind == T_ENUM)
            return 1;
        return a->uns == b->uns || a->kind == T_BOOL;
    }
}

static void type_to_str1(CStr *cs, Type *t, const char *inner);

static const char *basic_name(Type *t)
{
    switch (t->kind) {
    case T_VOID: return "void";
    case T_BOOL: return "_Bool";
    case T_CHAR: return t->uns ? "unsigned char" : "char";
    case T_SHORT: return t->uns ? "unsigned short" : "short";
    case T_INT: return t->uns ? "unsigned int" : "int";
    case T_LONG: return t->uns ? "unsigned long" : "long";
    case T_LLONG: return t->uns ? "unsigned long long" : "long long";
    case T_FLOAT: return "float";
    case T_DOUBLE: return "double";
    case T_LDOUBLE: return "long double";
    }
    return "?";
}

void type_to_str(CStr *cs, Type *t, const char *varname)
{
    type_to_str1(cs, t, varname);
}

static void type_to_str1(CStr *cs, Type *t, const char *inner)
{
    CStr tmp;
    switch (t->kind) {
    case T_PTR: {
        cstr_init(&tmp);
        cstr_ccat(&tmp, '*');
        if (t->quals & Q_CONST) cstr_cat(&tmp, " const", -1);
        if (t->quals & Q_VOLATILE) cstr_cat(&tmp, " volatile", -1);
        if (inner && *inner) {
            if (t->ref->kind == T_FUNC || t->ref->kind == T_ARRAY) {
                cstr_cat(&tmp, inner, -1);
            } else
                cstr_cat(&tmp, inner, -1);
        }
        if (t->ref->kind == T_FUNC || t->ref->kind == T_ARRAY) {
            CStr p;
            cstr_init(&p);
            cstr_ccat(&p, '(');
            cstr_cat(&p, tmp.data, tmp.len);
            cstr_ccat(&p, ')');
            type_to_str1(cs, t->ref, p.data);
            cstr_free(&p);
        } else
            type_to_str1(cs, t->ref, tmp.data);
        cstr_free(&tmp);
        return;
    }
    case T_ARRAY: {
        cstr_init(&tmp);
        if (inner) cstr_cat(&tmp, inner, -1);
        if (t->len >= 0) cstr_printf(&tmp, "[%d]", t->len);
        else cstr_cat(&tmp, "[]", -1);
        type_to_str1(cs, t->ref, tmp.data);
        cstr_free(&tmp);
        return;
    }
    case T_FUNC: {
        Sym *p;
        cstr_init(&tmp);
        if (inner) cstr_cat(&tmp, inner, -1);
        cstr_ccat(&tmp, '(');
        for (p = t->params; p; p = p->next) {
            type_to_str1(&tmp, p->type, NULL);
            if (p->next || t->variadic) cstr_cat(&tmp, ", ", -1);
        }
        if (t->variadic) cstr_cat(&tmp, "...", -1);
        cstr_ccat(&tmp, ')');
        type_to_str1(cs, t->ref, tmp.data);
        cstr_free(&tmp);
        return;
    }
    case T_STRUCT: case T_UNION: case T_ENUM:
        if (t->quals & Q_CONST) cstr_cat(cs, "const ", -1);
        if (t->quals & Q_VOLATILE) cstr_cat(cs, "volatile ", -1);
        cstr_cat(cs, t->kind == T_STRUCT ? "struct " : t->kind == T_UNION ? "union " : "enum ", -1);
        if (t->sym && t->sym->id)
