static ScopeEntry *scope_stack;
static int scope_sp, scope_cap;
static int *scope_marks;
static int scope_marks_cap;

static Sym **slot_ptr(Ident *id, int slot)
{
    switch (slot) {
    case 0: return &id->sym_id;
    case 1: return &id->sym_struct;
    default: return &id->sym_label;
    }
}

Sym *sym_push(int slot, int id, int kind, Type *type)
{
    Sym *s = xcalloc(sizeof(Sym));
    s->id = id;
    s->kind = kind;
    s->type = type;
    s->scope = cur_scope;
    s->size = -1;
    s->binding_slot = slot;
    if (id) {
