            if (scope_sp >= scope_cap) {
                scope_cap = scope_cap ? scope_cap * 2 : 256;
                scope_stack = xrealloc(scope_stack, scope_cap * sizeof(ScopeEntry));
            }
            scope_stack[scope_sp].ident = ident;
            scope_stack[scope_sp].slot = slot;
            scope_stack[scope_sp].prev = s->prev_binding;
            scope_sp++;
        }
    }
