}

Sym *sym_global(int id, int kind, Type *type)
{
    int save = cur_scope;
    Sym *s;
    cur_scope = 0;
    s = sym_push(0, id, kind, type);
    cur_scope = save;
    /* global pushed while in a scope: it must not be popped; insert below */
    if (save > 0 && id) {
