        if (*p == s && s->prev_binding) {
            /* move s to the end of the chain */
            Sym *q = s->prev_binding;
            *p = q;
            while (q->prev_binding) q = q->prev_binding;
            q->prev_binding = s;
            s->prev_binding = NULL;
            /* scope stack entries pointing to NULL prev stay valid: when the
               innermost binding is popped, prev becomes the one below. However
               the entry whose prev was NULL must now point to s. */
            {
