    if (a->kind == T_DOUBLE || b->kind == T_DOUBLE) return type_double;
    if (a->kind == T_FLOAT || b->kind == T_FLOAT) return type_float;
    a = type_promote(a);
    b = type_promote(b);
    ra = type_rank(a); rb = type_rank(b);
    if (ra == rb) {
        if (a->uns) return a;
        return b;
    }
    if (ra < rb) { Type *t = a; a = b; b = t; }
