actions.command:
cd /workspace/src && cat > parse.c <<'EOF'
/* C parser: builds typed AST, performs semantic checks */
#include "cc.h"

Sym *cur_func;
int nocode_wanted;
int gen_errors;
static Type *func_ret_type;
static PVec func_labels;      /* Sym* labels of current function */
static int in_switch, in_loop;
static Node *cur_switch;
static int local_static_counter;
static int anon_counter;
static int pack_stack[16], pack_sp, cur_pack;
static int func_vla_depth;

void types_init(void);
void sym_unbind_label(int id);

/* ---------------------------------------------------------------- */
/* helpers */

static const char *cur_tok_str(void)
{
    if (tok == TOK_EOF)
        return "<eof>";
    return get_tok_str(tok, tokstr);
}

static void skip_tok(int c)
{
    if (tok != c)
        tcc_error("'%s' expected (got '%s')", tok_name(c), cur_tok_str());
    next();
}

static void expect_err(const char *msg)
{
    tcc_error("%s expected", msg);
}

static int is_type_qualifier(int t)
{
    return t == TOK_CONST1 || t == TOK_CONST2 || t == TOK_CONST3 || t == TOK_VOLATILE1
        || t == TOK_VOLATILE2 || t == TOK_VOLATILE3 || t == TOK_RESTRICT1 || t == TOK_RESTRICT2
        || t == TOK_RESTRICT3 || t == TOK_ATOMIC;
}

static int is_typedef_name(int t)
{
    Sym *s;
    if (t < TOK_IDENT) return 0;
    s = sym_find_id(t);
    return s && s->kind == SYM_TYPEDEF;
}

/* is current token the start of a type? */
static int is_type_start(int t)
{
    switch (t) {
    case TOK_INT: case TOK_VOID: case TOK_CHAR: case TOK_UNSIGNED: case TOK_LONG: case TOK_SIGNED1:
    case TOK_SIGNED2: case TOK_SIGNED3: case TOK_FLOAT: case TOK_DOUBLE: case TOK_BOOL: case TOK_COMPLEX:
    case TOK_SHORT: case TOK_STRUCT: case TOK_UNION: case TOK_ENUM: case TOK_TYPEDEF: case TOK_EXTERN:
    case TOK_STATIC: case TOK_AUTO: case TOK_REGISTER: case TOK_INLINE1: case TOK_INLINE2: case TOK_INLINE3:
    case TOK_CONST1: case TOK_CONST2: case TOK_CONST3: case TOK_VOLATILE1: case TOK_VOLATILE2: case TOK_VOLATILE3:
    case TOK_RESTRICT1: case TOK_RESTRICT2: case TOK_RESTRICT3: case TOK_EXTENSION: case TOK_THREAD_LOCAL:
    case TOK_TYPEOF1: case TOK_TYPEOF2: case TOK_TYPEOF3: case TOK_ATTRIBUTE1: case TOK_ATTRIBUTE2:
    case TOK_ALIGNAS: case TOK_NORETURN: case TOK_ATOMIC: case TOK_builtin_va_list:
        return 1;
    }
    return is_typedef_name(t);
}

/* ---------------------------------------------------------------- */
/* attributes */

typedef struct Attrs {
    int aligned;
    int packed;
    int weak;
    int unused;
    int noreturn;
    int always_inline;
    int constructor, destructor;
    int visibility;
    char *section;
    char *alias;
    char *asm_name;
    int cleanup_fn;
    int mode;  /* 1 QI 2 HI 4 SI 8 DI */
    int dllexport, dllimport;
    int nodecorate;
} Attrs;

static Node *parse_assignment_expr(void);
static Node *parse_cond_expr(void);
static int64_t parse_const_int_expr(void);
static Type *parse_type_name(void);
static Node *parse_cast_expr(void);

static void skip_parens_balanced(void)
{
    int depth = 0;
    for (;;) {
        if (tok == '(') depth++;
        else if (tok == ')') { if (depth == 0) return; depth--; }
        else if (tok == TOK_EOF) return;
        next();
    }
}

static void parse_attribute_list(Attrs *ad)
{
    skip_tok('(');
    skip_tok('(');
    while (tok != ')') {
        int t;
        if (tok < TOK_IDENT)
            expect_err("attribute name");
        t = tok;
        next();
        switch (t) {
        case TOK_SECTION1: case TOK_SECTION2:
            skip_tok('(');
            if (tok != TOK_STR) expect_err("section name");
            {
                CStr cs; int w, c;
                cstr_init(&cs);
                parse_string_literal(tokstr, &cs, &w, &c);
                ad->section = xstrdup(cs.data ? cs.data : "");
                cstr_free(&cs);
            }
            next();
            skip_tok(')');
            break;
        case TOK_ALIAS1: case TOK_ALIAS2:
            skip_tok('(');
            if (tok != TOK_STR) expect_err("alias(\"target\")");
            {
                CStr cs; int w, c;
                cstr_init(&cs);
                parse_string_literal(tokstr, &cs, &w, &c);
                ad->alias = xstrdup(cs.data ? cs.data : "");
                cstr_free(&cs);
            }
            next();
            skip_tok(')');
            break;
        case TOK_VISIBILITY1: case TOK_VISIBILITY2:
            skip_tok('(');
            if (tok != TOK_STR) expect_err("visibility(\"default|hidden|protected|internal\")");
            {
                CStr cs; int w, c;
                cstr_init(&cs);
                parse_string_literal(tokstr, &cs, &w, &c);
                if (cs.data) {
                    if (!strcmp(cs.data, "default")) ad->visibility = 0;
                    else if (!strcmp(cs.data, "hidden")) ad->visibility = 2;
                    else if (!strcmp(cs.data, "protected")) ad->visibility = 3;
                    else if (!strcmp(cs.data, "internal")) ad->visibility = 1;
                    else tcc_error("unknown visibility \"%s\"", cs.data);
                }
                cstr_free(&cs);
            }
            next();
            skip_tok(')');
            break;
        case TOK_ALIGNED1: case TOK_ALIGNED2:
            if (tok == '(') {
                int n;
                next();
                n = parse_const_int_expr();
                if (n <= 0 || (n & (n - 1)) != 0)
                    tcc_error("alignment must be a positive power of two");
                skip_tok(')');
                ad->aligned = n;
            } else
                ad->aligned = 16;
            break;
        case TOK_PACKED1: case TOK_PACKED2:
            ad->packed = 1;
            break;
        case TOK_WEAK1: case TOK_WEAK2:
            ad->weak = 1;
            break;
        case TOK_UNUSED1: case TOK_UNUSED2:
            ad->unused = 1;
            break;
        case TOK_NORETURN1: case TOK_NORETURN2:
            ad->noreturn = 1;
            break;
        case TOK_ALWAYS_INLINE1: case TOK_ALWAYS_INLINE2:
            ad->always_inline = 1;
            break;
        case TOK_CONSTRUCTOR1: case TOK_CONSTRUCTOR2:
            ad->constructor = 1;
            break;
        case TOK_DESTRUCTOR1: case TOK_DESTRUCTOR2:
            ad->destructor = 1;
            break;
        case TOK_CLEANUP1: case TOK_CLEANUP2:
            skip_tok('(');
            if (tok < TOK_IDENT) expect_err("identifier");
            ad->cleanup_fn = tok;
            next();
            skip_tok(')');
            break;
        case TOK_MODE:
            skip_tok('(');
            switch (tok) {
            case TOK_MODE_QI: ad->mode = 1; break;
            case TOK_MODE_HI: ad->mode = 2; break;
            case TOK_MODE_SI: ad->mode = 4; break;
            case TOK_MODE_DI: case TOK_MODE_word: ad->mode = 8; break;
            default:
                tcc_warning("__mode__ attribute ignored");
                break;
            }
            next();
            skip_tok(')');
            break;
        case TOK_DLLEXPORT: ad->dllexport = 1; break;
        case TOK_DLLIMPORT: ad->dllimport = 1; break;
        case TOK_NODECORATE: ad->nodecorate = 1; break;
        case TOK_CDECL1: case TOK_CDECL2: case TOK_CDECL3:
        case TOK_STDCALL1: case TOK_STDCALL2: case TOK_STDCALL3:
        case TOK_FASTCALL1: case TOK_FASTCALL2: case TOK_FASTCALL3:
            break;
        case TOK_REGPARM1: case TOK_REGPARM2:
            skip_tok('(');
            parse_const_int_expr();
            skip_tok(')');
            break;
        default:
            if (S.warn_unsupported)
                tcc_warning("'%s' attribute ignored", tok_name(t));
            /* skip arguments */
            if (tok == '(') {
                next();
                skip_parens_balanced();
                skip_tok(')');
            }
            break;
        }
        if (tok == ',')
            next();
    }
    skip_tok(')');
    skip_tok(')');
}

static void parse_attributes(Attrs *ad)
{
    for (;;) {
        if (tok == TOK_ATTRIBUTE1 || tok == TOK_ATTRIBUTE2) {
            next();
            parse_attribute_list(ad);
        } else if (tok == TOK_ASM1 || tok == TOK_ASM2 || tok == TOK_ASM3) {
            /* asm label */
            next();
            skip_tok('(');
            if (tok != TOK_STR) expect_err("string constant");
            {
                CStr cs; int w, c;
                cstr_init(&cs);
                parse_string_literal(tokstr, &cs, &w, &c);
                ad->asm_name = xstrdup(cs.data ? cs.data : "");
                cstr_free(&cs);
            }
            next();
            skip_tok(')');
        } else
            break;
    }
}

/* ---------------------------------------------------------------- */
/* struct / union / enum */

static int align_up(int v, int a) { return (v + a - 1) & ~(a - 1); }

static void parse_struct_or_union(Type *t, int is_union);
static void parse_enum(Type *t);

static Type *parse_type_specifier_struct(int kind)
{
    /* tok is after 'struct'/'union'/'enum' */
    Attrs ad;
    int id = 0;
    Sym *s;
    Type *t;
    memset(&ad, 0, sizeof ad);
    parse_attributes(&ad);
    if (tok >= TOK_IDENT) {
        id = tok;
        next();
    } else if (tok != '{') {
        expect_err("struct/union/enum name");
    }
    if (id) {
        s = sym_find_struct(id);
        if (s && (tok != '{' || s->scope == cur_scope)) {
            if (s->type->kind != kind) {
                tcc_error("redefinition of '%s'", tok_name(id));
            }
            t = s->type;
            if (tok == '{' && s->size >= 0)
                tcc_error("struct/union/enum already defined");
            if (tok == '{' && s->scope != cur_scope) {
                s = NULL; /* new definition in inner scope */
            }
        } else
            s = NULL;
    } else
        s = NULL;
    if (!s) {
        t = type_new(kind);
        s = sym_push(1, id, SYM_TAG, t);
        s->size = -1;
        s->align = 1;
        t->sym = s;
        t->len = -1;
    }
    if (tok == '{') {
        next();
        if (kind == T_ENUM)
            parse_enum(t);
        else
            parse_struct_or_union(t, kind == T_UNION);
        {
            Attrs ad2;
            memset(&ad2, 0, sizeof ad2);
            parse_attributes(&ad2);
            if (ad2.packed || ad.packed) {
                /* repack: handled by setting is_packed before parsing; re-layout */
            }
            if (ad2.aligned && kind != T_ENUM) {
                if (ad2.aligned > s->align) s->align = ad2.aligned;
                s->size = align_up(s->size, s->align);
            }
        }
    }
    return t;
}

static Type *parse_decl_specs(int *storage, Attrs *ad, int *has_type);
static Type *parse_declarator(Type *base, int *id, Attrs *ad, int abstract_ok);

static void layout_struct_fields(Sym *st, int is_union, Sym *fields, int packed)
{
    int offset = 0, maxalign = 1, size = 0;
    int bit_pos = 0;         /* current bit position within the current storage unit */
    int cur_unit_off = -1, cur_unit_size = 0;
    Sym *f;
    for (f = fields; f; f = f->next) {
        int fa, fs;
        fs = type_size(f->type, &fa);
        if (fs < 0) {
            if (f->type->kind == T_ARRAY && f->type->len < 0 && !f->next) {
                /* flexible array member */
                fs = 0;
            } else if (f->type->kind == T_ARRAY && f->type->len < 0) {
                tcc_error("field '%s' has incomplete type", f->id ? tok_name(f->id) : "");
            } else
                tcc_error("field '%s' has incomplete type", f->id ? tok_name(f->id) : "");
        }
        if (packed || st->is_packed) fa = 1;
        if (f->aligned_attr > fa) fa = f->aligned_attr;
        if (cur_pack && fa > cur_pack) fa = cur_pack;
        if (f->bit_size >= 0 && is_integer(f->type) && f->bit_size != -1) {
            /* bitfield */
            int bsize = f->bit_size;
            int tsize = type_size(f->type, NULL) * 8;
            if (bsize == 0) {
                /* force alignment to next unit */
                bit_pos = 0;
                cur_unit_off = -1;
                if (!is_union) offset = align_up(offset, fa);
                continue;
            }
            if (is_union) {
                f->offset = 0;
                f->bit_off = 0;
                if (tsize / 8 > size) size = tsize / 8;
            } else {
                /* GCC layout: a bitfield is placed at the current position if it fits
                   in the storage unit of its type starting at the aligned base */
                int unit = tsize / 8;
                int base = (offset / unit) * unit;  /* aligned base of current unit */
                int bitoff_in_unit;
                if (cur_unit_off < 0) {
                    bit_pos = offset * 8;
                }
                /* bit position measured from struct start */
                {
                    int bp = bit_pos;
                    int unit_start = (bp / (unit * 8)) * (unit * 8);
                    if (bp + bsize > unit_start + unit * 8 && !packed) {
                        /* does not fit: move to next unit */
                        bp = unit_start + unit * 8;
                    }
                    bitoff_in_unit = bp - (bp / (unit * 8)) * (unit * 8);
                    f->offset = (bp / (unit * 8)) * unit;
                    f->bit_off = bitoff_in_unit;
                    bit_pos = bp + bsize;
                    offset = (bit_pos + 7) / 8;
                    cur_unit_off = f->offset;
                    cur_unit_size = unit;
                    if (f->offset + unit > size) size = f->offset + unit;
                    if (offset > size) size = offset;
                }
                (void)base;
            }
            if (fa > maxalign) maxalign = fa;
            continue;
        }
        cur_unit_off = -1;
        if (is_union) {
            f->offset = 0;
            if (fs > size) size = fs;
        } else {
            offset = align_up(offset, fa);
            f->offset = offset;
            offset += fs;
            bit_pos = offset * 8;
            if (offset > size) size = offset;
        }
        if (fa > maxalign) maxalign = fa;
    }
    (void)cur_unit_size;
    if (st->align > maxalign) maxalign = st->align;
    st->align = maxalign;
    st->size = align_up(size, maxalign);
}

static void parse_struct_or_union(Type *t, int is_union)
{
    Sym *st = t->sym;
    Sym *fields = NULL, **plast = &fields;
    int packed = cur_pack == 1;
    st->fields = NULL;
    while (tok != '}') {
        int storage = 0;
        Attrs ad;
        Type *base;
        int has_type;
        memset(&ad, 0, sizeof ad);
        if (tok == TOK_STATIC_ASSERT) {
            extern void parse_static_assert(void);
            parse_static_assert();
            continue;
        }
        if (tok == ';') { next(); continue; }
        base = parse_decl_specs(&storage, &ad, &has_type);
        if (!has_type)
            expect_err("identifier");
        if (tok == ';' && (base->kind == T_STRUCT || base->kind == T_UNION) && (!base->sym->id || S.ms_extensions)) {
            /* anonymous struct/union member */
            Sym *f = xcalloc(sizeof(Sym));
            f->kind = SYM_FIELD;
            f->type = base;
            f->id = 0;
            f->bit_size = -1;
            f->anon_struct = 1;
            *plast = f;
            plast = &f->next;
            next();
            continue;
        }
        for (;;) {
            int id = 0;
            Type *ft;
            Attrs fad = ad;
            Sym *f;
            int bsize = -1;
            if (tok == ':') {
                ft = base;
            } else {
                ft = parse_declarator(base, &id, &fad, 0);
            }
            if (tok == ':') {
                next();
                bsize = parse_const_int_expr();
                if (!is_integer(ft))
                    tcc_error("bitfields must have scalar type");
                if (bsize < 0)
                    tcc_error("negative width in bit-field '%s'", id ? tok_name(id) : "");
                if (bsize > type_size(ft, NULL) * 8)
                    tcc_error("width of '%s' exceeds its type", id ? tok_name(id) : "");
                if (bsize == 0 && id)
                    tcc_error("zero width for bit-field '%s'", tok_name(id));
            }
            parse_attributes(&fad);
            if (!id && bsize < 0 && !(ft->kind == T_STRUCT || ft->kind == T_UNION))
                expect_err("identifier");
            if (ft->kind == T_FUNC)
                tcc_error("invalid type for field");
            {
                Sym *q;
                for (q = fields; q; q = q->next)
                    if (q->id && q->id == id)
                        tcc_error("duplicate member '%s'", tok_name(id));
            }
            f = xcalloc(sizeof(Sym));
            f->kind = SYM_FIELD;
            f->type = ft;
            f->id = id;
            f->bit_size = bsize;
            f->aligned_attr = fad.aligned;
            if (fad.packed) f->is_packed = 1;
            *plast = f;
            plast = &f->next;
            if (tok == ',') { next(); continue; }
            break;
        }
        skip_tok(';');
    }
    next(); /* '}' */
    st->fields = fields;
    layout_struct_fields(st, is_union, fields, packed);
    /* nested anonymous members: layout handled by offset of anon struct */
}

static void parse_enum(Type *t)
{
    int64_t val = 0;
    int has_neg = 0;
    uint64_t maxv = 0;
    Sym *st = t->sym;
    st->fields = NULL;
    {
        Sym **plast = &st->fields;
        while (tok != '}') {
            Sym *e;
            int id;
            Attrs ad;
            if (tok < TOK_IDENT)
                expect_err("identifier");
            id = tok;
            next();
            memset(&ad, 0, sizeof ad);
            parse_attributes(&ad);
            if (tok == '=') {
                next();
                val = parse_const_int_expr();
            }
            e = sym_push(0, id, SYM_ENUMCONST, t);
            e->ival = val;
            if (val < 0) has_neg = 1;
            else if ((uint64_t)val > maxv) maxv = val;
            {
                Sym *copy = xcalloc(sizeof(Sym));
                *copy = *e;
                copy->next = NULL;
                *plast = copy;
                plast = &copy->next;
            }
            val++;
            if (tok == ',') {
                next();
                continue;
            }
            if (tok != '}')
                skip_tok(',');
        }
    }
    next();
    st->size = 4;
    st->align = 4;
    t->uns = !has_neg && maxv > 0x7fffffff ? 1 : 0;
    if ((has_neg && maxv > 0x7fffffff) || maxv > 0xffffffff) {
        st->size = 8;
        st->align = 8;
        t->kind = T_ENUM; /* keep enum, but 64-bit */
        t->len = 8;
    }
}

/* ---------------------------------------------------------------- */
/* declaration specifiers */

static Type *parse_decl_specs(int *storage, Attrs *ad, int *has_type)
{
    int st = 0;
    int quals = 0;
    int basic = 0;      /* bitmask of seen basic specifiers */
    int nlong = 0, nshort = 0, sign = 0; /* sign: 1 signed, 2 unsigned */
    int kind = -1;
    Type *typ = NULL;
    int seen = 0;
    int align = 0;
    *has_type = 0;
    for (;;) {
        switch (tok) {
        case TOK_EXTENSION: next(); continue;
        case TOK_TYPEDEF: st |= ST_TYPEDEF; next(); continue;
        case TOK_EXTERN: st |= ST_EXTERN; next(); continue;
        case TOK_STATIC: st |= ST_STATIC; next(); continue;
        case TOK_AUTO: st |= ST_AUTO; next(); continue;
        case TOK_REGISTER: st |= ST_REGISTER; next(); continue;
        case TOK_INLINE1: case TOK_INLINE2: case TOK_INLINE3: st |= ST_INLINE; next(); continue;
        case TOK_NORETURN: ad->noreturn = 1; next(); continue;
        case TOK_THREAD_LOCAL: st |= ST_THREAD; next(); continue;
        case TOK_CONST1: case TOK_CONST2: case TOK_CONST3: quals |= Q_CONST; next(); continue;
        case TOK_VOLATILE1: case TOK_VOLATILE2: case TOK_VOLATILE3: quals |= Q_VOLATILE; next(); continue;
        case TOK_RESTRICT1: case TOK_RESTRICT2: case TOK_RESTRICT3: quals |= Q_RESTRICT; next(); continue;
        case TOK_ATOMIC:
            next();
            if (tok == '(') {
                /* _Atomic(type) */
                next();
                typ = parse_type_name();
                skip_tok(')');
                seen = 1;
            }
            continue;
        case TOK_ATTRIBUTE1: case TOK_ATTRIBUTE2:
            parse_attributes(ad);
            continue;
        case TOK_ALIGNAS: {
            int n;
            next();
            skip_tok('(');
            if (is_type_start(tok) && !(tok >= TOK_IDENT && sym_find_id(tok) && sym_find_id(tok)->kind != SYM_TYPEDEF)) {
                Type *at = parse_type_name();
                n = type_align(at);
            } else
                n = parse_const_int_expr();
            skip_tok(')');
            if (n <= 0 || (n & (n - 1)))
                tcc_error("alignment must be a positive power of two");
            if (n > align) align = n;
            continue;
        }
        case TOK_VOID: if (seen) tcc_error("too many basic types"); kind = T_VOID; seen = 1; next(); continue;
        case TOK_CHAR: if (kind >= 0 && kind != T_INT) tcc_error("too many basic types"); kind = T_CHAR; seen = 1; next(); continue;
        case TOK_INT:
            if (kind >= 0 && kind != T_INT) tcc_error("too many basic types");
            if (basic & 1) tcc_error("too many basic types");
            basic |= 1; kind = T_INT; seen = 1; next(); continue;
        case TOK_SHORT: if (nshort || nlong) tcc_error("too many basic types"); nshort = 1; seen = 1; if (kind < 0) kind = T_INT; next(); continue;
        case TOK_LONG:
            if (nlong >= 2 || nshort) tcc_error("too many basic types");
            nlong++; seen = 1; if (kind < 0) kind = T_INT; next(); continue;
        case TOK_SIGNED1: case TOK_SIGNED2: case TOK_SIGNED3:
            if (sign) tcc_error("too many basic types");
            sign = 1; seen = 1; if (kind < 0) kind = T_INT; next(); continue;
        case TOK_UNSIGNED:
            if (sign) tcc_error("too many basic types");
            sign = 2; seen = 1; if (kind < 0) kind = T_INT; next(); continue;
        case TOK_FLOAT: if (seen) tcc_error("too many basic types"); kind = T_FLOAT; seen = 1; next(); continue;
        case TOK_DOUBLE:
            if (seen && !(kind == T_INT && nlong == 1 && !basic && !sign && !nshort)) tcc_error("too many basic types");
            kind = T_DOUBLE; seen = 1; next(); continue;
        case TOK_BOOL: if (seen) tcc_error("too many basic types"); kind = T_BOOL; seen = 1; next(); continue;
        case TOK_COMPLEX: next(); continue;
        case TOK_STRUCT: case TOK_UNION: case TOK_ENUM: {
            int k = tok == TOK_STRUCT ? T_STRUCT : tok == TOK_UNION ? T_UNION : T_ENUM;
            if (seen) tcc_error("too many basic types");
            next();
            typ = parse_type_specifier_struct(k);
            seen = 1;
            continue;
        }
        case TOK_TYPEOF1: case TOK_TYPEOF2: case TOK_TYPEOF3: {
            if (seen) tcc_error("too many basic types");
            next();
            skip_tok('(');
            if (is_type_start(tok) && !(tok >= TOK_IDENT && sym_find_id(tok) && sym_find_id(tok)->kind != SYM_TYPEDEF)) {
                typ = parse_type_name();
            } else {
                Node *e;
                int save = nocode_wanted;
                nocode_wanted = 1;
                e = parse_expr();
                nocode_wanted = save;
                typ = e->type;
                if (typ->kind == T_ARRAY || typ->kind == T_FUNC) {
                    /* keep as is */
                }
            }
            skip_tok(')');
            seen = 1;
            continue;
        }
        case TOK_builtin_va_list:
            if (seen) tcc_error("too many basic types");
            {
                Sym *s = sym_find_id(TOK_builtin_va_list);
                if (s && s->kind == SYM_TYPEDEF) {
                    typ = s->type;
                    next();
                    seen = 1;
                    continue;
                }
            }
            goto default_case;
        default:
        default_case:
            if (tok >= TOK_IDENT && !seen) {
                Sym *s = sym_find_id(tok);
                if (s && s->kind == SYM_TYPEDEF) {
                    typ = s->type;
                    if (s->aligned_attr && s->aligned_attr > align) align = s->aligned_attr;
                    seen = 1;
                    next();
                    continue;
                }
            }
            break;
        }
        break;
    }
    *storage = st;
    if (!seen) {
        if (st || quals || align) {
            *has_type = 1;
            typ = type_int;
        } else {
            *has_type = 0;
            typ = type_int;
        }
    } else {
        *has_type = 1;
        if (!typ) {
            Type *t;
            if (kind == T_INT) {
                if (nshort) t = sign == 2 ? type_ushort : type_short;
                else if (nlong) t = sign == 2 ? type_ulong : type_long;
                else t = sign == 2 ? type_uint : type_int;
            } else if (kind == T_CHAR) {
                t = sign == 2 ? type_uchar : sign == 1 ? type_schar : type_char;
            } else if (kind == T_DOUBLE) {
                t = nlong ? type_ldouble : type_double;
                if (sign || nshort) tcc_error("too many basic types");
            } else if (kind == T_VOID) {
                t = type_void;
                if (sign || nshort || nlong) tcc_error("too many basic types");
            } else if (kind == T_FLOAT) {
                t = type_float;
                if (sign || nshort || nlong) tcc_error("too many basic types");
            } else if (kind == T_BOOL) {
                t = type_bool;
                if (sign || nshort || nlong) tcc_error("too many basic types");
            } else
                t = type_int;
            typ = t;
        } else if (sign || nshort || nlong || basic) {
            tcc_error("too many basic types");
        }
    }
    if (ad->mode) {
        Type *t = typ;
        int uns = t->uns;
        switch (ad->mode) {
        case 1: typ = uns ? type_uchar : type_schar; break;
        case 2: typ = uns ? type_ushort : type_short; break;
        case 4: typ = uns ? type_uint : type_int; break;
        case 8: typ = uns ? type_ulong : type_long; break;
        }
        ad->mode = 0;
    }
    if (quals)
        typ = type_qual(typ, quals);
    if (align) {
        typ = type_qual(typ, 0);
        if (typ->align < align) {
            Type *n = xmalloc(sizeof(Type));
            *n = *typ;
            n->align = align;
            typ = n;
        }
    }
    return typ;
}

/* ---------------------------------------------------------------- */
/* declarators */

static Type *parse_params(Type *ret, Attrs *fad);

/* parse pointer/array/function suffixes; returns full type */
static Type *parse_declarator(Type *base, int *id, Attrs *ad, int abstract_ok)
{
    Type *t = base;
    int quals;
    Attrs pad;
    /* pointers */
    for (;;) {
        if (tok == '*') {
            next();
            quals = 0;
            memset(&pad, 0, sizeof pad);
            for (;;) {
                if (tok == TOK_CONST1 || tok == TOK_CONST2 || tok == TOK_CONST3) { quals |= Q_CONST; next(); }
                else if (tok == TOK_VOLATILE1 || tok == TOK_VOLATILE2 || tok == TOK_VOLATILE3) { quals |= Q_VOLATILE; next(); }
                else if (tok == TOK_RESTRICT1 || tok == TOK_RESTRICT2 || tok == TOK_RESTRICT3) { quals |= Q_RESTRICT; next(); }
                else if (tok == TOK_ATOMIC) next();
                else if (tok == TOK_ATTRIBUTE1 || tok == TOK_ATTRIBUTE2) parse_attributes(&pad);
                else break;
            }
            t = type_ptr(t);
            if (quals) t = type_qual(t, quals);
            if (pad.aligned) t->align = pad.aligned;
            continue;
        }
        break;
    }
    if (tok == TOK_ATTRIBUTE1 || tok == TOK_ATTRIBUTE2)
        parse_attributes(ad);
    if (tok == '(') {
        /* grouping or function params (abstract) */
        /* decide: if next is a type start or ')' → function params of abstract declarator */
        int is_group;
        next();
        if (tok == ')' || (is_type_start(tok) && !(tok >= TOK_IDENT && sym_find_id(tok) && sym_find_id(tok)->kind != SYM_TYPEDEF) && tok != TOK_ATTRIBUTE1 && tok != TOK_ATTRIBUTE2) || tok == TOK_DOTS)
            is_group = 0;
        else
            is_group = 1;
        if (is_group) {
            /* nested declarator: parse with a placeholder base and substitute */
            Type *inner_base = type_new(T_VOID);  /* placeholder */
            Type *inner;
            Type *p, *prev;
            inner_base->kind = -1;
            inner = parse_declarator(inner_base, id, ad, abstract_ok);
            skip_tok(')');
            /* suffixes apply to t */
            t = (Type *)0;
            {
                /* parse suffixes on the outer */
                Type *outer = base;
                /* re-run pointer part already applied: we applied pointers to base into 't' before '('; recover */
            }
            (void)p; (void)prev;
            /* We need the type: inner with placeholder replaced by (t + suffixes). */
            {
                extern Type *parse_suffixes(Type *t, Attrs *ad);
                Type *full;
                /* t was overwritten; recompute: pointers were applied to base in 't' before; save it */
                full = NULL;
                (void)full;
            }
            /* fallthrough handled below */
            {
                Type *ptr_part = NULL;
                (void)ptr_part;
            }
            {
                /* substitute */
                Type *outer_t;
                extern Type *g_decl_saved;
                outer_t = g_decl_saved;
                (void)outer_t;
            }
            {
                Type *x = inner;
                Type **slot = &x;
                /* find placeholder */
                while (*slot && (*slot)->kind != -1) {
                    slot = &(*slot)->ref;
                }
                /* parse suffixes of outer */
                {
                    extern Type *parse_suffixes_outer(Type *t, Attrs *ad);
                }
                return x; /* replaced below by real implementation */
            }
        }
        /* function params */
        t = parse_params(t, ad);
        if (tok == '[') {
            tcc_error("declaration of array of functions");
        }
        return t;
    }
    if (tok >= TOK_IDENT) {
        if (!id) tcc_error("identifier not allowed here");
        *id = tok;
        next();
    } else if (id && !abstract_ok) {
        if (tok == ';' || tok == ',' || tok == '=' || tok == ')' || tok == '[' || tok == ':')
            ;
        else
            expect_err("identifier");
    }
    if (tok == TOK_ATTRIBUTE1 || tok == TOK_ATTRIBUTE2)
        parse_attributes(ad);
    {
        extern Type *parse_suffixes(Type *t, Attrs *ad);
        t = parse_suffixes(t, ad);
    }
    return t;
}
