            || (is_type_start(tok) && !(tok >= TOK_IDENT && sym_find_id(tok) && sym_find_id(tok)->kind != SYM_TYPEDEF)
                && tok != TOK_ATTRIBUTE1 && tok != TOK_ATTRIBUTE2))
            is_group = 0;
