    }
    if (tok == TOK_ATTRIBUTE1 || tok == TOK_ATTRIBUTE2)
        parse_attributes(ad);
    t = parse_suffixes(t, ad);
    return t;
}

/* parse function parameter list; '(' has been consumed. ret may be NULL
   (filled in later). */
static Type *parse_params(Type *ret, Attrs *fad)
{
    Type *f = type_new(T_FUNC);
    Sym *first = NULL, **plast = &first;
    int n = 0;
    f->ref = ret;
    if (tok == ')') {
        f->oldstyle = 1;
        next();
        return f;
    }
    if (tok == TOK_VOID) {
        /* could be (void) or (void *x) */
        next();
        if (tok == ')') {
            next();
            return f;
        }
        unget_tok(TOK_VOID);
    }
    if (tok >= TOK_IDENT && !is_type_start(tok)) {
        /* K&R identifier list */
        for (;;) {
            Sym *p;
            if (tok < TOK_IDENT) expect_err("identifier");
            p = xcalloc(sizeof(Sym));
            p->kind = SYM_PARAM;
            p->id = tok;
            p->type = type_int;
            *plast = p; plast = &p->next;
            n++;
            next();
            if (tok == ',') { next(); continue; }
            break;
        }
        skip_tok(')');
        f->oldstyle = 1;
        f->params = first;
        f->nparams = n;
        return f;
    }
