            t = type_ptr(t);
            if (quals) t->quals = quals;
            if (pad.aligned) t->align = pad.aligned;
            continue;
        }
        break;
    }
    if (tok == TOK_ATTRIBUTE1 || tok == TOK_ATTRIBUTE2)
        parse_attributes(ad);
