        p->type = pt;
        p->storage = storage;
        *plast = p; plast = &p->next;
        n++;
        if (tok == ',') {
            next();
            continue;
        }
        break;
    }
    skip_tok(')');
    f->params = first;
    f->nparams = n;
    return f;
}

static Type *parse_type_name(void)
{
    int storage, has_type;
    Attrs ad;
    Type *t;
    memset(&ad, 0, sizeof ad);
    t = parse_decl_specs(&storage, &ad, &has_type);
