/* ---------------------------------------------------------------- */
/* expression helpers */

static const char *type_str(Type *t)
{
    static CStr bufs[4];
    static int bi;
    CStr *cs = &bufs[bi++ & 3];
    cstr_reset(cs);
    if (!cs->data) cstr_init(cs);
    type_to_str(cs, t, NULL);
    return cs->data ? cs->data : "";
}

/* convert array/function to pointer (decay) */
static Node *decay(Node *n)
{
    if (n->type->kind == T_ARRAY) {
        Node *a = node1(N_ADDR, n);
        a->type = type_ptr(n->type->ref);
        a->lvalue = 0;
        return a;
    }
    if (n->type->kind == T_FUNC) {
        Node *a = node1(N_ADDR, n);
        a->type = type_ptr(n->type);
        return a;
    }
    return n;
}

Node *fold_const(Node *n);

static Node *mk_cast(Node *n, Type *t)
{
    Node *c;
    if (n->type == t)
        return n;
    c = node1(N_CAST, n);
    c->type = t;
    c->line = n->line;
    return fold_const(c);
}

/* check cast validity (explicit or implicit conversions) */
static void check_cast(Node *n, Type *t, int explicit)
{
    Type *s = n->type;
    if (t->kind == T_VOID)
        return;
    if (is_struct(t) || is_struct(s)) {
        if (is_struct(t) && is_struct(s) && type_compatible(type_unqual(t), type_unqual(s), 0))
            return;
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    }
    if (s->kind == T_VOID)
        tcc_error("cannot cast from/to void");
    if (t->kind == T_ARRAY || t->kind == T_FUNC) {
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    }
    if (is_ptr(t) && is_float(s))
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    if (is_float(t) && is_ptr(s))
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    if (is_ptr(s) && is_integer(t) && type_size(t, NULL) != 8 && t->kind != T_BOOL) {
        if (!nocode_wanted || 1)
            tcc_warning("cast between pointer and integer of different size");
    }
    if (is_ptr(t) && is_integer(s) && type_size(s, NULL) != 8 && explicit) {
        int64_t v;
        if (!node_is_const_int(n, &v))
            tcc_warning("cast between pointer and integer of different size");
    }
}

static Node *cast_checked(Node *n, Type *t, int explicit)
{
    n = decay(n);
    check_cast(n, t, explicit);
    return mk_cast(n, t);
}

/* integer promotion of an rvalue */
static Node *promote(Node *n)
{
    Type *t = type_promote(n->type);
    if (t->kind != n->type->kind || t->uns != n->type->uns)
        return mk_cast(n, t);
    return n;
}

static int is_null_ptr_const(Node *n)
{
    int64_t v;
    if (is_integer(n->type) && node_is_const_int(n, &v) && v == 0)
        return 1;
    if (is_ptr(n->type) && n->type->ref->kind == T_VOID && n->op == N_CAST && n->a->op == N_CONST && n->a->ival == 0)
        return 1;
    return 0;
}

static int ptr_target_quals_lost(Type *dst, Type *src)
{
    /* dst, src are pointer types */
    Type *d = dst->ref, *s = src->ref;
    return (s->quals & ~d->quals) != 0;
}

static int ptr_compatible(Type *d, Type *s)
{
    /* d, s pointer types */
    Type *dr = d->ref, *sr = s->ref;
    if (dr->kind == T_VOID || sr->kind == T_VOID)
        return 1;
    if (type_compatible(type_unqual(dr), type_unqual(sr), 0))
        return 1;
    /* allow signedness differences for same-size integers? tcc warns */
    if (dr->kind == T_FUNC && sr->kind == T_FUNC)
        return type_compatible(dr, sr, 0);
    return 0;
}

/* implicit conversion for assignment-like contexts */
static Node *assign_convert(Node *n, Type *t, const char *ctx)
{
    Type *s;
    n = decay(n);
    s = n->type;
    if (t->kind == T_VOID)
        return n;
    if (is_struct(t) || is_struct(s)) {
        if (is_struct(t) && is_struct(s) && type_compatible(type_unqual(t), type_unqual(s), 0))
            return n;
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    }
    if (s->kind == T_VOID)
        tcc_error("cannot cast from/to void");
    if (t->kind == T_BOOL) {
        return mk_cast(n, t);
    }
    if (is_ptr(t)) {
        if (is_integer(s)) {
            if (!is_null_ptr_const(n))
                tcc_warning("assignment makes pointer from integer without a cast");
        } else if (is_ptr(s)) {
            if (!ptr_compatible(t, s)) {
                if (s->ref->kind == T_FUNC && t->ref->kind != T_VOID && t->ref->kind != T_FUNC)
                    tcc_warning("assignment from incompatible pointer type");
                else if (is_integer(t->ref) && is_integer(s->ref) && type_size(t->ref, NULL) == type_size(s->ref, NULL)
                         && t->ref->kind != T_BOOL && s->ref->kind != T_BOOL)
                    tcc_warning("assignment from incompatible pointer type");
                else
                    tcc_warning("assignment from incompatible pointer type");
            } else if (ptr_target_quals_lost(t, s) && !(t->ref->kind == T_VOID && 0)) {
                if (!(S.warn_write_strings == 0 && n->op == N_ADDR && n->a->op == N_STR) || (s->ref->quals & Q_CONST))
                    tcc_warning_c(&S.warn_discarded_qualifiers, "assignment discards qualifiers from pointer target type");
            }
        } else if (is_float(s)) {
            tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
        }
        return mk_cast(n, t);
    }
    if (is_integer(t)) {
        if (is_ptr(s)) {
            tcc_warning("assignment makes integer from pointer without a cast");
            if (type_size(t, NULL) != 8)
                tcc_warning("cast between pointer and integer of different size");
        }
        return mk_cast(n, t);
    }
    if (is_float(t)) {
        if (is_ptr(s)) {
            /* tcc silently converts */
        }
        return mk_cast(n, t);
    }
    return mk_cast(n, t);
}

/* ---------------------------------------------------------------- */
/* constant folding */

int node_is_const_int(Node *n, int64_t *v)
{
    n = fold_const(n);
    if (n->op == N_CONST && (is_integer(n->type) || is_ptr(n->type))) {
        *v = n->ival;
        return 1;
    }
    return 0;
}

static int64_t trunc_int(int64_t v, Type *t)
{
    int sz = type_size(t, NULL);
    if (t->kind == T_BOOL) return v != 0;
    switch (sz) {
    case 1: return t->uns ? (uint8_t)v : (int8_t)v;
    case 2: return t->uns ? (uint16_t)v : (int16_t)v;
    case 4: return t->uns ? (int64_t)(uint32_t)v : (int32_t)v;
    default: return v;
    }
}

Node *fold_const(Node *n)
{
    Node *a, *b;
    int64_t x, y, r;
    if (!n) return n;
    switch (n->op) {
    case N_CAST:
        a = n->a;
        if (a->op == N_CONST) {
            if (is_integer(n->type) || is_ptr(n->type)) {
                Node *c = node_const(n->type, is_ptr(n->type) ? a->ival : trunc_int(a->ival, n->type));
                c->line = n->line;
                return c;
            }
            if (is_float(n->type)) {
                long double f = a->type->uns ? (long double)(uint64_t)a->ival : (long double)a->ival;
                Node *c = node_fconst(n->type, n->type->kind == T_FLOAT ? (float)f : n->type->kind == T_DOUBLE ? (double)f : f);
                c->line = n->line;
                return c;
            }
        } else if (a->op == N_FCONST) {
            if (is_integer(n->type)) {
                int64_t v;
                if (n->type->uns && type_size(n->type, NULL) == 8)
                    v = (int64_t)(uint64_t)a->fval;
                else
                    v = (int64_t)a->fval;
                return node_const(n->type, trunc_int(v, n->type));
            }
            if (is_float(n->type)) {
                long double f = a->fval;
                return node_fconst(n->type, n->type->kind == T_FLOAT ? (float)f : n->type->kind == T_DOUBLE ? (double)f : f);
            }
        } else if (a->op == N_CAST && is_integer(n->type) && is_integer(a->type) && is_integer(a->a->type)
                   && type_size(a->type, NULL) >= type_size(n->type, NULL) && type_size(a->type, NULL) >= type_size(a->a->type, NULL)) {
            /* collapse widening then narrowing */
        }
        return n;
    case N_NEG: case N_NOT: case N_LNOT:
        a = n->a;
        if (a->op == N_CONST) {
            x = a->ival;
            if (n->op == N_NEG) r = -(uint64_t)x;
            else if (n->op == N_NOT) r = ~x;
            else r = !x;
            return node_const(n->type, trunc_int(r, n->type));
        }
        if (a->op == N_FCONST) {
            if (n->op == N_NEG) return node_fconst(n->type, -a->fval);
            if (n->op == N_LNOT) return node_const(n->type, !a->fval);
        }
        return n;
    case N_ADD: case N_SUB: case N_MUL: case N_DIV: case N_MOD: case N_SHL: case N_SHR:
    case N_AND: case N_OR: case N_XOR: case N_EQ: case N_NE: case N_LT: case N_LE: case N_GT: case N_GE:
    case N_LAND: case N_LOR:
        a = n->a; b = n->b;
        if (a->op == N_CONST && b->op == N_CONST && (is_integer(a->type) || is_ptr(a->type)) && (is_integer(b->type) || is_ptr(b->type))) {
            int uns = (a->type->uns || b->type->uns) && !(is_ptr(a->type) && is_ptr(b->type));
            int sz = type_size(a->type, NULL);
            if (type_size(b->type, NULL) > sz) sz = type_size(b->type, NULL);
            x = a->ival; y = b->ival;
            if (is_ptr(a->type) || is_ptr(b->type)) uns = 1;
            if (sz <= 4 && !is_ptr(a->type) && !is_ptr(b->type)) {
                if (uns) { x = (uint32_t)x; y = (uint32_t)y; }
            }
            switch (n->op) {
            case N_ADD: r = x + y; break;
            case N_SUB: r = x - y; break;
            case N_MUL: r = (int64_t)((uint64_t)x * (uint64_t)y); break;
            case N_DIV:
                if (y == 0) { if (nocode_wanted) return n; tcc_error("division by zero in constant"); }
                if (uns) r = (int64_t)((uint64_t)x / (uint64_t)y);
                else r = (x == INT64_MIN && y == -1) ? x : x / y;
                break;
            case N_MOD:
                if (y == 0) { if (nocode_wanted) return n; tcc_error("division by zero in constant"); }
                if (uns) r = (int64_t)((uint64_t)x % (uint64_t)y);
                else r = (y == -1) ? 0 : x % y;
