            case N_SHR:
                if (uns) r = (int64_t)((uint64_t)x >> (y & (sz <= 4 ? 31 : 63)));
                else r = x >> (y & (sz <= 4 ? 31 : 63));
                break;
            case N_AND: r = x & y; break;
            case N_OR: r = x | y; break;
            case N_XOR: r = x ^ y; break;
            case N_EQ: r = x == y; break;
            case N_NE: r = x != y; break;
            case N_LT: r = uns ? (uint64_t)x < (uint64_t)y : x < y; break;
            case N_LE: r = uns ? (uint64_t)x <= (uint64_t)y : x <= y; break;
            case N_GT: r = uns ? (uint64_t)x > (uint64_t)y : x > y; break;
            case N_GE: r = uns ? (uint64_t)x >= (uint64_t)y : x >= y; break;
            case N_LAND: r = x && y; break;
            case N_LOR: r = x || y; break;
            default: return n;
            }
            return node_const(n->type, trunc_int(r, n->type));
        }
