/* ---------------------------------------------------------------- */
/* expression helpers */

static const char *type_str(Type *t)
{
    static CStr bufs[4];
    static int bi;
    CStr *cs = &bufs[bi++ & 3];
    cstr_reset(cs);
    if (!cs->data) cstr_init(cs);
    type_to_str(cs, t, NULL);
    return cs->data ? cs->data : "";
}

/* convert array/function to pointer (decay) */
static Node *decay(Node *n)
{
    if (n->type->kind == T_ARRAY) {
        Node *a = node1(N_ADDR, n);
        a->type = type_ptr(n->type->ref);
        a->lvalue = 0;
        return a;
    }
    if (n->type->kind == T_FUNC) {
        Node *a = node1(N_ADDR, n);
        a->type = type_ptr(n->type);
        return a;
    }
    return n;
}

Node *fold_const(Node *n);

static Node *mk_cast(Node *n, Type *t)
{
    Node *c;
    if (n->type == t)
        return n;
    c = node1(N_CAST, n);
    c->type = t;
    c->line = n->line;
    return fold_const(c);
}

/* check cast validity (explicit or implicit conversions) */
static void check_cast(Node *n, Type *t, int explicit)
{
    Type *s = n->type;
    if (t->kind == T_VOID)
        return;
    if (is_struct(t) || is_struct(s)) {
        if (is_struct(t) && is_struct(s) && type_compatible(type_unqual(t), type_unqual(s), 0))
            return;
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    }
    if (s->kind == T_VOID)
        tcc_error("cannot cast from/to void");
    if (t->kind == T_ARRAY || t->kind == T_FUNC) {
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    }
    if (is_ptr(t) && is_float(s))
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    if (is_float(t) && is_ptr(s))
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    if (is_ptr(s) && is_integer(t) && type_size(t, NULL) != 8 && t->kind != T_BOOL) {
        if (!nocode_wanted || 1)
            tcc_warning("cast between pointer and integer of different size");
    }
    if (is_ptr(t) && is_integer(s) && type_size(s, NULL) != 8 && explicit) {
        int64_t v;
        if (!node_is_const_int(n, &v))
            tcc_warning("cast between pointer and integer of different size");
    }
}

static Node *cast_checked(Node *n, Type *t, int explicit)
{
    n = decay(n);
    check_cast(n, t, explicit);
    return mk_cast(n, t);
}

/* integer promotion of an rvalue */
static Node *promote(Node *n)
{
    Type *t = type_promote(n->type);
    if (t->kind != n->type->kind || t->uns != n->type->uns)
        return mk_cast(n, t);
    return n;
}

static int is_null_ptr_const(Node *n)
{
    int64_t v;
    if (is_integer(n->type) && node_is_const_int(n, &v) && v == 0)
        return 1;
    if (is_ptr(n->type) && n->type->ref->kind == T_VOID && n->op == N_CAST && n->a->op == N_CONST && n->a->ival == 0)
        return 1;
    return 0;
}

static int ptr_target_quals_lost(Type *dst, Type *src)
{
    /* dst, src are pointer types */
    Type *d = dst->ref, *s = src->ref;
    return (s->quals & ~d->quals) != 0;
}

static int ptr_compatible(Type *d, Type *s)
{
    /* d, s pointer types */
    Type *dr = d->ref, *sr = s->ref;
    if (dr->kind == T_VOID || sr->kind == T_VOID)
        return 1;
    if (type_compatible(type_unqual(dr), type_unqual(sr), 0))
        return 1;
    /* allow signedness differences for same-size integers? tcc warns */
    if (dr->kind == T_FUNC && sr->kind == T_FUNC)
        return type_compatible(dr, sr, 0);
    return 0;
}

/* implicit conversion for assignment-like contexts */
static Node *assign_convert(Node *n, Type *t, const char *ctx)
{
    Type *s;
    n = decay(n);
    s = n->type;
    if (t->kind == T_VOID)
        return n;
    if (is_struct(t) || is_struct(s)) {
        if (is_struct(t) && is_struct(s) && type_compatible(type_unqual(t), type_unqual(s), 0))
            return n;
        tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
    }
    if (s->kind == T_VOID)
        tcc_error("cannot cast from/to void");
    if (t->kind == T_BOOL) {
        return mk_cast(n, t);
    }
    if (is_ptr(t)) {
        if (is_integer(s)) {
            if (!is_null_ptr_const(n))
                tcc_warning("assignment makes pointer from integer without a cast");
        } else if (is_ptr(s)) {
            if (!ptr_compatible(t, s)) {
                if (s->ref->kind == T_FUNC && t->ref->kind != T_VOID && t->ref->kind != T_FUNC)
                    tcc_warning("assignment from incompatible pointer type");
                else if (is_integer(t->ref) && is_integer(s->ref) && type_size(t->ref, NULL) == type_size(s->ref, NULL)
                         && t->ref->kind != T_BOOL && s->ref->kind != T_BOOL)
                    tcc_warning("assignment from incompatible pointer type");
                else
                    tcc_warning("assignment from incompatible pointer type");
            } else if (ptr_target_quals_lost(t, s) && !(t->ref->kind == T_VOID && 0)) {
                if (!(S.warn_write_strings == 0 && n->op == N_ADDR && n->a->op == N_STR) || (s->ref->quals & Q_CONST))
                    tcc_warning_c(&S.warn_discarded_qualifiers, "assignment discards qualifiers from pointer target type");
            }
        } else if (is_float(s)) {
            tcc_error("cannot cast '%s' to '%s'", type_str(s), type_str(t));
        }
        return mk_cast(n, t);
    }
    if (is_integer(t)) {
        if (is_ptr(s)) {
            tcc_warning("assignment makes integer from pointer without a cast");
            if (type_size(t, NULL) != 8)
                tcc_warning("cast between pointer and integer of different size");
        }
        return mk_cast(n, t);
    }
    if (is_float(t)) {
        if (is_ptr(s)) {
            /* tcc silently converts */
        }
        return mk_cast(n, t);
    }
    return mk_cast(n, t);
}

/* ---------------------------------------------------------------- */
/* constant folding */

int node_is_const_int(Node *n, int64_t *v)
{
    n = fold_const(n);
    if (n->op == N_CONST && (is_integer(n->type) || is_ptr(n->type))) {
        *v = n->ival;
        return 1;
    }
    return 0;
}

static int64_t trunc_int(int64_t v, Type *t)
{
    int sz = type_size(t, NULL);
    if (t->kind == T_BOOL) return v != 0;
    switch (sz) {
    case 1: return t->uns ? (uint8_t)v : (int8_t)v;
    case 2: return t->uns ? (uint16_t)v : (int16_t)v;
    case 4: return t->uns ? (int64_t)(uint32_t)v : (int32_t)v;
    default: return v;
    }
}

Node *fold_const(Node *n)
{
    Node *a, *b;
    int64_t x, y, r;
    if (!n) return n;
    switch (n->op) {
    case N_CAST:
        a = n->a;
        if (a->op == N_CONST) {
            if (is_integer(n->type) || is_ptr(n->type)) {
                Node *c = node_const(n->type, is_ptr(n->type) ? a->ival : trunc_int(a->ival, n->type));
                c->line = n->line;
                return c;
            }
            if (is_float(n->type)) {
                long double f = a->type->uns ? (long double)(uint64_t)a->ival : (long double)a->ival;
                Node *c = node_fconst(n->type, n->type->kind == T_FLOAT ? (float)f : n->type->kind == T_DOUBLE ? (double)f : f);
                c->line = n->line;
                return c;
            }
        } else if (a->op == N_FCONST) {
            if (is_integer(n->type)) {
                int64_t v;
                if (n->type->uns && type_size(n->type, NULL) == 8)
                    v = (int64_t)(uint64_t)a->fval;
                else
                    v = (int64_t)a->fval;
                return node_const(n->type, trunc_int(v, n->type));
            }
            if (is_float(n->type)) {
                long double f = a->fval;
                return node_fconst(n->type, n->type->kind == T_FLOAT ? (float)f : n->type->kind == T_DOUBLE ? (double)f : f);
            }
        } else if (a->op == N_CAST && is_integer(n->type) && is_integer(a->type) && is_integer(a->a->type)
                   && type_size(a->type, NULL) >= type_size(n->type, NULL) && type_size(a->type, NULL) >= type_size(a->a->type, NULL)) {
            /* collapse widening then narrowing */
        }
        return n;
    case N_NEG: case N_NOT: case N_LNOT:
        a = n->a;
        if (a->op == N_CONST) {
            x = a->ival;
            if (n->op == N_NEG) r = -(uint64_t)x;
            else if (n->op == N_NOT) r = ~x;
            else r = !x;
            return node_const(n->type, trunc_int(r, n->type));
        }
        if (a->op == N_FCONST) {
            if (n->op == N_NEG) return node_fconst(n->type, -a->fval);
            if (n->op == N_LNOT) return node_const(n->type, !a->fval);
        }
        return n;
    case N_ADD: case N_SUB: case N_MUL: case N_DIV: case N_MOD: case N_SHL: case N_SHR:
    case N_AND: case N_OR: case N_XOR: case N_EQ: case N_NE: case N_LT: case N_LE: case N_GT: case N_GE:
    case N_LAND: case N_LOR:
        a = n->a; b = n->b;
        if (a->op == N_CONST && b->op == N_CONST && (is_integer(a->type) || is_ptr(a->type)) && (is_integer(b->type) || is_ptr(b->type))) {
            int uns = (a->type->uns || b->type->uns) && !(is_ptr(a->type) && is_ptr(b->type));
            int sz = type_size(a->type, NULL);
            if (type_size(b->type, NULL) > sz) sz = type_size(b->type, NULL);
            x = a->ival; y = b->ival;
            if (is_ptr(a->type) || is_ptr(b->type)) uns = 1;
            if (sz <= 4 && !is_ptr(a->type) && !is_ptr(b->type)) {
                if (uns) { x = (uint32_t)x; y = (uint32_t)y; }
            }
            switch (n->op) {
            case N_ADD: r = x + y; break;
            case N_SUB: r = x - y; break;
            case N_MUL: r = (int64_t)((uint64_t)x * (uint64_t)y); break;
            case N_DIV:
                if (y == 0) { if (nocode_wanted) return n; tcc_error("division by zero in constant"); }
                if (uns) r = (int64_t)((uint64_t)x / (uint64_t)y);
                else r = (x == INT64_MIN && y == -1) ? x : x / y;
                break;
            case N_MOD:
                if (y == 0) { if (nocode_wanted) return n; tcc_error("division by zero in constant"); }
                if (uns) r = (int64_t)((uint64_t)x % (uint64_t)y);
                else r = (y == -1) ? 0 : x % y;
                break;
            case N_SHL: r = (int64_t)((uint64_t)x << (y & (sz <= 4 ? 31 : 63))); break;
            case N_SHR:
                if (uns) r = (int64_t)((uint64_t)x >> (y & (sz <= 4 ? 31 : 63)));
                else r = x >> (y & (sz <= 4 ? 31 : 63));
                break;
            case N_AND: r = x & y; break;
            case N_OR: r = x | y; break;
            case N_XOR: r = x ^ y; break;
            case N_EQ: r = x == y; break;
            case N_NE: r = x != y; break;
            case N_LT: r = uns ? (uint64_t)x < (uint64_t)y : x < y; break;
            case N_LE: r = uns ? (uint64_t)x <= (uint64_t)y : x <= y; break;
            case N_GT: r = uns ? (uint64_t)x > (uint64_t)y : x > y; break;
            case N_GE: r = uns ? (uint64_t)x >= (uint64_t)y : x >= y; break;
            case N_LAND: r = x && y; break;
            case N_LOR: r = x || y; break;
            default: return n;
            }
            return node_const(n->type, trunc_int(r, n->type));
        }
        if ((a->op == N_FCONST || a->op == N_CONST) && (b->op == N_FCONST || b->op == N_CONST)
            && (a->op == N_FCONST || b->op == N_FCONST) && !is_ptr(a->type) && !is_ptr(b->type)) {
            long double fx = a->op == N_FCONST ? a->fval : (a->type->uns ? (long double)(uint64_t)a->ival : (long double)a->ival);
            long double fy = b->op == N_FCONST ? b->fval : (b->type->uns ? (long double)(uint64_t)b->ival : (long double)b->ival);
            long double fr;
            switch (n->op) {
            case N_ADD: fr = fx + fy; break;
            case N_SUB: fr = fx - fy; break;
            case N_MUL: fr = fx * fy; break;
            case N_DIV: fr = fx / fy; break;
            case N_EQ: return node_const(n->type, fx == fy);
            case N_NE: return node_const(n->type, fx != fy);
            case N_LT: return node_const(n->type, fx < fy);
            case N_LE: return node_const(n->type, fx <= fy);
            case N_GT: return node_const(n->type, fx > fy);
            case N_GE: return node_const(n->type, fx >= fy);
            case N_LAND: return node_const(n->type, fx && fy);
            case N_LOR: return node_const(n->type, fx || fy);
            default: return n;
            }
            if (is_float(n->type))
                return node_fconst(n->type, n->type->kind == T_FLOAT ? (float)fr : n->type->kind == T_DOUBLE ? (double)fr : fr);
            return n;
        }
        /* a && 0 style: logical with one constant: keep (short circuit) */
        return n;
    case N_COND:
        if (n->a->op == N_CONST) {
            return n->a->ival ? n->b : n->c;
        }
        if (n->a->op == N_FCONST)
            return n->a->fval ? n->b : n->c;
        return n;
    default:
        return n;
    }
}

/* evaluate an integer constant expression; error if not constant */
int eval_const_expr(Node *n, int64_t *val)
{
    n = fold_const(n);
    if (n->op == N_CONST) {
        *val = n->ival;
        return 1;
    }
    return 0;
}

/* ---------------------------------------------------------------- */
/* expression parsing */

static Node *parse_primary(void);
static Node *parse_postfix(Node *n);
static Node *parse_unary(void);
static Node *parse_binary(int prec);
Node *parse_expr(void);
static Node *parse_initializer_as_node(Type *t, int is_static);
static Node *parse_stmt(void);
static Node *parse_compound(int new_scope);
static Node *parse_string_node(void);

static Node *mk_unary_arith(int op, Node *a)
{
    Node *n;
    a = decay(a);
    if (op == N_LNOT) {
        if (!is_scalar(a->type))
            tcc_error("invalid operand type");  /* tcc: ... */
        n = node1(N_LNOT, a);
        n->type = type_int;
        return fold_const(n);
    }
    if (!is_arith(a->type)) {
        tcc_error("invalid operand types for binary operation");
    }
    if (op == N_NOT && !is_integer(a->type))
        tcc_error("invalid operand types for binary operation");
    a = promote(a);
    n = node1(op, a);
    n->type = a->type;
    return fold_const(n);
}

/* pointer arithmetic: p + i, with elem size */
static Node *mk_ptr_add(Node *p, Node *i, int sub)
{
    Node *n;
    Type *elem = p->type->ref;
    int es = type_size(elem, NULL);
    if (es < 0 && elem->kind != T_VOID && elem->kind != T_FUNC) {
        if (elem->kind == T_ARRAY && elem->len == -2)
            es = -1;
        else
            tcc_error("unknown type size");
    }
    if (elem->kind == T_VOID || elem->kind == T_FUNC) es = 1;
    i = mk_cast(promote(i), type_long);
    if (es != 1 && es >= 0) {
        Node *m = node2(N_MUL, i, node_const(type_long, es));
        m->type = type_long;
        i = fold_const(m);
    }
    n = node2(sub ? N_SUB : N_ADD, p, i);
    n->type = p->type;
    return fold_const(n);
}

static Node *mk_binary(int op, Node *a, Node *b)
{
    Node *n;
    Type *ta, *tb;
    a = decay(a);
    b = decay(b);
    ta = a->type; tb = b->type;
    switch (op) {
    case N_ADD:
        if (is_ptr(ta) && is_integer(tb)) return mk_ptr_add(a, b, 0);
        if (is_ptr(tb) && is_integer(ta)) return mk_ptr_add(b, a, 0);
        if (is_ptr(ta) && is_ptr(tb)) tcc_error("invalid operand types for binary operation");
        break;
    case N_SUB:
        if (is_ptr(ta) && is_integer(tb)) return mk_ptr_add(a, b, 1);
        if (is_ptr(ta) && is_ptr(tb)) {
            int es;
            Type *elem = ta->ref;
            if (!type_compatible(type_unqual(ta->ref), type_unqual(tb->ref), 0) && ta->ref->kind != T_VOID && tb->ref->kind != T_VOID)
                tcc_error("incompatible types for pointer subtraction"); /* tcc: cannot ... */
            es = type_size(elem, NULL);
            if (es <= 0) es = 1;
            n = node2(N_SUB, mk_cast(a, type_long), mk_cast(b, type_long));
            n->type = type_long;
            if (es != 1) {
                Node *d = node2(N_DIV, n, node_const(type_long, es));
                d->type = type_long;
                n = d;
            }
            return fold_const(n);
        }
        if (is_integer(ta) && is_ptr(tb)) tcc_error("invalid operand types for binary operation");
        break;
    case N_EQ: case N_NE: case N_LT: case N_LE: case N_GT: case N_GE:
        if (is_ptr(ta) || is_ptr(tb)) {
            if (is_ptr(ta) && is_ptr(tb)) {
                if (!ptr_compatible(ta, tb) || (ta->ref->kind == T_FUNC) != (tb->ref->kind == T_FUNC)) {
                    if (!(ta->ref->kind == T_VOID || tb->ref->kind == T_VOID))
                        tcc_warning("comparison of distinct pointer types lacks a cast");
                }
            } else {
                Node *other = is_ptr(ta) ? b : a;
                if (is_float(other->type))
                    tcc_error("invalid operand types for binary operation");
                if (!is_null_ptr_const(other))
                    tcc_warning("comparison between pointer and integer");
            }
            n = node2(op, mk_cast(a, type_ulong), mk_cast(b, type_ulong));
            n->type = type_int;
            return fold_const(n);
        }
        break;
    case N_LAND: case N_LOR:
        if (!is_scalar(ta) || !is_scalar(tb))
            tcc_error("invalid operand types for binary operation");
        n = node2(op, a, b);
        n->type = type_int;
        return fold_const(n);
    }
    if (!is_arith(ta) || !is_arith(tb))
        tcc_error("invalid operand types for binary operation");
    if ((op == N_MOD || op == N_SHL || op == N_SHR || op == N_AND || op == N_OR || op == N_XOR)
        && (!is_integer(ta) || !is_integer(tb)))
        tcc_error("invalid operand types for binary operation");
    if (op == N_SHL || op == N_SHR) {
        a = promote(a);
        b = promote(b);
        n = node2(op, a, b);
        n->type = a->type;
        return fold_const(n);
    }
    {
        Type *ct = type_common_arith(ta, tb);
        a = mk_cast(a, ct);
        b = mk_cast(b, ct);
        n = node2(op, a, b);
        if (op >= N_EQ && op <= N_GE)
            n->type = type_int;
        else
            n->type = ct;
        return fold_const(n);
    }
}

static int is_lvalue(Node *n)
{
    return n->lvalue;
}

static void check_assignable(Node *n)
{
    if (!is_lvalue(n))
        tcc_error("lvalue expected");
    if (n->type->kind == T_ARRAY)
        tcc_error("lvalue expected");
    if (n->type->quals & Q_CONST)
        tcc_error("assignment of read-only location");
    if (is_struct(n->type) && n->type->sym && type_size(n->type, NULL) < 0)
        tcc_error("incomplete type");
}

static Node *mk_assign(Node *lhs, Node *rhs)
{
    Node *n;
    check_assignable(lhs);
    rhs = assign_convert(rhs, lhs->type, "assignment");
    n = node2(N_ASSIGN, lhs, rhs);
    n->type = type_unqual(lhs->type);
    return n;
}

static Node *mk_incdec(int op, Node *a)
{
    Node *n;
    check_assignable(a);
    if (!is_scalar(a->type))
        tcc_error("invalid operand types for binary operation");
    if (is_ptr(a->type)) {
        int es = type_size(a->type->ref, NULL);
        if (es < 0 && a->type->ref->kind != T_VOID) tcc_error("unknown type size");
    }
    n = node1(op, a);
    n->type = type_unqual(a->type);
    return n;
}

static Node *mk_deref(Node *a)
{
    Node *n;
    a = decay(a);
    if (!is_ptr(a->type))
        tcc_error("pointer expected");
    n = node1(N_DEREF, a);
    n->type = a->type->ref;
    n->lvalue = n->type->kind != T_FUNC;
    if (n->type->kind == T_VOID)
        n->lvalue = 1;
    return n;
}

static Node *mk_addr(Node *a)
{
    Node *n;
    if (a->op == N_DEREF) {
        Node *p = a->a;
        return p;
    }
    if (a->type->kind == T_FUNC) {
        n = node1(N_ADDR, a);
        n->type = type_ptr(a->type);
        return n;
    }
    if (!a->lvalue)
        tcc_error("lvalue expected");
    if (a->bitfield)
        tcc_error("cannot take address of bitfield"); /* tcc: ... */
    if (a->op == N_VAR && a->sym && a->sym->storage & ST_REGISTER)
        ;
    n = node1(N_ADDR, a);
    n->type = type_ptr(a->type);
    return n;
}

/* find struct field, including anonymous members. returns offset accumulation */
static Sym *find_field(Sym *st, int id, int *offset)
{
    Sym *f;
    for (f = st->fields; f; f = f->next) {
        if (f->id == id) {
            *offset += f->offset;
            return f;
        }
        if (f->anon_struct || (!f->id && is_struct(f->type))) {
            int off = f->offset;
            Sym *r = find_field(f->type->sym, id, &off);
            if (r) {
                *offset += off;
                return r;
            }
        }
    }
    return NULL;
}

static Node *mk_member(Node *a, int id)
{
    Node *n;
    Sym *f;
    int off = 0;
    Type *st = a->type;
    if (!is_struct(st))
        tcc_error("struct or union expected");
    if (st->sym->size < 0)
        tcc_error("incomplete type");  /* hmm */
    f = find_field(st->sym, id, &off);
    if (!f)
        tcc_error("field not found: %s", tok_name(id));
    n = node1(N_MEMBER, a);
    n->sym = f;
    n->ival = off;
    n->type = type_qual(f->type, st->quals);
    n->lvalue = a->lvalue || 1;
    if (f->bit_size >= 0) n->bitfield = 1;
    return n;
}

static Node *mk_index(Node *a, Node *i)
{
    Node *n;
    a = decay(a);
    i = decay(i);
    if (is_integer(a->type) && is_ptr(i->type)) { Node *t = a; a = i; i = t; }
    if (!is_ptr(a->type))
        tcc_error("pointer expected");
    if (!is_integer(i->type))
        tcc_error("integer expected");  /* hmm */
    n = mk_ptr_add(a, i, 0);
    n = node1(N_DEREF, n);
    n->type = a->type->ref;
    n->lvalue = 1;
    return n;
}

static Node *mk_cond(Node *c, Node *a, Node *b)
{
    Node *n;
    Type *ta, *tb, *rt;
    c = decay(c);
    if (!is_scalar(c->type))
        tcc_error("invalid operand types for binary operation");
    a = decay(a);
    b = decay(b);
    ta = a->type; tb = b->type;
    if (is_arith(ta) && is_arith(tb)) {
        rt = type_common_arith(ta, tb);
        a = mk_cast(a, rt);
        b = mk_cast(b, rt);
    } else if (is_struct(ta) && is_struct(tb)) {
        if (!type_compatible(type_unqual(ta), type_unqual(tb), 0))
            tcc_error("incompatible types in conditional expression");
        rt = type_unqual(ta);
    } else if (ta->kind == T_VOID || tb->kind == T_VOID) {
        rt = type_void;
    } else if (is_ptr(ta) && is_ptr(tb)) {
        if (ta->ref->kind == T_VOID) rt = type_ptr(type_qual(type_void, ta->ref->quals | tb->ref->quals));
        else if (tb->ref->kind == T_VOID) rt = type_ptr(type_qual(type_void, ta->ref->quals | tb->ref->quals));
        else {
            if (!ptr_compatible(ta, tb))
                tcc_warning("pointer type mismatch in conditional expression");
            rt = type_ptr(type_qual(ta->ref, tb->ref->quals));
        }
        a = mk_cast(a, rt);
        b = mk_cast(b, rt);
    } else if (is_ptr(ta) && is_integer(tb)) {
        if (!is_null_ptr_const(b))
            tcc_warning("pointer/integer mismatch in conditional expression");
        rt = ta;
        b = mk_cast(b, rt);
    } else if (is_ptr(tb) && is_integer(ta)) {
        if (!is_null_ptr_const(a))
            tcc_warning("pointer/integer mismatch in conditional expression");
        rt = tb;
        a = mk_cast(a, rt);
    } else {
        tcc_error("invalid operand types for binary operation");
        rt = ta;
    }
    n = node_new(N_COND);
    n->a = c; n->b = a; n->c = b;
    n->type = rt;
    return fold_const(n);
}

/* function call */
static Node *mk_call(Node *f, Node **args, int nargs)
{
    Node *n;
    Type *ft;
    Sym *p;
    int i;
    f = decay(f);
    if (!is_ptr(f->type) || f->type->ref->kind != T_FUNC)
        tcc_error("function pointer expected");
    ft = f->type->ref;
    n = node_new(N_CALL);
    n->a = f;
    n->type = ft->ref;
    if (!ft->oldstyle) {
        if (nargs < ft->nparams)
            tcc_error("too few arguments to function");
        if (nargs > ft->nparams && !ft->variadic)
            tcc_error("too many arguments to function");
    }
    p = ft->params;
    for (i = 0; i < nargs; i++) {
        Node *a = args[i];
        if (p && !ft->oldstyle) {
            a = assign_convert(a, p->type, "argument");
            p = p->next;
        } else {
            a = decay(a);
            if (a->type->kind == T_VOID) tcc_error("cannot cast from/to void");
            /* default argument promotions */
            if (is_integer(a->type)) a = promote(a);
            else if (a->type->kind == T_FLOAT) a = mk_cast(a, type_double);
            if (p) p = p->next;
        }
        node_push(n, a);
    }
    return n;
}

static Type *parse_type_in_parens_or_expr_type(void);

static Node *parse_sizeof(int is_alignof)
{
    Node *n;
    Type *t;
    int sz, al;
    Node *e = NULL;
    next();
    if (tok == '(') {
        next();
        if (is_type_start(tok) && !(tok >= TOK_IDENT && sym_find_id(tok) && sym_find_id(tok)->kind != SYM_TYPEDEF)) {
            t = parse_type_name();
            skip_tok(')');
            /* compound literal? (type){...} */
            if (tok == '{') {
                e = parse_initializer_as_node(t, 0);
                e = parse_postfix(e);
                t = e->type;
            }
        } else {
            int save = nocode_wanted;
            nocode_wanted++;
            e = parse_expr();
            nocode_wanted = save;
            skip_tok(')');
            e = parse_postfix(e);
            t = e->type;
        }
    } else {
        int save = nocode_wanted;
        nocode_wanted++;
        e = parse_unary();
        nocode_wanted = save;
        t = e->type;
    }
    if (e && e->bitfield)
        tcc_error("sizeof applied to a bitfield");  /* hmm */
    sz = type_size(t, &al);
    if (t->kind == T_ARRAY && t->len == -2) {
        /* VLA sizeof: runtime */
        Node *v = node_new(N_SIZEOF_EXPR);
        v->a = e;
        v->cast_type = t;
        v->type = type_size_t;
        return v;
    }
    if (sz < 0)
        tcc_error("sizeof applied to an incomplete type");
    n = node_const(type_size_t, is_alignof ? al : sz);
    return n;
}

static Node *parse_builtin_call(int id)
{
    Node *n;
    next();
    switch (id) {
    case TOK_builtin_types_compatible_p: {
        Type *t1, *t2;
        skip_tok('(');
        t1 = parse_type_name();
        skip_tok(',');
        t2 = parse_type_name();
        skip_tok(')');
        if (t1->kind == T_ARRAY) t1 = type_ptr(t1->ref);
        if (t2->kind == T_ARRAY) t2 = type_ptr(t2->ref);
        return node_const(type_int, type_compatible(type_unqual(t1), type_unqual(t2), 0));
    }
    case TOK_builtin_choose_expr: {
        int64_t c;
        Node *a, *b;
        skip_tok('(');
        a = parse_cond_expr();
        if (!eval_const_expr(a, &c))
            tcc_error("constant expression expected");
        skip_tok(',');
        if (c) {
            a = parse_assignment_expr();
            skip_tok(',');
            nocode_wanted++;
            b = parse_assignment_expr();
            nocode_wanted--;
            skip_tok(')');
            return a;
        } else {
            nocode_wanted++;
            a = parse_assignment_expr();
            nocode_wanted--;
            skip_tok(',');
            b = parse_assignment_expr();
            skip_tok(')');
            return b;
        }
    }
    case TOK_builtin_constant_p: {
        Node *a;
        int r;
        skip_tok('(');
        nocode_wanted++;
        a = parse_expr();
        nocode_wanted--;
        skip_tok(')');
        a = fold_const(a);
        r = a->op == N_CONST || a->op == N_FCONST;
        return node_const(type_int, r);
    }
    case TOK_builtin_expect: {
        Node *a, *b;
        skip_tok('(');
        a = parse_assignment_expr();
        skip_tok(',');
        b = parse_assignment_expr();
        skip_tok(')');
        (void)b;
        return mk_cast(decay(a), type_long);
    }
    case TOK_builtin_frame_address: case TOK_builtin_return_address: {
        int64_t level;
        Node *a;
        skip_tok('(');
        a = parse_assignment_expr();
        if (!eval_const_expr(a, &level))
            tcc_error("constant expression expected");
        skip_tok(')');
        n = node_new(N_BUILTIN);
        n->subop = id;
        n->ival = level;
        n->type = type_voidptr;
        return n;
    }
    case TOK_builtin_unreachable:
        skip_tok('(');
        skip_tok(')');
        n = node_new(N_BUILTIN);
        n->subop = id;
        n->type = type_void;
        return n;
    case TOK_builtin_va_arg_types: {
        Type *t;
        int cls;
        skip_tok('(');
        t = parse_type_name();
        skip_tok(')');
        /* 0: integer class, 1: sse, 2: memory */
        if (is_float(t)) cls = t->kind == T_LDOUBLE ? 2 : 1;
        else if (is_struct(t)) {
            int sz = type_size(t, NULL);
            cls = sz > 16 ? 2 : 0;
            /* struct containing floats only -> sse; mixed -> memory-ish: simplified */
        } else cls = 0;
        return node_const(type_int, cls);
    }
    case TOK___va_arg: {
        Node *ap, *cls, *sz, *al;
        skip_tok('(');
        ap = parse_assignment_expr();
        skip_tok(',');
        cls = parse_assignment_expr();
        skip_tok(',');
        sz = parse_assignment_expr();
        skip_tok(',');
        al = parse_assignment_expr();
        skip_tok(')');
        n = node_new(N_VAARG);
        n->a = decay(ap);
        n->b = cls; n->c = sz; n->d = al;
        n->type = type_voidptr;
        return n;
    }
    }
    tcc_error("unsupported builtin");
    return NULL;
}

static Node *parse_generic(void)
{
    Node *ctrl, *result = NULL, *def = NULL;
    Type *ct;
    int matched = 0;
    next();
    skip_tok('(');
    nocode_wanted++;
    ctrl = parse_assignment_expr();
    nocode_wanted--;
    ctrl = decay(ctrl);
    ct = type_unqual(ctrl->type);
    skip_tok(',');
    for (;;) {
        Node *e;
        if (tok == TOK_DEFAULT) {
            next();
            skip_tok(':');
            if (def) tcc_error("too many 'default'");
            nocode_wanted++;
            e = parse_assignment_expr();
            nocode_wanted--;
            def = e;
        } else {
            Type *t = parse_type_name();
            skip_tok(':');
            if (type_compatible(type_unqual(t), ct, 0) && t->quals == ctrl->type->quals) {
                if (matched) tcc_error("type match twice");
                e = parse_assignment_expr();
                result = e;
                matched = 1;
            } else {
                nocode_wanted++;
                e = parse_assignment_expr();
                nocode_wanted--;
            }
        }
        if (tok == ',') { next(); continue; }
        break;
    }
    skip_tok(')');
    if (!result) {
        if (!def) tcc_error("type '%s' does not match any association", type_str(ctrl->type));
        result = def;
    }
    return result;
}

static Node *mk_var_ref(Sym *s)
{
    Node *n;
    if (s->kind == SYM_ENUMCONST) {
        Node *c = node_const(type_int, s->ival);
        c->type = s->type && s->type->kind == T_ENUM && s->type->len == 8 ? type_long : type_int;
        return c;
    }
    n = node_new(N_VAR);
    n->sym = s;
    n->type = s->type;
    n->lvalue = s->type->kind != T_FUNC;
    s->used = 1;
    s->referenced = 1;
    return n;
}

static Node *parse_primary(void)
{
    Node *n;
    switch (tok) {
    case TOK_PPNUM: {
        NumVal nv;
        parse_number(tokstr, &nv);
        if (nv.is_float) {
            Type *t = nv.is_float == 1 ? type_float : nv.is_float == 2 ? type_double : type_ldouble;
            n = node_fconst(t, nv.is_float == 1 ? (float)nv.f : nv.is_float == 2 ? (double)nv.f : nv.f);
        } else {
            Type *t;
            if (nv.longlong) t = nv.uns ? type_ullong : type_llong;
            else t = nv.uns ? type_uint : type_int;
            /* unsuffixed decimals exceeding int become long (tcc uses long long) */
            n = node_const(t, nv.u);
        }
        next();
        return n;
    }
    case TOK_CCHAR: {
        int64_t v; int wide, nb;
        parse_char_const(tokstr, &v, &wide, &nb);
        n = node_const(wide ? type_int : type_int, v);
        if (!wide && nb == 1) n->type = type_int;
        next();
        return n;
    }
    case TOK_STR:
        return parse_string_node();
    case '(': {
        next();
        if (tok == '{') {
            /* statement expression */
            Node *blk;
            Node *last;
            Node *se = node_new(N_STMT_EXPR);
            blk = parse_compound(1);
            skip_tok(')');
            se->a = blk;
            se->type = type_void;
            if (blk->nlist > 0) {
                last = blk->list[blk->nlist - 1];
                if (last->op == N_EXPR && last->a) {
                    se->type = last->a->type;
                    if (se->type->kind == T_ARRAY) se->type = type_ptr(se->type->ref);
                }
            }
            return se;
        }
        if (is_type_start(tok) && !(tok >= TOK_IDENT && sym_find_id(tok) && sym_find_id(tok)->kind != SYM_TYPEDEF)) {
            Type *t = parse_type_name();
            skip_tok(')');
            if (tok == '{') {
                /* compound literal */
                n = parse_initializer_as_node(t, 0);
                return n;
            }
            /* cast */
            n = parse_cast_expr();
            n = cast_checked(n, t, 1);
            if (t->kind == T_VOID) {
                Node *c = node1(N_CAST, decay(n->op == N_CAST ? n->a : n));
                c->type = type_void;
                return c;
            }
            return n;
        }
        n = parse_expr();
        skip_tok(')');
        /* parenthesized lvalue stays lvalue */
        return n;
    }
    case TOK_SIZEOF:
        return parse_sizeof(0);
    case TOK_ALIGNOF1: case TOK_ALIGNOF2: case TOK_ALIGNOF3:
        return parse_sizeof(1);
    case TOK_GENERIC:
        return parse_generic();
    case TOK___FUNCTION__: case TOK___FUNC__: {
        const char *name = cur_func ? tok_name(cur_func->id) : "";
        int len = strlen(name);
        n = node_new(N_STR);
        n->str = intern(name, len);
        n->slen = len + 1;
        n->type = type_array(type_char, len + 1);
        n->lvalue = 1;
        next();
        return n;
    }
    case TOK_builtin_types_compatible_p: case TOK_builtin_choose_expr: case TOK_builtin_constant_p:
    case TOK_builtin_expect: case TOK_builtin_frame_address: case TOK_builtin_return_address:
    case TOK_builtin_unreachable: case TOK_builtin_va_arg_types: case TOK___va_arg:
        return parse_builtin_call(tok);
    case TOK_LAND: {
        /* &&label : computed goto address */
        Sym *s;
        next();
        if (tok < TOK_IDENT) expect_err("label identifier");
        s = sym_find_label(tok);
        if (!s) {
            s = sym_push(2, tok, SYM_LABEL, NULL);
            pvec_push(&func_labels, s);
        }
        s->label_used = 1;
        n = node_new(N_LABELADDR);
        n->sym = s;
        n->type = type_voidptr;
        next();
        return n;
    }
    default:
        if (tok >= TOK_IDENT) {
            int id = tok;
            Sym *s = sym_find_id(id);
            next();
            if (!s) {
                if (tok == '(') {
                    /* implicit function declaration */
                    Type *ft = type_new(T_FUNC);
                    ft->ref = type_int;
                    ft->oldstyle = 1;
                    tcc_warning_c(&S.warn_implicit_function_declaration, "implicit declaration of function '%s'", tok_name(id));
                    s = sym_global(id, SYM_FUNC, ft);
                    s->storage = ST_EXTERN;
                } else {
                    tcc_error("'%s' undeclared", tok_name(id));
                }
            }
            if (s->kind == SYM_TYPEDEF)
                tcc_error("'%s' undeclared", tok_name(id));  /* hmm */
            return mk_var_ref(s);
        }
        tcc_error("expression expected before '%s'", cur_tok_str());
    }
    return NULL;
}

static Node *parse_string_node(void)
{
    CStr cs;
    int wide = 0, w, csz;
    Node *n;
    cstr_init(&cs);
    while (tok == TOK_STR) {
        parse_string_literal(tokstr, &cs, &w, &csz);
        if (w) wide = 1;
        next();
    }
    /* mixed narrow/wide: convert narrow parts? rare; ignore */
    n = node_new(N_STR);
    if (wide) {
        /* all parts assumed wide */
        int32_t z = 0;
        cstr_cat(&cs, (char *)&z, 4);
        n->type = type_array(type_int, cs.len / 4);
        n->slen = cs.len;
    } else {
        cstr_ccat(&cs, 0);
        n->type = type_array(type_char, cs.len);
        n->slen = cs.len;
    }
    n->str = intern(cs.data, cs.len);
    n->ival = cs.len;
    n->lvalue = 1;
    cstr_free(&cs);
    return n;
}

static Node *parse_args_call(Node *f)
{
    Node **args = NULL;
    int n = 0, cap = 0;
    Node *r;
    skip_tok('(');
    if (tok != ')') {
        for (;;) {
            Node *a = parse_assignment_expr();
            if (n >= cap) { cap = cap ? cap * 2 : 8; args = xrealloc(args, cap * sizeof(Node *)); }
            args[n++] = a;
            if (tok == ',') { next(); continue; }
            break;
        }
    }
    skip_tok(')');
    r = mk_call(f, args, n);
    free(args);
    return r;
}

static Node *parse_postfix(Node *n)
{
    for (;;) {
        switch (tok) {
        case '[': {
            Node *i;
            next();
            i = parse_expr();
            skip_tok(']');
            n = mk_index(n, i);
            continue;
        }
        case '(':
            n = parse_args_call(n);
            continue;
        case '.': case TOK_ARROW: {
            int arrow = tok == TOK_ARROW;
            next();
            if (tok < TOK_IDENT) expect_err("field name");
            if (arrow) n = mk_deref(n);
            n = mk_member(n, tok);
            next();
            continue;
        }
        case TOK_INC:
            next();
            n = mk_incdec(N_POSTINC, n);
            continue;
        case TOK_DEC:
            next();
            n = mk_incdec(N_POSTDEC, n);
            continue;
        default:
            return n;
        }
    }
}

static Node *parse_cast_expr(void)
{
    return parse_unary();
}

static Node *parse_unary(void)
{
    Node *n;
    switch (tok) {
    case TOK_INC: next(); n = parse_unary(); return mk_incdec(N_PREINC, n);
    case TOK_DEC: next(); n = parse_unary(); return mk_incdec(N_PREDEC, n);
    case '&': next(); n = parse_unary(); return mk_addr(n);
    case '*': next(); n = parse_unary(); return mk_deref(n);
    case '+': next(); n = parse_unary(); n = decay(n); if (!is_arith(n->type)) tcc_error("invalid operand types for binary operation"); return promote(n);
    case '-': next(); n = parse_unary(); return mk_unary_arith(N_NEG, n);
    case '~': next(); n = parse_unary(); return mk_unary_arith(N_NOT, n);
    case '!': next(); n = parse_unary(); return mk_unary_arith(N_LNOT, n);
    case TOK_EXTENSION: next(); return parse_unary();
    case TOK_SIZEOF: case TOK_ALIGNOF1: case TOK_ALIGNOF2: case TOK_ALIGNOF3:
        return parse_postfix(parse_primary());
    default:
        n = parse_primary();
        return parse_postfix(n);
    }
}

static int binop_prec(int t, int *op)
{
    switch (t) {
    case '*': *op = N_MUL; return 12;
    case '/': *op = N_DIV; return 12;
    case '%': *op = N_MOD; return 12;
    case '+': *op = N_ADD; return 11;
    case '-': *op = N_SUB; return 11;
    case TOK_SHL: *op = N_SHL; return 10;
    case TOK_SAR: *op = N_SHR; return 10;
    case '<': *op = N_LT; return 9;
    case '>': *op = N_GT; return 9;
    case TOK_LE: *op = N_LE; return 9;
    case TOK_GE: *op = N_GE; return 9;
    case TOK_EQ: *op = N_EQ; return 8;
    case TOK_NE: *op = N_NE; return 8;
    case '&': *op = N_AND; return 7;
    case '^': *op = N_XOR; return 6;
    case '|': *op = N_OR; return 5;
    case TOK_LAND: *op = N_LAND; return 4;
    case TOK_LOR: *op = N_LOR; return 3;
    }
    return 0;
}

static Node *parse_binary(int minprec)
{
    Node *l = parse_unary();
    for (;;) {
        int op, prec = binop_prec(tok, &op);
        Node *r;
        if (prec == 0 || prec < minprec)
            return l;
        next();
        r = parse_binary(prec + 1);
        l = mk_binary(op, l, r);
    }
}

static Node *parse_cond_expr(void)
{
    Node *c = parse_binary(3);
    if (tok == '?') {
        Node *a, *b;
        next();
        if (tok == ':') {
            /* GNU ?: */
            a = c;
        } else
            a = parse_expr();
        skip_tok(':');
        b = parse_cond_expr();
        return mk_cond(c, a, b);
    }
    return c;
}

static int assign_op(int t)
{
    switch (t) {
    case TOK_A_ADD: return N_ADD;
    case TOK_A_SUB: return N_SUB;
    case TOK_A_MUL: return N_MUL;
    case TOK_A_DIV: return N_DIV;
    case TOK_A_MOD: return N_MOD;
    case TOK_A_AND: return N_AND;
    case TOK_A_OR: return N_OR;
    case TOK_A_XOR: return N_XOR;
    case TOK_A_SHL: return N_SHL;
    case TOK_A_SAR: return N_SHR;
    }
    return 0;
}

static Node *parse_assignment_expr(void)
{
    Node *l = parse_cond_expr();
    int op;
    if (tok == '=') {
        Node *r;
        next();
        r = parse_assignment_expr();
        return mk_assign(l, r);
    }
    if ((op = assign_op(tok)) != 0) {
        Node *r, *n, *tmp;
        next();
        r = parse_assignment_expr();
        check_assignable(l);
        /* type check via mk_binary on a copy */
        {
            Node *lc = xmalloc(sizeof(Node));
            *lc = *l;
            tmp = mk_binary(op, lc, r);
        }
        n = node2(N_ASSIGN_OP, l, r);
        n->subop = op;
        n->type = type_unqual(l->type);
        n->c = tmp;  /* typed binary for codegen */
        if (is_ptr(l->type) && (op != N_ADD && op != N_SUB))
            tcc_error("invalid operand types for binary operation");
        return n;
    }
    return l;
}

Node *parse_expr(void)
{
    Node *l = parse_assignment_expr();
    while (tok == ',') {
        Node *r, *n;
        next();
        r = parse_assignment_expr();
        n = node2(N_COMMA, l, decay(r));
        n->type = n->b->type;
        l = n;
    }
    return l;
}

static int64_t parse_const_int_expr(void)
{
    Node *n;
    int64_t v;
    n = parse_cond_expr();
    n = decay(n);
    if (!eval_const_expr(n, &v))
        tcc_error("constant expression expected");
    return v;
}

static Type *parse_type_in_parens_or_expr_type(void) { return NULL; }
