/* ---------------------------------------------------------------- */
/* frame allocation for locals */

static long loc_offset;    /* current negative offset from rbp */
static long loc_max;       /* max frame size */

long alloc_local(int size, int align)
{
    if (align < 1) align = 1;
    if (size < 0) size = 0;
    loc_offset -= size;
    loc_offset &= -(long)align;
    if (-loc_offset > loc_max) loc_max = -loc_offset;
    return loc_offset;
}

long cur_frame_size(void) { return loc_max; }

/* ---------------------------------------------------------------- */
/* initializers */

typedef struct InitEntry {
    long off;
    Type *type;
    Node *val;
    int bit_off, bit_size;
} InitEntry;

typedef struct InitList {
    InitEntry *e;
    int n, cap;
    Type *type;        /* object type (array length may be completed) */
} InitList;

static void init_add(InitList *il, long off, Type *t, Node *val, int bit_off, int bit_size)
{
    if (il->n >= il->cap) {
        il->cap = il->cap ? il->cap * 2 : 16;
        il->e = xrealloc(il->e, il->cap * sizeof(InitEntry));
    }
    il->e[il->n].off = off;
    il->e[il->n].type = t;
    il->e[il->n].val = val;
    il->e[il->n].bit_off = bit_off;
    il->e[il->n].bit_size = bit_size;
    il->n++;
}

static void parse_init(InitList *il, Type *t, long off, int braced_ok, int *array_len_out);

/* initialize a scalar (or struct from expression) from the current expression */
static void init_scalar(InitList *il, Type *t, long off, Node *e, int bit_off, int bit_size)
{
    if (is_struct(t)) {
        e = decay(e);
        if (!is_struct(e->type) || !type_compatible(type_unqual(t), type_unqual(e->type), 0))
            tcc_error("cannot cast '%s' to '%s'", type_str(e->type), type_str(t));
        init_add(il, off, t, e, 0, 0);
        return;
    }
    if (t->kind == T_ARRAY) {
        /* char array from string literal handled by caller */
        tcc_error("invalid initializer");  /* hmm */
    }
    e = assign_convert(e, t, "initialization");
    init_add(il, off, t, e, bit_off, bit_size);
}

static int is_string_init(Type *t, Node *e)
{
    if (t->kind != T_ARRAY || !e || e->op != N_STR) return 0;
    if (t->ref->kind == T_CHAR && e->type->ref->kind == T_CHAR) return 1;
    if (t->ref->kind == T_INT && e->type->ref->kind == T_INT) return 1;
    return 0;
}

/* parse initializer for object of type t located at off. If tok is '{' a
   brace list is parsed; else a single expression (with brace elision for
   aggregates when called from an enclosing list: handled by caller). */
static void parse_init_list(InitList *il, Type *t, long off, int *len_out);

static void parse_init_elem(InitList *il, Type *t, long off, int *len_out)
{
    if (tok == '{') {
        parse_init_list(il, t, off, len_out);
        return;
    }
    if (t->kind == T_ARRAY && tok == TOK_STR) {
        Node *e = parse_string_node();
        if (is_string_init(t, e)) {
            int elen = e->type->len;  /* includes NUL */
            if (t->len < 0) {
                if (len_out) *len_out = elen;
            } else if (elen - 1 > t->len) {
                tcc_warning("initializer-string for array is too long");  /* hmm */
            }
            init_add(il, off, t, e, 0, 0);
            return;
        }
        tcc_error("invalid initializer"); /* hmm */
    }
    if (is_struct(t) || t->kind == T_ARRAY) {
        /* expression initializing an aggregate: must be compatible struct */
        Node *e = parse_assignment_expr();
        if (is_struct(t)) {
            init_scalar(il, t, off, e, 0, 0);
            return;
        }
        tcc_error("invalid initializer"); /* array from non-string */
    }
    {
        Node *e = parse_assignment_expr();
        init_scalar(il, t, off, e, 0, 0);
    }
}

/* brace-elided initialization of sub-aggregate from an element list.
   Consumes items for the sub-aggregate t at off until it is full or '}' */
static void parse_init_flat(InitList *il, Type *t, long off);

static Sym *next_init_field(Sym *f)
{
    return f ? f->next : NULL;
}

/* parse a brace-enclosed initializer list for t */
static void parse_init_list(InitList *il, Type *t, long off, int *len_out)
{
    skip_tok('{');
    if (is_struct(t)) {
        Sym *st = t->sym;
        Sym *f = st->fields;
        int is_union = t->kind == T_UNION;
        if (st->size < 0)
            tcc_error("initialization of incomplete type"); /* hmm */
        while (tok != '}') {
            if (tok == '.') {
                /* designator */
                int id;
                int foff = 0;
                Sym *ff;
                next();
                if (tok < TOK_IDENT) expect_err("field name");
                id = tok;
                next();
                ff = find_field(st, id, &foff);
                if (!ff) tcc_error("field not found: %s", tok_name(id));
                /* nested designators */
                f = ff;
                /* locate top-level field for continuation */
                {
                    Sym *q;
                    for (q = st->fields; q; q = q->next) if (q == ff) break;
                    if (!q) {
                        /* designated field is inside anonymous member: continue from it */
                    }
                }
                if (tok == '.' || tok == '[') {
                    /* chained designators: parse sub-initializer with designator */
                    InitList sub;
                    (void)sub;
                    /* reuse: treat as nested list element */
                    {
                        Type *ft = ff->type;
                        long fo = off + foff;
                        /* parse rest of designator chain */
                        while (tok == '.' || tok == '[') {
                            if (tok == '.') {
                                int o2 = 0; Sym *f2;
                                next();
                                if (tok < TOK_IDENT) expect_err("field name");
                                if (!is_struct(ft)) tcc_error("struct or union expected");
                                f2 = find_field(ft->sym, tok, &o2);
                                if (!f2) tcc_error("field not found: %s", tok_name(tok));
                                next();
                                fo += o2;
                                ft = f2->type;
                                ff = f2;
                            } else {
                                int64_t idx;
                                next();
                                idx = parse_const_int_expr();
                                skip_tok(']');
                                if (ft->kind != T_ARRAY) tcc_error("array expected"); /* hmm */
                                if (ft->len >= 0 && idx >= ft->len) tcc_error("index too large");
                                fo += idx * type_size(ft->ref, NULL);
                                ft = ft->ref;
                                ff = NULL;
                            }
                        }
                        skip_tok('=');
                        if (ff && ff->bit_size >= 0) {
                            Node *e = parse_assignment_expr();
                            init_scalar(il, ft, fo, e, ff->bit_off, ff->bit_size);
                        } else
                            parse_init_elem(il, ft, fo, NULL);
                    }
                    f = next_init_field(f);
                    if (tok == ',') { next(); continue; }
                    break;
                }
                skip_tok('=');
                if (ff->bit_size >= 0) {
                    Node *e = parse_assignment_expr();
                    init_scalar(il, ff->type, off + foff, e, ff->bit_off, ff->bit_size);
                } else
                    parse_init_elem(il, ff->type, off + foff, NULL);
                f = next_init_field(ff);
                if (tok == ',') { next(); if (tok == '}') break; continue; }
                break;
            }
            if (!f) {
                tcc_error("too many initializers");  /* hmm: tcc "too many initializers" */
            }
            if (f->anon_struct || (!f->id && is_struct(f->type))) {
                /* anonymous struct member: flat init */
                if (tok == '{')
                    parse_init_list(il, f->type, off + f->offset, NULL);
                else
                    parse_init_flat(il, f->type, off + f->offset);
            } else if (f->bit_size >= 0) {
                Node *e;
                if (tok == '{') {
                    next();
                    e = parse_assignment_expr();
                    skip_tok('}');
                } else
                    e = parse_assignment_expr();
                init_scalar(il, f->type, off + f->offset, e, f->bit_off, f->bit_size);
            } else if ((is_struct(f->type) || f->type->kind == T_ARRAY) && tok != '{' && !(f->type->kind == T_ARRAY && tok == TOK_STR)) {
                /* brace elision or struct expression */
                if (is_struct(f->type)) {
                    /* could be a struct-typed expression */
                    Node *e = parse_assignment_expr();
                    e = decay(e);
                    if (is_struct(e->type) && type_compatible(type_unqual(e->type), type_unqual(f->type), 0)) {
                        init_add(il, off + f->offset, f->type, e, 0, 0);
                    } else {
                        /* flat: first element gets e */
                        extern void init_flat_with_first(InitList *il, Type *t, long off, Node *first);
                        init_flat_with_first(il, f->type, off + f->offset, e);
                    }
                } else {
                    Node *e = parse_assignment_expr();
                    extern void init_flat_with_first(InitList *il, Type *t, long off, Node *first);
                    init_flat_with_first(il, f->type, off + f->offset, e);
                }
            } else {
                parse_init_elem(il, f->type, off + f->offset, NULL);
            }
            f = is_union ? NULL : f->next;
            if (tok == ',') { next(); continue; }
            break;
        }
    } else if (t->kind == T_ARRAY) {
        Type *et = t->ref;
        int es = type_size(et, NULL);
        long idx = 0, maxidx = 0;
        if (es < 0) tcc_error("unknown type size");
        while (tok != '}') {
            if (tok == '[') {
                int64_t i1, i2;
                next();
                i1 = parse_const_int_expr();
                i2 = i1;
                if (tok == TOK_DOTS) {
                    next();
                    i2 = parse_const_int_expr();
                }
                skip_tok(']');
                if (i1 < 0 || (t->len >= 0 && i2 >= t->len))
                    tcc_error("index too large");
                idx = i1;
                if (tok == '.' || tok == '[') {
                    /* nested designator */
                    Type *ft = et;
                    long fo = off + idx * es;
                    Sym *ff = NULL;
                    while (tok == '.' || tok == '[') {
                        if (tok == '.') {
                            int o2 = 0; Sym *f2;
                            next();
                            if (tok < TOK_IDENT) expect_err("field name");
                            if (!is_struct(ft)) tcc_error("struct or union expected");
                            f2 = find_field(ft->sym, tok, &o2);
                            if (!f2) tcc_error("field not found: %s", tok_name(tok));
                            next();
                            fo += o2;
                            ft = f2->type;
                            ff = f2;
                        } else {
                            int64_t ix;
                            next();
                            ix = parse_const_int_expr();
                            skip_tok(']');
                            if (ft->kind != T_ARRAY) tcc_error("array expected");
                            if (ft->len >= 0 && ix >= ft->len) tcc_error("index too large");
                            fo += ix * type_size(ft->ref, NULL);
                            ft = ft->ref;
                            ff = NULL;
                        }
                    }
                    skip_tok('=');
                    if (ff && ff->bit_size >= 0) {
                        Node *e = parse_assignment_expr();
                        init_scalar(il, ft, fo, e, ff->bit_off, ff->bit_size);
                    } else
                        parse_init_elem(il, ft, fo, NULL);
                    idx++;
                    if (idx > maxidx) maxidx = idx;
                    if (tok == ',') { next(); continue; }
                    break;
                }
                skip_tok('=');
                {
                    long k;
                    /* GNU range: evaluate once, replicate */
                    int save_n = il->n;
                    parse_init_elem(il, et, off + i1 * es, NULL);
                    for (k = i1 + 1; k <= i2; k++) {
                        int j;
                        for (j = save_n; j < il->n && j < save_n + 1000; j++) {
                            InitEntry e = il->e[j];
                            if (il->e[j].off >= off + i1 * es && il->e[j].off < off + (i1 + 1) * es) {
                                init_add(il, e.off + (k - i1) * es, e.type, e.val, e.bit_off, e.bit_size);
                            }
                        }
                    }
