/* flat initialization: consume following elements for aggregate t (brace elision) */
static int flat_cursor_active;

/* initialize aggregate t at off with first element already parsed (first),
   then continue consuming ',' separated items until full */
static void init_flat_aggregate(InitList *il, Type *t, long off, Node *first, int *done)
{
    if (is_struct(t)) {
        Sym *f = t->sym->fields;
        int is_union = t->kind == T_UNION;
        while (f) {
            Type *ft = f->type;
            if (first) {
                if (f->bit_size >= 0) init_scalar(il, ft, off + f->offset, first, f->bit_off, f->bit_size);
                else if (is_struct(ft) || ft->kind == T_ARRAY) {
                    if (is_struct(ft) && is_struct(decay(first)->type))
                        init_add(il, off + f->offset, ft, decay(first), 0, 0);
                    else
                        init_flat_aggregate(il, ft, off + f->offset, first, done);
                } else init_scalar(il, ft, off + f->offset, first, 0, 0);
                first = NULL;
            } else {
                if (tok != ',' || *done) { *done = 1; return; }
                next();
                if (tok == '}') { *done = 1; return; }
                if (tok == '.' || tok == '[') { unget_tok(','); *done = 1; return; }
                if (tok == '{')
                    parse_init_list(il, ft, off + f->offset, NULL);
                else if (f->bit_size >= 0) {
                    Node *e = parse_assignment_expr();
                    init_scalar(il, ft, off + f->offset, e, f->bit_off, f->bit_size);
