                        parse_init_elem(il, ft, off + f->offset, NULL);
                    } else {
                        Node *e = parse_assignment_expr();
                        init_flat_aggregate(il, ft, off + f->offset, e, done);
                    }
                } else {
                    Node *e = parse_assignment_expr();
                    init_scalar(il, ft, off + f->offset, e, 0, 0);
                }
            }
            if (is_union) break;
            f = f->next;
        }
        return;
    }
    if (t->kind == T_ARRAY) {
        Type *et = t->ref;
        int es = type_size(et, NULL);
        long idx = 0;
        if (t->len < 0) tcc_error("unknown type size"); /* flat init of incomplete array */
        while (idx < t->len) {
            if (first) {
                if (is_struct(et) || et->kind == T_ARRAY) init_flat_aggregate(il, et, off + idx * es, first, done);
                else init_scalar(il, et, off + idx * es, first, 0, 0);
                first = NULL;
            } else {
                if (tok != ',' || *done) { *done = 1; return; }
                next();
                if (tok == '}') { *done = 1; return; }
                if (tok == '.' || tok == '[') { unget_tok(','); *done = 1; return; }
                if (tok == '{')
