                        parse_init_elem(il, et, off + idx * es, NULL);
                    else {
                        Node *e = parse_assignment_expr();
                        init_flat_aggregate(il, et, off + idx * es, e, done);
                    }
                } else {
                    Node *e = parse_assignment_expr();
                    init_scalar(il, et, off + idx * es, e, 0, 0);
                }
            }
            idx++;
        }
        return;
    }
    if (first) init_scalar(il, t, off, first, 0, 0);
}

void init_flat_with_first(InitList *il, Type *t, long off, Node *first)
{
    int done = 0;
    init_flat_aggregate(il, t, off, first, &done);
    /* the caller expects tok to be ',' or '}' after the flat group: if we
       consumed items up to a ',' that belongs to the next element, we stopped
       with tok at that element; emulate by pushing back a ',' */
    if (!done && tok != ',' && tok != '}') {
        /* we are positioned at the next element: pretend a comma was seen */
        unget_tok(',');
    } else if (done && tok != ',' && tok != '}') {
        unget_tok(',');
    }
}

static void parse_init_flat(InitList *il, Type *t, long off)
{
    Node *e = parse_assignment_expr();
    init_flat_with_first(il, t, off, e);
}

/* top-level initializer for a declared object */
static void parse_initializer(InitList *il, Type **ptype)
{
    Type *t = *ptype;
    int len = -1;
    memset(il, 0, sizeof *il);
    if (tok == '{') {
        parse_init_list(il, t, 0, &len);
    } else {
        parse_init_elem(il, t, 0, &len);
    }
    if (t->kind == T_ARRAY && t->len < 0) {
        Type *nt = type_array(t->ref, len < 0 ? 0 : len);
        nt->quals = t->quals;
        *ptype = nt;
    }
    il->type = *ptype;
}

/* compound literal: (type){...} ; returns node for a temporary object */
static Node *parse_initializer_as_node(Type *t, int is_static)
{
    InitList il;
    Node *n;
    Sym *s;
    Type *ty = t;
    parse_initializer(&il, &ty);
    s = xcalloc(sizeof(Sym));
    s->kind = SYM_VAR;
    s->type = ty;
    s->id = 0;
    if (cur_func && !is_static) {
        int al;
        int sz = type_size(ty, &al);
        s->is_local = 1;
        s->loc = alloc_local(sz, al);
    } else {
        extern void define_global_data(Sym *s, InitList *il, int is_static);
        s->storage = ST_STATIC;
        define_global_data(s, &il, 1);
    }
    n = node_new(N_COMPOUND_LIT);
    n->sym = s;
    n->type = ty;
    n->lvalue = 1;
    if (s->is_local) {
        /* attach init entries */
        n->list = (Node **)il.e;
        n->nlist = il.n;
    }
    return n;
}
