/* top-level initializer for a declared object */
static void parse_initializer(InitList *il, Type **ptype)
{
    Type *t = *ptype;
    int len = -1;
    memset(il, 0, sizeof *il);
    init_pending = NULL;
    init_item(il, t, 0, 0, 0, &len);
    if (t->kind == T_ARRAY && t->len < 0) {
        Type *nt = type_array(t->ref, len < 0 ? 0 : len);
        nt->quals = t->quals;
        *ptype = nt;
    }
    il->type = *ptype;
}

void define_global_data(Sym *s, InitList *il, int is_static);

/* compound literal: (type){...} ; returns node for a temporary object */
static Node *parse_initializer_as_node(Type *t, int is_static)
{
    InitList il;
    Node *n;
    Sym *s;
    Type *ty = t;
    parse_initializer(&il, &ty);
    s = xcalloc(sizeof(Sym));
    s->kind = SYM_VAR;
    s->type = ty;
    s->id = 0;
    if (cur_func && !is_static) {
        int al;
        int sz = type_size(ty, &al);
        s->is_local = 1;
        s->loc = alloc_local(sz, al);
    } else {
        s->storage = ST_STATIC;
        define_global_data(s, &il, 1);
    }
    n = node_new(N_COMPOUND_LIT);
    n->sym = s;
    n->type = ty;
    n->lvalue = 1;
    if (s->is_local) {
        n->list = (Node **)il.e;
        n->nlist = il.n;
    }
    return n;
}
