static Node *parse_compound(int new_scope)
{
    Node *blk = node_new(N_BLOCK);
    skip_tok('{');
    if (new_scope) scope_enter();
    while (tok != '}') {
        if (tok == TOK_EOF)
            tcc_error("unexpected end of file");  /* hmm */
        if (tok == TOK_LABEL) {
            /* __label__ declarations */
            next();
            for (;;) {
                Sym *l;
                if (tok < TOK_IDENT) expect_err("label identifier");
                l = sym_push(2, tok, SYM_LABEL, NULL);
                pvec_push(&func_labels, l);
                next();
                if (tok == ',') { next(); continue; }
                break;
            }
            skip_tok(';');
            continue;
        }
        if (is_type_start(tok) && !(tok >= TOK_IDENT && is_typedef_name(tok) && 0)) {
            /* a typedef name followed by ':' is a label; else declaration */
            if (tok >= TOK_IDENT) {
                /* typedef name: could still be a label */
                int id = tok;
                next();
                if (tok == ':') {
                    unget_tok(id);
                    tokcur.s = NULL;
                    node_push(blk, parse_stmt());
                    continue;
                }
                unget_tok(id);
                tokcur.s = NULL;
            }
            parse_decl(1, blk);
            continue;
        }
        node_push(blk, parse_stmt());
    }
    next();
    if (new_scope) scope_leave();
    return blk;
}

