                        char buf[256];
                        snprintf(buf, sizeof buf, "%s.%d", tok_name(id), ++sym_counter);
                        s->asm_name = xstrdup(buf);
                        s->is_static_fn = 1; /* marks local static */
                    }
                } else if (local && is_extern) {
                    Sym *g = NULL;
                    /* extern in block: refers to global */
                    if (old && old->scope == 0) g = old;
                    if (!g) {
                        for (g = old; g; g = g->prev_binding) if (g->scope == 0) break;
                    }
                    if (g) {
                        if (!type_compatible(g->type, t, 0))
                            tcc_error("incompatible types for redefinition of '%s'", tok_name(id));
                        g->type = merge_types(g->type, t);
                        /* local alias binding */
                        s = sym_push(0, id, SYM_VAR, g->type);
                        *s = *g;
                        s->scope = cur_scope;
                        s->prev_binding = old;
                    } else {
                        if (old && old->scope == cur_scope)
                            tcc_error("redeclaration of '%s'", tok_name(id));
                        g = sym_global(id, SYM_VAR, t);
                        g->storage = ST_EXTERN;
                        s = sym_push(0, id, SYM_VAR, t);
                        *s = *g;
                        s->scope = cur_scope;
                        s->prev_binding = ident_get(id)->sym_id == s ? g : old;
                        /* keep binding chain: s -> ... */
                        {
                            Ident *ident = ident_get(id);
                            ident->sym_id = s;
                            s->prev_binding = g;
                        }
                    }
                    s = g;
                } else {
                    /* file scope */
                    if (old && old->scope == 0) {
                        if (old->kind != SYM_VAR)
                            tcc_error("redeclaration of '%s'", tok_name(id));
                        check_redecl_global(old, t, storage, has_init, id);
                        if (has_init && old->defined)
                            tcc_error("redefinition of '%s'", tok_name(id));
                        s = old;
                        s->type = merge_types(old->type, t);
                        if (!is_extern) s->storage &= ~ST_EXTERN;
                        if (storage & ST_STATIC) {
                            if (!(old->storage & ST_STATIC) && !(old->storage & ST_EXTERN) && 0)
                                tcc_error("static declaration follows non-static");
                            s->storage |= ST_STATIC;
                        }
                        redecl = 1;
                    } else {
                        s = sym_push(0, id, SYM_VAR, t);
                        s->storage = storage;
                    }
                }
                apply_attrs(s, &dad);
                if (has_init) {
                    InitList il;
                    Type *ty = s->type;
                    next();
                    if (is_extern && !local)
                        ; /* extern with initializer: definition */
                    parse_initializer(&il, &ty);
                    s->type = ty;
                    s->defined = 1;
                    define_global_data(s, &il, (s->storage & ST_STATIC) != 0);
                } else if (!is_extern && !redecl) {
                    /* tentative definition: handled at end (bss) */
                    extern void add_tentative(Sym *s);
                    add_tentative(s);
                } else if (!is_extern && redecl) {
                    extern void add_tentative(Sym *s);
                    add_tentative(s);
                }
                (void)redecl;
            }
        }
        if (tok == ',') {
            next();
            continue;
        }
        skip_tok(';');
        break;
    }
}

/* ---------------------------------------------------------------- */
/* function definition */

static void parse_function_body(Sym *fsym, Type *ft)
{
    Node *body;
    Sym *p;
    int i;
    Sym **params;
    int nparams = 0;
    Sym *save_func = cur_func;

    if (cur_scope != 0)
        tcc_error("function definition not allowed here");
    cur_func = fsym;
    func_ret_type = ft->ref;
    loc_offset = 0;
    loc_max = 0;
    func_labels.len = 0;
    in_loop = in_switch = 0;
    cur_switch = NULL;
    scope_enter();
    /* K&R: parameter declarations */
    if (ft->oldstyle && tok != '{') {
        /* parse declarations of params */
        while (tok != '{') {
            int storage, has_type;
            Attrs ad;
            Type *base;
            memset(&ad, 0, sizeof ad);
            base = parse_decl_specs(&storage, &ad, &has_type);
            if (!has_type) tcc_error("declaration expected");
            for (;;) {
                int id = 0;
                Type *t = parse_declarator(base, &id, &ad, 0);
                Sym *q;
                if (!id) expect_err("identifier");
                for (q = ft->params; q; q = q->next)
                    if (q->id == id) break;
                if (!q)
                    tcc_error("declaration for parameter '%s' but no such parameter", tok_name(id));
                if (t->kind == T_ARRAY) t = type_ptr(t->ref);
                else if (t->kind == T_FUNC) t = type_ptr(t);
                else if (is_integer(t)) t = t; /* no promotion of declared types */
                q->type = t;
                if (tok == ',') { next(); continue; }
                break;
            }
            skip_tok(';');
        }
    }
    /* push params */
    params = xcalloc(sizeof(Sym *) * (ft->nparams + 1));
    for (p = ft->params; p; p = p->next) {
        Sym *s;
        int sz, al;
        if (!p->id) {
            if (!ft->oldstyle)
                ; /* unnamed parameter allowed in definition? tcc: error */
            tcc_error("identifier expected");
        }
        s = sym_push(0, p->id, SYM_VAR, p->type);
        s->is_local = 1;
        s->storage = p->storage;
        sz = type_size(p->type, &al);
        if (sz < 0) tcc_error("unknown type size");
        if (sz < 8) sz = 8;
        s->loc = alloc_local(sz, al < 8 ? 8 : al);
        params[nparams++] = s;
    }
    /* struct return: hidden pointer slot */
    body = parse_compound(0);
    /* check labels */
    for (i = 0; i < func_labels.len; i++) {
        Sym *l = func_labels.p[i];
        if (l->label_used && !l->label_defined)
            tcc_error("label '%s' used but not defined", tok_name(l->id));
    }
    scope_leave();
    gen_function(fsym, body, params, nparams, (int)loc_max);
    for (i = 0; i < func_labels.len; i++) {
        Sym *l = func_labels.p[i];
        sym_unbind_label(l->id);
    }
    func_labels.len = 0;
    free(params);
    cur_func = save_func;
}

/* ---------------------------------------------------------------- */
/* top level */

static void parse_pragma_compile(TokVec *toks);

void parser_init(void)
{
    types_init();
    /* __builtin_va_list typedef is provided by the predefined buffer */
    pp_set_pragma_hook(parse_pragma_compile);
}

void parse_translation_unit(void)
{
    next();
    while (tok != TOK_EOF) {
        if (tok == ';') { next(); continue; }
        if (tok == TOK_STATIC_ASSERT) { parse_static_assert(); continue; }
        if (tok == TOK_ASM1 || tok == TOK_ASM2 || tok == TOK_ASM3) {
            Node *n = node_new(N_ASM);
            parse_asm_statement(n);
            gen_asm_statement(n);
            continue;
        }
        if (!is_type_start(tok)) {
            if (tok >= TOK_IDENT && !sym_find_id(tok)) {
                /* implicit int? tcc: "declaration expected"? For 'foo() {}' tcc assumes int */
                int id = tok;
                next();
                if (tok == '(') {
                    unget_tok(id);
                    tokcur.s = NULL;
                    /* treat as implicit int function */
                    {
                        extern void parse_decl_implicit_int(void);
                        parse_decl_implicit_int();
                    }
                    continue;
                }
                unget_tok(id);
                tokcur.s = NULL;
            }
            tcc_error("declaration expected");
        }
        parse_decl(0, NULL);
    }
}

void parse_decl_implicit_int(void)
{
    /* like parse_decl but with base type int and no specifiers */
    int id = 0;
    Attrs ad;
    Type *t;
    Sym *s, *old;
    memset(&ad, 0, sizeof ad);
    t = parse_declarator(type_int, &id, &ad, 0);
    if (t->kind != T_FUNC)
        tcc_error("declaration expected");
    old = sym_find_id(id);
    if (old && old->kind == SYM_FUNC) {
        s = old;
    } else {
        s = sym_global(id, SYM_FUNC, t);
    }
    if (tok == '{' || (t->oldstyle && tok != ';' && tok != ',')) {
        if (s->func_defined)
            tcc_error("redefinition of '%s'", tok_name(id));
        s->func_defined = s->defined = 1;
        parse_function_body(s, t);
        return;
    }
    skip_tok(';');
}

/* #pragma handling in compile mode */
static void parse_pragma_compile(TokVec *toks)
{
    int i = 0;
    if (toks->len == 0) return;
    while (i < toks->len && toks->t[i].id == ' ') i++;
    if (i >= toks->len) return;
    if (toks->t[i].id == TOK_PACK) {
        /* pack(n) / pack() / pack(push[,n]) / pack(pop) */
        int j = i + 1;
        while (j < toks->len && toks->t[j].id == ' ') j++;
        if (j < toks->len && toks->t[j].id == '(') {
            int k = j + 1;
            while (k < toks->len && toks->t[k].id == ' ') k++;
            if (k < toks->len && toks->t[k].id == ')') {
                cur_pack = 0;
                return;
            }
            if (k < toks->len && toks->t[k].id == TOK_PUSH) {
                if (pack_sp < 16) pack_stack[pack_sp++] = cur_pack;
                k++;
                while (k < toks->len && toks->t[k].id == ' ') k++;
                if (k < toks->len && toks->t[k].id == ',') {
                    k++;
                    while (k < toks->len && toks->t[k].id == ' ') k++;
                    if (k < toks->len && toks->t[k].id == TOK_PPNUM)
                        cur_pack = atoi(toks->t[k].s);
                }
                return;
            }
            if (k < toks->len && toks->t[k].id == TOK_POP) {
                if (pack_sp > 0) cur_pack = pack_stack[--pack_sp];
                return;
            }
            if (k < toks->len && toks->t[k].id == TOK_PPNUM) {
                cur_pack = atoi(toks->t[k].s);
                return;
            }
        }
        tcc_warning("#pragma pack: invalid syntax"); /* hmm */
        return;
    }
    if (toks->t[i].id == TOK_COMMENT) {
        /* comment(lib, "name") / comment(option, "...") */
        int j = i + 1;
        while (j < toks->len && toks->t[j].id == ' ') j++;
        if (j < toks->len && toks->t[j].id == '(') {
            int k = j + 1;
            while (k < toks->len && toks->t[k].id == ' ') k++;
            if (k < toks->len && (toks->t[k].id == TOK_LIB || toks->t[k].id == TOK_OPTION)) {
                int is_lib = toks->t[k].id == TOK_LIB;
                k++;
                while (k < toks->len && toks->t[k].id == ' ') k++;
                if (k < toks->len && toks->t[k].id == ',') k++;
                while (k < toks->len && toks->t[k].id == ' ') k++;
                if (k < toks->len && toks->t[k].id == TOK_STR) {
                    CStr cs; int w, c;
                    cstr_init(&cs);
                    parse_string_literal(toks->t[k].s, &cs, &w, &c);
                    if (is_lib) {
                        char buf[1024];
                        snprintf(buf, sizeof buf, "-l%s", cs.data ? cs.data : "");
                        pvec_push(&S.pragma_libs, xstrdup(buf));
                    } else {
                        /* options: only -D/-I/-l etc; ignore mostly */
                    }
                    cstr_free(&cs);
                }
                return;
            }
        }
        return;
    }
    if (S.warn_unsupported) {
        CStr cs;
        cstr_init(&cs);
        for (i = 0; i < toks->len; i++) cstr_cat(&cs, tok_spelling(&toks->t[i]), -1);
        tcc_warning("#pragma %s is ignored", cs.data ? cs.data : "");
        cstr_free(&cs);
    }
}
EOF
echo ok"}

actions.command:
cd /workspace/src && cat >> parse.c <<'EOF'

/* ---------------------------------------------------------------- */
/* statements */

void parse_static_assert(void)
{
    int64_t v;
    Node *e;
    next();
    skip_tok('(');
    e = parse_cond_expr();
    if (!eval_const_expr(e, &v))
        tcc_error("constant expression expected");
    if (tok == ',') {
        next();
        if (tok != TOK_STR)
            expect_err("string constant");
        if (!v) {
            CStr cs; int w, c;
            cstr_init(&cs);
            parse_string_literal(tokstr, &cs, &w, &c);
            tcc_error("%s", cs.data ? cs.data : "");
        }
        next();
    } else if (!v)
        tcc_error("_Static_assert fail");
    skip_tok(')');
    skip_tok(';');
}

static void parse_decl(int local, Node *block);

static Node *parse_cond_scalar(void)
{
    Node *e = parse_expr();
    e = decay(e);
    if (!is_scalar(e->type)) {
        if (is_struct(e->type) || e->type->kind == T_VOID)
            tcc_error("invalid operand types for binary operation"); /* hmm */
    }
    return e;
}

static Node *parse_stmt(void)
{
    Node *n;
    switch (tok) {
    case '{':
        return parse_compound(1);
    case TOK_IF: {
        n = node_new(N_IF);
        next();
        skip_tok('(');
        n->a = parse_cond_scalar();
        skip_tok(')');
        n->b = parse_stmt();
        if (tok == TOK_ELSE) {
            next();
            n->c = parse_stmt();
        }
        return n;
    }
    case TOK_WHILE: {
        n = node_new(N_WHILE);
        next();
        skip_tok('(');
        n->a = parse_cond_scalar();
        skip_tok(')');
        in_loop++;
        n->b = parse_stmt();
        in_loop--;
        return n;
    }
    case TOK_DO: {
        n = node_new(N_DO);
        next();
        in_loop++;
        n->b = parse_stmt();
        in_loop--;
        if (tok != TOK_WHILE)
            skip_tok(TOK_WHILE);
        next();
        skip_tok('(');
        n->a = parse_cond_scalar();
        skip_tok(')');
        skip_tok(';');
        return n;
    }
    case TOK_FOR: {
        n = node_new(N_FOR);
        next();
        skip_tok('(');
        scope_enter();
        if (tok != ';') {
            if (is_type_start(tok)) {
                Node *blk = node_new(N_BLOCK);
                parse_decl(1, blk);
                n->a = blk;
            } else {
                n->a = node1(N_EXPR, parse_expr());
                skip_tok(';');
            }
        } else
            next();
        if (tok != ';')
            n->b = parse_cond_scalar();
        skip_tok(';');
        if (tok != ')')
            n->c = parse_expr();
        skip_tok(')');
        in_loop++;
        n->d = parse_stmt();
        in_loop--;
        scope_leave();
        return n;
    }
    case TOK_SWITCH: {
        Node *save = cur_switch;
        n = node_new(N_SWITCH);
        next();
        skip_tok('(');
        n->a = parse_expr();
        n->a = decay(n->a);
        if (!is_integer(n->a->type))
            tcc_error("switch value must be an integer"); /* hmm */
        n->a = promote(n->a);
        skip_tok(')');
        cur_switch = n;
        in_switch++;
        n->b = parse_stmt();
        in_switch--;
        cur_switch = save;
        return n;
    }
    case TOK_CASE: {
        int64_t v1, v2;
        int i;
        n = node_new(N_CASE);
        next();
        if (!cur_switch)
            tcc_error("case not in switch");  /* hmm */
        {
            Node *e = parse_cond_expr();
            e = decay(e);
            if (!eval_const_expr(e, &v1))
                tcc_error("constant expression expected");
            v2 = v1;
            if (tok == TOK_DOTS) {
                next();
                e = parse_cond_expr();
                if (!eval_const_expr(decay(e), &v2))
                    tcc_error("constant expression expected");
                if (v2 < v1)
                    tcc_warning("empty case range");
            }
        }
        /* truncate to switch type */
        {
            Type *st = cur_switch->a->type;
            v1 = trunc_int(v1, st);
            v2 = trunc_int(v2, st);
        }
        skip_tok(':');
        for (i = 0; i < cur_switch->nlist; i++) {
            Node *c = cur_switch->list[i];
            if (c->op == N_CASE) {
                int64_t a = c->ival, b = c->fval;
                if (!(v2 < a || v1 > b))
                    tcc_error("duplicate case value");
            }
        }
        n->ival = v1;
        n->fval = (long double)v2;
        n->label = gen_new_label();
        node_push(cur_switch, n);
        if (tok == '}') {
            n->a = NULL;
            return n;
        }
        n->a = parse_stmt();
        return n;
    }
    case TOK_DEFAULT: {
        int i;
        next();
        skip_tok(':');
        if (!cur_switch)
            tcc_error("'default' not in switch"); /* hmm */
        for (i = 0; i < cur_switch->nlist; i++)
            if (cur_switch->list[i]->op == N_DEFAULT)
                tcc_error("too many 'default'");
        n = node_new(N_DEFAULT);
        n->label = gen_new_label();
        node_push(cur_switch, n);
        if (tok == '}') return n;
        n->a = parse_stmt();
        return n;
    }
    case TOK_BREAK:
        next();
        if (!in_loop && !in_switch)
            tcc_error("cannot break");
        skip_tok(';');
        return node_new(N_BREAK);
    case TOK_CONTINUE:
        next();
        if (!in_loop)
            tcc_error("cannot continue");
        skip_tok(';');
        return node_new(N_CONTINUE);
    case TOK_RETURN: {
        n = node_new(N_RETURN);
        next();
        if (tok != ';') {
            Node *e = parse_expr();
            if (func_ret_type->kind == T_VOID) {
                e = decay(e);
                if (e->type->kind != T_VOID)
                    tcc_error("cannot cast from/to void");  /* hmm: tcc */
                n->a = e;
            } else {
                n->a = assign_convert(e, func_ret_type, "return");
            }
        } else if (func_ret_type->kind != T_VOID) {
            /* tcc: no diagnostic by default */
        }
        skip_tok(';');
        return n;
    }
    case TOK_GOTO: {
        next();
        if (tok == '*') {
            Node *e;
            next();
            e = parse_expr();
            e = decay(e);
            if (!is_ptr(e->type) && !is_integer(e->type))
                tcc_error("pointer expected");
            n = node_new(N_COMPGOTO);
            n->a = e;
            skip_tok(';');
            return n;
        }
        if (tok < TOK_IDENT)
            expect_err("label identifier");
        {
            Sym *s = sym_find_label(tok);
            if (!s) {
                s = sym_push(2, tok, SYM_LABEL, NULL);
                pvec_push(&func_labels, s);
            }
            s->label_used = 1;
            n = node_new(N_GOTO);
            n->sym = s;
            next();
        }
        skip_tok(';');
        return n;
    }
    case ';':
        next();
        return node_new(N_NOP);
    case TOK_ASM1: case TOK_ASM2: case TOK_ASM3:
        n = node_new(N_ASM);
        parse_asm_statement(n);
        return n;
    case TOK_STATIC_ASSERT:
        parse_static_assert();
        return node_new(N_NOP);
    default:
        if (tok >= TOK_IDENT) {
            /* label? */
            int id = tok;
            Sym *s = sym_find_id(id);
            next();
            if (tok == ':') {
                Sym *l;
                next();
                l = sym_find_label(id);
                if (l) {
                    if (l->label_defined)
                        tcc_error("duplicate label '%s'", tok_name(id));
                } else {
                    l = sym_push(2, id, SYM_LABEL, NULL);
                    pvec_push(&func_labels, l);
                }
                l->label_defined = 1;
                n = node_new(N_LABEL);
                n->sym = l;
                {
                    Attrs ad;
                    memset(&ad, 0, sizeof ad);
                    parse_attributes(&ad);
                }
                if (tok == '}') {
                    return n;
                }
                n->a = parse_stmt();
                return n;
            }
            unget_tok(id);
            tokcur.s = NULL;
            (void)s;
        }
        n = node_new(N_EXPR);
        n->a = parse_expr();
        skip_tok(';');
        return n;
    }
}

static Node *parse_compound(int new_scope)
{
    Node *blk = node_new(N_BLOCK);
    skip_tok('{');
    if (new_scope) scope_enter();
    while (tok != '}') {
        if (tok == TOK_EOF)
            tcc_error("unexpected end of file");  /* hmm */
        if (tok == TOK_LABEL) {
            /* __label__ declarations */
            next();
            for (;;) {
                Sym *l;
                if (tok < TOK_IDENT) expect_err("label identifier");
                l = sym_push(2, tok, SYM_LABEL, NULL);
                pvec_push(&func_labels, l);
                next();
                if (tok == ',') { next(); continue; }
                break;
            }
            skip_tok(';');
            continue;
        }
        if (is_type_start(tok) && !(tok >= TOK_IDENT && is_typedef_name(tok) && 0)) {
            /* a typedef name followed by ':' is a label; else declaration */
            if (tok >= TOK_IDENT) {
                /* typedef name: could still be a label */
                int id = tok;
                next();
                if (tok == ':') {
                    unget_tok(id);
                    tokcur.s = NULL;
                    node_push(blk, parse_stmt());
                    continue;
                }
                unget_tok(id);
                tokcur.s = NULL;
            }
            parse_decl(1, blk);
            continue;
        }
        node_push(blk, parse_stmt());
    }
    next();
    if (new_scope) scope_leave();
    return blk;
}

/* ---------------------------------------------------------------- */
/* declarations */

static int sym_counter;

static void check_redecl_global(Sym *s, Type *t, int storage, int has_init, int id)
{
    (void)storage; (void)has_init; (void)id;
    if (!type_compatible(s->type, t, 0)) {
        tcc_error("incompatible types for redefinition of '%s'", tok_name(s->id));
    }
}

/* merge type info (e.g. complete array size, function prototype) */
static Type *merge_types(Type *old, Type *new_)
{
    if (old->kind == T_ARRAY && new_->kind == T_ARRAY) {
        if (old->len < 0 && new_->len >= 0) return new_;
        return old;
    }
    if (old->kind == T_FUNC && new_->kind == T_FUNC) {
        if (old->oldstyle && !new_->oldstyle) return new_;
        return old;
    }
    return new_;
}

static void parse_function_body(Sym *fsym, Type *ft);

static void apply_attrs(Sym *s, Attrs *ad)
{
    if (ad->weak) s->weak = 1;
    if (ad->section) s->section_name = ad->section;
    if (ad->alias) s->alias_target = ad->alias;
    if (ad->asm_name) s->asm_name = ad->asm_name;
    if (ad->aligned > s->aligned_attr) s->aligned_attr = ad->aligned;
    if (ad->noreturn) s->noreturn = 1;
    if (ad->constructor) s->constructor = 1;
    if (ad->destructor) s->destructor = 1;
    if (ad->visibility) s->visibility = ad->visibility;
    if (ad->cleanup_fn) s->cleanup_id = ad->cleanup_fn;
    if (ad->always_inline) s->always_inline = 1;
}

static void parse_decl(int local, Node *block)
{
    int storage, has_type;
    Attrs ad;
    Type *base;
    memset(&ad, 0, sizeof ad);
    base = parse_decl_specs(&storage, &ad, &has_type);
    if (!has_type) {
