/* ---------------------------------------------------------------- */
/* function definition */

static void parse_function_body(Sym *fsym, Type *ft)
{
    Node *body;
    Sym *p;
    int i;
    Sym **params;
    int nparams = 0;
    Sym *save_func = cur_func;

    if (cur_scope != 0)
        tcc_error("function definition not allowed here");
    cur_func = fsym;
    func_ret_type = ft->ref;
    loc_offset = 0;
    loc_max = 0;
    func_labels.len = 0;
    in_loop = in_switch = 0;
    cur_switch = NULL;
    scope_enter();
    /* K&R: parameter declarations */
    if (ft->oldstyle && tok != '{') {
        /* parse declarations of params */
        while (tok != '{') {
            int storage, has_type;
            Attrs ad;
            Type *base;
            memset(&ad, 0, sizeof ad);
            base = parse_decl_specs(&storage, &ad, &has_type);
            if (!has_type) tcc_error("declaration expected");
            for (;;) {
                int id = 0;
                Type *t = parse_declarator(base, &id, &ad, 0);
                Sym *q;
                if (!id) expect_err("identifier");
                for (q = ft->params; q; q = q->next)
                    if (q->id == id) break;
                if (!q)
                    tcc_error("declaration for parameter '%s' but no such parameter", tok_name(id));
                if (t->kind == T_ARRAY) t = type_ptr(t->ref);
                else if (t->kind == T_FUNC) t = type_ptr(t);
                else if (is_integer(t)) t = t; /* no promotion of declared types */
                q->type = t;
                if (tok == ',') { next(); continue; }
                break;
            }
            skip_tok(';');
        }
    }
    /* push params */
    params = xcalloc(sizeof(Sym *) * (ft->nparams + 1));
    for (p = ft->params; p; p = p->next) {
        Sym *s;
        int sz, al;
        if (!p->id) {
            if (!ft->oldstyle)
                ; /* unnamed parameter allowed in definition? tcc: error */
            tcc_error("identifier expected");
        }
        s = sym_push(0, p->id, SYM_VAR, p->type);
        s->is_local = 1;
        s->storage = p->storage;
        sz = type_size(p->type, &al);
        if (sz < 0) tcc_error("unknown type size");
        if (sz < 8) sz = 8;
        s->loc = alloc_local(sz, al < 8 ? 8 : al);
        params[nparams++] = s;
    }
    /* struct return: hidden pointer slot */
    body = parse_compound(0);
    /* check labels */
    for (i = 0; i < func_labels.len; i++) {
        Sym *l = func_labels.p[i];
        if (l->label_used && !l->label_defined)
            tcc_error("label '%s' used but not defined", tok_name(l->id));
    }
    scope_leave();
    gen_function(fsym, body, params, nparams, (int)loc_max);
    for (i = 0; i < func_labels.len; i++) {
        Sym *l = func_labels.p[i];
        sym_unbind_label(l->id);
    }
    func_labels.len = 0;
    free(params);
    cur_func = save_func;
}

/* ---------------------------------------------------------------- */
/* top level */

static void parse_pragma_compile(TokVec *toks);

void parser_init(void)
{
    types_init();
    /* __builtin_va_list typedef is provided by the predefined buffer */
    pp_set_pragma_hook(parse_pragma_compile);
}

void parse_translation_unit(void)
{
    next();
    while (tok != TOK_EOF) {
        if (tok == ';') { next(); continue; }
        if (tok == TOK_STATIC_ASSERT) { parse_static_assert(); continue; }
        if (tok == TOK_ASM1 || tok == TOK_ASM2 || tok == TOK_ASM3) {
            Node *n = node_new(N_ASM);
            parse_asm_statement(n);
            gen_asm_statement(n);
            continue;
        }
        if (!is_type_start(tok)) {
            if (tok >= TOK_IDENT && !sym_find_id(tok)) {
                /* implicit int? tcc: "declaration expected"? For 'foo() {}' tcc assumes int */
                int id = tok;
                next();
                if (tok == '(') {
                    unget_tok(id);
                    tokcur.s = NULL;
                    /* treat as implicit int function */
                    {
                        extern void parse_decl_implicit_int(void);
                        parse_decl_implicit_int();
                    }
                    continue;
                }
                unget_tok(id);
                tokcur.s = NULL;
            }
            tcc_error("declaration expected");
        }
        parse_decl(0, NULL);
    }
}

void parse_decl_implicit_int(void)
{
    /* like parse_decl but with base type int and no specifiers */
    int id = 0;
    Attrs ad;
    Type *t;
    Sym *s, *old;
    memset(&ad, 0, sizeof ad);
    t = parse_declarator(type_int, &id, &ad, 0);
    if (t->kind != T_FUNC)
        tcc_error("declaration expected");
    old = sym_find_id(id);
    if (old && old->kind == SYM_FUNC) {
        s = old;
    } else {
        s = sym_global(id, SYM_FUNC, t);
    }
    if (tok == '{' || (t->oldstyle && tok != ';' && tok != ',')) {
        if (s->func_defined)
            tcc_error("redefinition of '%s'", tok_name(id));
        s->func_defined = s->defined = 1;
        parse_function_body(s, t);
        return;
    }
    skip_tok(';');
}

/* #pragma handling in compile mode */
static void parse_pragma_compile(TokVec *toks)
{
    int i = 0;
    if (toks->len == 0) return;
    while (i < toks->len && toks->t[i].id == ' ') i++;
    if (i >= toks->len) return;
    if (toks->t[i].id == TOK_PACK) {
        /* pack(n) / pack() / pack(push[,n]) / pack(pop) */
        int j = i + 1;
        while (j < toks->len && toks->t[j].id == ' ') j++;
        if (j < toks->len && toks->t[j].id == '(') {
            int k = j + 1;
            while (k < toks->len && toks->t[k].id == ' ') k++;
            if (k < toks->len && toks->t[k].id == ')') {
                cur_pack = 0;
                return;
            }
            if (k < toks->len && toks->t[k].id == TOK_PUSH) {
                if (pack_sp < 16) pack_stack[pack_sp++] = cur_pack;
                k++;
                while (k < toks->len && toks->t[k].id == ' ') k++;
                if (k < toks->len && toks->t[k].id == ',') {
                    k++;
                    while (k < toks->len && toks->t[k].id == ' ') k++;
                    if (k < toks->len && toks->t[k].id == TOK_PPNUM)
                        cur_pack = atoi(toks->t[k].s);
                }
                return;
            }
            if (k < toks->len && toks->t[k].id == TOK_POP) {
                if (pack_sp > 0) cur_pack = pack_stack[--pack_sp];
                return;
            }
            if (k < toks->len && toks->t[k].id == TOK_PPNUM) {
                cur_pack = atoi(toks->t[k].s);
                return;
            }
        }
        tcc_warning("#pragma pack: invalid syntax"); /* hmm */
        return;
    }
    if (toks->t[i].id == TOK_COMMENT) {
        /* comment(lib, "name") / comment(option, "...") */
        int j = i + 1;
        while (j < toks->len && toks->t[j].id == ' ') j++;
        if (j < toks->len && toks->t[j].id == '(') {
            int k = j + 1;
            while (k < toks->len && toks->t[k].id == ' ') k++;
            if (k < toks->len && (toks->t[k].id == TOK_LIB || toks->t[k].id == TOK_OPTION)) {
                int is_lib = toks->t[k].id == TOK_LIB;
                k++;
                while (k < toks->len && toks->t[k].id == ' ') k++;
                if (k < toks->len && toks->t[k].id == ',') k++;
                while (k < toks->len && toks->t[k].id == ' ') k++;
                if (k < toks->len && toks->t[k].id == TOK_STR) {
                    CStr cs; int w, c;
                    cstr_init(&cs);
                    parse_string_literal(toks->t[k].s, &cs, &w, &c);
                    if (is_lib) {
                        char buf[1024];
                        snprintf(buf, sizeof buf, "-l%s", cs.data ? cs.data : "");
                        pvec_push(&S.pragma_libs, xstrdup(buf));
                    } else {
                        /* options: only -D/-I/-l etc; ignore mostly */
                    }
                    cstr_free(&cs);
                }
                return;
            }
        }
        return;
    }
    if (S.warn_unsupported) {
        CStr cs;
        cstr_init(&cs);
        for (i = 0; i < toks->len; i++) cstr_cat(&cs, tok_spelling(&toks->t[i]), -1);
        tcc_warning("#pragma %s is ignored", cs.data ? cs.data : "");
        cstr_free(&cs);
    }
}
