static void section_reserve(Section *s, long size)
{
    if (size > s->cap) {
        long nc = s->cap ? s->cap : 1024;
        while (nc < size) nc *= 2;
        s->data = xrealloc(s->data, nc);
        memset(s->data + s->cap, 0, nc - s->cap);
        s->cap = nc;
    }
}

long section_add(Section *s, long size, int align)
{
    long off;
    if (align > s->align) s->align = align;
    off = (s->size + align - 1) & -(long)align;
    s->size = off + size;
    if (s->type != SHT_NOBITS)
        section_reserve(s, s->size);
    return off;
}

void section_put(Section *s, const void *data, long size)
{
    section_reserve(s, s->size + size);
    memcpy(s->data + s->size, data, size);
    s->size += size;
}

void section_putc(Section *s, int c)
{
    section_reserve(s, s->size + 1);
    s->data[s->size++] = c;
