/* x86-64 code generator from AST */
#include "cc.h"
#include <elf.h>

/* register numbers */
enum { RAX = 0, RCX, RDX, RBX, RSP, RBP, RSI, RDI, R8, R9, R10, R11, R12, R13, R14, R15, RIP = -1 };

static Section *cs;             /* current code section */
static long func_start;
static int nlabels;
typedef struct Label { long pos; int defined; } Label;
static Label *labels;
static int labels_cap;
typedef struct Fixup { long pos; int label; } Fixup;
static Fixup *fixups;
static int nfixups, fixups_cap;
static long frame_size_pos;
static long frame_size;
static long frame_temp_off;     /* temp slots allocated during codegen */
static int break_label, continue_label;
static Sym *gen_func_sym;
static int func_variadic;
static long reg_save_off;
static int ret_label;
static long ret_struct_ptr_off;  /* slot holding hidden return pointer */
static int func_has_vla;
static long vla_sp_save;

static void o(int b) { section_putc(cs, b & 0xff); }
static void o32(uint32_t v) { section_put32(cs, v); }
static void o64(uint64_t v) { section_put64(cs, v); }
static long ind(void) { return cs->size; }

/* ---------------------------------------------------------------- */
/* labels */

int gen_new_label(void)
{
    if (nlabels >= labels_cap) {
        labels_cap = labels_cap ? labels_cap * 2 : 256;
        labels = xrealloc(labels, labels_cap * sizeof(Label));
    }
    labels[nlabels].pos = -1;
    labels[nlabels].defined = 0;
    return nlabels++;
}

static void label_here(int l)
{
    labels[l].pos = ind();
    labels[l].defined = 1;
}

static void add_fixup(long pos, int l)
{
    if (nfixups >= fixups_cap) {
        fixups_cap = fixups_cap ? fixups_cap * 2 : 256;
        fixups = xrealloc(fixups, fixups_cap * sizeof(Fixup));
    }
    fixups[nfixups].pos = pos;
    fixups[nfixups].label = l;
    nfixups++;
}

static void resolve_fixups(void)
{
    int i;
    for (i = 0; i < nfixups; i++) {
        Fixup *f = &fixups[i];
        long target = labels[f->label].pos;
        int32_t rel;
        if (!labels[f->label].defined)
            tcc_error("internal: undefined label");
        rel = (int32_t)(target - (f->pos + 4));
        section_patch32(cs, f->pos, rel);
    }
    nfixups = 0;
}

/* jmp rel32 */
static void gen_jmp(int l)
{
    o(0xe9);
    add_fixup(ind(), l);
    o32(0);
}

/* jcc rel32: cc is the condition code (0x84 = je ...) */
static void gen_jcc(int cc, int l)
{
    o(0x0f);
    o(0x80 | cc);
    add_fixup(ind(), l);
    o32(0);
}

/* ---------------------------------------------------------------- */
/* instruction encoding helpers */

static void rex(int w, int reg, int index, int base)
{
    int r = 0x40 | (w ? 8 : 0) | ((reg >> 3) & 1) << 2 | ((index >> 3) & 1) << 1 | ((base >> 3) & 1);
    if (r != 0x40 || w)
        o(r);
}

/* modrm with memory operand [base + disp], base may be RIP */
static void modrm_mem(int reg, int base, long disp)
{
    if (base == RIP) {
        o(((reg & 7) << 3) | 5);
        o32((uint32_t)disp);
        return;
    }
    if (disp == 0 && (base & 7) != 5) {
        o(((reg & 7) << 3) | (base & 7));
        if ((base & 7) == 4) o(0x24);
        return;
    }
    if (disp >= -128 && disp <= 127) {
        o(0x40 | ((reg & 7) << 3) | (base & 7));
        if ((base & 7) == 4) o(0x24);
        o(disp & 0xff);
        return;
    }
    o(0x80 | ((reg & 7) << 3) | (base & 7));
    if ((base & 7) == 4) o(0x24);
    o32((uint32_t)disp);
}

static void modrm_reg(int reg, int rm)
{
    o(0xc0 | ((reg & 7) << 3) | (rm & 7));
}

/* generic: opcode with reg,reg (64-bit if w) */
static void op_rr(int w, int opc, int reg, int rm)
{
    rex(w, reg, 0, rm);
    o(opc);
    modrm_reg(reg, rm);
}

/* mov dst, src (64-bit) */
static void mov_rr(int dst, int src) { op_rr(1, 0x89, src, dst); }
static void mov_rr32(int dst, int src) { op_rr(0, 0x89, src, dst); }

/* mov reg, imm64 */
static void mov_ri(int reg, int64_t v)
{
    if (v >= 0 && v <= 0xffffffffLL) {
        rex(0, 0, 0, reg);
        o(0xb8 + (reg & 7));
        o32((uint32_t)v);
    } else if (v >= INT32_MIN && v <= INT32_MAX) {
        rex(1, 0, 0, reg);
        o(0xc7);
        modrm_reg(0, reg);
        o32((uint32_t)v);
    } else {
        rex(1, 0, 0, reg);
        o(0xb8 + (reg & 7));
        o64(v);
    }
}

/* memory ops: size 1,2,4,8 */
static void load_reg_mem(int size, int reg, int base, long disp, int sign)
{
    /* load into reg (64-bit result, extended per sign) */
    switch (size) {
    case 1:
        rex(1, reg, 0, base);
        o(0x0f); o(sign ? 0xbe : 0xb6);
        modrm_mem(reg, base, disp);
        break;
    case 2:
        rex(1, reg, 0, base);
        o(0x0f); o(sign ? 0xbf : 0xb7);
        modrm_mem(reg, base, disp);
        break;
    case 4:
        if (sign) {
            rex(1, reg, 0, base);
            o(0x63);
            modrm_mem(reg, base, disp);
        } else {
            rex(0, reg, 0, base);
            o(0x8b);
            modrm_mem(reg, base, disp);
        }
        break;
    default:
        rex(1, reg, 0, base);
        o(0x8b);
        modrm_mem(reg, base, disp);
        break;
    }
}

static void store_reg_mem(int size, int reg, int base, long disp)
{
    switch (size) {
    case 1:
        if (reg >= 4) rex(0, reg, 0, base); else rex(0, reg, 0, base);
        if (reg >= 4 && reg < 8 && !((base >> 3) & 1)) o(0x40 | ((reg >> 3) << 2) | ((base >> 3) & 1));  /* need REX for sil/dil */
        o(0x88);
        modrm_mem(reg, base, disp);
        break;
    case 2:
        o(0x66);
        rex(0, reg, 0, base);
        o(0x89);
        modrm_mem(reg, base, disp);
        break;
    case 4:
        rex(0, reg, 0, base);
        o(0x89);
        modrm_mem(reg, base, disp);
        break;
    default:
        rex(1, reg, 0, base);
        o(0x89);
        modrm_mem(reg, base, disp);
        break;
    }
}

static void lea(int reg, int base, long disp)
{
    rex(1, reg, 0, base);
    o(0x8d);
    modrm_mem(reg, base, disp);
}

static void push_r(int r) { rex(0, 0, 0, r); o(0x50 + (r & 7)); }
static void pop_r(int r) { rex(0, 0, 0, r); o(0x58 + (r & 7)); }

/* arithmetic reg, reg: opcodes: add 01, or 09, and 21, sub 29, xor 31, cmp 39 */
static void alu_rr(int w, int opc, int dst, int src) { op_rr(w, opc, src, dst); }

/* add/sub rsp, imm32 */
static void add_rsp(long v)
{
    if (v == 0) return;
    rex(1, 0, 0, RSP);
    o(0x81);
    modrm_reg(0, RSP);
    o32((uint32_t)v);
}
static void sub_rsp(long v)
{
    if (v == 0) return;
    rex(1, 0, 0, RSP);
    o(0x81);
    modrm_reg(5, RSP);
    o32((uint32_t)v);
}

/* SSE: movsd/movss xmm, [base+disp] and store */
static void sse_load(int is_double, int xmm, int base, long disp)
{
    o(is_double ? 0xf2 : 0xf3);
    rex(0, xmm, 0, base);
    o(0x0f); o(0x10);
    modrm_mem(xmm, base, disp);
}
static void sse_store(int is_double, int xmm, int base, long disp)
{
    o(is_double ? 0xf2 : 0xf3);
    rex(0, xmm, 0, base);
    o(0x0f); o(0x11);
    modrm_mem(xmm, base, disp);
}
/* sse op xmm_dst, xmm_src: op byte e.g. 0x58 add, 0x5c sub, 0x59 mul, 0x5e div, 0x2e ucomis, 0x10 mov */
static void sse_rr(int is_double, int opb, int dst, int src)
{
    if (opb == 0x2e) o(is_double ? 0x66 : 0); /* ucomisd needs 66, ucomiss none */
    else o(is_double ? 0xf2 : 0xf3);
    rex(0, dst, 0, src);
    o(0x0f); o(opb);
    modrm_reg(dst, src);
}

/* push xmm0 (8 bytes) */
static void push_xmm0(int is_double)
{
    sub_rsp(8);
    sse_store(1, 0, RSP, 0);
    (void)is_double;
}
static void pop_xmm(int xmm)
{
    sse_load(1, xmm, RSP, 0);
    add_rsp(8);
}

/* x87 */
static void x87_fld_mem(int base, long disp) { rex(0, 0, 0, base); o(0xdb); modrm_mem(5, base, disp); }   /* fld tbyte */
static void x87_fstp_mem(int base, long disp) { rex(0, 0, 0, base); o(0xdb); modrm_mem(7, base, disp); }  /* fstp tbyte */
static void x87_fld64(int base, long disp) { rex(0, 0, 0, base); o(0xdd); modrm_mem(0, base, disp); }
static void x87_fstp64(int base, long disp) { rex(0, 0, 0, base); o(0xdd); modrm_mem(3, base, disp); }
static void x87_fld32(int base, long disp) { rex(0, 0, 0, base); o(0xd9); modrm_mem(0, base, disp); }
static void x87_fstp32(int base, long disp) { rex(0, 0, 0, base); o(0xd9); modrm_mem(3, base, disp); }
static void x87_fild64(int base, long disp) { rex(0, 0, 0, base); o(0xdf); modrm_mem(5, base, disp); }
static void x87_fisttp64(int base, long disp) { rex(0, 0, 0, base); o(0xdd); modrm_mem(1, base, disp); }
static void push_st0(void) { sub_rsp(16); x87_fstp_mem(RSP, 0); }
static void pop_st0(void) { x87_fld_mem(RSP, 0); add_rsp(16); }

/* ---------------------------------------------------------------- */
/* symbol references */

static int sym_elf_index(Sym *s);

/* lea rax, [rip + sym + addend] */
static void lea_sym(int reg, Sym *s, long addend)
{
    int idx = sym_elf_index(s);
    rex(1, reg, 0, 0);
    o(0x8d);
    modrm_mem(reg, RIP, 0);
    section_reloc(cs, ind() - 4, R_X86_64_PC32, idx, addend - 4);
}

static void call_sym(Sym *s)
{
    int idx = sym_elf_index(s);
    o(0xe8);
    section_reloc(cs, ind(), R_X86_64_PLT32, idx, -4);
    o32(0);
}

/* string literals */
static int string_counter;

static int new_string_literal(const char *data, int len, Type *t, Sym **psym)
{
    long off;
    char name[32];
    int idx;
    Sym *s;
    int al = type_align(t);
    off = section_add(rodata_section, len, al);
    memcpy(rodata_section->data + off, data, len);
    snprintf(name, sizeof name, "L.%d", string_counter++);
    idx = elf_sym_add(name, off, len, STB_LOCAL, STT_OBJECT, rodata_section->sh_num);
    s = xcalloc(sizeof(Sym));
    s->kind = SYM_VAR;
    s->type = t;
    s->elf_sym = idx;
    s->section = rodata_section->sh_num;
    s->sec_offset = off;
    s->defined = 1;
    s->storage = ST_STATIC;
    if (psym) *psym = s;
    return idx;
}

static const char *sym_name(Sym *s)
{
    if (s->asm_name) return s->asm_name;
    return tok_name(s->id);
}

static int sym_elf_index(Sym *s)
{
    if (s->elf_sym)
        return s->elf_sym;
    if (s->id == 0 && !s->asm_name) {
        /* anonymous object (compound literal / string) */
        char name[32];
        snprintf(name, sizeof name, "L.%d", string_counter++);
        s->asm_name = xstrdup(name);
    }
    {
        int bind = (s->storage & ST_STATIC) || s->is_static_fn ? STB_LOCAL : STB_GLOBAL;
        int type = s->kind == SYM_FUNC ? STT_FUNC : STT_NOTYPE;
        const char *name = sym_name(s);
        int idx;
        if (bind == STB_GLOBAL) {
            idx = elf_sym_find(name);
            if (idx) {
                s->elf_sym = idx;
                return idx;
            }
        }
        if (s->weak) bind = STB_WEAK;
        idx = elf_sym_add(name, 0, 0, bind, type, SHN_UNDEF);
        if (s->visibility) {
            extern void elf_sym_set_other(int idx, int other);
            elf_sym_set_other(idx, s->visibility);
        }
        s->elf_sym = idx;
        return idx;
    }
}

/* ---------------------------------------------------------------- */
/* type classification helpers */

static int tsize(Type *t) { return type_size(t, NULL); }

enum { CLS_INT, CLS_SSE, CLS_MEM, CLS_X87 };

/* classify a type for argument passing: returns class of each eightbyte in cls[0..1], number of eightbytes */
static int classify(Type *t, int *cls)
{
    int sz = tsize(t);
    if (is_float(t)) {
        if (t->kind == T_LDOUBLE) { cls[0] = CLS_X87; return 1; }
        cls[0] = CLS_SSE;
        return 1;
    }
    if (is_integer(t) || is_ptr(t)) {
        cls[0] = CLS_INT;
        return 1;
    }
    if (is_struct(t) || t->kind == T_ARRAY) {
        int n, i;
        if (sz > 16 || sz < 0) { cls[0] = CLS_MEM; return (sz + 7) / 8; }
        n = (sz + 7) / 8;
        for (i = 0; i < n; i++) cls[i] = -1;
        /* scan fields */
        {
            /* flatten fields to leaves with offsets */
            void scan(Type *ty, int off, int *cls);
            extern void classify_scan(Type *ty, int off, int *cls, int *fail);
            int fail = 0;
            classify_scan(t, 0, cls, &fail);
            if (fail) { cls[0] = CLS_MEM; return n; }
        }
        for (i = 0; i < n; i++) if (cls[i] < 0) cls[i] = CLS_SSE;
        return n;
    }
    cls[0] = CLS_INT;
    return 1;
}

void classify_scan(Type *ty, int off, int *cls, int *fail)
{
    if (is_struct(ty)) {
        Sym *f;
        for (f = ty->sym->fields; f; f = f->next) {
            if (f->bit_size == 0 && f->bit_size != -1) continue;
            classify_scan(f->type, off + f->offset, cls, fail);
        }
        return;
    }
    if (ty->kind == T_ARRAY) {
        int es = tsize(ty->ref), i;
        for (i = 0; i < ty->len; i++)
            classify_scan(ty->ref, off + i * es, cls, fail);
        return;
    }
    {
        int idx = off / 8;
        int c;
        if (ty->kind == T_LDOUBLE) { *fail = 1; return; }
        c = is_float(ty) ? CLS_SSE : CLS_INT;
        if (idx > 1) { *fail = 1; return; }
        if (cls[idx] == -1 || cls[idx] == CLS_SSE) cls[idx] = c;
        else if (c == CLS_INT) cls[idx] = CLS_INT;
        /* unaligned fields -> memory (ignored) */
    }
}

/* ---------------------------------------------------------------- */
/* temp slots in frame */

static long alloc_temp(int size, int align)
{
    extern long alloc_local(int size, int align);
    return alloc_local(size, align);
}

/* ---------------------------------------------------------------- */
/* expression code generation */

static void gen_expr(Node *n);          /* value -> rax / xmm0 / st0 ; struct -> address in rax */
static void gen_addr(Node *n);          /* address of lvalue -> rax */
static void gen_stmt(Node *n);
static void gen_block(Node *n);

static int value_kind(Type *t)
{
    /* 0 int (rax), 1 sse (xmm0), 2 x87 (st0), 3 struct (addr in rax), 4 void */
    if (t->kind == T_VOID) return 4;
    if (t->kind == T_LDOUBLE) return 2;
    if (is_float(t)) return 1;
    if (is_struct(t) || t->kind == T_ARRAY) return 3;
    return 0;
}

/* push the current value (according to type) onto stack */
static void push_value(Type *t)
{
    switch (value_kind(t)) {
    case 1: push_xmm0(t->kind == T_DOUBLE); break;
    case 2: push_st0(); break;
    default: push_r(RAX); break;
    }
}

/* load value of type t from address in rax into result register */
static void load_value(Type *t)
{
    switch (t->kind) {
    case T_FLOAT: sse_load(0, 0, RAX, 0); break;
    case T_DOUBLE: sse_load(1, 0, RAX, 0); break;
    case T_LDOUBLE: x87_fld_mem(RAX, 0); break;
    case T_STRUCT: case T_UNION: case T_ARRAY: case T_FUNC: break;
    case T_VOID: break;
    default: {
        int sz = tsize(t);
        load_reg_mem(sz, RAX, RAX, 0, !t->uns && t->kind != T_BOOL);
        break;
    }
    }
}

/* store value in rax/xmm0/st0 to address in rcx, type t */
static void store_value(Type *t)
{
    switch (t->kind) {
    case T_FLOAT: sse_store(0, 0, RCX, 0); break;
    case T_DOUBLE: sse_store(1, 0, RCX, 0); break;
    case T_LDOUBLE: x87_fstp_mem(RCX, 0); break;
    case T_STRUCT: case T_UNION: {
        /* rax = source address, rcx = dest address */
        int sz = tsize(t);
        extern void gen_memcpy_rax_to_rcx(int sz);
        gen_memcpy_rax_to_rcx(sz);
        break;
    }
    default:
        store_reg_mem(tsize(t), RAX, RCX, 0);
        break;
    }
}

/* copy sz bytes from [rax] to [rcx], preserving rax/rcx */
void gen_memcpy_rax_to_rcx(int sz)
{
    long off = 0;
    /* use rdx as temp */
    while (sz - off >= 8) {
        load_reg_mem(8, RDX, RAX, off, 0);
        store_reg_mem(8, RDX, RCX, off);
        off += 8;
    }
    while (sz - off >= 4) {
        load_reg_mem(4, RDX, RAX, off, 0);
        store_reg_mem(4, RDX, RCX, off);
        off += 4;
    }
    while (sz - off >= 2) {
        load_reg_mem(2, RDX, RAX, off, 0);
        store_reg_mem(2, RDX, RCX, off);
        off += 2;
    }
    while (sz - off >= 1) {
        load_reg_mem(1, RDX, RAX, off, 0);
        store_reg_mem(1, RDX, RCX, off);
        off += 1;
    }
}

/* zero sz bytes at [rcx] using rdx=0 */
static void gen_zero_rcx(int sz)
{
    long off = 0;
    alu_rr(1, 0x31, RDX, RDX); /* xor rdx,rdx */
    if (sz > 128) {
        /* loop: rdi = rcx; rax saved? use rep stosb with rdi, rcx, al */
        push_r(RAX);
        push_r(RCX);
        mov_rr(RDI, RCX);
        mov_ri(RCX, sz);
        alu_rr(1, 0x31, RAX, RAX);
        o(0xf3); o(0xaa); /* rep stosb */
        pop_r(RCX);
        pop_r(RAX);
        return;
    }
    while (sz - off >= 8) { store_reg_mem(8, RDX, RCX, off); off += 8; }
    while (sz - off >= 4) { store_reg_mem(4, RDX, RCX, off); off += 4; }
    while (sz - off >= 2) { store_reg_mem(2, RDX, RCX, off); off += 2; }
    while (sz - off >= 1) { store_reg_mem(1, RDX, RCX, off); off += 1; }
}

/* convert value in result register from type 'from' to type 'to' */
static void gen_cast(Type *from, Type *to)
{
    int fk = value_kind(from), tk = value_kind(to);
    if (to->kind == T_VOID) return;
    if (from->kind == T_VOID) return;
    if (to->kind == T_BOOL) {
        /* value != 0 */
        if (fk == 0) {
            alu_rr(1, 0x85, RAX, RAX);  /* test rax, rax */
            o(0x0f); o(0x95); o(0xc0); /* setne al */
            rex(0, RAX, 0, RAX); o(0x0f); o(0xb6); o(0xc0); /* movzx eax, al */
        } else if (fk == 1) {
            int d = from->kind == T_DOUBLE;
            /* xorps xmm1,xmm1; ucomisd xmm0,xmm1; setne al; setp cl; or al,cl */
            o(0x0f); o(0x57); o(0xc9);
            sse_rr(d, 0x2e, 0, 1);
            o(0x0f); o(0x95); o(0xc0);
            o(0x0f); o(0x9a); o(0xc1);
            o(0x08); o(0xc8);
            rex(0, RAX, 0, RAX); o(0x0f); o(0xb6); o(0xc0);
        } else if (fk == 2) {
            /* fldz; fucomip; fstp; setne */
            o(0xd9); o(0xee);            /* fldz */
            o(0xdf); o(0xe9);            /* fucomip st(1) */
            o(0xdd); o(0xd8);            /* fstp st(0) */
            o(0x0f); o(0x95); o(0xc0);
            o(0x0f); o(0x9a); o(0xc1);
            o(0x08); o(0xc8);
            rex(0, RAX, 0, RAX); o(0x0f); o(0xb6); o(0xc0);
        }
        return;
    }
    if (fk == 0 && tk == 0) {
        int fs = tsize(from), ts = tsize(to);
        /* integer -> integer: truncate/extend per target */
        if (ts < 8 && (ts < fs || (ts == fs && to->uns != from->uns) || ts <= fs)) {
            switch (ts) {
            case 1: rex(1, RAX, 0, RAX); o(0x0f); o(to->uns ? 0xb6 : 0xbe); o(0xc0); break;
            case 2: rex(1, RAX, 0, RAX); o(0x0f); o(to->uns ? 0xb7 : 0xbf); o(0xc0); break;
            case 4:
                if (to->uns) { mov_rr32(RAX, RAX); }
                else { rex(1, RAX, 0, RAX); o(0x63); o(0xc0); } /* movsxd rax, eax */
                break;
            }
        }
        /* widening: value already extended per source type */
        return;
    }
    if (fk == 0 && tk == 1) {
        int d = to->kind == T_DOUBLE;
        int fs = tsize(from);
        if (from->uns && fs == 8) {
            /* unsigned 64 -> float: handle high bit */
            int l1 = gen_new_label(), l2 = gen_new_label();
            alu_rr(1, 0x85, RAX, RAX);
            gen_jcc(0x8, l1); /* js */
            o(d ? 0xf2 : 0xf3); rex(1, 0, 0, RAX); o(0x0f); o(0x2a); o(0xc0); /* cvtsi2sd xmm0, rax */
            gen_jmp(l2);
            label_here(l1);
            /* rcx = rax >> 1 | (rax & 1) */
            mov_rr(RCX, RAX);
            rex(1, 0, 0, RCX); o(0xd1); o(0xe9); /* shr rcx,1 */
            o(0x83); o(0xe0); o(0x01); /* and eax,1 */
            alu_rr(1, 0x09, RCX, RAX); /* or rcx, rax */
            o(d ? 0xf2 : 0xf3); rex(1, 0, 0, RCX); o(0x0f); o(0x2a); o(0xc1); /* cvtsi2sd xmm0, rcx */
            sse_rr(d, 0x58, 0, 0); /* add xmm0, xmm0 */
            label_here(l2);
        } else {
            /* 32-bit unsigned already zero-extended in rax -> use 64-bit convert */
            o(d ? 0xf2 : 0xf3); rex(1, 0, 0, RAX); o(0x0f); o(0x2a); o(0xc0);
        }
        return;
    }
    if (fk == 1 && tk == 0) {
        int d = from->kind == T_DOUBLE;
        int ts = tsize(to);
        if (to->uns && ts == 8) {
            /* double -> uint64: if >= 2^63 subtract */
            int l1 = gen_new_label(), l2 = gen_new_label();
            /* load 2^63 constant into xmm1 */
            mov_ri(RAX, d ? 0x43e0000000000000LL : 0x5f000000LL);
            if (d) { o(0x66); rex(1, 1, 0, RAX); o(0x0f); o(0x6e); o(0xc8); } /* movq xmm1, rax */
            else { o(0x66); rex(0, 1, 0, RAX); o(0x0f); o(0x6e); o(0xc8); }   /* movd xmm1, eax */
            sse_rr(d, 0x2e, 0, 1); /* ucomisd xmm0, xmm1 */
            gen_jcc(0x3, l1); /* jae */
            o(d ? 0xf2 : 0xf3); rex(1, RAX, 0, 0); o(0x0f); o(0x2c); o(0xc0); /* cvttsd2si rax, xmm0 */
            gen_jmp(l2);
            label_here(l1);
            sse_rr(d, 0x5c, 0, 1); /* sub xmm0, xmm1 */
            o(d ? 0xf2 : 0xf3); rex(1, RAX, 0, 0); o(0x0f); o(0x2c); o(0xc0);
            mov_ri(RCX, INT64_MIN);
            alu_rr(1, 0x31, RAX, RCX); /* xor rax, rcx */
            label_here(l2);
        } else {
            o(d ? 0xf2 : 0xf3); rex(1, RAX, 0, 0); o(0x0f); o(0x2c); o(0xc0); /* cvttsd2si rax, xmm0 */
            gen_cast(type_long, to);
        }
        return;
    }
    if (fk == 1 && tk == 1) {
        if (from->kind == to->kind) return;
        if (to->kind == T_DOUBLE) { o(0xf3); o(0x0f); o(0x5a); o(0xc0); } /* cvtss2sd */
        else { o(0xf2); o(0x0f); o(0x5a); o(0xc0); } /* cvtsd2ss */
        return;
    }
    if (tk == 2) {
        /* to long double */
        if (fk == 2) return;
        if (fk == 1) {
            sub_rsp(8);
            sse_store(1, 0, RSP, 0);
            if (from->kind == T_DOUBLE) x87_fld64(RSP, 0); else x87_fld32(RSP, 0);
            add_rsp(8);
            return;
        }
        /* int */
        if (from->uns && tsize(from) == 8) {
            /* unsigned 64: fild then add 2^64 if negative */
            int l1 = gen_new_label();
            push_r(RAX);
            x87_fild64(RSP, 0);
            add_rsp(8);
            alu_rr(1, 0x85, RAX, RAX);
            gen_jcc(0x9, l1); /* jns */
            /* add 2^64: push constant 0x5f800000 (float) */
            mov_ri(RCX, 0x5f800000);
            push_r(RCX);
            x87_fld32(RSP, 0);
            add_rsp(8);
            o(0xde); o(0xc1); /* faddp */
            label_here(l1);
        } else {
            push_r(RAX);
            x87_fild64(RSP, 0);
            add_rsp(8);
        }
        return;
    }
    if (fk == 2) {
        /* from long double */
        if (tk == 1) {
            sub_rsp(8);
            if (to->kind == T_DOUBLE) { x87_fstp64(RSP, 0); sse_load(1, 0, RSP, 0); }
            else { x87_fstp32(RSP, 0); sse_load(0, 0, RSP, 0); }
            add_rsp(8);
            return;
        }
        /* to int */
        sub_rsp(8);
        x87_fisttp64(RSP, 0);
        pop_r(RAX);
        gen_cast(type_long, to);
        return;
    }
}

/* evaluate condition: jump to label if value is zero (if jz) / nonzero */
static void gen_test_jump(Node *n, int jump_if_true, int l)
{
    Type *t;
    n = fold_const(n);
    if (n->op == N_LNOT) {
        gen_test_jump(n->a, !jump_if_true, l);
        return;
    }
    if (n->op == N_LAND) {
        if (jump_if_true) {
            int skip = gen_new_label();
            gen_test_jump(n->a, 0, skip);
            gen_test_jump(n->b, 1, l);
            label_here(skip);
        } else {
            gen_test_jump(n->a, 0, l);
            gen_test_jump(n->b, 0, l);
        }
        return;
    }
    if (n->op == N_LOR) {
        if (jump_if_true) {
            gen_test_jump(n->a, 1, l);
            gen_test_jump(n->b, 1, l);
        } else {
            int skip = gen_new_label();
            gen_test_jump(n->a, 1, skip);
            gen_test_jump(n->b, 0, l);
            label_here(skip);
        }
        return;
    }
    if (n->op >= N_EQ && n->op <= N_GE && is_integer(n->a->type) || (n->op >= N_EQ && n->op <= N_GE && is_ptr(n->a->type))) {
        /* compare and jcc */
        int cc;
        int uns = n->a->type->uns || is_ptr(n->a->type);
        int w = tsize(n->a->type) == 8;
        gen_expr(n->a);
        push_r(RAX);
        gen_expr(n->b);
        mov_rr(RCX, RAX);
        pop_r(RAX);
        alu_rr(w, 0x39, RAX, RCX); /* cmp rax, rcx */
        switch (n->op) {
        case N_EQ: cc = 0x4; break;
        case N_NE: cc = 0x5; break;
        case N_LT: cc = uns ? 0x2 : 0xc; break;
        case N_GE: cc = uns ? 0x3 : 0xd; break;
        case N_LE: cc = uns ? 0x6 : 0xe; break;
        default: cc = uns ? 0x7 : 0xf; break; /* GT */
        }
        if (!jump_if_true) cc ^= 1;
        gen_jcc(cc, l);
        return;
    }
    gen_expr(n);
    t = n->type;
    switch (value_kind(t)) {
    case 0:
        alu_rr(1, 0x85, RAX, RAX);
        gen_jcc(jump_if_true ? 0x5 : 0x4, l);
        break;
    case 1: {
        int d = t->kind == T_DOUBLE;
        o(0x0f); o(0x57); o(0xc9);  /* xorps xmm1, xmm1 */
        sse_rr(d, 0x2e, 0, 1);
        /* ZF=1 and PF=0 means equal (zero) */
        if (jump_if_true) {
            gen_jcc(0x5, l); /* jne */
            gen_jcc(0xa, l); /* jp */
        } else {
            int skip = gen_new_label();
            gen_jcc(0xa, skip); /* jp: unordered -> true */
            gen_jcc(0x4, l);    /* je */
            label_here(skip);
        }
        break;
    }
    case 2:
        o(0xd9); o(0xee);   /* fldz */
        o(0xdf); o(0xe9);   /* fucomip st(1) */
        o(0xdd); o(0xd8);   /* fstp st(0) */
        if (jump_if_true) { gen_jcc(0x5, l); gen_jcc(0xa, l); }
        else { int skip = gen_new_label(); gen_jcc(0xa, skip); gen_jcc(0x4, l); label_here(skip); }
        break;
    default:
        break;
    }
}

/* result of a comparison: rax = 0/1 */
static void gen_setcc(int cc)
{
    o(0x0f); o(0x90 | cc); o(0xc0);              /* setcc al */
    rex(0, RAX, 0, RAX); o(0x0f); o(0xb6); o(0xc0); /* movzx eax, al */
}

static void gen_binary_int(int op, Type *t, int uns)
{
    /* rax = rax op rcx */
    int w = tsize(t) == 8;
    switch (op) {
    case N_ADD: alu_rr(w, 0x01, RAX, RCX); break;
    case N_SUB: alu_rr(w, 0x29, RAX, RCX); break;
    case N_AND: alu_rr(w, 0x21, RAX, RCX); break;
    case N_OR:  alu_rr(w, 0x09, RAX, RCX); break;
    case N_XOR: alu_rr(w, 0x31, RAX, RCX); break;
    case N_MUL: rex(w, RAX, 0, RCX); o(0x0f); o(0xaf); modrm_reg(RAX, RCX); break;
    case N_DIV: case N_MOD:
        if (uns) {
            alu_rr(1, 0x31, RDX, RDX);   /* xor rdx,rdx */
            rex(w, 0, 0, RCX); o(0xf7); modrm_reg(6, RCX); /* div rcx */
        } else {
            if (w) { rex(1, 0, 0, 0); o(0x99); } else o(0x99); /* cqo / cdq */
            rex(w, 0, 0, RCX); o(0xf7); modrm_reg(7, RCX); /* idiv rcx */
        }
        if (op == N_MOD) mov_rr(RAX, RDX);
        break;
    case N_SHL: rex(w, 0, 0, RAX); o(0xd3); modrm_reg(4, RAX); break;
    case N_SHR: rex(w, 0, 0, RAX); o(0xd3); modrm_reg(uns ? 5 : 7, RAX); break;
    case N_EQ: alu_rr(w, 0x39, RAX, RCX); gen_setcc(0x4); break;
    case N_NE: alu_rr(w, 0x39, RAX, RCX); gen_setcc(0x5); break;
    case N_LT: alu_rr(w, 0x39, RAX, RCX); gen_setcc(uns ? 0x2 : 0xc); break;
    case N_GE: alu_rr(w, 0x39, RAX, RCX); gen_setcc(uns ? 0x3 : 0xd); break;
    case N_LE: alu_rr(w, 0x39, RAX, RCX); gen_setcc(uns ? 0x6 : 0xe); break;
    case N_GT: alu_rr(w, 0x39, RAX, RCX); gen_setcc(uns ? 0x7 : 0xf); break;
    }
    /* normalize result extension for sub-64-bit types */
    if (!w && op != N_EQ && op != N_NE && op != N_LT && op != N_GE && op != N_LE && op != N_GT) {
        if (t->uns) mov_rr32(RAX, RAX);
        else { rex(1, RAX, 0, RAX); o(0x63); o(0xc0); }
    }
}

static void gen_binary_sse(int op, int d)
{
    /* xmm0 = xmm0 op xmm1 */
    switch (op) {
    case N_ADD: sse_rr(d, 0x58, 0, 1); break;
    case N_SUB: sse_rr(d, 0x5c, 0, 1); break;
    case N_MUL: sse_rr(d, 0x59, 0, 1); break;
    case N_DIV: sse_rr(d, 0x5e, 0, 1); break;
    case N_EQ: case N_NE: case N_LT: case N_LE: case N_GT: case N_GE: {
        /* use ucomisd with operand order giving above/below flags */
        int cc;
        if (op == N_LT || op == N_LE) { sse_rr(d, 0x2e, 1, 0); cc = op == N_LT ? 0x7 : 0x3; } /* xmm1 > xmm0 */
        else { sse_rr(d, 0x2e, 0, 1); cc = op == N_GT ? 0x7 : op == N_GE ? 0x3 : op == N_EQ ? 0x4 : 0x5; }
        if (op == N_EQ) {
            /* equal and not unordered */
            o(0x0f); o(0x94); o(0xc0); /* sete al */
            o(0x0f); o(0x9b); o(0xc1); /* setnp cl */
            o(0x20); o(0xc8);          /* and al, cl */
            rex(0, RAX, 0, RAX); o(0x0f); o(0xb6); o(0xc0);
        } else if (op == N_NE) {
            o(0x0f); o(0x95); o(0xc0); /* setne al */
            o(0x0f); o(0x9a); o(0xc1); /* setp cl */
            o(0x08); o(0xc8);          /* or al, cl */
            rex(0, RAX, 0, RAX); o(0x0f); o(0xb6); o(0xc0);
        } else
            gen_setcc(cc);
        break;
    }
    }
}

static void gen_binary_x87(int op)
{
    /* st0 = st1 op st0 ... we have: a pushed on stack (16 bytes), b in st0 */
    /* load a: st0 = a, st1 = b */
    pop_st0();
    switch (op) {
    case N_ADD: o(0xde); o(0xc1); break; /* faddp st1, st0 */
    case N_SUB: o(0xde); o(0xe9); break; /* fsubp st1, st0 : st1 = st1 - st0 -> wrong order? st1=b, st0=a: want a-b = st0 - st1 -> fsubrp */
    case N_MUL: o(0xde); o(0xc9); break; /* fmulp */
    case N_DIV: o(0xde); o(0xf1); break; /* fdivrp: st1 = st0 / st1 */
    default: {
        /* comparison: st0 = a, st1 = b; fucomip compares st0 with st1 -> flags a ? b */
        int cc;
        o(0xdf); o(0xe9); /* fucomip st(1) */
        o(0xdd); o(0xd8); /* fstp st(0) */
        switch (op) {
        case N_EQ: cc = 0x4; break; case N_NE: cc = 0x5; break;
        case N_LT: cc = 0x2; break; case N_GE: cc = 0x3; break;
        case N_LE: cc = 0x6; break; default: cc = 0x7; break;
        }
        gen_setcc(cc);
        return;
    }
    }
}

/* bitfield helpers: n is N_MEMBER with bitfield; address of storage unit in rax */
static void gen_bitfield_load(Node *n)
{
    Sym *f = n->sym;
    Type *t = f->type;
    int usize = tsize(t);
    int bits = f->bit_size, boff = f->bit_off;
    load_reg_mem(usize, RAX, RAX, 0, 0);
    /* shift left to drop high bits then right */
    {
        int left = 64 - (boff + bits);
        if (left) { rex(1, 0, 0, RAX); o(0xc1); modrm_reg(4, RAX); o(left); }
        rex(1, 0, 0, RAX); o(0xc1); modrm_reg(t->uns || t->kind == T_BOOL ? 5 : 7, RAX); o(left + boff);
    }
    if (tsize(t) < 8 && !t->uns) {
        /* sign extend to type size semantics: result fits */
    }
}

/* store rax (value) into bitfield at address rcx */
static void gen_bitfield_store(Node *n)
{
    Sym *f = n->sym;
    Type *t = f->type;
    int usize = tsize(t);
    int bits = f->bit_size, boff = f->bit_off;
    uint64_t mask = bits == 64 ? ~0ULL : ((1ULL << bits) - 1);
    /* rdx = old value */
    load_reg_mem(usize, RDX, RCX, 0, 0);
    /* rax = (rax & mask) << boff */
    push_r(RAX);
    mov_ri(RAX, mask);
    mov_rr(R8, RAX);           /* r8 = mask */
    pop_r(RAX);
    alu_rr(1, 0x21, RAX, R8);  /* and rax, r8 */
    if (boff) { rex(1, 0, 0, RAX); o(0xc1); modrm_reg(4, RAX); o(boff); }
    /* rdx &= ~(mask << boff) */
    push_r(RAX);
    mov_ri(RAX, ~(mask << boff));
    alu_rr(1, 0x21, RDX, RAX);
    pop_r(RAX);
    alu_rr(1, 0x09, RDX, RAX); /* or rdx, rax */
    store_reg_mem(usize, RDX, RCX, 0);
}

static void gen_call(Node *n);
static void gen_vaarg(Node *n);
static void gen_init_local(Sym *s, InitEntry_dummy_unused);
EOF
echo ok"}

