/* address of lvalue n -> rax */
static void gen_addr(Node *n)
{
    switch (n->op) {
    case N_VAR: {
        Sym *s = n->sym;
        if (s->is_local) {
            if (s->type->kind == T_ARRAY && s->type->len == -2) {
                /* VLA: slot holds pointer */
                load_reg_mem(8, RAX, RBP, s->loc, 0);
            } else
                lea(RAX, RBP, s->loc);
        } else
            lea_sym(RAX, s, 0);
        return;
    }
    case N_COMPOUND_LIT: {
        Sym *s = n->sym;
        if (s->is_local) {
            extern void gen_init_entries(Sym *s, InitEntry *e, int ne, long base_off);
            /* initialize the temporary at each evaluation */
            gen_init_entries(s, (InitEntry *)n->list, n->nlist, 0);
            lea(RAX, RBP, s->loc);
        } else
            lea_sym(RAX, s, 0);
        return;
    }
    case N_STR: {
        Sym *s;
        new_string_literal(n->str, n->slen, n->type, &s);
        lea_sym(RAX, s, 0);
        return;
    }
    case N_DEREF:
        gen_expr(n->a);
        return;
    case N_MEMBER:
        if (n->a->op == N_DEREF || n->a->lvalue)
            gen_addr(n->a);
        else {
            /* struct rvalue (e.g. function return): address in rax */
            gen_expr(n->a);
        }
        if (n->ival) {
            lea(RAX, RAX, n->ival);
        }
        return;
    case N_CALL: case N_ASSIGN: case N_COND: case N_COMMA: case N_STMT_EXPR: case N_CAST:
        /* struct-valued rvalue: address in rax */
        gen_expr(n);
        return;
    case N_FUNCREF:
        lea_sym(RAX, n->sym, 0);
        return;
    default:
        if (is_struct(n->type)) {
            gen_expr(n);
            return;
        }
        tcc_error("lvalue expected");
    }
}

/* load value of lvalue node n (address in rax) respecting bitfields */
static void gen_load_lvalue(Node *n)
{
    if (n->op == N_MEMBER && n->bitfield) {
        gen_bitfield_load(n);
        return;
    }
    load_value(n->type);
}

static void gen_assign_to(Node *lhs, Type *t)
{
    /* value in result reg; address in rcx */
    if (lhs->op == N_MEMBER && lhs->bitfield) {
        gen_bitfield_store(lhs);
        return;
    }
    store_value(t);
}

/* evaluate lvalue address into rcx while preserving value in result reg */
static void gen_addr_to_rcx_keep(Node *lhs, Type *vt)
{
    push_value(vt);
    gen_addr(lhs);
    mov_rr(RCX, RAX);
    switch (value_kind(vt)) {
    case 1: pop_xmm(0); break;
    case 2: pop_st0(); break;
    default: pop_r(RAX); break;
    }
}

static void gen_incdec(Node *n, int is_inc, int is_post)
{
    Node *a = n->a;
    Type *t = n->type;
    long step = 1;
    if (is_ptr(t)) {
        step = tsize(t->ref);
        if (step <= 0) step = 1;
    }
    gen_addr(a);
    mov_rr(RCX, RAX);
    /* load current value */
    gen_load_lvalue(a);
    if (is_float(t)) {
        int k = value_kind(t);
        if (k == 1) {
            int d = t->kind == T_DOUBLE;
            if (is_post) { push_xmm0(d); }
            mov_ri(RAX, 1);
            /* xmm1 = 1.0 */
            o(d ? 0xf2 : 0xf3); rex(1, 1, 0, RAX); o(0x0f); o(0x2a); modrm_reg(1, RAX);
            sse_rr(d, is_inc ? 0x58 : 0x5c, 0, 1);
            sse_store(d, 0, RCX, 0);
            if (is_post) pop_xmm(0);
        } else {
            if (is_post) { x87_fld_mem(RCX, 0); } /* duplicate: st0=old, st1=old */
            o(0xd9); o(0xe8); /* fld1 */
            o(0xde); o(is_inc ? 0xc1 : 0xe9); /* faddp / fsubp */
            if (is_post) {
                /* st0 = new, st1 = old */
                x87_fstp_mem(RCX, 0);
            } else {
                x87_fstp_mem(RCX, 0);
                x87_fld_mem(RCX, 0);
            }
        }
        return;
    }
    /* integer / pointer */
    if (is_post) push_r(RAX);
    mov_ri(RDX, step);
    alu_rr(1, is_inc ? 0x01 : 0x29, RAX, RDX);
    if (tsize(t) < 8) gen_cast(type_long, t);
    gen_assign_to(a, t);
    if (is_post) pop_r(RAX);
}

/* arguments layout for a call */
typedef struct ArgInfo {
    Type *type;
    int cls[2];
    int ncls;
    int in_mem;        /* passed on stack */
    long tmp;          /* temp slot offset (frame) */
    long stack_off;    /* offset in the outgoing stack area */
    int ireg[2], sreg[2];
} ArgInfo;

static const int int_arg_regs[6] = { RDI, RSI, RDX, RCX, R8, R9 };

/* move value in result reg to temp slot of its type */
static void store_to_temp(Type *t, long off)
{
    switch (value_kind(t)) {
    case 0: store_reg_mem(tsize(t) < 8 ? 8 : 8, RAX, RBP, off); break;
    case 1: sse_store(t->kind == T_DOUBLE, 0, RBP, off); break;
    case 2: x87_fstp_mem(RBP, off); break;
    case 3: {
        /* copy struct from [rax] to temp */
        lea(RCX, RBP, off);
        gen_memcpy_rax_to_rcx(tsize(t));
        break;
    }
    }
}

static void gen_call(Node *n)
{
    Node *f = n->a;
    Type *ft = f->type->ref;   /* function type */
    Type *rt = n->type;
    int nargs = n->nlist;
    ArgInfo *ai = xcalloc(sizeof(ArgInfo) * (nargs + 1));
    int i, nint = 0, nsse = 0;
    long stack_size = 0;
    int ret_cls[2], ret_n = 0, ret_mem = 0;
    long ret_tmp = 0;
    int direct_sym = 0;
    long fptr_tmp = 0;

    /* return value classification */
    if (is_struct(rt)) {
        ret_n = classify(rt, ret_cls);
        if (ret_cls[0] == CLS_MEM) ret_mem = 1;
        ret_tmp = alloc_temp(tsize(rt), 16);
        if (ret_mem) nint = 1;
    } else if (rt->kind == T_LDOUBLE) {
        ret_tmp = alloc_temp(16, 16);
    }
    /* classify args */
    for (i = 0; i < nargs; i++) {
        Node *a = n->list[i];
        ArgInfo *x = &ai[i];
        int k, ni = 0, ns = 0;
        x->type = a->type;
        x->ncls = classify(a->type, x->cls);
        if (x->cls[0] == CLS_MEM || x->cls[0] == CLS_X87) { x->in_mem = 1; }
        else {
            for (k = 0; k < x->ncls; k++) {
                if (x->cls[k] == CLS_INT) ni++; else ns++;
            }
            if (nint + ni > 6 || nsse + ns > 8) x->in_mem = 1;
            else {
                for (k = 0; k < x->ncls; k++) {
                    if (x->cls[k] == CLS_INT) x->ireg[k] = int_arg_regs[nint++];
                    else x->sreg[k] = nsse++;
                }
            }
        }
        if (x->in_mem) {
            int sz = tsize(a->type);
            int al = type_align(a->type);
            if (al < 8) al = 8;
            stack_size = (stack_size + al - 1) & -al;
            x->stack_off = stack_size;
            stack_size += (sz + 7) & ~7;
        }
        x->tmp = alloc_temp(tsize(a->type) < 8 ? 8 : tsize(a->type), 16);
    }
    stack_size = (stack_size + 15) & ~15;
    /* evaluate args into temps */
    if (f->op == N_ADDR && f->a->op == N_VAR && f->a->sym->kind == SYM_FUNC)
        direct_sym = 1;
    else if (f->op == N_ADDR && f->a->op == N_VAR && f->a->type->kind == T_FUNC)
        direct_sym = 1;
    {
        int order_rev = S.reverse_funcargs;
        for (i = 0; i < nargs; i++) {
            int j = order_rev ? nargs - 1 - i : i;
            Node *a = n->list[j];
            gen_expr(a);
            store_to_temp(a->type, ai[j].tmp);
        }
    }
    if (!direct_sym) {
        fptr_tmp = alloc_temp(8, 8);
        gen_expr(f);
        store_reg_mem(8, RAX, RBP, fptr_tmp);
    }
    /* set up stack */
    mov_rr(RBX, RSP);
    if (stack_size) sub_rsp(stack_size);
    rex(1, 0, 0, RSP); o(0x83); modrm_reg(4, RSP); o(0xf0); /* and rsp, -16 */
    /* copy memory args */
    for (i = 0; i < nargs; i++) {
        ArgInfo *x = &ai[i];
        if (!x->in_mem) continue;
        {
            int sz = tsize(x->type);
            lea(RAX, RBP, x->tmp);
            lea(RCX, RSP, x->stack_off);
            if (value_kind(x->type) == 2) sz = 16;
            if (sz < 8 && !is_struct(x->type)) sz = 8;
            gen_memcpy_rax_to_rcx(sz);
        }
    }
    /* load register args */
    for (i = 0; i < nargs; i++) {
        ArgInfo *x = &ai[i];
        int k;
        if (x->in_mem) continue;
        for (k = 0; k < x->ncls; k++) {
            if (x->cls[k] == CLS_INT) {
                load_reg_mem(8, x->ireg[k], RBP, x->tmp + 8 * k, 0);
            } else {
                int d = !(x->type->kind == T_FLOAT);
                if (is_struct(x->type)) {
                    /* eightbyte of struct: load as double (8 bytes) */
                    sse_load(1, x->sreg[k], RBP, x->tmp + 8 * k);
                } else
                    sse_load(d, x->sreg[k], RBP, x->tmp);
            }
        }
    }
    if (ret_mem) {
        lea(RDI, RBP, ret_tmp);
    }
    if (ft->variadic || ft->oldstyle) {
        mov_ri(RAX, nsse);  /* al = number of vector registers */
    }
    if (direct_sym) {
        call_sym(f->a->sym);
    } else {
        load_reg_mem(8, R11, RBP, fptr_tmp, 0);
        rex(0, 0, 0, R11); o(0xff); modrm_reg(2, R11); /* call r11 */
    }
    mov_rr(RSP, RBX);
    /* return value */
    if (is_struct(rt)) {
        if (!ret_mem) {
            /* store rax/rdx/xmm0/xmm1 into ret_tmp */
            int ni = 0, ns = 0, k;
            for (k = 0; k < ret_n; k++) {
                if (ret_cls[k] == CLS_INT) {
                    store_reg_mem(8, ni == 0 ? RAX : RDX, RBP, ret_tmp + 8 * k);
                    ni++;
                } else {
                    sse_store(1, ns, RBP, ret_tmp + 8 * k);
                    ns++;
                }
            }
        }
        lea(RAX, RBP, ret_tmp);
    } else if (rt->kind == T_LDOUBLE) {
        /* in st0 already */
    } else if (value_kind(rt) == 0 && rt->kind != T_VOID) {
        /* normalize extension */
        if (tsize(rt) < 8) gen_cast(type_long, rt);
    }
    free(ai);
}

/* __va_arg(ap, cls, size, align) -> pointer in rax */
static void gen_vaarg(Node *n)
{
    int64_t cls = 0, size = 8, align = 8;
    int l_mem, l_end;
    eval_const_expr(n->b, &cls);
    eval_const_expr(n->c, &size);
    eval_const_expr(n->d, &align);
    gen_expr(n->a);          /* rax = ap (pointer to va_list struct) */
    mov_rr(RCX, RAX);        /* rcx = ap */
    l_mem = gen_new_label();
    l_end = gen_new_label();
    if (cls == 0 && size <= 8) {
        /* gp_offset at [rcx], reg_save_area at [rcx+16] */
        load_reg_mem(4, RAX, RCX, 0, 0);
        rex(0, 0, 0, RAX); o(0x3d); o32(48);          /* cmp eax, 48 */
        gen_jcc(0x3, l_mem);                            /* jae mem */
        load_reg_mem(8, RDX, RCX, 16, 0);
        alu_rr(1, 0x01, RDX, RAX);                     /* rdx = reg_save + gp_offset */
        o(0x83); o(0xc0); o(8);                         /* add eax, 8 */
        store_reg_mem(4, RAX, RCX, 0);
        mov_rr(RAX, RDX);
        gen_jmp(l_end);
    } else if (cls == 0 && size <= 16) {
        /* two integer eightbytes */
        load_reg_mem(4, RAX, RCX, 0, 0);
        rex(0, 0, 0, RAX); o(0x3d); o32(40);          /* cmp eax, 40 */
        gen_jcc(0x7, l_mem);                            /* ja mem */
        load_reg_mem(8, RDX, RCX, 16, 0);
        alu_rr(1, 0x01, RDX, RAX);
        o(0x83); o(0xc0); o(16);
        store_reg_mem(4, RAX, RCX, 0);
        mov_rr(RAX, RDX);
        gen_jmp(l_end);
    } else if (cls == 1 && size <= 8) {
        load_reg_mem(4, RAX, RCX, 4, 0);
        rex(0, 0, 0, RAX); o(0x3d); o32(176);
        gen_jcc(0x3, l_mem);
        load_reg_mem(8, RDX, RCX, 16, 0);
        alu_rr(1, 0x01, RDX, RAX);
        o(0x83); o(0xc0); o(16);
        store_reg_mem(4, RAX, RCX, 4);
        mov_rr(RAX, RDX);
        gen_jmp(l_end);
    } else if (cls == 1 && size <= 16) {
        /* struct of two floats/doubles: two sse regs: regs are 16 bytes apart, need packing: copy to temp */
        long tmp = alloc_temp(16, 16);
        load_reg_mem(4, RAX, RCX, 4, 0);
        rex(0, 0, 0, RAX); o(0x3d); o32(160);
        gen_jcc(0x7, l_mem);
        load_reg_mem(8, RDX, RCX, 16, 0);
        alu_rr(1, 0x01, RDX, RAX);
        o(0x83); o(0xc0); o(32);
        store_reg_mem(4, RAX, RCX, 4);
        load_reg_mem(8, RAX, RDX, 0, 0);
        store_reg_mem(8, RAX, RBP, tmp);
        load_reg_mem(8, RAX, RDX, 16, 0);
        store_reg_mem(8, RAX, RBP, tmp + 8);
        lea(RAX, RBP, tmp);
        gen_jmp(l_end);
    }
    label_here(l_mem);
    /* overflow_arg_area at [rcx+8] */
    load_reg_mem(8, RAX, RCX, 8, 0);
    if (align > 8) {
        rex(1, 0, 0, RAX); o(0x83); modrm_reg(0, RAX); o(align - 1);   /* add rax, align-1 */
        rex(1, 0, 0, RAX); o(0x83); modrm_reg(4, RAX); o(-align & 0xff); /* and rax, -align */
    }
    mov_rr(RDX, RAX);
    rex(1, 0, 0, RDX); o(0x81); modrm_reg(0, RDX); o32((size + 7) & ~7);  /* add rdx, size rounded */
    store_reg_mem(8, RDX, RCX, 8);
    label_here(l_end);
}

/* initialize local object at s->loc from init entries */
void gen_init_entries(Sym *s, InitEntry *e, int ne, long base_off)
{
    int i;
    int sz = tsize(s->type);
    int need_zero = is_struct(s->type) || s->type->kind == T_ARRAY;
    if (need_zero) {
        /* check whether a single string init covers everything */
        if (ne == 1 && e[0].val->op == N_STR && e[0].type->kind == T_ARRAY && e[0].off == 0 && e[0].val->slen >= sz)
            need_zero = 0;
    }
    if (need_zero) {
        lea(RCX, RBP, s->loc);
        gen_zero_rcx(sz);
    }
    for (i = 0; i < ne; i++) {
        InitEntry *x = &e[i];
        Node *v = x->val;
        if (v->op == N_STR && x->type->kind == T_ARRAY) {
            int n = v->slen;
            int tl = tsize(x->type);
            if (n > tl) n = tl;
            gen_addr(v);
            lea(RCX, RBP, s->loc + x->off);
            gen_memcpy_rax_to_rcx(n);
            continue;
        }
        gen_expr(v);
        lea(RCX, RBP, s->loc + x->off);
        if (x->bit_size > 0) {
            /* construct a fake member node for bitfield store */
            Node m;
            Sym f;
            memset(&m, 0, sizeof m);
            memset(&f, 0, sizeof f);
            f.type = x->type;
            f.bit_off = x->bit_off;
            f.bit_size = x->bit_size;
            m.op = N_MEMBER;
            m.sym = &f;
            m.bitfield = 1;
            gen_bitfield_store(&m);
        } else
            store_value(x->type);
    }
    (void)base_off;
}

static void gen_expr(Node *n)
{
    switch (n->op) {
    case N_CONST:
        mov_ri(RAX, n->ival);
        if (tsize(n->type) < 8 && !is_ptr(n->type)) gen_cast(type_long, n->type);
        return;
    case N_FCONST: {
        /* load constant via rodata */
        Type *t = n->type;
        if (t->kind == T_LDOUBLE) {
            long off = section_add(rodata_section, 16, 16);
            long double v = n->fval;
            memcpy(rodata_section->data + off, &v, 10);
            {
                Sym *s = xcalloc(sizeof(Sym));
                char name[32];
                snprintf(name, sizeof name, "L.%d", string_counter++);
                s->elf_sym = elf_sym_add(name, off, 16, STB_LOCAL, STT_OBJECT, rodata_section->sh_num);
                s->kind = SYM_VAR; s->type = t; s->storage = ST_STATIC;
                lea_sym(RAX, s, 0);
                x87_fld_mem(RAX, 0);
            }
        } else if (t->kind == T_DOUBLE) {
            double v = (double)n->fval;
            uint64_t bits;
            memcpy(&bits, &v, 8);
            mov_ri(RAX, bits);
            o(0x66); rex(1, 0, 0, RAX); o(0x0f); o(0x6e); o(0xc0); /* movq xmm0, rax */
        } else {
            float v = (float)n->fval;
            uint32_t bits;
            memcpy(&bits, &v, 4);
            mov_ri(RAX, bits);
            o(0x66); rex(0, 0, 0, RAX); o(0x0f); o(0x6e); o(0xc0); /* movd xmm0, eax */
        }
        return;
    }
    case N_STR:
    case N_COMPOUND_LIT:
        gen_addr(n);
        if (!is_struct(n->type) && n->type->kind != T_ARRAY)
            gen_load_lvalue(n);
        return;
    case N_VAR: {
        Sym *s = n->sym;
        if (s->type->kind == T_FUNC) {
            lea_sym(RAX, s, 0);
            return;
        }
        gen_addr(n);
        if (s->type->kind == T_ARRAY) return;
        load_value(s->type);
        return;
    }
    case N_MEMBER:
        gen_addr(n);
        if (is_struct(n->type) || n->type->kind == T_ARRAY) return;
        gen_load_lvalue(n);
        return;
    case N_DEREF:
        gen_expr(n->a);
        if (is_struct(n->type) || n->type->kind == T_ARRAY || n->type->kind == T_FUNC) return;
        load_value(n->type);
        return;
    case N_ADDR:
        if (n->a->type->kind == T_FUNC && n->a->op == N_VAR) {
            lea_sym(RAX, n->a->sym, 0);
            return;
        }
        gen_addr(n->a);
        return;
    case N_CAST:
        gen_expr(n->a);
        if (is_struct(n->type)) return;
        gen_cast(n->a->type, n->type);
        return;
    case N_NEG:
        gen_expr(n->a);
        switch (value_kind(n->type)) {
        case 0: rex(tsize(n->type) == 8, 0, 0, RAX); o(0xf7); modrm_reg(3, RAX);
                if (tsize(n->type) < 8) gen_cast(type_long, n->type); break;
        case 1: {
            int d = n->type->kind == T_DOUBLE;
            /* xmm0 = 0 - xmm0 : use sign flip via xor with sign mask */
            mov_ri(RAX, d ? 0x8000000000000000ULL : 0x80000000ULL);
            if (d) { o(0x66); rex(1, 1, 0, RAX); o(0x0f); o(0x6e); o(0xc8); } else { o(0x66); rex(0, 1, 0, RAX); o(0x0f); o(0x6e); o(0xc8); }
            o(0x66); o(0x0f); o(0x57); o(0xc1); /* xorpd xmm0, xmm1 */
            break;
        }
        case 2: o(0xd9); o(0xe0); break; /* fchs */
        }
        return;
    case N_NOT:
        gen_expr(n->a);
        rex(tsize(n->type) == 8, 0, 0, RAX); o(0xf7); modrm_reg(2, RAX);
        if (tsize(n->type) < 8) gen_cast(type_long, n->type);
        return;
    case N_LNOT: {
        int l = gen_new_label(), e = gen_new_label();
        gen_test_jump(n->a, 1, l);
        mov_ri(RAX, 1);
        gen_jmp(e);
        label_here(l);
        mov_ri(RAX, 0);
        label_here(e);
        return;
    }
    case N_LAND: case N_LOR: {
        int l = gen_new_label(), e = gen_new_label();
        gen_test_jump(n, 1, l);
        mov_ri(RAX, 0);
        gen_jmp(e);
        label_here(l);
        mov_ri(RAX, 1);
        label_here(e);
        return;
    }
    case N_ADD: case N_SUB: case N_MUL: case N_DIV: case N_MOD: case N_SHL: case N_SHR:
    case N_AND: case N_OR: case N_XOR:
    case N_EQ: case N_NE: case N_LT: case N_LE: case N_GT: case N_GE: {
        Type *ot = n->a->type;  /* operand type */
        int k = value_kind(ot);
        gen_expr(n->a);
        push_value(ot);
        gen_expr(n->b);
        if (k == 0) {
            mov_rr(RCX, RAX);
            pop_r(RAX);
            gen_binary_int(n->op, (n->op >= N_EQ && n->op <= N_GE) ? ot : n->type, ot->uns || is_ptr(ot));
        } else if (k == 1) {
            int d = ot->kind == T_DOUBLE;
            sse_rr(1, 0x10, 1, 0);  /* movsd xmm1, xmm0 */
            pop_xmm(0);
            gen_binary_sse(n->op, d);
        } else {
            gen_binary_x87(n->op);
        }
        return;
    }
    case N_ASSIGN: {
        Node *lhs = n->a, *rhs = n->b;
        if (is_struct(n->type)) {
            gen_expr(rhs);        /* rax = source address */
            push_r(RAX);
            gen_addr(lhs);
            mov_rr(RCX, RAX);
            pop_r(RAX);
            gen_memcpy_rax_to_rcx(tsize(n->type));
            mov_rr(RAX, RCX);
            return;
        }
        gen_expr(rhs);
        gen_addr_to_rcx_keep(lhs, n->type);
        gen_assign_to(lhs, n->type);
        /* value remains in result reg (for x87 it was popped by fstp: reload) */
        if (n->type->kind == T_LDOUBLE) x87_fld_mem(RCX, 0);
        return;
    }
    case N_ASSIGN_OP: {
        Node *lhs = n->a;
        Node *bin = n->c;       /* typed binary node: bin->a is a copy of lhs, bin->b rhs converted */
        Type *lt = n->type;
        Type *ot = bin->a->type;  /* operation type (after conversion of lhs copy) */
        int k;
        /* evaluate rhs first (in op type) */
        gen_expr(bin->b);
        push_value(bin->b->type);
        gen_addr(lhs);
        mov_rr(RCX, RAX);
        push_r(RCX);
        gen_load_lvalue(lhs);
        /* convert lhs value to operation type */
        if (bin->a->op == N_CAST) gen_cast(lhs->type, bin->a->type);
        ot = bin->a->type;
        k = value_kind(ot);
        if (k == 0) {
            /* rax = lhs(op type); stack: [rcx][rhs] */
            pop_r(RCX);          /* rcx = address */
            pop_r(RDX);          /* rdx = rhs */
            push_r(RCX);
            mov_rr(RCX, RDX);
            if (is_ptr(lt)) {
                /* pointer += int : bin->b already scaled */
            }
            gen_binary_int(bin->op, bin->type, ot->uns || is_ptr(ot));
            /* convert back to lhs type */
            gen_cast(bin->type, lt);
            pop_r(RCX);
        } else if (k == 1) {
            int d = ot->kind == T_DOUBLE;
            pop_r(RCX);
            pop_xmm(1);
            push_r(RCX);
            gen_binary_sse(bin->op, d);
            gen_cast(bin->type, lt);
            pop_r(RCX);
        } else {
            /* x87: stack has rhs (16 bytes) then rcx (8) on top */
            pop_r(RCX);
            push_r(RCX); /* keep */
            /* st0 = lhs; need st0=lhs, st1=rhs -> load rhs below: rearrange */
            /* current stack: [rsp]=rcx, [rsp+8..] = rhs */
            x87_fld_mem(RSP, 8);     /* st0 = rhs, st1 = lhs */
            o(0xd9); o(0xc9);        /* fxch: st0 = lhs, st1 = rhs */
            switch (bin->op) {
            case N_ADD: o(0xde); o(0xc1); break;
            case N_SUB: o(0xde); o(0xe9); break; /* fsubp st1,st0: st1 = st1 - st0 = rhs - lhs: wrong -> use fsubrp */
            case N_MUL: o(0xde); o(0xc9); break;
            case N_DIV: o(0xde); o(0xf1); break;
            }
            pop_r(RCX);
            add_rsp(16);
            gen_cast(bin->type, lt);
        }
        gen_assign_to(lhs, lt);
        if (lt->kind == T_LDOUBLE) x87_fld_mem(RCX, 0);
        return;
    }
    case N_PREINC: gen_incdec(n, 1, 0); return;
    case N_PREDEC: gen_incdec(n, 0, 0); return;
    case N_POSTINC: gen_incdec(n, 1, 1); return;
    case N_POSTDEC: gen_incdec(n, 0, 1); return;
    case N_COMMA:
        gen_expr(n->a);
        if (n->a->type->kind == T_LDOUBLE) { o(0xdd); o(0xd8); } /* fstp st0 */
        gen_expr(n->b);
        return;
    case N_COND: {
        int lf = gen_new_label(), le = gen_new_label();
        gen_test_jump(n->a, 0, lf);
        gen_expr(n->b);
        if (is_struct(n->type)) {
            /* copy to temp so both branches yield the same place */
            long tmp = alloc_temp(tsize(n->type), 16);
            lea(RCX, RBP, tmp);
            gen_memcpy_rax_to_rcx(tsize(n->type));
            gen_jmp(le);
            label_here(lf);
            gen_expr(n->c);
            lea(RCX, RBP, tmp);
            gen_memcpy_rax_to_rcx(tsize(n->type));
            label_here(le);
            lea(RAX, RBP, tmp);
            return;
        }
        gen_jmp(le);
        label_here(lf);
        gen_expr(n->c);
        label_here(le);
        return;
    }
    case N_CALL:
        gen_call(n);
        return;
    case N_STMT_EXPR: {
        Node *blk = n->a;
        int i;
        for (i = 0; i < blk->nlist; i++) {
            Node *s = blk->list[i];
            if (i == blk->nlist - 1 && s->op == N_EXPR && s->a) {
                gen_expr(s->a);
                if (s->a->type->kind == T_ARRAY) ; /* address */
            } else
                gen_stmt(s);
        }
        return;
    }
    case N_BUILTIN:
        switch (n->subop) {
        case TOK_builtin_frame_address:
            mov_rr(RAX, RBP);
            { int64_t i; for (i = 0; i < n->ival; i++) load_reg_mem(8, RAX, RAX, 0, 0); }
            return;
        case TOK_builtin_return_address:
            mov_rr(RAX, RBP);
            { int64_t i; for (i = 0; i < n->ival; i++) load_reg_mem(8, RAX, RAX, 0, 0); }
            load_reg_mem(8, RAX, RAX, 8, 0);
            return;
        case TOK_builtin_unreachable:
            return;
        }
        return;
    case N_VAARG:
        gen_vaarg(n);
        return;
    case N_SIZEOF_EXPR: {
        /* VLA sizeof */
        Type *t = n->cast_type;
        if (n->a && n->a->op == N_VAR && n->a->sym->is_local) {
            /* size stored in a hidden slot next to pointer: we store size at loc+8? use vla size slot */
            extern long vla_size_slot(Sym *s);
            load_reg_mem(8, RAX, RBP, vla_size_slot(n->a->sym), 0);
            return;
        }
        mov_ri(RAX, tsize(t) < 0 ? 0 : tsize(t));
        return;
    }
    case N_LABELADDR: {
        Sym *l = n->sym;
        if (!l->label_id) l->label_id = gen_new_label();
        lea(RAX, RIP, 0);
        add_fixup(ind() - 4, l->label_id);
        return;
    }
    default:
        tcc_error("internal: unsupported expression node %d", n->op);
    }
}

/* ---------------------------------------------------------------- */
/* statements */

long vla_size_slot(Sym *s) { return s->loc - 8; }

static void gen_vla_alloc(Node *d)
{
    Sym *s = d->sym;
    Type *t = s->type;
    /* compute total size: product of VLA dims * element size */
    Type *q = t;
    int first = 1;
    long elem_size;
    /* multiply all dimension expressions */
    while (q->kind == T_ARRAY && q->len == -2) {
        gen_expr(q->vla_size);
        gen_cast(q->vla_size->type, type_long);
        if (first) { push_r(RAX); first = 0; }
        else { pop_r(RCX); rex(1, RAX, 0, RCX); o(0x0f); o(0xaf); modrm_reg(RAX, RCX); push_r(RAX); }
        q = q->ref;
    }
    elem_size = tsize(q);
    if (elem_size < 0) elem_size = 1;
    pop_r(RAX);
    mov_ri(RCX, elem_size);
    rex(1, RAX, 0, RCX); o(0x0f); o(0xaf); modrm_reg(RAX, RCX);
    store_reg_mem(8, RAX, RBP, vla_size_slot(s));
    /* rsp -= (size + 15) & -16 */
    rex(1, 0, 0, RAX); o(0x83); modrm_reg(0, RAX); o(15);
    rex(1, 0, 0, RAX); o(0x83); modrm_reg(4, RAX); o(0xf0);
    alu_rr(1, 0x29, RSP, RAX);
    store_reg_mem(8, RSP, RBP, s->loc);
}

static void gen_decl(Node *d)
{
    Sym *s = d->sym;
    if (d->ival == 1) {
        gen_vla_alloc(d);
        return;
    }
    if (d->nlist || d->list)
        gen_init_entries(s, (InitEntry *)d->list, d->nlist, 0);
}

static void gen_switch(Node *n)
{
    int save_break = break_label;
    int lend = gen_new_label();
    int i;
    Type *t = n->a->type;
    int w = tsize(t) == 8;
    Node *def = NULL;
    gen_expr(n->a);
    /* compare chain */
    for (i = 0; i < n->nlist; i++) {
        Node *c = n->list[i];
        if (c->op == N_DEFAULT) { def = c; continue; }
        {
            int64_t v1 = c->ival, v2 = (int64_t)c->fval;
            if (v1 == v2) {
                mov_ri(RCX, v1);
                alu_rr(w, 0x39, RAX, RCX);
                gen_jcc(0x4, c->label);
            } else {
                /* range: v1 <= x <= v2 */
                int skip = gen_new_label();
                mov_ri(RCX, v1);
                alu_rr(w, 0x39, RAX, RCX);
                gen_jcc(t->uns ? 0x2 : 0xc, skip);  /* jb/jl skip */
                mov_ri(RCX, v2);
                alu_rr(w, 0x39, RAX, RCX);
                gen_jcc(t->uns ? 0x6 : 0xe, c->label); /* jbe/jle */
                label_here(skip);
            }
        }
    }
    if (def) gen_jmp(def->label);
    else gen_jmp(lend);
    break_label = lend;
    gen_stmt(n->b);
    label_here(lend);
    break_label = save_break;
}

static void gen_return(Node *n)
{
    Type *rt = gen_func_sym->type->ref;
    if (n->a) {
        gen_expr(n->a);
        if (is_struct(rt)) {
            int cls[2], ncls, k, ni = 0, ns = 0;
            ncls = classify(rt, cls);
            if (cls[0] == CLS_MEM) {
                /* copy to hidden pointer */
                load_reg_mem(8, RCX, RBP, ret_struct_ptr_off, 0);
                gen_memcpy_rax_to_rcx(tsize(rt));
                mov_rr(RAX, RCX);
            } else {
                /* load eightbytes */
                mov_rr(RCX, RAX);
                for (k = 0; k < ncls; k++) {
                    if (cls[k] == CLS_INT) {
                        load_reg_mem(8, ni == 0 ? RAX : RDX, RCX, 8 * k, 0);
                        ni++;
                    } else {
                        sse_load(1, ns, RCX, 8 * k);
                        ns++;
                    }
                }
            }
        }
    }
    gen_jmp(ret_label);
}

static void gen_stmt(Node *n)
{
    if (!n) return;
    switch (n->op) {
    case N_BLOCK: gen_block(n); return;
    case N_EXPR:
        gen_expr(n->a);
        if (n->a->type->kind == T_LDOUBLE) { o(0xdd); o(0xd8); }
        return;
    case N_DECL: gen_decl(n); return;
    case N_IF: {
        int lelse = gen_new_label(), lend = gen_new_label();
        gen_test_jump(n->a, 0, lelse);
        gen_stmt(n->b);
        if (n->c) {
            gen_jmp(lend);
            label_here(lelse);
            gen_stmt(n->c);
            label_here(lend);
        } else
            label_here(lelse);
        return;
    }
    case N_WHILE: {
        int save_b = break_label, save_c = continue_label;
        int ltop = gen_new_label(), lend = gen_new_label();
        break_label = lend; continue_label = ltop;
        label_here(ltop);
        gen_test_jump(n->a, 0, lend);
        gen_stmt(n->b);
        gen_jmp(ltop);
        label_here(lend);
        break_label = save_b; continue_label = save_c;
        return;
    }
    case N_DO: {
        int save_b = break_label, save_c = continue_label;
        int ltop = gen_new_label(), lend = gen_new_label(), lcond = gen_new_label();
        break_label = lend; continue_label = lcond;
        label_here(ltop);
        gen_stmt(n->b);
        label_here(lcond);
        gen_test_jump(n->a, 1, ltop);
        label_here(lend);
        break_label = save_b; continue_label = save_c;
        return;
    }
    case N_FOR: {
        int save_b = break_label, save_c = continue_label;
        int ltop = gen_new_label(), lend = gen_new_label(), lcont = gen_new_label();
        if (n->a) gen_stmt(n->a);
        break_label = lend; continue_label = lcont;
        label_here(ltop);
        if (n->b) gen_test_jump(n->b, 0, lend);
        gen_stmt(n->d);
        label_here(lcont);
        if (n->c) { gen_expr(n->c); if (n->c->type->kind == T_LDOUBLE) { o(0xdd); o(0xd8); } }
        gen_jmp(ltop);
        label_here(lend);
        break_label = save_b; continue_label = save_c;
        return;
    }
    case N_SWITCH: gen_switch(n); return;
    case N_CASE: case N_DEFAULT:
        label_here(n->label);
        gen_stmt(n->a);
        return;
    case N_BREAK: gen_jmp(break_label); return;
    case N_CONTINUE: gen_jmp(continue_label); return;
    case N_RETURN: gen_return(n); return;
    case N_GOTO: {
        Sym *l = n->sym;
        if (!l->label_id) l->label_id = gen_new_label();
        gen_jmp(l->label_id);
        return;
    }
    case N_COMPGOTO:
        gen_expr(n->a);
        rex(0, 0, 0, RAX); o(0xff); modrm_reg(4, RAX); /* jmp rax */
        return;
    case N_LABEL: {
        Sym *l = n->sym;
        if (!l->label_id) l->label_id = gen_new_label();
        label_here(l->label_id);
        gen_stmt(n->a);
        return;
    }
    case N_NOP: return;
    case N_ASM: gen_asm_statement(n); return;
    default:
        tcc_error("internal: unsupported statement node %d", n->op);
    }
}

static void gen_block(Node *n)
{
    int i;
    for (i = 0; i < n->nlist; i++)
        gen_stmt(n->list[i]);
}

/* ---------------------------------------------------------------- */
/* functions */

static void func_prologue(Sym **params, int nparams)
{
    Type *ft = gen_func_sym->type;
    int nint = 0, nsse = 0, i;
    long stack_off = 16;    /* first stack arg at [rbp+16] */
    int ret_cls[2];
    push_r(RBP);
    mov_rr(RBP, RSP);
    sub_rsp(0);             /* patched later */
    frame_size_pos = ind() - 4;
    store_reg_mem(8, RBX, RBP, -8);
    /* hidden struct return pointer */
    if (is_struct(ft->ref) && (classify(ft->ref, ret_cls), ret_cls[0] == CLS_MEM)) {
        ret_struct_ptr_off = alloc_temp(8, 8);
        store_reg_mem(8, RDI, RBP, ret_struct_ptr_off);
        nint = 1;
    }
    /* save all arg registers for variadic functions */
    if (ft->variadic) {
        reg_save_off = alloc_temp(176, 16);
        for (i = 0; i < 6; i++) store_reg_mem(8, int_arg_regs[i], RBP, reg_save_off + 8 * i);
        /* test al; movaps xmm0-7 */
        for (i = 0; i < 8; i++) {
            /* movaps [rbp+off], xmmi */
            rex(0, i, 0, RBP);
            o(0x0f); o(0x29);
            modrm_mem(i, RBP, reg_save_off + 48 + 16 * i);
        }
    }
    for (i = 0; i < nparams; i++) {
        Sym *p = params[i];
        int cls[2], ncls, k, ni = 0, ns = 0;
        ncls = classify(p->type, cls);
        if (cls[0] == CLS_MEM || cls[0] == CLS_X87) goto in_mem;
        for (k = 0; k < ncls; k++) { if (cls[k] == CLS_INT) ni++; else ns++; }
        if (nint + ni > 6 || nsse + ns > 8) goto in_mem;
        for (k = 0; k < ncls; k++) {
            if (cls[k] == CLS_INT) {
                store_reg_mem(8, int_arg_regs[nint++], RBP, p->loc + 8 * k);
            } else {
                if (is_struct(p->type)) sse_store(1, nsse++, RBP, p->loc + 8 * k);
                else sse_store(p->type->kind == T_DOUBLE, nsse++, RBP, p->loc);
            }
        }
        continue;
    in_mem: {
            int sz = tsize(p->type);
            int al = type_align(p->type);
            if (al < 8) al = 8;
            stack_off = (stack_off + al - 1) & -al;
            lea(RAX, RBP, stack_off);
            lea(RCX, RBP, p->loc);
            gen_memcpy_rax_to_rcx(sz < 8 ? 8 : sz);
            stack_off += (sz + 7) & ~7;
        }
    }
    if (ft->variadic) {
        /* initialize va_list struct at rbp-24: gp_offset, fp_offset, overflow_arg_area, reg_save_area */
        mov_ri(RAX, nint * 8);
        store_reg_mem(4, RAX, RBP, -24);
        mov_ri(RAX, 48 + nsse * 16);
        store_reg_mem(4, RAX, RBP, -20);
        lea(RAX, RBP, stack_off);
        store_reg_mem(8, RAX, RBP, -16);
        lea(RAX, RBP, reg_save_off);
        store_reg_mem(8, RAX, RBP, -8 - 8 + 0); /* placeholder, fixed below */
        /* reg_save_area at offset 16 of struct: rbp-24+16 = rbp-8 ... but rbp-8 holds rbx! */
    }
}

/* NOTE: va_list struct placement: we put it at rbp-40..rbp-16 and keep rbx at rbp-8.
   The predefined macro uses frame_address-24 so struct must start at rbp-24.
   To honor that, rbx is saved at rbp-32 instead. See gen_function. */

void gen_function(Sym *fsym, Node *body, Sym **params, int nparams, int frame_hint)
{
    long fsz;
    int i;
    cs = cur_text_section;
    gen_func_sym = fsym;
    nlabels = 0;
    nfixups = 0;
    func_start = ind();
    /* align function start */
    while (ind() & 7) o(0x90);
    func_start = ind();
    ret_label = gen_new_label();
