/* ---------------------------------------------------------------- */
/* static data */

/* evaluate address constant: returns 1 and sets *sym, *addend */
static int eval_addr_const(Node *n, Sym **sym, long *addend)
{
    switch (n->op) {
    case N_ADDR: {
        Node *a = n->a;
        if (a->op == N_VAR) {
            if (a->sym->is_local) return 0;
            *sym = a->sym; *addend = 0;
            return 1;
        }
        if (a->op == N_STR) {
