            *sym = s; *addend = 0;
            return 1;
        }
        if (a->op == N_COMPOUND_LIT) {
            if (a->sym->is_local) return 0;
            *sym = a->sym; *addend = 0;
            return 1;
        }
        if (a->op == N_MEMBER) {
            Node tmp = *n;
            tmp.a = a->a;
            if (a->a->op == N_DEREF) {
                if (!eval_addr_const(a->a->a, sym, addend)) return 0;
            } else if (!eval_addr_const(&tmp, sym, addend)) return 0;
            *addend += a->ival;
            return 1;
        }
        if (a->op == N_DEREF) {
            return eval_addr_const(a->a, sym, addend);
        }
        return 0;
    }
    case N_CAST:
        if (!is_ptr(n->type) && !(is_integer(n->type) && tsize(n->type) == 8)) return 0;
        return eval_addr_const(n->a, sym, addend);
    case N_ADD: case N_SUB: {
        int64_t v;
        if (node_is_const_int(n->b, &v)) {
            if (!eval_addr_const(n->a, sym, addend)) return 0;
            *addend += n->op == N_ADD ? v : -v;
            return 1;
        }
        if (n->op == N_ADD && node_is_const_int(n->a, &v)) {
            if (!eval_addr_const(n->b, sym, addend)) return 0;
            *addend += v;
            return 1;
        }
        return 0;
    }
    case N_VAR:
        if (n->type->kind == T_FUNC && !n->sym->is_local) { *sym = n->sym; *addend = 0; return 1; }
        return 0;
    case N_STR: {
        Sym *s;
        new_string_literal(n->str, n->slen, n->type, &s);
        *sym = s; *addend = 0;
        return 1;
    }
    case N_COND: {
        int64_t c;
        if (node_is_const_int(n->a, &c))
            return eval_addr_const(c ? n->b : n->c, sym, addend);
        return 0;
    }
    default:
        return 0;
    }
}

static void put_bits(unsigned char *p, int size, int bit_off, int bit_size, uint64_t v)
{
    uint64_t old = 0, mask;
    memcpy(&old, p, size);
    mask = bit_size >= 64 ? ~0ULL : ((1ULL << bit_size) - 1);
    old &= ~(mask << bit_off);
    old |= (v & mask) << bit_off;
    memcpy(p, &old, size);
}

static void emit_static_value(Section *sec, long off, Type *t, Node *v, int bit_off, int bit_size)
{
    unsigned char *p;
    v = fold_const(v);
    if (sec->type == SHT_NOBITS)
        tcc_error("internal: init into bss");
    p = sec->data + off;
    if (v->op == N_STR && t->kind == T_ARRAY) {
        int n = v->slen, tl = tsize(t);
        if (n > tl) n = tl;
        memcpy(p, v->str, n);
        return;
    }
    if (is_struct(t)) {
        /* struct from constant compound literal */
        if (v->op == N_COMPOUND_LIT && !v->sym->is_local) {
            Sym *s = v->sym;
            Section *src = NULL;
            int i;
            for (i = 0; i < all_sections.len; i++)
                if (((Section *)all_sections.p[i])->sh_num == s->section) src = all_sections.p[i];
            if (src && src->type != SHT_NOBITS)
                memcpy(p, src->data + s->sec_offset, tsize(t));
            return;
        }
        tcc_error("initializer element is not constant");
    }
    if (v->op == N_CONST) {
        int sz = tsize(t);
        if (bit_size > 0) { put_bits(p, sz, bit_off, bit_size, (uint64_t)v->ival); return; }
        if (t->kind == T_BOOL) { p[0] = v->ival != 0; return; }
        switch (sz) {
        case 1: p[0] = (uint8_t)v->ival; break;
        case 2: { uint16_t x = (uint16_t)v->ival; memcpy(p, &x, 2); break; }
        case 4: { uint32_t x = (uint32_t)v->ival; memcpy(p, &x, 4); break; }
        default: { uint64_t x = (uint64_t)v->ival; memcpy(p, &x, 8); break; }
        }
        return;
    }
    if (v->op == N_FCONST) {
        if (t->kind == T_FLOAT) { float f = (float)v->fval; memcpy(p, &f, 4); }
        else if (t->kind == T_DOUBLE) { double d = (double)v->fval; memcpy(p, &d, 8); }
        else { long double ld = v->fval; memcpy(p, &ld, 10); }
        return;
    }
    {
        Sym *s; long addend;
        if (eval_addr_const(v, &s, &addend)) {
            int sz = tsize(t);
            if (sz != 8)
                tcc_error("initializer element is not computable at load time");
            section_reloc(sec, off, R_X86_64_64, sym_elf_index(s), addend);
            return;
        }
    }
    tcc_error("initializer element is not constant");
}

static PVec tentatives;

void add_tentative(Sym *s)
{
    int i;
    for (i = 0; i < tentatives.len; i++)
        if (tentatives.p[i] == s) return;
    pvec_push(&tentatives, s);
}

static int all_zero_entries(InitList *il)
{
    int i;
    for (i = 0; i < il->n; i++) {
        Node *v = fold_const(il->e[i].val);
        if (v->op == N_CONST && v->ival == 0) continue;
        if (v->op == N_FCONST && v->fval == 0) continue;
        return 0;
    }
    return 1;
}

void define_global_data(Sym *s, InitList *il, int is_static)
{
    Section *sec;
    int sz, al;
    long off;
    int i;
    int idx;
    sz = type_size(s->type, &al);
    if (sz < 0)
        tcc_error("unknown type size");
    if (s->aligned_attr > al) al = s->aligned_attr;
    if (s->section_name)
        sec = section_find(s->section_name);
    else if (il && il->n == 0 && S.common == 0 && 0)
        sec = bss_section;
    else if (s->type->quals & Q_CONST)
        sec = rodata_section;
    else
        sec = data_section;
    if (s->section_name && !sec) {
        sec = section_new(s->section_name, SHT_PROGBITS, SHF_ALLOC | SHF_WRITE);
        sec->align = 8;
    }
    (void)all_zero_entries;
    off = section_add(sec, sz, al);
    if (sec->type != SHT_NOBITS)
        memset(sec->data + off, 0, sz);
    for (i = 0; il && i < il->n; i++) {
        InitEntry *e = &il->e[i];
        emit_static_value(sec, off + e->off, e->type, e->val, e->bit_off, e->bit_size);
    }
    s->section = sec->sh_num;
    s->sec_offset = off;
    s->defined = 1;
    idx = sym_elf_index(s);
    {
        int bind = (s->storage & ST_STATIC) || s->is_static_fn || (!s->id && !s->asm_name) ? STB_LOCAL : (s->weak ? STB_WEAK : STB_GLOBAL);
        if (!s->id) bind = STB_LOCAL;
        elf_sym_update(idx, off, sz, bind, STT_OBJECT, sec->sh_num);
    }
    (void)is_static;
}

void gen_tentatives(void)
{
    int i;
    for (i = 0; i < tentatives.len; i++) {
        Sym *s = tentatives.p[i];
        int sz, al, idx;
        long off;
        Section *sec;
        if (s->defined) continue;
        if (s->storage & ST_EXTERN) continue;
        sz = type_size(s->type, &al);
        if (sz < 0) {
            if (s->type->kind == T_ARRAY && s->type->len < 0) {
                s->type = type_array(s->type->ref, 1);
                sz = type_size(s->type, &al);
            } else
                tcc_error("unknown type size");
        }
        if (s->aligned_attr > al) al = s->aligned_attr;
        if (s->section_name) {
            sec = section_find(s->section_name);
            if (!sec) { sec = section_new(s->section_name, SHT_PROGBITS, SHF_ALLOC | SHF_WRITE); sec->align = 8; }
            off = section_add(sec, sz, al);
            if (sec->type != SHT_NOBITS) memset(sec->data + off, 0, sz);
        } else {
            sec = bss_section;
            off = section_add(sec, sz, al);
        }
        s->section = sec->sh_num;
        s->sec_offset = off;
        s->defined = 1;
        idx = sym_elf_index(s);
        {
            int bind = (s->storage & ST_STATIC) || s->is_static_fn ? STB_LOCAL : (s->weak ? STB_WEAK : STB_GLOBAL);
            elf_sym_update(idx, off, sz, bind, STT_OBJECT, sec->sh_num);
        }
    }
    tentatives.len = 0;
}

void gen_init(void)
{
    string_counter = 0;
    tentatives.len = 0;
    nlabels = 0;
}

/* ---------------------------------------------------------------- */
/* inline asm (minimal) */

void parse_asm_statement(Node *n)
{
    CStr cs;
    int w, c;
    next();
    while (tok == TOK_VOLATILE1 || tok == TOK_VOLATILE2 || tok == TOK_VOLATILE3 || tok == TOK_INLINE1 || tok == TOK_GOTO)
        next();
    skip('(');
    if (tok != TOK_STR)
        expect("string constant");
    cstr_init(&cs);
    while (tok == TOK_STR) {
        parse_string_literal(tokstr, &cs, &w, &c);
        next();
    }
    n->str = cs.data ? intern(cs.data, cs.len) : "";
    n->slen = cs.len;
    cstr_free(&cs);
    /* operands: skip them syntactically */
    {
        int ncolon = 0;
        while (tok == ':') {
            next();
            ncolon++;
            while (tok != ':' && tok != ')') {
                if (tok == '[') {
                    next();
                    if (tok < TOK_IDENT) expect("identifier");
                    next();
                    skip(']');
                }
                if (tok == TOK_STR) {
                    next();
                } else if (ncolon == 3 || ncolon == 4) {
                    if (tok >= TOK_IDENT) next();
                } else
                    expect("string constant");
                if (tok == '(') {
                    Node *e;
                    next();
                    e = parse_expr();
                    (void)e;
                    skip(')');
                    n->nlist++;
                }
                if (tok == ',') next();
                else break;
            }
        }
    }
    skip(')');
    if (tok == ';') next();
}

void gen_asm_statement(Node *n)
{
    /* only empty asm statements (barriers) are supported */
    const char *p = n->str;
    while (p && *p && (*p == ' ' || *p == '\t' || *p == '\n')) p++;
    if (p && *p)
        tcc_error("inline assembly not supported");
}
