#include "cc.h"

void pp_build_cmdline_buf(const char *main_filename, int is_pp);
void pp_start_compile(void);
void pp_reset_state(void);
void pp_clear_macros(void);
static int compile_started;

static void add_cmdline_includes(void)
{
