        memset(sec->data + off, 0, sz);
    for (i = 0; il && i < il->n; i++) {
        InitEntry *e = &il->e[i];
        emit_static_value(sec, off + e->off, e->type, e->val, e->bit_off, e->bit_size);
    }
    s->section = sec->sh_num;
    s->sec_offset = off;
    s->defined = 1;
    idx = sym_elf_index(s);
    {
        int bind = (s->storage & ST_STATIC) || s->is_static_fn || (!s->id && !s->asm_name) ? STB_LOCAL : (s->weak ? STB_WEAK : STB_GLOBAL);
        if (!s->id) bind = STB_LOCAL;
        elf_sym_update(idx, off, sz, bind, STT_OBJECT, sec->sh_num);
    }
    (void)is_static;
}

void gen_tentatives(void)
{
    int i;
    for (i = 0; i < tentatives.len; i++) {
        Sym *s = tentatives.p[i];
        int sz, al, idx;
        long off;
        Section *sec;
        if (s->defined) continue;
        if (s->storage & ST_EXTERN) continue;
        sz = type_size(s->type, &al);
        if (sz < 0) {
            if (s->type->kind == T_ARRAY && s->type->len < 0) {
                s->type = type_array(s->type->ref, 1);
                sz = type_size(s->type, &al);
            } else
                tcc_error("unknown type size");
        }
        if (s->aligned_attr > al) al = s->aligned_attr;
        if (s->section_name) {
            sec = section_find(s->section_name);
            if (!sec) { sec = section_new(s->section_name, SHT_PROGBITS, SHF_ALLOC | SHF_WRITE); sec->align = 8; }
            off = section_add(sec, sz, al);
            if (sec->type != SHT_NOBITS) memset(sec->data + off, 0, sz);
        } else {
            sec = bss_section;
            off = section_add(sec, sz, al);
        }
        s->section = sec->sh_num;
        s->sec_offset = off;
        s->defined = 1;
        idx = sym_elf_index(s);
        {
            int bind = (s->storage & ST_STATIC) || s->is_static_fn ? STB_LOCAL : (s->weak ? STB_WEAK : STB_GLOBAL);
            elf_sym_update(idx, off, sz, bind, STT_OBJECT, sec->sh_num);
        }
    }
    tentatives.len = 0;
}

void gen_init(void)
{
    string_counter = 0;
    tentatives.len = 0;
    nlabels = 0;
}

/* ---------------------------------------------------------------- */
/* inline asm (minimal) */

void parse_asm_statement(Node *n)
{
    CStr cs;
    int w, c;
    next();
    while (tok == TOK_VOLATILE1 || tok == TOK_VOLATILE2 || tok == TOK_VOLATILE3 || tok == TOK_INLINE1 || tok == TOK_GOTO)
        next();
    skip('(');
    if (tok != TOK_STR)
        expect("string constant");
    cstr_init(&cs);
    while (tok == TOK_STR) {
        parse_string_literal(tokstr, &cs, &w, &c);
        next();
    }
    n->str = cs.data ? intern(cs.data, cs.len) : "";
    n->slen = cs.len;
    cstr_free(&cs);
    /* operands: skip them syntactically */
    {
        int ncolon = 0;
        while (tok == ':') {
            next();
            ncolon++;
            while (tok != ':' && tok != ')') {
                if (tok == '[') {
                    next();
                    if (tok < TOK_IDENT) expect("identifier");
                    next();
                    skip(']');
                }
                if (tok == TOK_STR) {
                    next();
                } else if (ncolon == 3 || ncolon == 4) {
                    if (tok >= TOK_IDENT) next();
                } else
                    expect("string constant");
                if (tok == '(') {
                    Node *e;
                    next();
                    e = parse_expr();
                    (void)e;
                    skip(')');
                    n->nlist++;
                }
                if (tok == ',') next();
                else break;
            }
        }
    }
    skip(')');
    if (tok == ';') next();
}

void gen_asm_statement(Node *n)
{
    /* only empty asm statements (barriers) are supported */
    const char *p = n->str;
    while (p && *p && (*p == ' ' || *p == '\t' || *p == '\n')) p++;
    if (p && *p)
        tcc_error("inline assembly not supported");
}
