int tcc_compile_file(InFile *f, const char *outname)
{
    int ret = 0;
    if (f->type == FT_OBJ || f->type == FT_LIB)
        return 0;
    pp_reset_state();
    pp_clear_macros();
    if (!compile_started) {
        tccelf_begin();
        gen_init();
        parser_init();
        compile_started = 1;
    }
    if (pp_open_file(f->name, -1) < 0)
        tcc_fatal("file '%s' not found", f->name);
    pp_add_dep(f->name);
    /* FILE symbol */
    elf_sym_add(f->name, 0, 0, 0 /*STB_LOCAL*/, 4 /*STT_FILE*/, 0xfff1 /*SHN_ABS*/);
    pp_build_cmdline_buf(f->name, 0);
    add_cmdline_includes();
    if (setjmp(error_jmp_buf) == 0) {
        error_set_jmp_enabled = 1;
        pp_start_compile();
        if (f->type == FT_ASM || f->type == FT_ASMPP) {
            tcc_error("assembler files not supported");
        }
        parse_translation_unit();
        gen_tentatives();
    } else {
        ret = 1;
    }
    error_set_jmp_enabled = 0;
    while (file)
        pp_close_file();
    if (ret)
        return ret;
    if (outname) {
        tccelf_output_file(outname);
    }
    return 0;
}
