#!/bin/bash
# compile each test with our tcc (-c) and link with gcc; compare output to gcc-built version
cd "$(dirname "$0")"
T=../../executable
pass=0; fail=0
for c in ${1:-*.c}; do
  n=${c%.c}
  gcc -w -o /tmp/ref_$n $c -lm 2>/dev/null || { echo "SKIP (gcc fails) $n"; continue; }
  /tmp/ref_$n > /tmp/ref_$n.out 2>&1; echo "rc=$?" >> /tmp/ref_$n.out
  if ! timeout 10 $T -c -o /tmp/tcc_$n.o $c 2>/tmp/tcc_$n.err; then echo "FAIL compile: $n"; head -5 /tmp/tcc_$n.err; fail=$((fail+1)); continue; fi
  if ! gcc -o /tmp/tcc_$n /tmp/tcc_$n.o -lm 2>/tmp/tcc_$n.lderr; then echo "FAIL link: $n"; head -5 /tmp/tcc_$n.lderr; fail=$((fail+1)); continue; fi
  timeout 10 /tmp/tcc_$n > /tmp/tcc_$n.out 2>&1; echo "rc=$?" >> /tmp/tcc_$n.out
  if diff -q /tmp/tcc_$n.out /tmp/ref_$n.out > /dev/null; then pass=$((pass+1)); else echo "FAIL output: $n"; diff /tmp/tcc_$n.out /tmp/ref_$n.out | head -10; fail=$((fail+1)); fi
done
echo "pass=$pass fail=$fail"
EOF
