/* object loading and static linking */
#include "cc.h"
#include <elf.h>
#include <ar.h>

int elf_sym_bind(int idx);
int elf_nb_syms(void);
Elf64_Sym *elf_sym_ptr(int idx);
void elf_sym_set_other(int idx, int other);

static int nb_dso_syms;
static char **dso_syms;   /* names defined by shared libraries given with -l */

static void add_dso_sym(const char *name)
{
    dso_syms = xrealloc(dso_syms, (nb_dso_syms + 1) * sizeof(char *));
    dso_syms[nb_dso_syms++] = xstrdup(name);
}

static int is_dso_sym(const char *name)
{
    int i;
    for (i = 0; i < nb_dso_syms; i++)
        if (!strcmp(dso_syms[i], name)) return 1;
    return 0;
}

static char *read_file_data(const char *path, long *plen)
{
    FILE *f = fopen(path, "rb");
    char *d;
    long n;
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    n = ftell(f);
    fseek(f, 0, SEEK_SET);
    d = xmalloc(n + 1);
    if (fread(d, 1, n, f) != (size_t)n) { fclose(f); free(d); return NULL; }
    fclose(f);
    d[n] = 0;
    *plen = n;
    return d;
}

/* find or add a global symbol by name during linking */
static int link_sym_find_or_add(const char *name, int bind, int type, int shndx, uint64_t value, uint64_t size, int *existed)
{
    int idx = elf_sym_find(name);
    *existed = idx != 0;
    if (!idx)
        idx = elf_sym_add(name, value, size, bind, type, shndx);
    return idx;
}

/* load an ELF relocatable object from memory into our sections */
static int load_object(const char *name, unsigned char *data, long len)
{
    Elf64_Ehdr *eh = (Elf64_Ehdr *)data;
    Elf64_Shdr *sh;
    int i;
    Section **secmap;     /* input section index -> our Section */
    long *offmap;         /* offset of input section data within our section */
    int *symmap;          /* input symbol index -> our symbol index */
    Elf64_Shdr *symtab_sh = NULL;
    Elf64_Sym *isyms = NULL;
    int nisyms = 0;
    const char *istrtab = NULL;
    const char *shstr;

    if (len < (long)sizeof(Elf64_Ehdr) || memcmp(eh->e_ident, ELFMAG, SELFMAG) || eh->e_type != ET_REL
        || eh->e_machine != EM_X86_64) {
        tcc_error_noabort("invalid object file '%s'", name);
        return -1;
    }
    sh = (Elf64_Shdr *)(data + eh->e_shoff);
    shstr = (const char *)(data + sh[eh->e_shstrndx].sh_offset);
    secmap = xcalloc(sizeof(Section *) * eh->e_shnum);
    offmap = xcalloc(sizeof(long) * eh->e_shnum);
    /* sections */
    for (i = 1; i < eh->e_shnum; i++) {
        Elf64_Shdr *h = &sh[i];
        const char *sname = shstr + h->sh_name;
        Section *s;
        if (h->sh_type == SHT_SYMTAB) { symtab_sh = h; continue; }
        if (h->sh_type == SHT_STRTAB || h->sh_type == SHT_RELA || h->sh_type == SHT_REL) continue;
        if (h->sh_type == SHT_NULL) continue;
        if (!(h->sh_flags & SHF_ALLOC)) {
            /* non-alloc sections (debug, comment, note): skip, except .note.GNU-stack */
            continue;
        }
        if (!strcmp(sname, ".rodata") || !strncmp(sname, ".rodata.", 8)) sname = ".data.ro";
        if (!strncmp(sname, ".text.", 6)) sname = ".text";
        if (!strncmp(sname, ".data.rel", 9)) sname = ".data";
        if (!strncmp(sname, ".data.", 6) && strcmp(sname, ".data.ro")) sname = ".data";
        if (!strncmp(sname, ".bss.", 5)) sname = ".bss";
        s = section_find(sname);
        if (!s) {
            s = section_new(sname, h->sh_type == SHT_NOBITS ? SHT_NOBITS : SHT_PROGBITS, h->sh_flags);
            s->align = 1;
        }
        {
            long off = section_add(s, h->sh_size, h->sh_addralign ? h->sh_addralign : 1);
            if (s->type != SHT_NOBITS && h->sh_type != SHT_NOBITS)
                memcpy(s->data + off, data + h->sh_offset, h->sh_size);
            secmap[i] = s;
            offmap[i] = off;
        }
    }
    if (!symtab_sh) {
        free(secmap); free(offmap);
        return 0;
    }
    isyms = (Elf64_Sym *)(data + symtab_sh->sh_offset);
    nisyms = symtab_sh->sh_size / sizeof(Elf64_Sym);
    istrtab = (const char *)(data + sh[symtab_sh->sh_link].sh_offset);
    symmap = xcalloc(sizeof(int) * nisyms);
    for (i = 1; i < nisyms; i++) {
        Elf64_Sym *s = &isyms[i];
        const char *sname = istrtab + s->st_name;
        int bind = ELF64_ST_BIND(s->st_info), type = ELF64_ST_TYPE(s->st_info);
        int shndx = s->st_shndx;
        uint64_t value = s->st_value;
        if (type == STT_SECTION) {
            /* section symbol: map to our section with offset */
            if (shndx < eh->e_shnum && secmap[shndx]) {
                symmap[i] = elf_sym_add(NULL, offmap[shndx], 0, STB_LOCAL, STT_SECTION, secmap[shndx]->sh_num);
            }
            continue;
        }
        if (type == STT_FILE) { symmap[i] = 0; continue; }
        if (shndx == SHN_COMMON) {
            /* allocate in bss */
            long off = section_add(bss_section, s->st_size, s->st_value ? s->st_value : 1);
            shndx = bss_section->sh_num;
            value = off;
        } else if (shndx == SHN_ABS) {
            ;
        } else if (shndx != SHN_UNDEF) {
            if (shndx >= eh->e_shnum || !secmap[shndx]) { symmap[i] = 0; continue; }
            value += offmap[shndx];
            shndx = secmap[shndx]->sh_num;
        }
        if (bind == STB_LOCAL) {
            symmap[i] = elf_sym_add(sname, value, s->st_size, STB_LOCAL, type, shndx);
            continue;
        }
        {
            int existed;
            int idx = link_sym_find_or_add(sname, bind, type, shndx, value, s->st_size, &existed);
            if (existed) {
                Elf64_Sym *o = elf_sym_ptr(idx);
                int obind = ELF64_ST_BIND(o->st_info);
                if (shndx != SHN_UNDEF) {
                    if (o->st_shndx == SHN_UNDEF) {
                        /* define it */
                        elf_sym_update(idx, value, s->st_size, bind == STB_WEAK && obind != STB_WEAK ? obind : bind, type, shndx);
                        if (bind != STB_WEAK) elf_sym_update(idx, value, s->st_size, STB_GLOBAL, type, shndx);
                    } else if (obind == STB_WEAK && bind != STB_WEAK) {
                        elf_sym_update(idx, value, s->st_size, bind, type, shndx);
                    } else if (bind == STB_WEAK) {
                        /* keep existing */
                    } else {
                        tcc_error_noabort("'%s' defined twice", sname);
                    }
                } else {
                    /* undefined reference: nothing */
                }
            }
            symmap[i] = idx;
        }
    }
    /* relocations */
    for (i = 1; i < eh->e_shnum; i++) {
        Elf64_Shdr *h = &sh[i];
        Elf64_Rela *r;
        int k, nr;
        Section *target;
        if (h->sh_type != SHT_RELA) continue;
        if (h->sh_info >= eh->e_shnum) continue;
        target = secmap[h->sh_info];
        if (!target) continue;
        r = (Elf64_Rela *)(data + h->sh_offset);
        nr = h->sh_size / sizeof(Elf64_Rela);
        for (k = 0; k < nr; k++) {
            int sym = ELF64_R_SYM(r[k].r_info);
            int type = ELF64_R_TYPE(r[k].r_info);
            int nsym = sym < nisyms ? symmap[sym] : 0;
            section_reloc(target, r[k].r_offset + offmap[h->sh_info], type, nsym, r[k].r_addend);
        }
    }
    free(secmap); free(offmap); free(symmap);
    return 0;
}

/* archive handling */
static int archive_defines_needed(unsigned char *data, long len, int *loaded_any);

static int load_archive(const char *name, unsigned char *data, long len, int whole)
{
    int changed, any;
    if (len < SARMAG || memcmp(data, ARMAG, SARMAG)) {
        tcc_error_noabort("invalid archive '%s'", name);
        return -1;
    }
    (void)whole;
    do {
        changed = 0;
        any = 0;
        if (archive_defines_needed(data, len, &any) < 0) return -1;
        changed = any;
    } while (changed);
    return 0;
}

/* iterate archive members; load those that define an undefined symbol */
static int archive_defines_needed(unsigned char *data, long len, int *loaded_any)
{
    long pos = SARMAG;
    char *longnames = NULL;
    *loaded_any = 0;
    while (pos + (long)sizeof(struct ar_hdr) <= len) {
        struct ar_hdr *hdr = (struct ar_hdr *)(data + pos);
        long size = atol(hdr->ar_size);
        unsigned char *mem = data + pos + sizeof(struct ar_hdr);
        char mname[256];
        int i;
        if (hdr->ar_name[0] == '/' && hdr->ar_name[1] == '/') {
            longnames = (char *)mem;
        } else if (hdr->ar_name[0] == '/' && (hdr->ar_name[1] == ' ' || hdr->ar_name[1] == 'S')) {
            /* symbol table: skip */
        } else {
            if (hdr->ar_name[0] == '/' && longnames) {
                long off = atol(hdr->ar_name + 1);
                char *p = longnames + off;
                for (i = 0; i < 255 && p[i] && p[i] != '/' && p[i] != '\n'; i++) mname[i] = p[i];
                mname[i] = 0;
            } else {
                for (i = 0; i < 16 && hdr->ar_name[i] && hdr->ar_name[i] != '/' && hdr->ar_name[i] != ' '; i++) mname[i] = hdr->ar_name[i];
                mname[i] = 0;
            }
            if (size >= (long)sizeof(Elf64_Ehdr) && !memcmp(mem, ELFMAG, SELFMAG)) {
                /* check whether this member defines any currently undefined symbol */
                Elf64_Ehdr *eh = (Elf64_Ehdr *)mem;
                Elf64_Shdr *sh = (Elf64_Shdr *)(mem + eh->e_shoff);
                int need = 0, s;
                for (s = 0; s < eh->e_shnum && !need; s++) {
                    if (sh[s].sh_type == SHT_SYMTAB) {
                        Elf64_Sym *syms = (Elf64_Sym *)(mem + sh[s].sh_offset);
                        int n = sh[s].sh_size / sizeof(Elf64_Sym), k;
                        const char *str = (const char *)(mem + sh[sh[s].sh_link].sh_offset);
                        for (k = 1; k < n; k++) {
                            int idx;
                            if (ELF64_ST_BIND(syms[k].st_info) == STB_LOCAL) continue;
                            if (syms[k].st_shndx == SHN_UNDEF) continue;
                            idx = elf_sym_find(str + syms[k].st_name);
                            if (idx && !elf_sym_is_defined(idx)) { need = 1; break; }
                        }
                    }
                }
                if (need) {
                    unsigned char *copy = xmalloc(size + 1);
                    memcpy(copy, mem, size);
                    load_object(mname, copy, size);
                    free(copy);
                    *loaded_any = 1;
                    /* mark member as loaded by zeroing its magic to avoid reloading */
                    memset(mem, 0, SELFMAG);
                }
            }
        }
        pos += sizeof(struct ar_hdr) + size;
        if (pos & 1) pos++;
    }
    return 0;
}

/* read dynamic symbols of a shared library */
static int load_dso_syms(const char *path)
{
    long len;
    unsigned char *data = (unsigned char *)read_file_data(path, &len);
    Elf64_Ehdr *eh;
    Elf64_Shdr *sh;
    int i;
    if (!data) return -1;
    eh = (Elf64_Ehdr *)data;
    if (len < (long)sizeof(*eh) || memcmp(eh->e_ident, ELFMAG, SELFMAG)) { free(data); return -1; }
    if (eh->e_type != ET_DYN) {
        /* maybe a linker script: GROUP ( /lib/.../libc.so.6 ... ) */
        char *p = strstr((char *)data, "GROUP");
        if (!p) p = strstr((char *)data, "INPUT");
        if (p) {
            char *q = strchr(p, '(');
            if (q) {
                q++;
                for (;;) {
                    char fn[1024];
                    int n = 0;
                    while (*q == ' ' || *q == '\t' || *q == '\n') q++;
                    if (*q == ')' || !*q) break;
                    if (!strncmp(q, "AS_NEEDED", 9)) { q += 9; while (*q == ' ') q++; if (*q == '(') q++; continue; }
                    while (*q && *q != ' ' && *q != ')' && *q != '\n' && n < 1000) fn[n++] = *q++;
                    fn[n] = 0;
                    if (n) {
                        const char *ext = strrchr(fn, '.');
                        if (ext && !strcmp(ext, ".a")) {
                            /* static part: load as archive for symbol resolution? skip */
                        } else if (strstr(fn, ".so"))
                            load_dso_syms(fn);
                    }
                    if (*q == ')') { q++; }
                }
            }
        }
        free(data);
        return 0;
    }
    sh = (Elf64_Shdr *)(data + eh->e_shoff);
    for (i = 0; i < eh->e_shnum; i++) {
        if (sh[i].sh_type == SHT_DYNSYM) {
            Elf64_Sym *syms = (Elf64_Sym *)(data + sh[i].sh_offset);
            int n = sh[i].sh_size / sizeof(Elf64_Sym), k;
            const char *str = (const char *)(data + sh[sh[i].sh_link].sh_offset);
            for (k = 1; k < n; k++) {
                if (syms[k].st_shndx != SHN_UNDEF)
                    add_dso_sym(str + syms[k].st_name);
            }
        }
    }
    free(data);
    return 0;
}

/* find a library file: returns malloc'd path or NULL */
static char *find_library(const char *name, int static_only)
{
    int i;
    char buf[1024];
    struct stat st;
    for (i = 0; i < S.library_paths.len; i++) {
        const char *dir = S.library_paths.p[i];
        if (!static_only) {
            snprintf(buf, sizeof buf, "%s/lib%s.so", dir, name);
            if (stat(buf, &st) == 0) return xstrdup(buf);
        }
        snprintf(buf, sizeof buf, "%s/lib%s.a", dir, name);
        if (stat(buf, &st) == 0) return xstrdup(buf);
    }
    return NULL;
}

static char *find_in_libpaths(const char *fname)
{
    int i;
    char buf[1024];
    struct stat st;
    for (i = 0; i < S.library_paths.len; i++) {
        snprintf(buf, sizeof buf, "%s/%s", (char *)S.library_paths.p[i], fname);
        if (stat(buf, &st) == 0) return xstrdup(buf);
    }
    return NULL;
}

static char *find_crt(const char *fname)
{
    int i;
    char buf[1024];
    struct stat st;
    for (i = 0; i < S.crt_paths.len; i++) {
        snprintf(buf, sizeof buf, "%s/%s", (char *)S.crt_paths.p[i], fname);
        if (stat(buf, &st) == 0) return xstrdup(buf);
    }
    return NULL;
}

int tcc_load_file(const char *path, int is_lib_name)
{
    long len;
    unsigned char *data;
    const char *ext;
    data = (unsigned char *)read_file_data(path, &len);
    if (!data) {
        tcc_error_noabort("file '%s' not found", path);
        return -1;
    }
    if (len >= SARMAG && !memcmp(data, ARMAG, SARMAG)) {
        int r = load_archive(path, data, len, 0);
        free(data);
        return r;
    }
    if (len >= (long)sizeof(Elf64_Ehdr) && !memcmp(data, ELFMAG, SELFMAG)) {
        Elf64_Ehdr *eh = (Elf64_Ehdr *)data;
        if (eh->e_type == ET_DYN) {
            free(data);
            return load_dso_syms(path);
        }
        {
            int r = load_object(path, data, len);
            free(data);
            return r;
        }
    }
    ext = strrchr(path, '.');
    if (ext && (!strcmp(ext, ".so") || strstr(path, ".so."))) {
        free(data);
        return load_dso_syms(path);
    }
    free(data);
    tcc_error_noabort("unrecognized file type");
    (void)is_lib_name;
    return -1;
}

static int load_library(const char *libname)
{
    char *path = find_library(libname, S.static_link);
    int r;
    if (!path) {
        tcc_error_noabort("library '%s' not found", libname);
        return -1;
    }
    r = tcc_load_file(path, 1);
    free(path);
    return r;
}

/* check undefined symbols; report errors like the original */
static int check_undefined(void)
{
    int i, n = elf_nb_syms(), ret = 0;
    for (i = 1; i < n; i++) {
        Elf64_Sym *s = elf_sym_ptr(i);
        const char *name;
        if (s->st_shndx != SHN_UNDEF) continue;
        if (ELF64_ST_BIND(s->st_info) == STB_WEAK) continue;
        if (ELF64_ST_BIND(s->st_info) == STB_LOCAL) continue;
        name = elf_sym_name(i);
        if (!*name) continue;
        if (is_dso_sym(name)) continue;
        if (!strcmp(name, "_GLOBAL_OFFSET_TABLE_")) continue;
        tcc_error_noabort("undefined symbol '%s'", name);
        ret = -1;
    }
    return ret;
}

/* ---------------------------------------------------------------- */
/* static executable output */

static int write_static_exe(const char *outfile, int is_run);

static int link_inputs(void)
{
    int i;
    for (i = 0; i < S.files.len; i++) {
        InFile *f = S.files.p[i];
        if (f->type == FT_LIB) {
            load_library(f->name + 2);
        } else if (f->type == FT_OBJ) {
            tcc_load_file(f->name, 0);
        }
    }
    for (i = 0; i < S.pragma_libs.len; i++)
        load_library((char *)S.pragma_libs.p[i] + 2);
    return 0;
}

static int opt_reloc_output(const char *outfile)
{
    return tccelf_output_file(outfile);
}

extern int opt_reloc;

int tcc_link_output(const char *outfile)
{
    int err = 0;
    if (opt_reloc) {
        link_inputs();
        return opt_reloc_output(outfile);
    }
    if (!S.nostdlib) {
        char *p;
        /* crt objects */
        if (S.output_type == OUT_EXE) {
            p = find_crt("crt1.o");
            if (!p) tcc_error_noabort("file 'crt1.o' not found"); else { tcc_load_file(p, 0); free(p); }
        }
        p = find_crt("crti.o");
        if (!p) tcc_error_noabort("file 'crti.o' not found"); else { tcc_load_file(p, 0); free(p); }
    }
    link_inputs();
    if (!S.nostdlib) {
        char *p = find_in_libpaths("libtcc1.a");
        if (!p) {
            tcc_error_noabort("file 'libtcc1.a' not found");
            err = 1;
        } else {
            tcc_load_file(p, 0);
            free(p);
        }
        load_library("c");
        if (S.pthread) load_library("pthread");
        p = find_crt("crtn.o");
        if (!p) tcc_error_noabort("file 'crtn.o' not found"); else { tcc_load_file(p, 0); free(p); }
    }
    if (check_undefined() < 0)
        err = 1;
    if (!S.nostdlib) {
        /* dynamic linking against libc is not supported: the original fails
           here too because libtcc1.a is missing */
        if (!err) {
            tcc_error_noabort("dynamic linking not supported");
            err = 1;
        }
        return 1;
    }
    if (err || S.nb_errors)
        return 1;
    if (S.output_type == OUT_DLL) {
        tcc_error_noabort("shared library output not supported");
        return 1;
    }
    return write_static_exe(outfile, 0);
}

/* run support: not available (needs runtime library) */
int tcc_run_output(int argc, char **argv)
{
    tcc_error_noabort("file 'runmain.o' not found");
    if (!S.nostdlib) {
        link_inputs();
        tcc_error_noabort("file 'libtcc1.a' not found");
        load_library("c");
        check_undefined();
    } else {
        link_inputs();
        check_undefined();
        tcc_error_noabort("_runmain not defined");
    }
    (void)argc; (void)argv;
    return 1;
}

/* ---------------------------------------------------------------- */

typedef struct SecAddr { Section *s; uint64_t addr; long fileoff; } SecAddr;

static int sec_is_exec(Section *s) { return (s->flags & SHF_EXECINSTR) != 0; }
static int sec_is_write(Section *s) { return (s->flags & SHF_WRITE) != 0; }

static int write_static_exe(const char *outfile, int is_run)
{
    uint64_t base = S.has_text_addr ? S.text_addr : 0x400000;
    uint64_t addr;
    long fileoff;
    int i, n = all_sections.len;
    SecAddr *sa = xcalloc(sizeof(SecAddr) * n);
    int entry_idx;
    FILE *f;
    Elf64_Ehdr eh;
    Elf64_Phdr ph[3];
    int nph = 0;
    uint64_t text_start, text_end, data_start, data_end, data_fileend;
    long text_fileoff;
    int ret = 0;
    (void)is_run;

    entry_idx = elf_sym_find(S.entryname ? S.entryname : "_start");
    if (!entry_idx || !elf_sym_is_defined(entry_idx)) {
        tcc_error_noabort("%s not defined", S.entryname ? S.entryname : "_start");
        free(sa);
        return 1;
    }
    /* layout: headers, then exec sections (RX), then page align, RW sections, bss */
    fileoff = sizeof(Elf64_Ehdr) + 3 * sizeof(Elf64_Phdr);
    addr = base + fileoff;
    text_fileoff = sizeof(Elf64_Ehdr);
    text_start = base;
    for (i = 0; i < n; i++) {
        Section *s = all_sections.p[i];
        if (!(s->flags & SHF_ALLOC) || !sec_is_exec(s) || s->type == SHT_NOBITS) continue;
        if (s->size == 0) continue;
        addr = (addr + s->align - 1) & -(uint64_t)s->align;
        fileoff = (fileoff + s->align - 1) & -(long)s->align;
        sa[i].s = s; sa[i].addr = addr; sa[i].fileoff = fileoff;
        addr += s->size; fileoff += s->size;
    }
    /* read-only data in the text segment too */
    for (i = 0; i < n; i++) {
        Section *s = all_sections.p[i];
        if (!(s->flags & SHF_ALLOC) || sec_is_exec(s) || sec_is_write(s) || s->type == SHT_NOBITS) continue;
        if (s->size == 0) continue;
        addr = (addr + s->align - 1) & -(uint64_t)s->align;
        fileoff = (fileoff + s->align - 1) & -(long)s->align;
        sa[i].s = s; sa[i].addr = addr; sa[i].fileoff = fileoff;
        addr += s->size; fileoff += s->size;
    }
    text_end = addr;
    /* RW segment on next page */
    {
        uint64_t pg = 0x1000;
        uint64_t na = (addr + pg - 1) & -pg;
        /* keep file offset congruent mod page */
        fileoff = (fileoff + pg - 1) & -(long)pg;
        addr = na + (fileoff & (pg - 1));
        addr = na;
    }
    data_start = addr;
    for (i = 0; i < n; i++) {
        Section *s = all_sections.p[i];
        if (!(s->flags & SHF_ALLOC) || !sec_is_write(s) || s->type == SHT_NOBITS) continue;
        if (s->size == 0) continue;
        addr = (addr + s->align - 1) & -(uint64_t)s->align;
        fileoff = (fileoff + s->align - 1) & -(long)s->align;
        sa[i].s = s; sa[i].addr = addr; sa[i].fileoff = fileoff;
        addr += s->size; fileoff += s->size;
    }
    data_fileend = addr;
    for (i = 0; i < n; i++) {
        Section *s = all_sections.p[i];
        if (!(s->flags & SHF_ALLOC) || s->type != SHT_NOBITS) continue;
        if (s->size == 0) continue;
        addr = (addr + s->align - 1) & -(uint64_t)s->align;
        sa[i].s = s; sa[i].addr = addr; sa[i].fileoff = -1;
        addr += s->size;
    }
    data_end = addr;
    /* symbol addresses */
    {
        int k, ns = elf_nb_syms();
        for (k = 1; k < ns; k++) {
            Elf64_Sym *s = elf_sym_ptr(k);
            int shndx = s->st_shndx;
            if (shndx == SHN_UNDEF || shndx == SHN_ABS || shndx >= SHN_LORESERVE) continue;
            for (i = 0; i < n; i++) {
                Section *sec = all_sections.p[i];
                if (sec->sh_num == shndx) {
                    if (sa[i].s) s->st_value += sa[i].addr;
                    break;
                }
            }
        }
    }
    /* apply relocations */
    for (i = 0; i < n; i++) {
        Section *r = all_sections.p[i];
        Section *target = NULL;
        int ti, k, nr;
        Elf64_Rela *rel;
        uint64_t taddr;
        if (r->type != SHT_RELA) continue;
        for (ti = 0; ti < n; ti++)
            if (((Section *)all_sections.p[ti])->sh_num == r->is_reloc_of) { target = all_sections.p[ti]; break; }
        if (!target || !sa[ti].s) continue;
        taddr = sa[ti].addr;
        rel = (Elf64_Rela *)r->data;
        nr = r->size / sizeof(Elf64_Rela);
        for (k = 0; k < nr; k++) {
            int sym = ELF64_R_SYM(rel[k].r_info);
            int type = ELF64_R_TYPE(rel[k].r_info);
            Elf64_Sym *s = elf_sym_ptr(sym);
            uint64_t S_ = s->st_value;
            int64_t A = rel[k].r_addend;
            uint64_t P = taddr + rel[k].r_offset;
            unsigned char *p = target->data + rel[k].r_offset;
            if (s->st_shndx == SHN_UNDEF && ELF64_ST_BIND(s->st_info) != STB_WEAK && *elf_sym_name(sym)) {
                /* already reported */
                S_ = 0;
            }
            switch (type) {
            case R_X86_64_64: { uint64_t v = S_ + A; memcpy(p, &v, 8); break; }
            case R_X86_64_32: { uint32_t v = (uint32_t)(S_ + A); memcpy(p, &v, 4); break; }
            case R_X86_64_32S: { int32_t v = (int32_t)(S_ + A); memcpy(p, &v, 4); break; }
            case R_X86_64_PC32:
            case R_X86_64_PLT32: { int32_t v = (int32_t)(S_ + A - P); memcpy(p, &v, 4); break; }
            case R_X86_64_PC64: { int64_t v = (int64_t)(S_ + A - P); memcpy(p, &v, 8); break; }
            case R_X86_64_NONE: break;
            default:
                tcc_error_noabort("unsupported relocation type %d", type);
                ret = 1;
            }
        }
    }
    if (ret) { free(sa); return 1; }
    /* write file */
    memset(&eh, 0, sizeof eh);
    memcpy(eh.e_ident, ELFMAG, SELFMAG);
    eh.e_ident[EI_CLASS] = ELFCLASS64;
    eh.e_ident[EI_DATA] = ELFDATA2LSB;
    eh.e_ident[EI_VERSION] = EV_CURRENT;
    eh.e_type = ET_EXEC;
    eh.e_machine = EM_X86_64;
    eh.e_version = EV_CURRENT;
    eh.e_entry = elf_sym_ptr(entry_idx)->st_value;
    eh.e_phoff = sizeof(Elf64_Ehdr);
    eh.e_ehsize = sizeof(Elf64_Ehdr);
    eh.e_phentsize = sizeof(Elf64_Phdr);
    memset(ph, 0, sizeof ph);
    ph[nph].p_type = PT_LOAD;
    ph[nph].p_flags = PF_R | PF_X;
    ph[nph].p_offset = 0;
    ph[nph].p_vaddr = ph[nph].p_paddr = base;
    ph[nph].p_filesz = text_end - base;
    ph[nph].p_memsz = text_end - base;
    ph[nph].p_align = 0x1000;
    nph++;
    if (data_end > data_start) {
        long dfile = -1;
        for (i = 0; i < n; i++) if (sa[i].s && sa[i].fileoff >= 0 && sa[i].addr >= data_start) { if (dfile < 0 || sa[i].fileoff < dfile) dfile = sa[i].fileoff; }
        if (dfile < 0) dfile = fileoff;
        ph[nph].p_type = PT_LOAD;
        ph[nph].p_flags = PF_R | PF_W;
        ph[nph].p_offset = dfile - (data_start & 0xfff) ;
        ph[nph].p_offset = dfile;
        ph[nph].p_vaddr = ph[nph].p_paddr = data_start;
        ph[nph].p_filesz = data_fileend - data_start;
        ph[nph].p_memsz = data_end - data_start;
        ph[nph].p_align = 0x1000;
        /* vaddr and offset must be congruent modulo page size */
        if ((ph[nph].p_vaddr & 0xfff) != (ph[nph].p_offset & 0xfff)) {
            /* adjust: shift data vaddr to match */
            uint64_t delta = (ph[nph].p_offset & 0xfff);
            /* re-layout is complex; instead place data at vaddr with same page offset */
            (void)delta;
        }
        nph++;
    }
    ph[nph].p_type = PT_GNU_STACK;
    ph[nph].p_flags = PF_R | PF_W;
    ph[nph].p_align = 16;
    nph++;
    eh.e_phnum = nph;
    f = fopen(outfile, "wb");
    if (!f) {
        tcc_error_noabort("could not write '%s'", outfile);
        free(sa);
        return 1;
    }
    fwrite(&eh, 1, sizeof eh, f);
    fwrite(ph, 1, nph * sizeof(Elf64_Phdr), f);
    for (i = 0; i < n; i++) {
        if (!sa[i].s || sa[i].fileoff < 0) continue;
        {
            long pos = ftell(f);
            while (pos < sa[i].fileoff) { fputc(0, f); pos++; }
            fwrite(sa[i].s->data, 1, sa[i].s->size, f);
        }
    }
    fclose(f);
    chmod(outfile, 0755);
    free(sa);
    (void)text_fileoff; (void)text_start;
    return 0;
}
