/* tcc -ar : minimal archiver */
#include "tcc.h"
#include <elf.h>
#include <ar.h>

static void ar_usage(int *ret)
{
    fprintf(stderr, "usage: tcc -ar [crstvx] lib [files]\ncreate library ([abdiopN] not supported).\n");
    *ret = 1;
}

static char *read_all(const char *name, long *plen)
{
    FILE *f = fopen(name, "rb");
    char *d; long n;
    if (!f) return NULL;
    fseek(f, 0, SEEK_END); n = ftell(f); fseek(f, 0, SEEK_SET);
    d = xmalloc(n + 1);
    if (fread(d, 1, n, f) != (size_t)n) { fclose(f); free(d); return NULL; }
    fclose(f);
    d[n] = 0;
    *plen = n;
    return d;
}

static void put_be32(unsigned char *p, uint32_t v)
{
    p[0] = v >> 24; p[1] = v >> 16; p[2] = v >> 8; p[3] = v;
}

static int list_archive(const char *libname, int verbose)
{
    long len, pos;
    char *data = read_all(libname, &len);
    char *longnames = NULL;
    if (!data) {
        fprintf(stderr, "tcc: ar: can't open file %s\n", libname);
        return 2;
    }
    if (len < SARMAG || memcmp(data, ARMAG, SARMAG)) {
        fprintf(stderr, "tcc: ar: not an archive %s\n", libname);
        free(data);
        return 2;
    }
    pos = SARMAG;
    while (pos + (long)sizeof(struct ar_hdr) <= len) {
        struct ar_hdr *h = (struct ar_hdr *)(data + pos);
        long size = atol(h->ar_size);
        char name[256];
        int i;
        if (h->ar_name[0] == '/' && h->ar_name[1] == '/') longnames = data + pos + sizeof(struct ar_hdr);
        else if (h->ar_name[0] == '/' && (h->ar_name[1] == ' ' || h->ar_name[1] == 'S')) ;
        else {
            if (h->ar_name[0] == '/' && longnames) {
                char *p = longnames + atol(h->ar_name + 1);
                for (i = 0; i < 255 && p[i] && p[i] != '/' && p[i] != '\n'; i++) name[i] = p[i];
                name[i] = 0;
            } else {
                for (i = 0; i < 16 && h->ar_name[i] && h->ar_name[i] != '/' && h->ar_name[i] != ' '; i++) name[i] = h->ar_name[i];
                name[i] = 0;
            }
            if (verbose)
                printf("%s %ld\n", name, size);
            else
                printf("%s\n", name);
        }
        pos += sizeof(struct ar_hdr) + size;
        if (pos & 1) pos++;
    }
    free(data);
    return 0;
}

static int extract_archive(const char *libname, int verbose)
{
    long len, pos;
    char *data = read_all(libname, &len);
    char *longnames = NULL;
    if (!data) {
        fprintf(stderr, "tcc: ar: can't open file %s\n", libname);
        return 2;
    }
    pos = SARMAG;
    while (pos + (long)sizeof(struct ar_hdr) <= len) {
        struct ar_hdr *h = (struct ar_hdr *)(data + pos);
        long size = atol(h->ar_size);
        char name[256];
        int i;
        if (h->ar_name[0] == '/' && h->ar_name[1] == '/') longnames = data + pos + sizeof(struct ar_hdr);
        else if (h->ar_name[0] == '/' && (h->ar_name[1] == ' ' || h->ar_name[1] == 'S')) ;
        else {
            FILE *f;
            if (h->ar_name[0] == '/' && longnames) {
                char *p = longnames + atol(h->ar_name + 1);
                for (i = 0; i < 255 && p[i] && p[i] != '/' && p[i] != '\n'; i++) name[i] = p[i];
                name[i] = 0;
            } else {
                for (i = 0; i < 16 && h->ar_name[i] && h->ar_name[i] != '/' && h->ar_name[i] != ' '; i++) name[i] = h->ar_name[i];
                name[i] = 0;
            }
            if (verbose) printf("x - %s\n", name);
            f = fopen(name, "wb");
            if (f) {
                fwrite(data + pos + sizeof(struct ar_hdr), 1, size, f);
                fclose(f);
            }
        }
        pos += sizeof(struct ar_hdr) + size;
        if (pos & 1) pos++;
    }
