    return 0;
}

int tcc_tool_ar(int argc, char **argv)
{
    int ret = 0;
    const char *ops;
    const char *libname;
    int i, do_create = 0, do_list = 0, do_extract = 0, verbose = 0, symtab = 1;
    CStr out, symnames, longnames;
    int nsyms = 0;
    uint32_t *symoffs = NULL;
    int nsymoffs = 0;
    long *member_off;
    int nmembers = 0;
    FILE *f;

    if (argc < 1) { ar_usage(&ret); return ret; }
    ops = argv[0];
    if (ops[0] == '-') ops++;
    for (i = 0; ops[i]; i++) {
        switch (ops[i]) {
        case 'c': do_create = 1; break;
        case 'r': do_create = 1; break;
        case 's': symtab = 1; break;
        case 'S': symtab = 0; break;
        case 't': do_list = 1; break;
        case 'v': verbose = 1; break;
        case 'x': do_extract = 1; break;
        default: ar_usage(&ret); return ret;
        }
    }
    if (argc < 2) { ar_usage(&ret); return ret; }
    libname = argv[1];
    if (do_list) return list_archive(libname, verbose);
    if (do_extract) return extract_archive(libname, verbose);
    if (!do_create) { ar_usage(&ret); return ret; }
    if (argc < 3) { ar_usage(&ret); return ret; }

    cstr_init(&out);
    cstr_init(&symnames);
    cstr_init(&longnames);
    member_off = xcalloc(sizeof(long) * argc);
    /* first pass: build members into 'out' (without the symbol table), collecting symbols */
    for (i = 2; i < argc; i++) {
        long len;
        char *data = read_all(argv[i], &len);
        struct ar_hdr h;
        const char *base;
        char namebuf[32];
        if (!data) {
            fprintf(stderr, "tcc: ar: can't open file %s\n", argv[i]);
            return 2;
        }
        base = strrchr(argv[i], '/');
        base = base ? base + 1 : argv[i];
        member_off[nmembers++] = out.len;
        memset(&h, ' ', sizeof h);
        if (strlen(base) >= 16) {
            snprintf(namebuf, sizeof namebuf, "/%d", longnames.len);
            cstr_cat(&longnames, base, -1);
            cstr_cat(&longnames, "/\n", 2);
        } else
            snprintf(namebuf, sizeof namebuf, "%s/", base);
        memcpy(h.ar_name, namebuf, strlen(namebuf));
        {
            char tmp[64];
            snprintf(tmp, sizeof tmp, "%-12d", 0); memcpy(h.ar_date, tmp, 12);
            snprintf(tmp, sizeof tmp, "%-6d", 0); memcpy(h.ar_uid, tmp, 6);
            snprintf(tmp, sizeof tmp, "%-6d", 0); memcpy(h.ar_gid, tmp, 6);
            snprintf(tmp, sizeof tmp, "%-8o", 0644); memcpy(h.ar_mode, tmp, 8);
            snprintf(tmp, sizeof tmp, "%-10ld", len); memcpy(h.ar_size, tmp, 10);
        }
        memcpy(h.ar_fmag, ARFMAG, 2);
        cstr_cat(&out, (char *)&h, sizeof h);
        cstr_cat(&out, data, len);
        if (len & 1) cstr_ccat(&out, '\n');
        /* collect global defined symbols */
        if (len >= (long)sizeof(Elf64_Ehdr) && !memcmp(data, ELFMAG, SELFMAG)) {
            Elf64_Ehdr *eh = (Elf64_Ehdr *)data;
            Elf64_Shdr *sh = (Elf64_Shdr *)(data + eh->e_shoff);
            int s;
            for (s = 0; s < eh->e_shnum; s++) {
                if (sh[s].sh_type == SHT_SYMTAB) {
                    Elf64_Sym *syms = (Elf64_Sym *)(data + sh[s].sh_offset);
                    int n = sh[s].sh_size / sizeof(Elf64_Sym), k;
                    const char *str = data + sh[sh[s].sh_link].sh_offset;
                    for (k = 1; k < n; k++) {
                        int bind = ELF64_ST_BIND(syms[k].st_info);
                        if (bind != STB_GLOBAL && bind != STB_WEAK) continue;
                        if (syms[k].st_shndx == SHN_UNDEF) continue;
                        if (ELF64_ST_TYPE(syms[k].st_info) == STT_SECTION || ELF64_ST_TYPE(syms[k].st_info) == STT_FILE) continue;
                        symoffs = xrealloc(symoffs, (nsymoffs + 1) * sizeof(uint32_t));
                        symoffs[nsymoffs++] = nmembers - 1;
                        cstr_cat(&symnames, str + syms[k].st_name, -1);
                        cstr_ccat(&symnames, 0);
                        nsyms++;
                    }
                }
            }
        }
        free(data);
    }
    f = fopen(libname, "wb");
    if (!f) {
        fprintf(stderr, "tcc: ar: can't create file %s\n", libname);
        return 2;
    }
    fwrite(ARMAG, 1, SARMAG, f);
    {
        long header_total = SARMAG;
        long symtab_size = 0, longnames_size = 0;
        if (symtab) {
            symtab_size = 4 + 4 * nsyms + symnames.len;
            if (symtab_size & 1) symtab_size++;
            header_total += sizeof(struct ar_hdr) + symtab_size;
        }
        if (longnames.len) {
            longnames_size = longnames.len;
            if (longnames_size & 1) longnames_size++;
            header_total += sizeof(struct ar_hdr) + longnames_size;
        }
        if (symtab) {
            struct ar_hdr h;
            unsigned char *buf = xcalloc(symtab_size);
            char tmp[64];
            int k;
            memset(&h, ' ', sizeof h);
            memcpy(h.ar_name, "/", 1);
            snprintf(tmp, sizeof tmp, "%-12d", 0); memcpy(h.ar_date, tmp, 12);
            snprintf(tmp, sizeof tmp, "%-6d", 0); memcpy(h.ar_uid, tmp, 6);
            snprintf(tmp, sizeof tmp, "%-6d", 0); memcpy(h.ar_gid, tmp, 6);
            snprintf(tmp, sizeof tmp, "%-8d", 0); memcpy(h.ar_mode, tmp, 8);
            snprintf(tmp, sizeof tmp, "%-10ld", (long)(4 + 4 * nsyms + symnames.len)); memcpy(h.ar_size, tmp, 10);
            memcpy(h.ar_fmag, ARFMAG, 2);
            fwrite(&h, 1, sizeof h, f);
            put_be32(buf, nsyms);
            for (k = 0; k < nsyms; k++)
                put_be32(buf + 4 + 4 * k, (uint32_t)(header_total + member_off[symoffs[k]]));
            if (symnames.len) memcpy(buf + 4 + 4 * nsyms, symnames.data, symnames.len);
            fwrite(buf, 1, symtab_size, f);
            free(buf);
        }
        if (longnames.len) {
            struct ar_hdr h;
            char tmp[64];
            memset(&h, ' ', sizeof h);
            memcpy(h.ar_name, "//", 2);
            snprintf(tmp, sizeof tmp, "%-12d", 0); memcpy(h.ar_date, tmp, 12);
            snprintf(tmp, sizeof tmp, "%-6d", 0); memcpy(h.ar_uid, tmp, 6);
            snprintf(tmp, sizeof tmp, "%-6d", 0); memcpy(h.ar_gid, tmp, 6);
            snprintf(tmp, sizeof tmp, "%-8d", 0); memcpy(h.ar_mode, tmp, 8);
            snprintf(tmp, sizeof tmp, "%-10ld", longnames_size); memcpy(h.ar_size, tmp, 10);
            memcpy(h.ar_fmag, ARFMAG, 2);
            fwrite(&h, 1, sizeof h, f);
            fwrite(longnames.data, 1, longnames.len, f);
            if (longnames.len & 1) fputc('\n', f);
        }
    }
    fwrite(out.data, 1, out.len, f);
    fclose(f);
    if (verbose) {
        for (i = 2; i < argc; i++) printf("a - %s\n", argv[i]);
    }
    return 0;
}
