    for (;;) {
        skip_ws();
        if ((*asm_p >= '0' && *asm_p <= '9') || *asm_p == '-' || *asm_p == '+') {
            if ((*asm_p == '-' || *asm_p == '+') && !(asm_p[1] >= '0' && asm_p[1] <= '9') && !is_idch(asm_p[1])) {
