cd /workspace/src && cat > asm.c <<'EOF'
/* minimal x86-64 AT&T syntax assembler for inline asm */
#include "cc.h"
#include <elf.h>

/* interface provided by gen.c */
void asm_emit_byte(int b);
long asm_ind(void);
void asm_reloc_sym(long off, int type, const char *symname, long addend);
void asm_patch32(long off, int32_t v);
void asm_define_label_sym(const char *name, int is_global);

typedef struct AOp {
    int kind;        /* 0 none, 1 reg, 2 imm, 3 mem, 4 symbol (jump target) */
    int reg;         /* register number; size in rsize */
    int rsize;       /* 1,2,4,8 ; 16 for xmm (reg = xmm index) */
    int64_t imm;
    const char *sym; /* symbol for imm/mem/jump */
    int base, index, scale;  /* mem: base/index reg numbers or -1 ; rip = 16 */
    int64_t disp;
    int indirect;    /* '*' prefix for jmp/call */
    int is_xmm;
} AOp;

static const char *asm_p;      /* current position in asm text */
static const char *asm_start;
static int asm_err_line;

typedef struct ALabel { char name[64]; long pos; int defined; } ALabel;
static ALabel *alabels;
static int nalabels, alabels_cap;
typedef struct AFix { long pos; char name[64]; int is_rel32; } AFix;
static AFix *afix;
static int nafix, afix_cap;

static void aerror(const char *msg)
{
    tcc_error("%s", msg);
}

static void skip_ws(void)
{
    while (*asm_p == ' ' || *asm_p == '\t')
        asm_p++;
}

static int is_idch(int c) { return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '.' || c == '$' || c == '@'; }

static int parse_ident(char *buf, int sz)
{
    int n = 0;
    skip_ws();
    while (is_idch(*asm_p) && n < sz - 1)
        buf[n++] = *asm_p++;
    buf[n] = 0;
    return n;
}

/* register name -> number and size */
static int reg_lookup(const char *s, int *size)
{
    static const char *r64[] = { "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi", "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15" };
    static const char *r32[] = { "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi", "r8d", "r9d", "r10d", "r11d", "r12d", "r13d", "r14d", "r15d" };
    static const char *r16[] = { "ax", "cx", "dx", "bx", "sp", "bp", "si", "di", "r8w", "r9w", "r10w", "r11w", "r12w", "r13w", "r14w", "r15w" };
    static const char *r8[] = { "al", "cl", "dl", "bl", "spl", "bpl", "sil", "dil", "r8b", "r9b", "r10b", "r11b", "r12b", "r13b", "r14b", "r15b" };
    int i;
    for (i = 0; i < 16; i++) {
        if (!strcmp(s, r64[i])) { *size = 8; return i; }
        if (!strcmp(s, r32[i])) { *size = 4; return i; }
        if (!strcmp(s, r16[i])) { *size = 2; return i; }
        if (!strcmp(s, r8[i])) { *size = 1; return i; }
    }
    if (!strcmp(s, "ah")) { *size = 1; return 20; }
    if (!strcmp(s, "ch")) { *size = 1; return 21; }
    if (!strcmp(s, "dh")) { *size = 1; return 22; }
    if (!strcmp(s, "bh")) { *size = 1; return 23; }
    if (!strcmp(s, "rip")) { *size = 8; return 16; }
    if (s[0] == 'x' && s[1] == 'm' && s[2] == 'm') { *size = 16; return atoi(s + 3); }
    return -1;
}

const char *asm_reg_name(int reg, int size)
{
    static const char *r64[] = { "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi", "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15" };
    static const char *r32[] = { "eax", "ecx", "edx", "ebx", "esp", "ebp", "esi", "edi", "r8d", "r9d", "r10d", "r11d", "r12d", "r13d", "r14d", "r15d" };
    static const char *r16[] = { "ax", "cx", "dx", "bx", "sp", "bp", "si", "di", "r8w", "r9w", "r10w", "r11w", "r12w", "r13w", "r14w", "r15w" };
    static const char *r8[] = { "al", "cl", "dl", "bl", "spl", "bpl", "sil", "dil", "r8b", "r9b", "r10b", "r11b", "r12b", "r13b", "r14b", "r15b" };
    switch (size) {
    case 1: return r8[reg];
    case 2: return r16[reg];
    case 4: return r32[reg];
    default: return r64[reg];
    }
}

static int64_t parse_number_str(const char **pp)
{
    const char *p = *pp;
    int64_t v;
    int neg = 0;
    if (*p == '-') { neg = 1; p++; }
    else if (*p == '+') p++;
    if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) v = strtoull(p + 2, (char **)&p, 16);
    else if (p[0] == '0' && p[1] >= '0' && p[1] <= '7') v = strtoull(p + 1, (char **)&p, 8);
    else if (p[0] == '0' && (p[1] == 'b' || p[1] == 'B')) v = strtoull(p + 2, (char **)&p, 2);
    else v = strtoull(p, (char **)&p, 10);
    *pp = p;
    return neg ? -v : v;
}

/* parse an expression: number, symbol, with + - */
static void parse_expr_sym(int64_t *val, const char **sym)
{
    int64_t v = 0;
    *sym = NULL;
    skip_ws();
    for (;;) {
        skip_ws();
        if ((*asm_p >= '0' && *asm_p <= '9') || *asm_p == '-' || *asm_p == '+') {
            if ((*asm_p == '-' || *asm_p == '+') && !(asm_p[1] >= '0' && asm_p[1] <= '9') && !is_idch(asm_p[1])) {
                break;
            }
            if (*asm_p == '+' && !(asm_p[1] >= '0' && asm_p[1] <= '9')) { asm_p++; continue; }
            if (*asm_p == '-' && !(asm_p[1] >= '0' && asm_p[1] <= '9')) {
                /* -symbol: unsupported, treat as 0 */
                asm_p++;
                continue;
            }
            v += parse_number_str(&asm_p);
        } else if (is_idch(*asm_p)) {
            char buf[128];
            parse_ident(buf, sizeof buf);
            if (*sym) aerror("invalid expression in asm");
            *sym = intern(buf, -1);
        } else if (*asm_p == '(') {
            int64_t v2; const char *s2;
            asm_p++;
            parse_expr_sym(&v2, &s2);
            skip_ws();
            if (*asm_p != ')') aerror("')' expected in asm");
            asm_p++;
            v += v2;
            if (s2) *sym = s2;
        } else
            break;
        skip_ws();
        if (*asm_p == '+' || *asm_p == '-') {
            if (*asm_p == '+') asm_p++;
            continue;
        }
        if (*asm_p == '*') {
            int64_t m;
            asm_p++;
            skip_ws();
            m = parse_number_str(&asm_p);
            v *= m;
            continue;
        }
        break;
    }
    *val = v;
}

static void parse_operand(AOp *op)
{
    memset(op, 0, sizeof *op);
    op->base = op->index = -1;
    skip_ws();
    if (*asm_p == '*') {
        op->indirect = 1;
        asm_p++;
        skip_ws();
    }
    if (*asm_p == '%') {
        char buf[32];
        int size;
        asm_p++;
        parse_ident(buf, sizeof buf);
        op->reg = reg_lookup(buf, &size);
        if (op->reg < 0) aerror("unknown register in asm");
        op->rsize = size;
        op->kind = 1;
        if (size == 16) op->is_xmm = 1;
        /* segment prefix like %fs:...? unsupported */
        return;
    }
    if (*asm_p == '$') {
        asm_p++;
        parse_expr_sym(&op->imm, &op->sym);
        op->kind = 2;
        return;
    }
    /* memory or symbol: [disp][(base,index,scale)] */
    if (*asm_p != '(') {
        parse_expr_sym(&op->disp, &op->sym);
    }
    skip_ws();
    if (*asm_p == '(') {
        char buf[32];
        int size;
        asm_p++;
        skip_ws();
        if (*asm_p == '%') {
            asm_p++;
            parse_ident(buf, sizeof buf);
            op->base = reg_lookup(buf, &size);
            if (op->base < 0) aerror("unknown register in asm");
        }
        skip_ws();
        if (*asm_p == ',') {
            asm_p++;
            skip_ws();
            if (*asm_p == '%') {
                asm_p++;
                parse_ident(buf, sizeof buf);
                op->index = reg_lookup(buf, &size);
                if (op->index < 0) aerror("unknown register in asm");
            }
            skip_ws();
            op->scale = 1;
            if (*asm_p == ',') {
                asm_p++;
                skip_ws();
                op->scale = (int)parse_number_str(&asm_p);
            }
        }
        skip_ws();
        if (*asm_p != ')') aerror("')' expected in asm");
        asm_p++;
        op->kind = 3;
        return;
    }
    /* bare symbol/number: memory operand (absolute) or jump target */
    op->kind = 4;
}

/* ---------------------------------------------------------------- */
/* encoding */

static void ob(int b) { asm_emit_byte(b & 0xff); }
static void o32v(uint32_t v) { ob(v); ob(v >> 8); ob(v >> 16); ob(v >> 24); }
static void o64v(uint64_t v) { o32v((uint32_t)v); o32v((uint32_t)(v >> 32)); }

static void emit_rex(int w, int reg, int index, int base, int force)
{
    int r = 0x40 | (w ? 8 : 0) | (((reg >> 3) & 1) << 2) | (((index >> 3) & 1) << 1) | ((base >> 3) & 1);
    if (r != 0x40 || force) ob(r);
}

static int needs_rex8(int reg) { return reg >= 4 && reg < 8; } /* spl, bpl, sil, dil */

/* emit modrm (+sib, disp) for operand op with reg field 'reg' */
static void emit_modrm(int reg, AOp *op)
{
    if (op->kind == 1) {
        ob(0xc0 | ((reg & 7) << 3) | (op->reg & 7));
        return;
    }
    if (op->kind == 4 || (op->kind == 3 && op->base < 0 && op->index < 0)) {
        /* absolute/symbol: use RIP-relative for symbols, disp32 absolute otherwise */
        if (op->sym) {
            ob(((reg & 7) << 3) | 5);
            asm_reloc_sym(asm_ind(), R_X86_64_PC32, op->sym, op->disp - 4);
            o32v(0);
        } else {
            ob(((reg & 7) << 3) | 4);
            ob(0x25);
            o32v((uint32_t)op->disp);
        }
        return;
    }
    if (op->base == 16) {
        /* rip relative */
        ob(((reg & 7) << 3) | 5);
        if (op->sym) {
            asm_reloc_sym(asm_ind(), R_X86_64_PC32, op->sym, op->disp - 4);
            o32v(0);
        } else
            o32v((uint32_t)op->disp);
        return;
    }
    {
        int base = op->base, index = op->index;
        int mod;
        int64_t disp = op->disp;
        int need_sib = index >= 0 || (base & 7) == 4 || base < 0;
        if (op->sym) aerror("symbol with base register not supported in asm");
        if (base < 0) {
            /* index only: disp32 with no base */
            ob(((reg & 7) << 3) | 4);
            {
                int ss = op->scale == 8 ? 3 : op->scale == 4 ? 2 : op->scale == 2 ? 1 : 0;
                ob((ss << 6) | ((index & 7) << 3) | 5);
            }
            o32v((uint32_t)disp);
            return;
        }
        if (disp == 0 && (base & 7) != 5) mod = 0;
        else if (disp >= -128 && disp <= 127) mod = 1;
        else mod = 2;
        ob((mod << 6) | ((reg & 7) << 3) | (need_sib ? 4 : (base & 7)));
        if (need_sib) {
            int ss = op->scale == 8 ? 3 : op->scale == 4 ? 2 : op->scale == 2 ? 1 : 0;
            ob((ss << 6) | ((index >= 0 ? index & 7 : 4) << 3) | (base & 7));
        }
        if (mod == 1) ob(disp & 0xff);
        else if (mod == 2) o32v((uint32_t)disp);
    }
}

static int rex_bits_for(AOp *op)
{
    /* returns index/base high bits as encoded in emit_rex args */
    (void)op;
    return 0;
}

/* operand size from suffix or register operands */
static int op_size(AOp *ops, int n, int suffix)
{
    int i;
    if (suffix == 'b') return 1;
    if (suffix == 'w') return 2;
    if (suffix == 'l') return 4;
    if (suffix == 'q') return 8;
    for (i = 0; i < n; i++)
        if (ops[i].kind == 1 && !ops[i].is_xmm) return ops[i].rsize;
    return 0;
}

/* generic emission of an instruction with reg/mem operands:
   opcode for size (uses 0x66 prefix for 16-bit, REX.W for 64) */
static void emit_prefix_rex(int size, int reg, AOp *mem, int force_rex)
{
    int base = mem->kind == 1 ? mem->reg : (mem->base >= 0 && mem->base != 16 ? mem->base : 0);
    int index = mem->kind == 3 && mem->index >= 0 ? mem->index : 0;
    if (size == 2) ob(0x66);
    emit_rex(size == 8, reg, index, base, force_rex);
}

static int alu_index(const char *m)
{
    static const char *names[] = { "add", "or", "adc", "sbb", "and", "sub", "xor", "cmp" };
    int i;
    for (i = 0; i < 8; i++) if (!strcmp(m, names[i])) return i;
    return -1;
}

static int cc_index(const char *s)
{
    static const char *cc[] = { "o", "no", "b", "ae", "e", "ne", "be", "a", "s", "ns", "p", "np", "l", "ge", "le", "g" };
    static const char *alt[] = { "", "", "c,nae", "nb,nc", "z", "nz", "na", "nbe", "", "", "pe", "po", "nge", "nl", "ng", "nle" };
    int i;
    for (i = 0; i < 16; i++) {
        if (!strcmp(s, cc[i])) return i;
        if (alt[i][0]) {
            const char *a = alt[i];
            while (*a) {
                const char *e = strchr(a, ',');
                int len = e ? (int)(e - a) : (int)strlen(a);
                if ((int)strlen(s) == len && !strncmp(s, a, len)) return i;
                if (!e) break;
                a = e + 1;
            }
        }
    }
    return -1;
}

static void add_label(const char *name, long pos)
{
    int i;
    for (i = 0; i < nalabels; i++)
        if (!strcmp(alabels[i].name, name)) {
            if (alabels[i].defined) aerror("duplicate label in asm");
            alabels[i].pos = pos; alabels[i].defined = 1;
            return;
        }
    if (nalabels >= alabels_cap) { alabels_cap = alabels_cap ? alabels_cap * 2 : 16; alabels = xrealloc(alabels, alabels_cap * sizeof(ALabel)); }
    snprintf(alabels[nalabels].name, 64, "%s", name);
    alabels[nalabels].pos = pos;
    alabels[nalabels].defined = 1;
    nalabels++;
}

static int find_label(const char *name, long *pos)
{
    int i;
    for (i = 0; i < nalabels; i++)
        if (!strcmp(alabels[i].name, name) && alabels[i].defined) { *pos = alabels[i].pos; return 1; }
    return 0;
}

static void add_fix(long pos, const char *name)
{
    if (nafix >= afix_cap) { afix_cap = afix_cap ? afix_cap * 2 : 16; afix = xrealloc(afix, afix_cap * sizeof(AFix)); }
    afix[nafix].pos = pos;
    snprintf(afix[nafix].name, 64, "%s", name);
    nafix++;
}

/* numeric local labels: "1:" and refs "1b"/"1f" */
static int numeric_counter[10];

/* emit a jump/call displacement to a symbol or label */
static void emit_rel32_target(const char *sym, int is_call)
{
    long pos;
    char buf[80];
    const char *target = sym;
    int len = strlen(sym);
    /* numeric label refs: digits followed by b/f */
    if (len >= 2 && sym[len - 1] == 'b' || len >= 2 && sym[len - 1] == 'f') {
        int alldig = 1, i;
        for (i = 0; i < len - 1; i++) if (sym[i] < '0' || sym[i] > '9') alldig = 0;
        if (alldig) {
            int n = atoi(sym);
            int cnt = numeric_counter[n % 10];
            if (sym[len - 1] == 'b') snprintf(buf, sizeof buf, ".L%d.%d", n, cnt);
            else snprintf(buf, sizeof buf, ".L%d.%d", n, cnt + 1);
            target = buf;
        }
    }
    if (find_label(target, &pos)) {
        int32_t rel = (int32_t)(pos - (asm_ind() + 4));
        o32v((uint32_t)rel);
        return;
    }
    if (target[0] == '.' || (target != sym)) {
        /* forward local label */
        add_fix(asm_ind(), target);
        o32v(0);
        return;
    }
    /* external symbol */
    asm_reloc_sym(asm_ind(), is_call ? R_X86_64_PLT32 : R_X86_64_PC32, target, -4);
    o32v(0);
    (void)pos;
}

static void resolve_asm_fixups(void)
{
    int i;
    for (i = 0; i < nafix; i++) {
        long pos;
        if (!find_label(afix[i].name, &pos))
            tcc_error("undefined label '%s' in asm", afix[i].name);
        asm_patch32(afix[i].pos, (int32_t)(pos - (afix[i].pos + 4)));
    }
    nafix = 0;
}

static void emit_imm(int size, int64_t v)
{
    switch (size) {
    case 1: ob(v); break;
    case 2: ob(v); ob(v >> 8); break;
    case 4: o32v((uint32_t)v); break;
    default: o32v((uint32_t)v); break;
    }
}

static int fits8(int64_t v) { return v >= -128 && v <= 127; }

static void emit_imm_or_sym(int size, AOp *op)
{
    if (op->sym) {
        if (size == 8 || size == 4) {
            asm_reloc_sym(asm_ind(), R_X86_64_32S, op->sym, op->imm);
            o32v(0);
        } else
            aerror("symbol immediate size unsupported");
        return;
    }
    emit_imm(size, op->imm);
}

/* assemble one instruction with mnemonic m and operands ops[0..n) in AT&T order (src, dst) */
static void assemble_insn(const char *mn, AOp *ops, int n)
{
    char base[32];
    int suffix = 0, size, len, ai;
    AOp *src = &ops[0], *dst = &ops[n - 1];

    snprintf(base, sizeof base, "%s", mn);
    len = strlen(base);
    /* special mnemonics without suffix handling */
    if (!strcmp(mn, "syscall")) { ob(0x0f); ob(0x05); return; }
    if (!strcmp(mn, "ret") || !strcmp(mn, "retq")) { if (n) { ob(0xc2); emit_imm(2, ops[0].imm); } else ob(0xc3); return; }
    if (!strcmp(mn, "leave") || !strcmp(mn, "leaveq")) { ob(0xc9); return; }
    if (!strcmp(mn, "nop")) { ob(0x90); return; }
    if (!strcmp(mn, "hlt")) { ob(0xf4); return; }
    if (!strcmp(mn, "pause")) { ob(0xf3); ob(0x90); return; }
    if (!strcmp(mn, "cpuid")) { ob(0x0f); ob(0xa2); return; }
    if (!strcmp(mn, "rdtsc")) { ob(0x0f); ob(0x31); return; }
    if (!strcmp(mn, "ud2")) { ob(0x0f); ob(0x0b); return; }
    if (!strcmp(mn, "int3")) { ob(0xcc); return; }
    if (!strcmp(mn, "int")) { ob(0xcd); emit_imm(1, ops[0].imm); return; }
    if (!strcmp(mn, "cltq")) { ob(0x48); ob(0x98); return; }
    if (!strcmp(mn, "cqto") || !strcmp(mn, "cqo")) { ob(0x48); ob(0x99); return; }
    if (!strcmp(mn, "cltd") || !strcmp(mn, "cdq")) { ob(0x99); return; }
    if (!strcmp(mn, "cwtl") || !strcmp(mn, "cwde")) { ob(0x98); return; }
    if (!strcmp(mn, "cwtd") || !strcmp(mn, "cwd")) { ob(0x66); ob(0x99); return; }
    if (!strcmp(mn, "mfence")) { ob(0x0f); ob(0xae); ob(0xf0); return; }
    if (!strcmp(mn, "lfence")) { ob(0x0f); ob(0xae); ob(0xe8); return; }
    if (!strcmp(mn, "sfence")) { ob(0x0f); ob(0xae); ob(0xf8); return; }
    if (!strcmp(mn, "lock")) { ob(0xf0); return; }
    if (!strcmp(mn, "rep") || !strcmp(mn, "repe") || !strcmp(mn, "repz")) { ob(0xf3); return; }
    if (!strcmp(mn, "repne") || !strcmp(mn, "repnz")) { ob(0xf2); return; }
    if (!strncmp(mn, "movs", 4) && (len == 5 || len == 4) && n == 0) {
        suffix = len == 5 ? mn[4] : 'l';
        if (suffix == 'q') ob(0x48); if (suffix == 'w') ob(0x66);
        ob(suffix == 'b' ? 0xa4 : 0xa5); return;
    }
    if (!strncmp(mn, "stos", 4) && (len == 5 || len == 4) && n == 0) {
        suffix = len == 5 ? mn[4] : 'l';
        if (suffix == 'q') ob(0x48); if (suffix == 'w') ob(0x66);
        ob(suffix == 'b' ? 0xaa : 0xab); return;
    }
    if (!strncmp(mn, "cmps", 4) && (len == 5 || len == 4) && n == 0) {
        suffix = len == 5 ? mn[4] : 'l';
        if (suffix == 'q') ob(0x48); if (suffix == 'w') ob(0x66);
        ob(suffix == 'b' ? 0xa6 : 0xa7); return;
    }
    if (!strncmp(mn, "scas", 4) && (len == 5 || len == 4) && n == 0) {
        suffix = len == 5 ? mn[4] : 'l';
        if (suffix == 'q') ob(0x48); if (suffix == 'w') ob(0x66);
        ob(suffix == 'b' ? 0xae : 0xaf); return;
    }
    if (!strncmp(mn, "lods", 4) && (len == 5 || len == 4) && n == 0) {
        suffix = len == 5 ? mn[4] : 'l';
        if (suffix == 'q') ob(0x48); if (suffix == 'w') ob(0x66);
        ob(suffix == 'b' ? 0xac : 0xad); return;
    }
    /* jumps */
    if (mn[0] == 'j') {
        if (!strcmp(mn, "jmp") || !strcmp(mn, "jmpq")) {
            if (n != 1) aerror("jmp needs one operand");
            if (ops[0].indirect || ops[0].kind == 1 || ops[0].kind == 3) {
                emit_prefix_rex(4, 0, &ops[0], 0);
                ob(0xff);
                emit_modrm(4, &ops[0]);
                return;
            }
            ob(0xe9);
            emit_rel32_target(ops[0].sym ? ops[0].sym : "", 0);
            return;
        }
        {
            int cc = cc_index(mn + 1);
            if (cc < 0) aerror("unknown instruction in asm");
            ob(0x0f); ob(0x80 | cc);
            emit_rel32_target(ops[0].sym ? ops[0].sym : "", 0);
            return;
        }
    }
    if (!strcmp(mn, "call") || !strcmp(mn, "callq")) {
        if (ops[0].indirect || ops[0].kind == 1 || ops[0].kind == 3) {
            emit_prefix_rex(4, 0, &ops[0], 0);
            ob(0xff);
            emit_modrm(2, &ops[0]);
            return;
        }
        ob(0xe8);
        emit_rel32_target(ops[0].sym ? ops[0].sym : "", 1);
        return;
    }
    /* setcc */
    if (!strncmp(mn, "set", 3)) {
        int cc = cc_index(mn + 3);
        if (cc < 0) aerror("unknown instruction in asm");
        emit_prefix_rex(1, 0, &ops[0], ops[0].kind == 1 && needs_rex8(ops[0].reg));
        ob(0x0f); ob(0x90 | cc);
        emit_modrm(0, &ops[0]);
        return;
    }
    /* cmovcc */
    if (!strncmp(mn, "cmov", 4)) {
        int cc;
        char ccs[8];
        snprintf(ccs, sizeof ccs, "%s", mn + 4);
        {
            int l2 = strlen(ccs);
            if (l2 > 1 && (ccs[l2 - 1] == 'l' || ccs[l2 - 1] == 'q' || ccs[l2 - 1] == 'w') && cc_index(ccs) < 0) { suffix = ccs[l2 - 1]; ccs[l2 - 1] = 0; }
        }
        cc = cc_index(ccs);
        if (cc < 0) aerror("unknown instruction in asm");
        size = op_size(ops, n, suffix);
        emit_prefix_rex(size, dst->reg, src, 0);
        ob(0x0f); ob(0x40 | cc);
        emit_modrm(dst->reg, src);
        return;
    }
    /* movzx / movsx: movzbl, movzbw, movzwl, movsbl, movsbq, movswl, movswq, movzbq, movzwq, movslq */
    if ((!strncmp(mn, "movz", 4) || !strncmp(mn, "movs", 4)) && len == 6) {
        int sz_from = mn[4] == 'b' ? 1 : mn[4] == 'w' ? 2 : mn[4] == 'l' ? 4 : 0;
        int sz_to = mn[5] == 'w' ? 2 : mn[5] == 'l' ? 4 : mn[5] == 'q' ? 8 : 0;
        int zero = mn[3] == 'z';
        if (!sz_from || !sz_to) aerror("unknown instruction in asm");
        if (sz_from == 4) {
            /* movslq */
            emit_prefix_rex(8, dst->reg, src, 0);
            ob(0x63);
            emit_modrm(dst->reg, src);
            return;
        }
        emit_prefix_rex(sz_to, dst->reg, src, src->kind == 1 && sz_from == 1 && needs_rex8(src->reg));
        ob(0x0f);
        ob((zero ? 0xb6 : 0xbe) | (sz_from == 2 ? 1 : 0));
        emit_modrm(dst->reg, src);
        return;
    }
    if (!strcmp(mn, "movslq") || !strcmp(mn, "movsxd")) {
        emit_prefix_rex(8, dst->reg, src, 0);
        ob(0x63);
        emit_modrm(dst->reg, src);
        return;
    }
    /* movabs */
    if (!strncmp(mn, "movabs", 6)) {
        if (src->kind == 2 && dst->kind == 1) {
            emit_rex(1, 0, 0, dst->reg, 0);
            ob(0xb8 + (dst->reg & 7));
            o64v(src->imm);
            return;
        }
        aerror("unsupported movabs form");
    }
    /* SSE moves (movsd/movss/movq/movd xmm) - basic */
    if ((!strcmp(mn, "movsd") || !strcmp(mn, "movss") || !strcmp(mn, "movapd") || !strcmp(mn, "movaps") || !strcmp(mn, "movq") || !strcmp(mn, "movd"))
        && (src->is_xmm || dst->is_xmm)) {
        int d = !strcmp(mn, "movsd");
        if (!strcmp(mn, "movq") || !strcmp(mn, "movd")) {
            int q = mn[3] == 'q';
            if (dst->is_xmm) { ob(0x66); emit_rex(q, dst->reg, src->kind == 3 && src->index >= 0 ? src->index : 0, src->kind == 1 ? src->reg : (src->base >= 0 && src->base != 16 ? src->base : 0), 0); ob(0x0f); ob(0x6e); emit_modrm(dst->reg, src); }
            else { ob(0x66); emit_rex(q, src->reg, dst->kind == 3 && dst->index >= 0 ? dst->index : 0, dst->kind == 1 ? dst->reg : (dst->base >= 0 && dst->base != 16 ? dst->base : 0), 0); ob(0x0f); ob(0x7e); emit_modrm(src->reg, dst); }
            return;
        }
        if (!strcmp(mn, "movapd")) ob(0x66);
        else if (!strcmp(mn, "movaps")) ;
        else ob(d ? 0xf2 : 0xf3);
        if (dst->is_xmm) {
            emit_rex(0, dst->reg, src->kind == 3 && src->index >= 0 ? src->index : 0, src->kind == 1 ? src->reg : (src->base >= 0 && src->base != 16 ? src->base : 0), 0);
            ob(0x0f); ob(!strcmp(mn, "movapd") || !strcmp(mn, "movaps") ? 0x28 : 0x10);
            emit_modrm(dst->reg, src);
        } else {
            emit_rex(0, src->reg, dst->kind == 3 && dst->index >= 0 ? dst->index : 0, dst->kind == 1 ? dst->reg : (dst->base >= 0 && dst->base != 16 ? dst->base : 0), 0);
            ob(0x0f); ob(!strcmp(mn, "movapd") || !strcmp(mn, "movaps") ? 0x29 : 0x11);
            emit_modrm(src->reg, dst);
        }
        return;
    }
    /* strip size suffix for the generic instructions */
    {
        static const char *bases[] = { "mov", "lea", "add", "or", "adc", "sbb", "and", "sub", "xor", "cmp", "test",
            "inc", "dec", "neg", "not", "push", "pop", "imul", "mul", "div", "idiv", "shl", "sal", "shr", "sar", "rol", "ror",
            "xchg", "cmpxchg", "xadd", "bswap", "bsf", "bsr", "bt", "bts", "btr", "btc", NULL };
        int i, matched = 0;
        for (i = 0; bases[i]; i++) {
            int bl = strlen(bases[i]);
            if (!strncmp(mn, bases[i], bl) && (len == bl || (len == bl + 1 && strchr("bwlq", mn[bl])))) {
                if (len == bl + 1) suffix = mn[bl];
                snprintf(base, sizeof base, "%s", bases[i]);
                matched = 1;
                break;
            }
        }
        if (!matched) aerror("unknown instruction in asm");
    }
    size = op_size(ops, n, suffix);
    if (!size) {
        if (!strcmp(base, "push") || !strcmp(base, "pop") || !strcmp(base, "call")) size = 8;
        else if (n && dst->kind == 2) size = 4;
        else size = 4;
    }
    if (!strcmp(base, "mov")) {
        if (n != 2) aerror("mov needs two operands");
        if (src->kind == 2) {
            if (dst->kind == 1) {
                if (size == 8) {
                    if (src->sym || src->imm < INT32_MIN || src->imm > INT32_MAX) {
                        emit_rex(1, 0, 0, dst->reg, 0);
                        ob(0xb8 + (dst->reg & 7));
                        if (src->sym) { asm_reloc_sym(asm_ind(), R_X86_64_64, src->sym, src->imm); o64v(0); } else o64v(src->imm);
                    } else {
                        emit_rex(1, 0, 0, dst->reg, 0); ob(0xc7); ob(0xc0 | (dst->reg & 7)); o32v((uint32_t)src->imm);
                    }
                } else {
                    if (size == 2) ob(0x66);
                    emit_rex(0, 0, 0, dst->reg, size == 1 && needs_rex8(dst->reg));
                    if (size == 1) { ob(0xb0 + (dst->reg & 7)); ob(src->imm); }
                    else { ob(0xb8 + (dst->reg & 7)); emit_imm_or_sym(size, src); }
                }
                return;
            }
            /* mov imm, mem */
            emit_prefix_rex(size, 0, dst, 0);
            ob(size == 1 ? 0xc6 : 0xc7);
            emit_modrm(0, dst);
            emit_imm_or_sym(size == 8 ? 4 : size, src);
            return;
        }
        if (src->kind == 1 && (dst->kind == 1 || dst->kind == 3 || dst->kind == 4)) {
            emit_prefix_rex(size, src->reg, dst, size == 1 && (needs_rex8(src->reg) || (dst->kind == 1 && needs_rex8(dst->reg))));
            ob(size == 1 ? 0x88 : 0x89);
            emit_modrm(src->reg, dst);
            return;
        }
        if (dst->kind == 1 && (src->kind == 3 || src->kind == 4)) {
            emit_prefix_rex(size, dst->reg, src, size == 1 && needs_rex8(dst->reg));
            ob(size == 1 ? 0x8a : 0x8b);
            emit_modrm(dst->reg, src);
            return;
        }
        aerror("unsupported mov operands");
    }
    if (!strcmp(base, "lea")) {
        emit_prefix_rex(size, dst->reg, src, 0);
        ob(0x8d);
        emit_modrm(dst->reg, src);
        return;
    }
    if ((ai = alu_index(base)) >= 0) {
        if (n != 2) aerror("instruction needs two operands");
        if (src->kind == 2) {
            if (dst->kind == 1 && dst->reg == 0 && !src->sym && !fits8(src->imm) && size != 1) {
                /* op eax, imm32 short form */
                emit_prefix_rex(size, 0, dst, 0);
                ob(0x05 + ai * 8);
                emit_imm(size == 8 ? 4 : size, src->imm);
                return;
            }
            emit_prefix_rex(size, 0, dst, size == 1 && dst->kind == 1 && needs_rex8(dst->reg));
            if (size == 1) { ob(0x80); emit_modrm(ai, dst); ob(src->imm); }
            else if (!src->sym && fits8(src->imm)) { ob(0x83); emit_modrm(ai, dst); ob(src->imm); }
            else { ob(0x81); emit_modrm(ai, dst); emit_imm_or_sym(size == 8 ? 4 : size, src); }
            return;
        }
        if (src->kind == 1) {
            emit_prefix_rex(size, src->reg, dst, size == 1 && (needs_rex8(src->reg) || (dst->kind == 1 && needs_rex8(dst->reg))));
            ob(ai * 8 + (size == 1 ? 0 : 1));
            emit_modrm(src->reg, dst);
            return;
        }
        if (dst->kind == 1) {
            emit_prefix_rex(size, dst->reg, src, size == 1 && needs_rex8(dst->reg));
            ob(ai * 8 + (size == 1 ? 2 : 3));
            emit_modrm(dst->reg, src);
            return;
        }
        aerror("unsupported operands");
    }
    if (!strcmp(base, "test")) {
        if (src->kind == 2) {
            emit_prefix_rex(size, 0, dst, size == 1 && dst->kind == 1 && needs_rex8(dst->reg));
            ob(size == 1 ? 0xf6 : 0xf7);
            emit_modrm(0, dst);
            emit_imm(size == 8 ? 4 : size, src->imm);
            return;
        }
        if (src->kind == 1) {
            emit_prefix_rex(size, src->reg, dst, size == 1 && (needs_rex8(src->reg) || (dst->kind == 1 && needs_rex8(dst->reg))));
            ob(size == 1 ? 0x84 : 0x85);
            emit_modrm(src->reg, dst);
            return;
        }
        if (dst->kind == 1) {
            emit_prefix_rex(size, dst->reg, src, 0);
            ob(size == 1 ? 0x84 : 0x85);
            emit_modrm(dst->reg, src);
            return;
        }
        aerror("unsupported operands");
    }
    if (!strcmp(base, "inc") || !strcmp(base, "dec") || !strcmp(base, "neg") || !strcmp(base, "not")
        || !strcmp(base, "mul") || !strcmp(base, "div") || !strcmp(base, "idiv")) {
        int ext = !strcmp(base, "inc") ? 0 : !strcmp(base, "dec") ? 1 : !strcmp(base, "not") ? 2 : !strcmp(base, "neg") ? 3
            : !strcmp(base, "mul") ? 4 : !strcmp(base, "div") ? 6 : 7;
        int opc = (!strcmp(base, "inc") || !strcmp(base, "dec")) ? 0xfe : 0xf6;
        if (!strcmp(base, "imul") && n == 1) { ext = 5; opc = 0xf6; }
        emit_prefix_rex(size, 0, dst, size == 1 && dst->kind == 1 && needs_rex8(dst->reg));
        ob(opc | (size == 1 ? 0 : 1));
        emit_modrm(ext, dst);
        return;
    }
    if (!strcmp(base, "imul")) {
        if (n == 1) {
            emit_prefix_rex(size, 0, dst, 0);
            ob(0xf7); emit_modrm(5, dst);
            return;
        }
        if (n == 2) {
            if (src->kind == 2) {
                emit_prefix_rex(size, dst->reg, dst, 0);
                if (fits8(src->imm)) { ob(0x6b); emit_modrm(dst->reg, dst); ob(src->imm); }
                else { ob(0x69); emit_modrm(dst->reg, dst); emit_imm(size == 8 ? 4 : size, src->imm); }
                return;
            }
            emit_prefix_rex(size, dst->reg, src, 0);
            ob(0x0f); ob(0xaf);
            emit_modrm(dst->reg, src);
            return;
        }
        if (n == 3) {
            /* imul $imm, src, dst */
            emit_prefix_rex(size, ops[2].reg, &ops[1], 0);
            if (fits8(ops[0].imm)) { ob(0x6b); emit_modrm(ops[2].reg, &ops[1]); ob(ops[0].imm); }
            else { ob(0x69); emit_modrm(ops[2].reg, &ops[1]); emit_imm(size == 8 ? 4 : size, ops[0].imm); }
            return;
        }
    }
    if (!strcmp(base, "shl") || !strcmp(base, "sal") || !strcmp(base, "shr") || !strcmp(base, "sar") || !strcmp(base, "rol") || !strcmp(base, "ror")) {
        int ext = !strcmp(base, "rol") ? 0 : !strcmp(base, "ror") ? 1 : (!strcmp(base, "shl") || !strcmp(base, "sal")) ? 4 : !strcmp(base, "shr") ? 5 : 7;
        AOp *d = &ops[n - 1];
        if (n == 1) {
            emit_prefix_rex(size, 0, d, 0);
            ob(size == 1 ? 0xd0 : 0xd1); emit_modrm(ext, d);
            return;
        }
        if (src->kind == 2) {
            emit_prefix_rex(size, 0, d, 0);
            if (src->imm == 1) { ob(size == 1 ? 0xd0 : 0xd1); emit_modrm(ext, d); }
            else { ob(size == 1 ? 0xc0 : 0xc1); emit_modrm(ext, d); ob(src->imm); }
            return;
        }
        /* by %cl */
        emit_prefix_rex(size, 0, d, 0);
        ob(size == 1 ? 0xd2 : 0xd3); emit_modrm(ext, d);
        return;
    }
    if (!strcmp(base, "push")) {
        if (dst->kind == 2) {
            if (fits8(dst->imm)) { ob(0x6a); ob(dst->imm); } else { ob(0x68); o32v((uint32_t)dst->imm); }
            return;
        }
        if (dst->kind == 1) { emit_rex(0, 0, 0, dst->reg, 0); ob(0x50 + (dst->reg & 7)); return; }
        emit_prefix_rex(4, 0, dst, 0); ob(0xff); emit_modrm(6, dst);
        return;
    }
    if (!strcmp(base, "pop")) {
        if (dst->kind == 1) { emit_rex(0, 0, 0, dst->reg, 0); ob(0x58 + (dst->reg & 7)); return; }
        emit_prefix_rex(4, 0, dst, 0); ob(0x8f); emit_modrm(0, dst);
        return;
    }
    if (!strcmp(base, "xchg")) {
        AOp *r = src->kind == 1 ? src : dst, *m = src->kind == 1 ? dst : src;
        emit_prefix_rex(size, r->reg, m, 0);
        ob(size == 1 ? 0x86 : 0x87);
        emit_modrm(r->reg, m);
        return;
    }
    if (!strcmp(base, "cmpxchg")) {
        emit_prefix_rex(size, src->reg, dst, 0);
        ob(0x0f); ob(size == 1 ? 0xb0 : 0xb1);
        emit_modrm(src->reg, dst);
        return;
    }
    if (!strcmp(base, "xadd")) {
        emit_prefix_rex(size, src->reg, dst, 0);
        ob(0x0f); ob(size == 1 ? 0xc0 : 0xc1);
        emit_modrm(src->reg, dst);
        return;
    }
    if (!strcmp(base, "bswap")) {
        emit_rex(size == 8, 0, 0, dst->reg, 0);
        ob(0x0f); ob(0xc8 + (dst->reg & 7));
        return;
    }
    if (!strcmp(base, "bsf") || !strcmp(base, "bsr")) {
        emit_prefix_rex(size, dst->reg, src, 0);
        ob(0x0f); ob(!strcmp(base, "bsf") ? 0xbc : 0xbd);
        emit_modrm(dst->reg, src);
        return;
    }
    if (!strcmp(base, "bt") || !strcmp(base, "bts") || !strcmp(base, "btr") || !strcmp(base, "btc")) {
        int ext = !strcmp(base, "bt") ? 4 : !strcmp(base, "bts") ? 5 : !strcmp(base, "btr") ? 6 : 7;
        if (src->kind == 2) {
            emit_prefix_rex(size, 0, dst, 0);
            ob(0x0f); ob(0xba); emit_modrm(ext, dst); ob(src->imm);
        } else {
            emit_prefix_rex(size, src->reg, dst, 0);
            ob(0x0f); ob(0x83 + (ext - 4) * 8 + (ext == 4 ? 0x20 : 0x20));
            emit_modrm(src->reg, dst);
        }
        return;
    }
    aerror("unknown instruction in asm");
}

/* directives */
static int handle_directive(const char *name)
{
    if (!strcmp(name, ".globl") || !strcmp(name, ".global")) {
        char buf[128];
        parse_ident(buf, sizeof buf);
        asm_define_label_sym(buf, 1);
        return 1;
    }
    if (!strcmp(name, ".text") || !strcmp(name, ".type") || !strcmp(name, ".size") || !strcmp(name, ".p2align")
        || !strcmp(name, ".align") || !strcmp(name, ".section") || !strcmp(name, ".data") || !strcmp(name, ".file")
        || !strcmp(name, ".ident") || !strcmp(name, ".weak") || !strcmp(name, ".hidden") || !strcmp(name, ".local")) {
        /* skip rest of line */
        while (*asm_p && *asm_p != '\n' && *asm_p != ';') asm_p++;
        return 1;
    }
    if (!strcmp(name, ".byte") || !strcmp(name, ".word") || !strcmp(name, ".short") || !strcmp(name, ".long") || !strcmp(name, ".int") || !strcmp(name, ".quad")) {
        int sz = !strcmp(name, ".byte") ? 1 : (!strcmp(name, ".word") || !strcmp(name, ".short")) ? 2 : !strcmp(name, ".quad") ? 8 : 4;
        for (;;) {
            int64_t v; const char *sym;
            parse_expr_sym(&v, &sym);
            if (sym) {
                if (sz == 8) { asm_reloc_sym(asm_ind(), R_X86_64_64, sym, v); o64v(0); }
                else if (sz == 4) { asm_reloc_sym(asm_ind(), R_X86_64_32S, sym, v); o32v(0); }
                else aerror("bad size for symbol");
            } else if (sz == 8) o64v(v);
            else emit_imm(sz, v);
            skip_ws();
            if (*asm_p == ',') { asm_p++; continue; }
            break;
        }
        return 1;
    }
    if (!strcmp(name, ".ascii") || !strcmp(name, ".asciz") || !strcmp(name, ".string")) {
        skip_ws();
        if (*asm_p != '"') aerror("string expected");
        asm_p++;
        while (*asm_p && *asm_p != '"') {
            int c = *asm_p++;
            if (c == '\\') {
                c = *asm_p++;
                switch (c) {
                case 'n': c = '\n'; break; case 't': c = '\t'; break; case 'r': c = '\r'; break;
                case '0': c = 0; break; case '\\': c = '\\'; break; case '"': c = '"'; break;
                }
            }
            ob(c);
        }
        if (*asm_p == '"') asm_p++;
        if (strcmp(name, ".ascii")) ob(0);
        return 1;
    }
    if (!strcmp(name, ".skip") || !strcmp(name, ".space") || !strcmp(name, ".zero")) {
        int64_t v; const char *sym;
        parse_expr_sym(&v, &sym);
        while (v-- > 0) ob(0);
        return 1;
    }
    return 0;
}

/* assemble a complete text (statements separated by newlines or ';') */
void asm_assemble_text(const char *text)
{
    asm_p = text;
    asm_start = text;
    nalabels = 0;
    nafix = 0;
    memset(numeric_counter, 0, sizeof numeric_counter);
    for (;;) {
        char mn[64];
        AOp ops[4];
        int n = 0;
        skip_ws();
        while (*asm_p == '\n' || *asm_p == ';') { asm_p++; skip_ws(); }
        if (!*asm_p) break;
        if (*asm_p == '#') { while (*asm_p && *asm_p != '\n') asm_p++; continue; }
        if (!parse_ident(mn, sizeof mn)) {
            aerror("syntax error in asm");
        }
        skip_ws();
        if (*asm_p == ':') {
            /* label */
            asm_p++;
            {
                int alldig = 1, i;
                for (i = 0; mn[i]; i++) if (mn[i] < '0' || mn[i] > '9') alldig = 0;
                if (alldig) {
                    char buf[80];
                    int k = atoi(mn) % 10;
                    numeric_counter[k]++;
                    snprintf(buf, sizeof buf, ".L%d.%d", atoi(mn), numeric_counter[k]);
                    add_label(buf, asm_ind());
                } else {
                    add_label(mn, asm_ind());
                    if (mn[0] != '.')
                        asm_define_label_sym(mn, 0);
                }
            }
            continue;
        }
        if (mn[0] == '.') {
            if (!handle_directive(mn))
                aerror("unknown asm directive");
            continue;
        }
        /* prefix instructions followed by another on same line: lock/rep */
        if (!strcmp(mn, "lock") || !strcmp(mn, "rep") || !strcmp(mn, "repe") || !strcmp(mn, "repne") || !strcmp(mn, "repz") || !strcmp(mn, "repnz")) {
            assemble_insn(mn, NULL, 0);
            continue;
        }
        /* operands */
        while (*asm_p && *asm_p != '\n' && *asm_p != ';') {
            if (n >= 4) aerror("too many operands");
            parse_operand(&ops[n]);
            n++;
            skip_ws();
            if (*asm_p == ',') { asm_p++; continue; }
            break;
        }
        /* lowercase mnemonic */
        {
            int i;
            for (i = 0; mn[i]; i++) if (mn[i] >= 'A' && mn[i] <= 'Z') mn[i] += 32;
        }
        assemble_insn(mn, ops, n);
    }
    resolve_asm_fixups();
}
