static void parse_asm_operands(AsmInfo *ai, int is_output)
{
    while (tok != ':' && tok != ')') {
        AsmOperand *op;
        ai->ops = xrealloc(ai->ops, (ai->nops + 1) * sizeof(AsmOperand));
        op = &ai->ops[ai->nops++];
