        else break;
    }
}

void parse_asm_statement(Node *n)
{
    CStr cs2;
    int w, c;
    AsmInfo *ai = xcalloc(sizeof(AsmInfo));
    next();
    while (tok == TOK_VOLATILE1 || tok == TOK_VOLATILE2 || tok == TOK_VOLATILE3 || tok == TOK_INLINE1 || tok == TOK_GOTO) {
        if (tok != TOK_GOTO) ai->is_volatile = 1;
        next();
    }
    skip('(');
    if (tok != TOK_STR)
        expect("string constant");
    cstr_init(&cs2);
    while (tok == TOK_STR) {
        parse_string_literal(tokstr, &cs2, &w, &c);
        next();
    }
    n->str = cs2.data ? intern(cs2.data, cs2.len) : "";
    n->slen = cs2.len;
    cstr_free(&cs2);
    if (tok == ':') {
        next();
        parse_asm_operands(ai, 1);
        if (tok == ':') {
            next();
            parse_asm_operands(ai, 0);
            if (tok == ':') {
                next();
                while (tok == TOK_STR) {
                    CStr cc; int w2, c2;
                    cstr_init(&cc);
                    parse_string_literal(tokstr, &cc, &w2, &c2);
                    ai->clobbers = xrealloc(ai->clobbers, (ai->nclob + 1) * sizeof(char *));
                    ai->clobbers[ai->nclob++] = xstrdup(cc.data ? cc.data : "");
                    cstr_free(&cc);
                    next();
                    if (tok == ',') next(); else break;
                }
                if (tok == ':') {
                    /* goto labels */
                    next();
                    while (tok >= TOK_IDENT) { next(); if (tok == ',') next(); else break; }
                }
            }
        }
    }
    skip(')');
    if (tok == ';') next();
    n->sym = (Sym *)ai;  /* stash */
    if (!cur_func) ai->is_global = 1;
}

static int reg_in_list(int *regs, int n, int r)
{
    int i;
    for (i = 0; i < n; i++) if (regs[i] == r) return 1;
    return 0;
}

static int clobbered_reg(AsmInfo *ai, int r)
{
    int i;
    for (i = 0; i < ai->nclob; i++) {
        int size;
        extern int asm_reg_lookup_name(const char *s, int *size);
        const char *c = ai->clobbers[i];
        if (c[0] == '%') c++;
        if (asm_reg_lookup_name(c, &size) == r) return 1;
    }
    return 0;
}

void gen_asm_statement(Node *n)
{
    AsmInfo *ai = (AsmInfo *)n->sym;
    int i;
    int used[16], nused = 0;
    static const int pool[] = { RAX, RCX, RDX, RSI, RDI, R8, R9, R10, R11, RBX };
    int scratch;
    CStr out;
    const char *p;

    if (ai->is_global) {
        /* file scope asm: assemble into text section */
        Section *save = cs;
        cs = cur_text_section;
        asm_assemble_text(n->str);
        cs = save;
        return;
    }
    /* fixed registers first */
    for (i = 0; i < ai->nops; i++) {
        AsmOperand *op = &ai->ops[i];
        const char *c = op->constraint;
        while (*c == '=' || *c == '+' || *c == '&' || *c == '%') c++;
        op->size = tsize(op->expr->type);
        if (op->size > 8) op->size = 8;
        if (op->size <= 0) op->size = 8;
        switch (*c) {
        case 'a': op->reg = RAX; break;
        case 'b': op->reg = RBX; break;
        case 'c': op->reg = RCX; break;
        case 'd': op->reg = RDX; break;
        case 'S': op->reg = RSI; break;
        case 'D': op->reg = RDI; break;
        case 'm': case 'o': case 'V': op->is_mem = 1; break;
        case 'i': case 'n': case 'I': case 'J': case 'K': case 'N': case 'e': case 'Z': {
            int64_t v;
            if (node_is_const_int(op->expr, &v)) { op->is_imm = 1; op->imm = v; }
            else op->is_mem = 0;
            break;
        }
        case 'x': op->is_xmm = 1; break;
        case '0': case '1': case '2': case '3': case '4': case '5': case '6': case '7': case '8': case '9':
            op->match = *c - '0';
            break;
        case 'g':
        case 'r': case 'q': case 'Q': case 'R': case 'l':
            break;
        default:
            break;
        }
        if (op->reg >= 0) used[nused++] = op->reg;
    }
    /* matching constraints */
    for (i = 0; i < ai->nops; i++) {
        AsmOperand *op = &ai->ops[i];
        if (op->match >= 0 && op->match < ai->nops) {
            AsmOperand *m = &ai->ops[op->match];
            if (m->reg >= 0) op->reg = m->reg;
        }
    }
    /* allocate the rest */
    for (i = 0; i < ai->nops; i++) {
        AsmOperand *op = &ai->ops[i];
        int k;
        if (op->reg >= 0 || op->is_imm || op->is_xmm) continue;
        if (op->match >= 0) {
            AsmOperand *m = &ai->ops[op->match];
            if (m->reg < 0) {
                for (k = 0; k < 10; k++) if (!reg_in_list(used, nused, pool[k]) && !clobbered_reg(ai, pool[k])) break;
                if (k == 10) tcc_error("too many asm operands");
                m->reg = pool[k]; used[nused++] = pool[k];
            }
            op->reg = m->reg;
            continue;
        }
        for (k = 0; k < 10; k++) if (!reg_in_list(used, nused, pool[k]) && !clobbered_reg(ai, pool[k])) break;
        if (k == 10) tcc_error("too many asm operands");
        op->reg = pool[k]; used[nused++] = pool[k];
    }
    for (scratch = 0; scratch < 10; scratch++)
        if (!reg_in_list(used, nused, pool[scratch]) && !clobbered_reg(ai, pool[scratch])) break;
    scratch = scratch < 10 ? pool[scratch] : R11;
    /* evaluate operands into temps */
    for (i = 0; i < ai->nops; i++) {
        AsmOperand *op = &ai->ops[i];
        op->tmp = alloc_temp(8, 8);
        if (op->is_imm) continue;
        if (op->is_mem || op->is_output) {
            /* address of lvalue (or of value for mem inputs) */
            if (op->expr->lvalue || op->is_output) {
                gen_addr(op->expr);
            } else {
                /* memory input of rvalue: materialize in temp */
                long t2 = alloc_temp(8, 8);
                gen_expr(op->expr);
                store_to_temp(op->expr->type, t2);
                lea(RAX, RBP, t2);
            }
            store_reg_mem(8, RAX, RBP, op->tmp);
            if (op->is_output && !op->is_mem && op->is_inout) {
                /* inout register: also need the value */
                long t3 = alloc_temp(8, 8);
                load_reg_mem(8, RCX, RBP, op->tmp, 0);
                mov_rr(RAX, RCX);
                load_value(op->expr->type);
                if (value_kind(op->expr->type) == 1) { sse_store(1, 0, RBP, t3); }
                else store_reg_mem(8, RAX, RBP, t3);
                op->imm = t3; /* reuse field: value temp */
            }
        } else {
            gen_expr(op->expr);
            if (value_kind(op->expr->type) == 1) sse_store(1, 0, RBP, op->tmp);
            else store_reg_mem(8, RAX, RBP, op->tmp);
        }
    }
    /* load registers */
    for (i = 0; i < ai->nops; i++) {
        AsmOperand *op = &ai->ops[i];
        if (op->is_imm) continue;
        if (op->is_xmm) {
            if (!op->is_output || op->is_inout) sse_load(1, i & 7, RBP, op->is_inout ? op->imm : op->tmp);
            continue;
        }
        if (op->is_mem) {
            load_reg_mem(8, op->reg, RBP, op->tmp, 0);
            continue;
        }
        if (op->is_output && !op->is_inout) continue;
        load_reg_mem(8, op->reg, RBP, op->is_inout ? op->imm : op->tmp, 0);
    }
    /* build substituted template */
    cstr_init(&out);
    for (p = n->str; *p; p++) {
        if (*p != '%') { cstr_ccat(&out, *p); continue; }
        p++;
        if (*p == '%') { cstr_ccat(&out, '%'); continue; }
        if (*p == '=') { cstr_printf(&out, "%d", (int)ind()); continue; }
        {
            int mod = 0, idx = -1;
            if (*p == 'k' || *p == 'q' || *p == 'w' || *p == 'b' || *p == 'h' || *p == 'c' || *p == 'P' || *p == 'l') { mod = *p; p++; }
            if (*p == '[') {
                char nm[32]; int k = 0;
                p++;
                while (*p && *p != ']' && k < 31) nm[k++] = *p++;
                nm[k] = 0;
                for (i = 0; i < ai->nops; i++) if (!strcmp(ai->ops[i].name, nm)) idx = i;
                if (idx < 0) tcc_error("unknown asm operand '%s'", nm);
            } else if (*p >= '0' && *p <= '9') {
                idx = 0;
                while (*p >= '0' && *p <= '9') idx = idx * 10 + (*p++ - '0');
                p--;
            } else
                tcc_error("invalid asm template");
            if (idx >= ai->nops) tcc_error("invalid asm operand number");
            {
                AsmOperand *op = &ai->ops[idx];
                if (op->is_imm) {
                    if (mod == 'c' || mod == 'P') cstr_printf(&out, "%lld", (long long)op->imm);
                    else cstr_printf(&out, "$%lld", (long long)op->imm);
                } else if (op->is_xmm) {
                    cstr_printf(&out, "%%xmm%d", idx & 7);
                } else if (op->is_mem) {
                    cstr_printf(&out, "(%%%s)", asm_reg_name(op->reg, 8));
                } else {
                    int sz = op->size;
                    if (mod == 'k') sz = 4; else if (mod == 'q') sz = 8; else if (mod == 'w') sz = 2; else if (mod == 'b') sz = 1;
                    if (sz == 1 && mod == 'h') { static const char *hi[] = { "ah", "ch", "dh", "bh" }; cstr_printf(&out, "%%%s", hi[op->reg & 3]); }
                    else cstr_printf(&out, "%%%s", asm_reg_name(op->reg, sz));
                }
            }
        }
    }
    asm_assemble_text(out.data ? out.data : "");
    cstr_free(&out);
    /* store outputs */
    for (i = 0; i < ai->nops; i++) {
        AsmOperand *op = &ai->ops[i];
        if (!op->is_output || op->is_mem) continue;
        load_reg_mem(8, scratch, RBP, op->tmp, 0);
        if (op->is_xmm) {
            if (op->expr->type->kind == T_FLOAT) sse_store(0, i & 7, scratch, 0); else sse_store(1, i & 7, scratch, 0);
            continue;
        }
        store_reg_mem(tsize(op->expr->type) > 8 ? 8 : tsize(op->expr->type), op->reg, scratch, 0);
    }
}
